INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('b7973510-a5cf-4aa7-9550-88800a43dd9e', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'Menjelang & Dalam Rangka (～にあたって) — Peluncuran Proyek & Pidato Resmi', 'Kuasai pola formal ～にあたって / ～にあたり untuk pidato pembukaan, peluncuran proyek, kontrak kerja, dan persiapan acara resmi di lingkungan bisnis maupun kampus Jepang.', 'curriculum', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('93ef21f5-3bd2-441f-b265-a57f384af3aa', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'Seiring Dengan (～に伴って) — Tren Ekonomi, Teknologi & Perubahan Sosial', 'Pelajari pola ～に伴って / ～に伴い / ～に伴う untuk menjelaskan dua perubahan yang terjadi beriringan dalam berita ekonomi, demografi, dan transformasi digital.', 'curriculum', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('2d087d02-4b0a-4f28-a2b3-9d3fad94a089', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'Tidak Terbatas Pada (～に限らず) — Analisis Pasar, Layanan Global & Keragaman', 'Gunakan pola ～に限らず untuk menyatakan cakupan yang luas melampaui satu kategori dalam presentasi pasar, kebijakan inklusif, dan diskusi budaya.', 'curriculum', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('9e811af4-8350-4fc5-b527-3d1f94534af8', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'Terikat Etika & Tanggung Jawab (～わけにはいかない) — Komitmen Profesional', 'Pahami cara menyatakan larangan psikologis, tanggung jawab etis, dan kewajiban sosial menggunakan ～わけにはいかない serta ～ないわけにはいかない di tempat kerja.', 'curriculum', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('c1cdf60d-8949-4d65-b21d-202f6542e8b2', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'Terpaksa Harus (～ざるを得ない) — Manajemen Krisis, Keputusan Berat & Negosiasi', 'Kuasai pola formal ～ざるを得ない (termasuk pengecualian せざるを得ない) untuk menyampaikan keputusan berat yang tidak terhindarkan dalam bisnis, berita, dan negosiasi.', 'curriculum', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('7c876e96-999a-469a-898e-7efce924ebb9', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'Meskipun & Terlepas Dari (～にもかかわらず) — Laporan Berita & Fakta Kontras', 'Kuasai pola formal ～にもかかわらず untuk menyatakan hasil tak terduga yang bertolak belakang dengan kondisi awal dalam laporan berita, evaluasi proyek, dan pidato sopan.', 'curriculum', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('6239ac44-49bc-404b-b00c-0c31a2cebd17', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'Setelah Mempertimbangkan & Dalam Hal (～上で) — Rapat Strategi & Kontrak', 'Bedakan dua fungsi krusial ～上で di JLPT N2: [V-た + 上で] (''setelah melakukan A, lalu B'') dan [V-dict / Nの + 上で] (''dalam hal / saat menjalankan...'').', 'curriculum', 7, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('ee802ba0-8a4b-47de-bac3-002789b922e2', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'Sedang Terus Berlangsung (～つつある) — Transformasi Industri & Tren', 'Gunakan pola formal ～つつある (Akar ます + つつある) untuk mendeskripsikan perubahan bertahap yang sedang berlangsung dalam berita ekonomi, lingkungan, dan masyarakat.', 'curriculum', 8, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('9e7daf95-0f54-496c-80bb-cc2402ab3d2e', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'Bisa Saja Berakibat Buruk (～かねない) — Manajemen Risiko & Peringatan', 'Kuasai pola peringatan ～かねない (Akar ます + かねない) untuk menyampaikan kemungkinan dampak negatif, risiko keamanan, dan peringatan serius di dunia kerja.', 'curriculum', 9, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('56884ee3-e50a-4cce-8f39-3ca7f17e32e9', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'Ungkapan Hormat Peninggi (Sonkeigo Baku) — Klien, Eksekutif & Kesiapan N2', 'Kuasai bentuk Sonkeigo baku (いらっしゃる, おっしゃる, ご覧になる, なさる, お～になる, ご～になる) untuk komunikasi klien, rapat eksekutif, serta pemantapan ujian JLPT N2.', 'curriculum', 10, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('1b659828-2088-4186-b3a1-aeddcdee8c61', 'dde2b2ff-276b-4591-b0ad-f79e636c93e5', 'Ujian Simulasi Kesiapan JLPT N2', 'Evaluasi komprehensif lintas 4 pilar (Membaca, Mendengar, Menulis, Berbicara) yang menguji seluruh 10 tata bahasa inti JLPT N2.', 'diagnostic_exam', 99, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
