INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6249d736-f25a-4762-a778-c0d5285fa588', '01575ac2-7d42-4b52-a3f0-a7ab76679118', 'd1000019-0000-0000-0000-000000000024', 'reading', 'fill_blank', 'Lengkapi kalimat bisnis berikut: 関係者全員と十分に協議した___、最終的な方針を決定したい。', '{"options":["上で","に伴って","に限らず","かねない"],"translation":"Setelah berdiskusi secara matang dengan semua pihak terkait, saya ingin menetapkan kebijakan final.","sentence_template":"関係者全員と十分に協議した[blank]、最終的な方針を決定したい。"}'::jsonb, '{"selected":"上で"}'::jsonb, NULL, NULL, 'V-ta + 上で menyatakan langkah A diselesaikan terlebih dahulu sebagai dasar sebelum melakukan B.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('023c6d12-c5ef-496b-9bf3-137ce545bf2c', '01575ac2-7d42-4b52-a3f0-a7ab76679118', 'd1000019-0000-0000-0000-000000000024', 'reading', 'fill_blank', 'Pilih bentuk penyambung yang tepat untuk konteks ''dalam hal'': 異文化を理解する___、相手の価値観を尊重する姿勢が大切だ。', '{"options":["上で","にあたらない","にもかかわらず","ざるを得ず"],"translation":"Dalam hal memahami lintas budaya, sikap menghormati nilai-nilai pihak lain sangatlah penting.","sentence_template":"異文化を理解する[blank]、相手の価値観を尊重する姿勢が大切だ。"}'::jsonb, '{"selected":"上で"}'::jsonb, NULL, NULL, 'V-dict + 上で berarti ''dalam hal / saat melakukan (tujuan tersebut)''.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('36374ce9-a497-487d-86c9-3c3e8692204a', '01575ac2-7d42-4b52-a3f0-a7ab76679118', 'd1000019-0000-0000-0000-000000000024', 'listening', 'listening_choice', 'Dengarkan arahan staf administrasi. Apa yang harus dilakukan pelamar sebelum mengirim formulir?', '{"options":[{"id":"opt_1","text":"Membaca panduan rekrutmen dengan saksama terlebih dahulu baru menyerahkan dokumen yang diperlukan"},{"id":"opt_2","text":"Mengirim dokumen kosong tanpa membaca panduan"},{"id":"opt_3","text":"Datang langsung ke kantor pusat tanpa membuat janji"},{"id":"opt_4","text":"Menunggu pengumuman hasil seleksi sebelum mendaftar"}],"audio_text":"募集要項をよくお読みいただいた上で、必要書類を期限までにご提出ください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'よくお読みいただいた上で menegaskan tindakan membaca panduan harus mendahului penyerahan dokumen.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c3b936e3-bbdd-4666-86bd-c683e88ee2bf', '01575ac2-7d42-4b52-a3f0-a7ab76679118', 'd1000019-0000-0000-0000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat: "Setelah memeriksa isi kontrak secara teliti, saya menandatanganinya."', '{"romaji":"Keiyakusho no naiyou o yoku kakunin shita ue de, shomei shita.","tokens":["内容をよく","上で、","した。","に伴って、","契約書の","確認した","署名","確認する"],"target_translation":"Setelah memeriksa isi kontrak secara teliti, saya menandatanganinya."}'::jsonb, '["契約書の","内容をよく","確認した","上で、","署名","した。"]'::jsonb, NULL, NULL, '確認した上で (setelah memastikan) memakai bentuk lampau V-ta sebelum tindakan berikutnya.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6c0a9afd-b29a-4c33-84ba-2a2009755b4c', '01575ac2-7d42-4b52-a3f0-a7ab76679118', 'd1000019-0000-0000-0000-000000000024', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dalam hal menjalankan proyek bersama, komunikasi yang terbuka sangat penting."', '{"romaji":"Kyoudou purojekuto o susumeru ue de, sotchoku na iken koukan ga fukaketsu desu.","display_text":"共同プロジェクトを進める上で、率直な意見交換が不可欠です。","phonetic_breakdown":["きょうどうぷろじぇくとを","すすめるうえで","そっちょくな","いけんこうかんが","ふかけつです"]}'::jsonb, '{"expected_transcript":"共同プロジェクトを進める上で、率直な意見交換が不可欠です。"}'::jsonb, NULL, NULL, '進める上で (dalam menjalankan) + 不可欠です (mutlak diperlukan) adalah struktur rapat formal N2.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('76df6b1c-4e5a-4d6b-b170-bdbd9e48757c', '01575ac2-7d42-4b52-a3f0-a7ab76679118', 'd1000019-0000-0000-0000-000000000024', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 現地を実際に視察した___なければ、正確な判断は下せない。', '{"options":["上で","にあたり","に伴い","つつ"],"translation":"Jika tidak setelah meninjau lokasi secara langsung terlebih dahulu, penilaian yang akurat tidak dapat dibuat.","sentence_template":"現地を実際に視察した[blank]なければ、正確な判断は下せない。"}'::jsonb, '{"selected":"上で"}'::jsonb, NULL, NULL, '～た上でなければ berarti ''kecuali setelah melakukan A terlebih dahulu, B tidak mungkin terwujud''.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('314e64fe-0482-4639-bb3b-1b53f5876f3d', '01575ac2-7d42-4b52-a3f0-a7ab76679118', 'd1000019-0000-0000-0000-000000000024', 'listening', 'listening_choice', 'Dengarkan saran dosen pembimbing. Apa yang perlu diperhatikan dalam menulis tesis?', '{"options":[{"id":"opt_1","text":"Mengabaikan seluruh penelitian terdahulu"},{"id":"opt_2","text":"Menulis kesimpulan sebelum mengumpulkan data"},{"id":"opt_3","text":"Merangkum penelitian terdahulu secara menyeluruh terlebih dahulu, baru menyajikan sudut pandang orisinal"},{"id":"opt_4","text":"Memperpendek jumlah halaman tesis hingga separuhnya"}],"audio_text":"先行研究を徹底的に整理した上で、独自の視点を提示することが論文の質を高めます。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '整理した上で (setelah menata/merangkum) menjadi landasan bagi 独自の視点を提示する.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d53dbb73-af78-49b5-a2d1-4964a854d975', '01575ac2-7d42-4b52-a3f0-a7ab76679118', 'd1000019-0000-0000-0000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat: "Dalam hal belajar bahasa asing, membiasakan diri mendengar setiap hari sangat efektif."', '{"romaji":"Gaikokugo o manabu ue de, mainichi kiku shuukan ga kouka-teki da.","tokens":["学ぶ","毎日聞く習慣が","だ。","にもかかわらず、","外国語を","上で、","効果的","学んだ"],"target_translation":"Dalam hal belajar bahasa asing, membiasakan diri mendengar setiap hari sangat efektif."}'::jsonb, '["外国語を","学ぶ","上で、","毎日聞く習慣が","効果的","だ。"]'::jsonb, NULL, NULL, '学ぶ上で (dalam hal mempelajari) menggunakan verba bentuk kamus.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('68b23c05-d92d-4f32-b4a2-7add26e55797', '097150fb-ce6e-40e8-8503-8c67db308718', 'd1000019-0000-0000-0000-000000000020', 'reading', 'fill_blank', 'Lengkapi artikel budaya berikut: 日本のアニメは若者___、幅広い世代から支持されている。', '{"options":["に限らず","にあたって","に伴って","かねない"],"translation":"Anime Jepang tidak terbatas pada kaum muda saja, melainkan didukung oleh berbagai generasi.","sentence_template":"日本のアニメは若者[blank]、幅広い世代から支持されている。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, NULL, NULL, '～に限らず menyatakan cakupan yang luas (bukan hanya A, tetapi juga B).', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e935fff5-bd12-4576-b1e4-176f03cc355b', '097150fb-ce6e-40e8-8503-8c67db308718', 'd1000019-0000-0000-0000-000000000020', 'reading', 'fill_blank', 'Pilih pola yang tepat untuk laporan bisnis: このサービスは法人___、個人事業主にも広く利用されている。', '{"options":["に限らず","にもかかわらず","ざるを得ず","つつあり"],"translation":"Layanan ini tidak terbatas pada badan hukum, tetapi juga digunakan secara luas oleh pelaku usaha perorangan.","sentence_template":"このサービスは法人[blank]、個人事業主にも広く利用されている。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, NULL, NULL, '法人 (badan usaha/perusahaan) dikontraskan perluasannya dengan 個人事業主 (pekerja mandiri/UMKM).', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d5007e4d-2937-4c1a-b622-47f83e8e3bd5', '097150fb-ce6e-40e8-8503-8c67db308718', 'd1000019-0000-0000-0000-000000000020', 'listening', 'listening_choice', 'Dengarkan iklan aplikasi belajar berikut. Siapa target pengguna aplikasi tersebut?', '{"options":[{"id":"opt_1","text":"Hanya khusus untuk siswa sekolah dasar"},{"id":"opt_2","text":"Hanya untuk penerjemah profesional bersertifikat"},{"id":"opt_3","text":"Tidak hanya pemula, tetapi juga pembelajar tingkat mahir untuk bisnis"},{"id":"opt_4","text":"Khusus untuk wisatawan yang berkunjung kurang dari seminggu"}],"audio_text":"この語学アプリは初心者のみに限らず、ビジネスで実践的な会話力を磨きたい上級者にも対応しています。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '初心者のみに限らず berarti tidak hanya terbatas pada pemula saja.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a6164a1b-a397-43b6-b116-8ce0402ffa7f', '097150fb-ce6e-40e8-8503-8c67db308718', 'd1000019-0000-0000-0000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat: "Masalah lingkungan tidak terbatas pada satu negara, melainkan isu seluruh dunia."', '{"romaji":"Kankyou mondai wa ikkoku ni kagirazu, sekaijuu no kadai da.","tokens":["一国","世界中の","だ。","にあたって、","環境問題は","に限らず、","課題","に伴って、"],"target_translation":"Masalah lingkungan tidak terbatas pada satu negara, melainkan isu seluruh dunia."}'::jsonb, '["環境問題は","一国","に限らず、","世界中の","課題","だ。"]'::jsonb, NULL, NULL, '一国に限らず (tidak terbatas pada satu negara) sangat sering muncul di bacaan opini N2.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f13c864a-be02-4fce-ae5a-666ede401fe3', '097150fb-ce6e-40e8-8503-8c67db308718', 'd1000019-0000-0000-0000-000000000020', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Produk ini tidak hanya populer di Jepang, tetapi juga di Asia Tenggara."', '{"romaji":"Kono shouhin wa Nihon kokunai ni kagirazu, Tounan Ajia demo ninki o atsumete imasu.","display_text":"この商品は日本国内に限らず、東南アジアでも人気を集めています。","phonetic_breakdown":["このしょうひんは","にほんこくないに","かぎらず","とうなんあじあでも","にんきを","あつめています"]}'::jsonb, '{"expected_transcript":"この商品は日本国内に限らず、東南アジアでも人気を集めています。"}'::jsonb, NULL, NULL, '人気を集める (menarik popularitas) + ～に限らず adalah struktur presentasi produk yang efektif.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5fab3067-3d69-4a55-93cb-f5a102111325', '097150fb-ce6e-40e8-8503-8c67db308718', 'd1000019-0000-0000-0000-000000000020', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 週末___、平日の夜もこの図書館は多くの利用者でにぎわっている。', '{"options":["に限らず","にあたり","の上で","わけにはいかず"],"translation":"Tidak hanya akhir pekan, pada malam hari kerja pun perpustakaan ini ramai oleh banyak pengunjung.","sentence_template":"週末[blank]、平日の夜もこの図書館は多くの利用者でにぎわっている。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, NULL, NULL, '週末に限らず diikuti 平日の夜も (bahkan malam hari kerja pun) untuk memperluas jangkauan waktu.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cae8ff16-028d-4fd4-b6b6-b18a92486b71', '097150fb-ce6e-40e8-8503-8c67db308718', 'd1000019-0000-0000-0000-000000000020', 'listening', 'listening_choice', 'Dengarkan wawancara kepala HRD. Kriteria apa yang dicari perusahaan?', '{"options":[{"id":"opt_1","text":"Hanya menerima lulusan universitas negeri di Tokyo"},{"id":"opt_2","text":"Merekrut talenta yang proaktif memecahkan masalah tanpa memandang latar pendidikan atau kewarganegaraan"},{"id":"opt_3","text":"Hanya merekrut pelamar dengan pengalaman kerja di atas sepuluh tahun"},{"id":"opt_4","text":"Membatasi rekrutmen hanya untuk bidang teknik mesin"}],"audio_text":"弊社では学歴や国籍に限らず、主体的に課題解決へ取り組める人材を採用しています。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '学歴や国籍に限らず berarti tidak terbatas pada latar belakang pendidikan atau kewarganegaraan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('149d0468-9608-45e8-ae82-9137c7b5f149', '097150fb-ce6e-40e8-8503-8c67db308718', 'd1000019-0000-0000-0000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat: "Keterampilan komunikasi penting tidak hanya dalam penjualan, tetapi juga di bidang teknik."', '{"romaji":"Komyunikeeshon nouryoku wa eigyou ni kagirazu, gijutsushoku demo juuyou da.","tokens":["営業","技術職でも","だ。","にもかかわらず、","コミュニケーション能力は","に限らず、","重要","に伴う"],"target_translation":"Keterampilan komunikasi penting tidak hanya dalam penjualan, tetapi juga di bidang teknik."}'::jsonb, '["コミュニケーション能力は","営業","に限らず、","技術職でも","重要","だ。"]'::jsonb, NULL, NULL, '営業に限らず、技術職でも memperluas lingkup pentingnya keterampilan komunikasi.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('06e51724-67bc-474f-afd5-c9be57d7b507', '0b40c1f2-d0e7-491e-9488-9a5dce2dd8b2', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 小さな確認ミスが、重大な___を引き起こしかねない。', '{"options":["事故","歓迎","卒業","普及"],"translation":"Kesalahan pengecekan kecil bisa saja memicu kecelakaan serius.","sentence_template":"小さな確認ミスが、重大な[blank]を引き起こしかねない。"}'::jsonb, '{"selected":"事故"}'::jsonb, NULL, NULL, '重大な事故を引き起こす berarti memicu kecelakaan serius; konteks negatif khas ～かねない.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('21654731-49fe-481a-8310-b02b19cf2184', '0b40c1f2-d0e7-491e-9488-9a5dce2dd8b2', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat peringatan bisnis berikut: 不適切な対応を続ければ、企業の___を損ないかねない。', '{"options":["信用","気候","趣味","季節"],"translation":"Jika terus memberikan penanganan yang tidak tepat, hal itu bisa saja merusak kredibilitas perusahaan.","sentence_template":"不適切な対応を続ければ、企業の[blank]を損ないかねない。"}'::jsonb, '{"selected":"信用"}'::jsonb, NULL, NULL, '信用を損なう (merusak kredibilitas/kepercayaan) adalah kolokasi penting bisnis N2.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e7634954-fdb7-4924-b1b4-006bda6fed92', '0b40c1f2-d0e7-491e-9488-9a5dce2dd8b2', NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: パスワードの使い回しは、個人情報の___につながりかねない。', '{"options":["漏洩","設立","開会","回復"],"translation":"Menggunakan kata sandi yang sama berulang kali bisa saja berujung pada kebocoran data pribadi.","sentence_template":"パスワードの使い回しは、個人情報の[blank]につながりかねない。"}'::jsonb, '{"selected":"漏洩"}'::jsonb, NULL, NULL, '漏洩 (rouei) berarti kebocoran informasi atau data.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('50b3cf7c-50ba-4789-a2b2-8866cda95123', '0b40c1f2-d0e7-491e-9488-9a5dce2dd8b2', NULL, 'listening', 'listening_choice', 'Dengarkan peringatan manajer keselamatan berikut. Risiko apa yang dikhawatirkan?', '{"options":[{"id":"opt_1","text":"Pekerja bisa saja mengalami cedera berat jika pemeriksaan mesin diabaikan"},{"id":"opt_2","text":"Mesin akan bekerja dua kali lebih cepat dari biasanya"},{"id":"opt_3","text":"Biaya listrik pabrik akan turun drastis bulan ini"},{"id":"opt_4","text":"Jadwal libur pekerja akan ditambah seminggu"}],"audio_text":"機械の点検を怠ると、作業員が大けがをしかねないので徹底してください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '点検を怠る (melalaikan inspeksi) → 大けがをしかねない (bisa saja mengalami cedera serius).', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('46245739-6014-4ea5-8c34-6f887a9dac41', '0b40c1f2-d0e7-491e-9488-9a5dce2dd8b2', NULL, 'listening', 'listening_choice', 'Dengarkan nasihat rekan kerja berikut. Mengapa ia mengingatkan soal cara bicara?', '{"options":[{"id":"opt_1","text":"Karena kalimatnya terlalu pendek untuk laporan resmi"},{"id":"opt_2","text":"Karena cara bicara seperti itu bisa saja menimbulkan kesalahpahaman"},{"id":"opt_3","text":"Karena lawan bicara tidak mengerti istilah teknis komputer"},{"id":"opt_4","text":"Karena suara pembicara terlalu pelan di ruang rapat"}],"audio_text":"その言い方だと、相手に誤解を与えかねないから表現を変えたほうがいいよ。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '誤解を与えかねない berarti ''bisa saja menimbulkan kesalahpahaman''.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3f207b49-a6f8-4614-adf8-2a97b6ed6584', '0b40c1f2-d0e7-491e-9488-9a5dce2dd8b2', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika terus bekerja tanpa istirahat, Anda bisa saja jatuh sakit."', '{"romaji":"Kyuusoku o torazu ni hataraki tsuzukeru to, taichou o kuzushikanemasen yo.","display_text":"休息を取らずに働き続けると、体調を崩しかねませんよ。","phonetic_breakdown":["きゅうそくを","とらずに","はたらきつづけると","たいちょうを","くずしかねませんよ"]}'::jsonb, '{"expected_transcript":"休息を取らずに働き続けると、体調を崩しかねませんよ。"}'::jsonb, NULL, NULL, '体調を崩す (jatuh sakit/kondisi fisik menurun) → 崩しかねない.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('409f3888-21e3-4581-a7b1-16a8daaab37b', '0b40c1f2-d0e7-491e-9488-9a5dce2dd8b2', 'd1000019-0000-0000-0000-000000000026', 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 軽率な行動は、チームの士気を___しかねない。', '{"options":["低下","達成","歓迎","祝賀"],"translation":"Tindakan yang gegabah bisa saja menurunkan semangat juang tim.","sentence_template":"軽率な行動は、チームの士気を[blank]しかねない。"}'::jsonb, '{"selected":"低下"}'::jsonb, NULL, NULL, '士気が低下する (semangat/moral tim menurun) adalah kolokasi penting dunia kerja.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0de31bb0-577d-4951-9687-23814098df05', '0b40c1f2-d0e7-491e-9488-9a5dce2dd8b2', 'd1000019-0000-0000-0000-000000000026', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kelelahan yang menumpuk bisa saja menyebabkan kesalahan kerja yang tidak terduga."', '{"romaji":"Hirou ga chikuseki suru to, omowanu sagyou misu ni tsunagarikanemasen.","display_text":"疲労が蓄積すると、思わぬ作業ミスにつながりかねません。","phonetic_breakdown":["ひろうが","ちくせきすると","おもわぬさぎょうみすに","つながりかねません"]}'::jsonb, '{"expected_transcript":"疲労が蓄積すると、思わぬ作業ミスにつながりかねません。"}'::jsonb, NULL, NULL, 'つながりかねません berarti bisa saja berujung pada akibat buruk.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6ebab1b9-3183-475f-9e92-ba3948128159', '0df8aeb7-cccc-4507-aa30-24aa6105a2f8', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 激しい___にもかかわらず、多くの来場者が会場に集まった。', '{"options":["悪天候","新製品","相談室","奨学金"],"translation":"Meskipun cuaca buruk sekali, banyak pengunjung berkumpul di lokasi acara.","sentence_template":"激しい[blank]にもかかわらず、多くの来場者が会場に集まった。"}'::jsonb, '{"selected":"悪天候"}'::jsonb, NULL, NULL, '悪天候 (akutenkou) berarti cuaca buruk dan sangat sering muncul bersama ～にもかかわらず.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('57355bb5-c09c-444f-80ab-42747d9c25f4', '0df8aeb7-cccc-4507-aa30-24aa6105a2f8', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat evaluasi berikut: 十分な___を行ったにもかかわらず、本番でトラブルが発生した。', '{"options":["検証","撤退","欠席","妥協"],"translation":"Meskipun telah dilakukan verifikasi yang memadai, gangguan tetap terjadi saat pelaksanaan utama.","sentence_template":"十分な[blank]を行ったにもかかわらず、本番でトラブルが発生した。"}'::jsonb, '{"selected":"検証"}'::jsonb, NULL, NULL, '検証 (kenshou) berarti verifikasi atau pengujian menyeluruh.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5eba3e3b-43fd-4b02-87cb-cff3dc1275ac', '0df8aeb7-cccc-4507-aa30-24aa6105a2f8', NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: 高い___を投じたにもかかわらず、期待したほどの成果は出なかった。', '{"options":["費用","挨拶","世代","気候"],"translation":"Meskipun telah menanamkan biaya besar, hasil yang diharapkan belum tercapai.","sentence_template":"高い[blank]を投じたにもかかわらず、期待したほどの成果は出なかった。"}'::jsonb, '{"selected":"費用"}'::jsonb, NULL, NULL, '費用を投じる berarti mengalokasikan atau mengeluarkan biaya.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b541966a-b013-40f9-a4c3-11e3beb1609c', '0df8aeb7-cccc-4507-aa30-24aa6105a2f8', NULL, 'listening', 'listening_choice', 'Dengarkan sambutan pembukaan berikut. Apa yang diapresiasi oleh pembicara?', '{"options":[{"id":"opt_1","text":"Kehadiran para peserta meski di tengah kesibukan"},{"id":"opt_2","text":"Kecepatan peserta menyelesaikan tes tertulis"},{"id":"opt_3","text":"Sumbangan dana dari para sponsor acara"},{"id":"opt_4","text":"Ketepatan waktu kedatangan kereta ekspres"}],"audio_text":"お忙しい中にもかかわらず、本日の説明会にご参加いただき誠にありがとうございます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'お忙しい中にもかかわらず adalah ungkapan pembuka bisnis yang sangat sopan (''meskipun di tengah kesibukan Anda'').', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('24d48963-23ca-491d-8566-c87498962c44', '0df8aeb7-cccc-4507-aa30-24aa6105a2f8', NULL, 'listening', 'listening_choice', 'Dengarkan laporan penjualan berikut. Fakta kontras apa yang dilaporkan?', '{"options":[{"id":"opt_1","text":"Pesanan menurun drastis karena kualitas kurang baik"},{"id":"opt_2","text":"Pesanan membanjir berkat kualitasnya yang unggul meski harganya lebih mahal"},{"id":"opt_3","text":"Harga produk diturunkan agar bisa bersaing dengan kompetitor"},{"id":"opt_4","text":"Pelanggan membatalkan pesanan karena pengiriman terlambat"}],"audio_text":"価格が他社より高いにもかかわらず、品質の良さから注文が殺到している。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '注文が殺到する (pesanan membanjir) berkontras dengan 価格が高い (harga mahal).', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ddb16470-090f-4de5-bb9c-b3d190c0947c', '0df8aeb7-cccc-4507-aa30-24aa6105a2f8', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun hujan deras, seluruh peserta hadir tepat waktu."', '{"romaji":"Hageshii ame ni mo kakawarazu, zenin ga jikandoori ni touchaku shimashita.","display_text":"激しい雨にもかかわらず、全員が時間通りに到着しました。","phonetic_breakdown":["はげしい","あめにも","かかわらず","ぜんいんが","じかんどおりに","とうちゃくしました"]}'::jsonb, '{"expected_transcript":"激しい雨にもかかわらず、全員が時間通りに到着しました。"}'::jsonb, NULL, NULL, '時間通りに (tepat waktu) dan 到着する (tiba) adalah pasangan umum dalam laporan kegiatan.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ca3d6685-a2b7-43e4-8972-66666ab3b578', '0df8aeb7-cccc-4507-aa30-24aa6105a2f8', 'd1000019-0000-0000-0000-000000000023', 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 懸命な___にもかかわらず、交渉は合意に至らなかった。', '{"options":["努力","休暇","風景","趣味"],"translation":"Meskipun telah dilakukan upaya sekuat tenaga, negosiasi tetap tidak mencapai kesepakatan.","sentence_template":"懸命な[blank]にもかかわらず、交渉は合意に至らなかった。"}'::jsonb, '{"selected":"努力"}'::jsonb, NULL, NULL, '懸命な努力 (upaya sekuat tenaga) adalah kolokasi alami dengan にもかかわらず.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('87bcfa20-40e9-4c47-ae7f-065a07e90423', '0df8aeb7-cccc-4507-aa30-24aa6105a2f8', 'd1000019-0000-0000-0000-000000000023', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun cuacanya dingin menusuk, antrean di depan toko sudah panjang sejak pagi."', '{"romaji":"Kibishii samusa ni mo kakawarazu, asa kara mise no mae ni wa nagai retsu ga dekite imasu.","display_text":"厳しい寒さにもかかわらず、朝から店の前には長い列ができています。","phonetic_breakdown":["きびしい","さむさに","もかかわらず","あさからみせのまえには","ながいれつが","できています"]}'::jsonb, '{"expected_transcript":"厳しい寒さにもかかわらず、朝から店の前には長い列ができています。"}'::jsonb, NULL, NULL, '厳しい寒さ (dingin yang menusuk) + にもかかわらず sangat alami untuk laporan berita.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fa8674ac-67e6-4dea-949c-fc93bc4f65cf', '19e88500-9efc-43f2-9830-e01ccce833fc', 'd1000019-0000-0000-0000-000000000026', 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 衛生管理が不十分だと、食中毒を___かねない。', '{"options":["引き起こし","引き起こす","引き起こした","引き起こして"],"translation":"Jika manajemen kebersihan kurang memadai, hal itu bisa saja menyebabkan keracunan makanan.","sentence_template":"衛生管理が不十分だと、食中毒を[blank]かねない。"}'::jsonb, '{"selected":"引き起こし"}'::jsonb, NULL, NULL, '引き起こす (Godan) → akar ます adalah 引き起こし → 引き起こしかねない.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('31eab5dc-21b3-490e-a4fd-073aa6054e45', '19e88500-9efc-43f2-9830-e01ccce833fc', 'd1000019-0000-0000-0000-000000000026', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 過密なスケジュールを強行すれば、社員の離職率が___。', '{"options":["上昇しかねない","上昇するにあたって","上昇するに限らず","上昇した上で"],"translation":"Jika memaksakan jadwal yang terlalu padat, tingkat pengunduran diri karyawan bisa saja meningkat.","sentence_template":"過密なスケジュールを強行すれば、社員の離職率が[blank]。"}'::jsonb, '{"selected":"上昇しかねない"}'::jsonb, NULL, NULL, '離職率 (tingkat turnover/resign karyawan) + 上昇しかねない.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('40273901-fd0f-4429-8bbd-94ada5a95f1f', '19e88500-9efc-43f2-9830-e01ccce833fc', 'd1000019-0000-0000-0000-000000000026', 'listening', 'listening_choice', 'Dengarkan peringatan berikut. Apa dampak buruk yang dikhawatirkan?', '{"options":[{"id":"opt_1","text":"Bisa saja meninggalkan beban serius bagi generasi mendatang"},{"id":"opt_2","text":"Sumber daya alam akan bertambah dua kali lipat"},{"id":"opt_3","text":"Biaya energi akan menjadi gratis dalam lima tahun"},{"id":"opt_4","text":"Generasi mendatang tidak perlu lagi bekerja"}],"audio_text":"このまま資源の浪費を続ければ、将来の世代に深刻な負担を残しかねない。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '資源の浪費 (pemborosan sumber daya) → 深刻な負担を残しかねない.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d94072e9-c98a-4578-830f-554641ce71ca', '19e88500-9efc-43f2-9830-e01ccce833fc', 'd1000019-0000-0000-0000-000000000026', 'listening', 'listening_choice', 'Dengarkan diskusi rapat berikut. Mengapa mereka berhati-hati merilis fitur baru?', '{"options":[{"id":"opt_1","text":"Karena jumlah pengguna baru akan langsung membludak"},{"id":"opt_2","text":"Karena bisa saja menyebabkan pengguna meninggalkan layanan"},{"id":"opt_3","text":"Karena biaya server akan turun terlalu rendah"},{"id":"opt_4","text":"Karena tim pemasaran belum menyiapkan logo baru"}],"audio_text":"十分なテストをせずに公開すると、利用者の離脱につながりかねないからです。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '利用者の離脱 (pengguna pergi/churn) + つながりかねない.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cf66b6b8-aa7b-4b1d-a92a-f48a49c3f9ff', '19e88500-9efc-43f2-9830-e01ccce833fc', 'd1000019-0000-0000-0000-000000000026', 'writing', 'sentence_builder', 'Susun kalimat: "Kesalahan penerjemahan dalam kontrak bisa saja memicu sengketa hukum."', '{"romaji":"Keiyakusho no goyaku wa, houteki toraburu ni hatten shikanenai.","tokens":["法的トラブルに","誤訳は、","発展する","つつある。","契約書の","発展","しかねない。"],"target_translation":"Kesalahan penerjemahan dalam kontrak bisa saja memicu sengketa hukum."}'::jsonb, '["契約書の","誤訳は、","法的トラブルに","発展","しかねない。"]'::jsonb, NULL, NULL, '誤訳 (kesalahan terjemahan) dan 法的トラブル (masalah hukum).', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('13bf704e-66c3-4b1b-bb03-57f324252599', '19e88500-9efc-43f2-9830-e01ccce833fc', 'd1000019-0000-0000-0000-000000000026', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Ketidakpastian informasi bisa saja menimbulkan kecemasan di kalangan karyawan."', '{"romaji":"Jouhou kyouyuu no okure wa, shanai ni fuyouna fuan o hirogekanemasen.","display_text":"情報共有の遅れは、社内に不要な不安を広げかねません。","phonetic_breakdown":["じょうほうきょうゆうの","おくれは","しゃないに","ふようなふあんを","ひろげかねません"]}'::jsonb, '{"expected_transcript":"情報共有の遅れは、社内に不要な不安を広げかねません。"}'::jsonb, NULL, NULL, '広げる (Ichidan, menyebarkan) → 広げかねない.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('56c46b94-f5a3-42fa-9b3f-3601d550043f', '19e88500-9efc-43f2-9830-e01ccce833fc', 'd1000019-0000-0000-0000-000000000026', 'listening', 'listening_choice', 'Dengarkan komentar pakar lingkungan. Apa dampak jangka panjang yang dikhawatirkan?', '{"options":[{"id":"opt_1","text":"Kualitas air sungai akan menjadi lebih jernih"},{"id":"opt_2","text":"Industri perikanan lokal akan berkembang pesat"},{"id":"opt_3","text":"Ekosistem setempat bisa saja rusak tak terpulihkan jika makin banyak pabrik melanggar standar limbah"},{"id":"opt_4","text":"Pemerintah akan menutup seluruh sungai di kota"}],"audio_text":"排水基準を守らない工場が増えれば、地域の生態系が取り返しのつかないほど破壊されかねない。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '破壊されかねない memperingatkan ancaman kerusakan permanen ekosistem.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2505af93-dbfc-43a6-aa44-e1cbd6167bb4', '19e88500-9efc-43f2-9830-e01ccce833fc', 'd1000019-0000-0000-0000-000000000026', 'writing', 'sentence_builder', 'Susun kalimat: "Jika terlalu percaya diri, kita bisa saja melewatkan celah kesalahan kecil."', '{"romaji":"Kajin shi sugiru to, chiisana misu o minogashikanenai.","tokens":["しすぎると、","見逃し","ない。","に限らず、","過信","小さなミスを","かね","見逃した"],"target_translation":"Jika terlalu percaya diri, kita bisa saja melewatkan celah kesalahan kecil."}'::jsonb, '["過信","しすぎると、","小さなミスを","見逃し","かね","ない。"]'::jsonb, NULL, NULL, '見逃しかねない (bisa saja terlewat/tidak terlihat) adalah peringatan sikap kerja teliti.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5a97265c-a743-4a1a-ac64-18b03a586f79', '1a2e9062-6fda-4fb6-809c-be73e78ad5ea', 'd1000019-0000-0000-0000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat: "Seiring melemahnya yen, biaya barang impor menjadi naik."', '{"romaji":"Enyasu no shinkou ni tomonatte, yunyuuhin no kakaku ga agatta.","tokens":["進行した","円安の","進行","輸入品の","にあたって、","に伴って、","価格が","上がった。"],"target_translation":"Seiring melemahnya yen, biaya barang impor menjadi naik."}'::jsonb, '["円安の","進行","に伴って、","輸入品の","価格が","上がった。"]'::jsonb, NULL, NULL, '円安 (pelemahan yen) dan 輸入品 (barang impor) adalah kosakata kunci berita ekonomi Jepang.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d7464548-f1ee-4f4a-b80a-eaaa3003bb7d', '1a2e9062-6fda-4fb6-809c-be73e78ad5ea', 'd1000019-0000-0000-0000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat: "Seiring perubahan gaya hidup, kebutuhan makanan siap saji meningkat."', '{"romaji":"Seikatsu youshiki no henka ni tomonai, reitou shokuhin no juyou ga nobite iru.","tokens":["変化して","伸びている。","変化","に伴い、","冷凍食品の","にもかかわらず、","生活様式の","需要が"],"target_translation":"Seiring perubahan gaya hidup, kebutuhan makanan siap saji meningkat."}'::jsonb, '["生活様式の","変化","に伴い、","冷凍食品の","需要が","伸びている。"]'::jsonb, NULL, NULL, '需要が伸びる berarti permintaan pasar tumbuh atau meningkat.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0c65ab4d-eac8-4200-a207-b1b746f8280b', '1a2e9062-6fda-4fb6-809c-be73e78ad5ea', 'd1000019-0000-0000-0000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat: "Risiko yang menyertai investasi harus dijelaskan terlebih dahulu."', '{"romaji":"Toushi ni tomonau risuku wa, jizen ni setsumei suru beki da.","tokens":["べきだ。","投資","事前に","にあたり","に伴う","説明する","に伴って","リスクは、"],"target_translation":"Risiko yang menyertai investasi harus dijelaskan terlebih dahulu."}'::jsonb, '["投資","に伴う","リスクは、","事前に","説明する","べきだ。"]'::jsonb, NULL, NULL, '投資に伴うリスク berarti ''risiko yang menyertai investasi''.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2c8eba52-9926-4641-97c0-dc2af350ed3f', '1a2e9062-6fda-4fb6-809c-be73e78ad5ea', 'd1000019-0000-0000-0000-000000000019', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring meluasnya belanja daring, beban kerja kurir pengiriman bertambah."', '{"romaji":"Netto tsuuhan no fukyuu ni tomonatte, haitatsuin no futan ga fuete imasu.","display_text":"ネット通販の普及に伴って、配達員の負担が増えています。","phonetic_breakdown":["ねっと","つうはんの","ふきゅうに","ともなって","はいたついんの","ふたんが","ふえています"]}'::jsonb, '{"expected_transcript":"ネット通販の普及に伴って、配達員の負担が増えています。"}'::jsonb, NULL, NULL, '負担が増える (beban bertambah) adalah kolokasi alami yang sering muncul di berita sosial.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('af7db17a-66d7-469b-862e-7c1e305f42ef', '1a2e9062-6fda-4fb6-809c-be73e78ad5ea', 'd1000019-0000-0000-0000-000000000019', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring naiknya suhu bumi, cuaca ekstrem makin sering terjadi."', '{"romaji":"Kion no joushou ni tomonai, ijou kishou ga hinpan ni hassei shite imasu.","display_text":"気温の上昇に伴い、異常気象が頻繁に発生しています。","phonetic_breakdown":["きおんの","じょうしょうに","ともない","いじょうきしょうが","ひんぱんに","はっせいしています"]}'::jsonb, '{"expected_transcript":"気温の上昇に伴い、異常気象が頻繁に発生しています。"}'::jsonb, NULL, NULL, '異常気象 (cuaca ekstrem) dan 頻繁に (dengan sering) adalah kosakata penting bacaan N2.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c294bb4d-dedd-4bec-9d0f-945b06b62c0f', '1a2e9062-6fda-4fb6-809c-be73e78ad5ea', 'd1000019-0000-0000-0000-000000000019', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring bertambahnya jumlah mahasiswa asing, layanan konseling diperkuat."', '{"romaji":"Ryuugakusei no zouka ni tomonatte, soudan madoguchi no taisei ga kyouka saremashita.","display_text":"留学生の増加に伴って、相談窓口の体制が強化されました。","phonetic_breakdown":["りゅうがくせいの","ぞうかに","ともなって","そうだんまどぐちの","たいせいが","きょうかされました"]}'::jsonb, '{"expected_transcript":"留学生の増加に伴って、相談窓口の体制が強化されました。"}'::jsonb, NULL, NULL, '相談窓口 (loket/layanan konsultasi) dan 体制が強化される (sistem diperkuat) sangat relevan dengan kehidupan kampus.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fe19f24b-0dfd-435b-8457-45632707f0ca', '1a2e9062-6fda-4fb6-809c-be73e78ad5ea', 'd1000019-0000-0000-0000-000000000019', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 気温が低下する___、暖房器具の売れ行きが伸びてきた。', '{"options":["に伴って","にもかかわらず","わけにはいかず","ざるを得ず"],"translation":"Seiring dengan turunnya suhu udara, penjualan alat pemanas mulai meningkat.","sentence_template":"気温が低下する[blank]、暖房器具の売れ行きが伸びてきた。"}'::jsonb, '{"selected":"に伴って"}'::jsonb, NULL, NULL, '気温が低下する (suhu menurun) + に伴って menyatakan perubahan paralel pada penjualan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e8822921-0425-496d-abe8-d29692a8ccf0', '1a2e9062-6fda-4fb6-809c-be73e78ad5ea', 'd1000019-0000-0000-0000-000000000019', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring dengan globalisasi, permintaan terhadap tenaga kerja multibahasa meningkat."', '{"romaji":"Guroobaruka ni tomonai, tagengo jinzai no juyou ga takamatte imasu.","display_text":"グローバル化に伴い、多言語人材の需要が高まっています。","phonetic_breakdown":["ぐろーばるかに","ともない","たげんごじんざいの","じゅようが","たかまっています"]}'::jsonb, '{"expected_transcript":"グローバル化に伴い、多言語人材の需要が高まっています。"}'::jsonb, NULL, NULL, '多言語人材 (SDM multibahasa) adalah istilah umum dalam rekrutmen perusahaan Jepang.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a4c253bc-2c42-4b49-99e0-669a5af5efcd', '2550372c-46b5-4512-83ed-30c5ae84a224', 'd1000019-0000-0000-0000-000000000021', 'reading', 'fill_blank', 'Lengkapi kalimat etika kerja berikut: 顧客から預かった機密情報を外部に漏らす___。', '{"options":["わけにはいかない","に伴っている","に限らない","つつある"],"translation":"Tidak mungkin boleh membocorkan informasi rahasia yang dipercayakan klien ke pihak luar.","sentence_template":"顧客から預かった機密情報を外部に漏らす[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, NULL, NULL, 'V-dict + わけにはいかない menyatakan larangan kuat berdasarkan etika atau tanggung jawab.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8672518b-ca7f-483c-8845-f8694894d84d', '2550372c-46b5-4512-83ed-30c5ae84a224', 'd1000019-0000-0000-0000-000000000021', 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk kewajiban moral: 責任者として、この不具合を解決しない___。', '{"options":["わけにはいかない","にあたらない","かねない","に伴わない"],"translation":"Sebagai penanggung jawab, mau tidak mau saya harus menyelesaikan gangguan ini.","sentence_template":"責任者として、この不具合を解決しない[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, NULL, NULL, 'V-nai + わけにはいかない berarti ''tidak bisa tidak melakukan / mau tidak mau harus melakukan''.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f251a25b-c9af-4015-9387-682b6fdb31ea', '2550372c-46b5-4512-83ed-30c5ae84a224', 'd1000019-0000-0000-0000-000000000021', 'listening', 'listening_choice', 'Dengarkan percakapan dua rekan kerja. Mengapa pembicara tidak bisa pulang cepat hari ini?', '{"options":[{"id":"opt_1","text":"Karena kereta terakhir sudah berangkat"},{"id":"opt_2","text":"Karena ada presentasi penting besok pagi sehingga harus menyelesaikan materi dulu"},{"id":"opt_3","text":"Karena sedang menunggu paket pribadi di kantor"},{"id":"opt_4","text":"Karena atasan melarang semua karyawan pulang sebelum tengah malam"}],"audio_text":"明日の朝一番で重要なプレゼンがあるので、資料が完成するまでは帰るわけにはいかないんだ。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '帰るわけにはいかない menyatakan tidak bisa pulang karena tanggung jawab presentasi besok pagi.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5c7e6f14-b602-4d0e-bd09-e095716d55f4', '2550372c-46b5-4512-83ed-30c5ae84a224', 'd1000019-0000-0000-0000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat: "Karena sudah berjanji kepada klien, kami tidak mungkin menunda pengiriman."', '{"romaji":"Kokyaku to yakusoku shita ijou, nouki o okuraseru wake ni wa ikanai.","tokens":["約束した以上、","遅らせる","いかない。","かねない。","顧客と","納期を","わけには","遅らせた"],"target_translation":"Karena sudah berjanji kepada klien, kami tidak mungkin menunda pengiriman."}'::jsonb, '["顧客と","約束した以上、","納期を","遅らせる","わけには","いかない。"]'::jsonb, NULL, NULL, '納期を遅らせるわけにはいかない berarti tidak mungkin bisa menunda tenggat pengiriman.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a792f5d0-d299-431f-8e43-62ae696f2141', '2550372c-46b5-4512-83ed-30c5ae84a224', 'd1000019-0000-0000-0000-000000000021', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun lelah, saya tidak bisa menyerah di tengah jalan."', '{"romaji":"Donna ni tsukarete itemo, tochuu de akirameru wake ni wa ikimasen.","display_text":"どんなに疲れていても、途中で諦めるわけにはいきません。","phonetic_breakdown":["どんなに","つかれていても","とちゅうで","あきらめる","わけにはいきません"]}'::jsonb, '{"expected_transcript":"どんなに疲れていても、途中で諦めるわけにはいきません。"}'::jsonb, NULL, NULL, '途中で諦めるわけにはいきません mencerminkan tekad dan tanggung jawab kuat.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1a48b8d5-38b7-40a5-b50a-06b40e2f01ae', '2550372c-46b5-4512-83ed-30c5ae84a224', 'd1000019-0000-0000-0000-000000000021', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: せっかく上司が誘ってくれたのだから、参加しない___。', '{"options":["わけにはいかない","つつある","にもかかわらず","にあたって"],"translation":"Karena atasan sudah susah payah mengajak, mau tidak mau saya harus ikut hadir.","sentence_template":"せっかく上司が誘ってくれたのだから、参加しない[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, NULL, NULL, '参加しないわけにはいかない (V-nai + わけにはいかない) menyatakan tidak enak jika tidak hadir, sehingga harus ikut.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bbf83c33-49be-4583-a246-379aab471eee', '2550372c-46b5-4512-83ed-30c5ae84a224', 'd1000019-0000-0000-0000-000000000021', 'listening', 'listening_choice', 'Dengarkan pernyataan kepala tim. Mengapa mereka tetap melanjutkan proyek tersebut?', '{"options":[{"id":"opt_1","text":"Karena belum ada biaya yang dikeluarkan sama sekali"},{"id":"opt_2","text":"Karena seluruh anggota tim ingin mengambil cuti panjang"},{"id":"opt_3","text":"Karena sudah menginvestasikan banyak dana dan waktu sehingga tidak mungkin membatalkan rencana"},{"id":"opt_4","text":"Karena pemerintah memerintahkan penutupan proyek"}],"audio_text":"ここまで多額の予算と時間を投じてきた以上、今さら計画を白紙に戻すわけにはいかない。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '白紙に戻すわけにはいかない berarti tidak mungkin membatalkan rencana kembali dari nol.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d6a9a4ea-e1a8-4a1c-8c3a-f311691ad2f6', '2550372c-46b5-4512-83ed-30c5ae84a224', 'd1000019-0000-0000-0000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat: "Karena besok ada ujian penting, malam ini saya tidak boleh begadang."', '{"romaji":"Ashita juuyou na shiken ga aru node, konya wa yofukashi suru wake ni wa ikanai.","tokens":["試験があるので、","夜更かしする","いかない。","ざるを得ない。","明日重要な","今夜は","わけには","夜更かしした"],"target_translation":"Karena besok ada ujian penting, malam ini saya tidak boleh begadang."}'::jsonb, '["明日重要な","試験があるので、","今夜は","夜更かしする","わけには","いかない。"]'::jsonb, NULL, NULL, '夜更かしするわけにはいかない menyatakan tidak bisa begadang demi ujian besok.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4f88e065-e7bb-4573-84a2-8e3b2dc11d10', '27558c4b-8e0b-47b9-b326-9137ab8e2d50', 'd1000019-0000-0000-0000-000000000018', 'reading', 'fill_blank', 'Simulasi N2 (1/10): Lengkapi kalimat formal berikut: 新規海外拠点の開設___、現地法規の専門チームを編成した。', '{"options":["にあたり","に伴って","に限らず","かねず"],"translation":"Menjelang pembukaan basis luar negeri baru, kami membentuk tim khusus hukum setempat.","sentence_template":"新規海外拠点の開設[blank]、現地法規の専門チームを編成した。"}'::jsonb, '{"selected":"にあたり"}'::jsonb, NULL, NULL, '～にあたり digunakan pada pengumuman atau persiapan resmi menjelang peristiwa penting.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('625382ab-a3e7-4017-bf59-71ffef47ca03', '27558c4b-8e0b-47b9-b326-9137ab8e2d50', 'd1000019-0000-0000-0000-000000000019', 'listening', 'listening_choice', 'Simulasi N2 (2/10): Dengarkan laporan ekonomi berikut. Perubahan apa yang menyertai tren belanja daring?', '{"options":[{"id":"opt_1","text":"Jumlah kurir melimpah dan biaya pengiriman turun drastis"},{"id":"opt_2","text":"Seiring meluasnya belanja daring, kekurangan kurir dan biaya kirim ulang makin parah di industri logistik"},{"id":"opt_3","text":"Belanja daring dilarang di wilayah perkotaan"},{"id":"opt_4","text":"Perusahaan logistik menghentikan layanan pengiriman rumah"}],"audio_text":"ネット通販の急拡大に伴い、物流業界では配達員不足と再配達コストの増加が深刻化している。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '急拡大に伴い menghubungkan pertumbuhan e-commerce dengan meningkatnya beban logistik.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9e877602-1af9-472f-9355-2dbb958a9a44', '27558c4b-8e0b-47b9-b326-9137ab8e2d50', 'd1000019-0000-0000-0000-000000000020', 'reading', 'fill_blank', 'Simulasi N2 (3/10): Pilih pola yang tepat: この奨学金制度は理系学生___、文系分野の研究者も対象としている。', '{"options":["に限らず","にあたって","にもかかわらず","の上で"],"translation":"Program beasiswa ini tidak terbatas pada mahasiswa sains, tetapi juga mencakup peneliti bidang humaniora.","sentence_template":"この奨学金制度は理系学生[blank]、文系分野の研究者も対象としている。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, NULL, NULL, '～に限らず memperluas cakupan subjek dari A ke B secara inklusif.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3aa432da-8af5-4e4e-917f-47c404fa7096', '27558c4b-8e0b-47b9-b326-9137ab8e2d50', 'd1000019-0000-0000-0000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat: "Karena sudah diberi kepercayaan sebagai pemimpin proyek, saya tidak mungkin mundur di tengah jalan."', '{"romaji":"Riidaa o makasareta ijou, tochuu de nagedasu wake ni wa ikanai.","tokens":["任された以上、","投げ出す","いかない。","かねない。","リーダーを","途中で","わけには","投げ出した"],"target_translation":"Karena sudah diberi kepercayaan sebagai pemimpin proyek, saya tidak mungkin mundur di tengah jalan."}'::jsonb, '["リーダーを","任された以上、","途中で","投げ出す","わけには","いかない。"]'::jsonb, NULL, NULL, 'V-dict + わけにはいかない menyatakan tidak mungkin melakukan sesuatu karena tanggung jawab.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('51186896-0510-41dc-b61a-7c5f920dfb9c', '27558c4b-8e0b-47b9-b326-9137ab8e2d50', 'd1000019-0000-0000-0000-000000000022', 'reading', 'fill_blank', 'Simulasi N2 (5/10): Pilih bentuk konjugasi yang benar: 設備の重大な故障が見つかり、工場の稼働を一時停止___。', '{"options":["せざるを得なかった","しざるを得なかった","すざるを得なかった","するざるを得なかった"],"translation":"Ditemukan kerusakan peralatan serius sehingga kami terpaksa menghentikan operasional pabrik sementara.","sentence_template":"設備の重大な故障が見つかり、工場の稼働を一時停止[blank]。"}'::jsonb, '{"selected":"せざるを得なかった"}'::jsonb, NULL, NULL, 'Kata kerja する selalu berubah menjadi せざるを得ない / せざるを得なかった.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('78ff90c0-b0d9-41bc-8109-1dfc89cd8940', '27558c4b-8e0b-47b9-b326-9137ab8e2d50', 'd1000019-0000-0000-0000-000000000023', 'listening', 'listening_choice', 'Simulasi N2 (6/10): Dengarkan berita berikut. Apa hal kontras yang dilaporkan?', '{"options":[{"id":"opt_1","text":"Pangsa pasar perusahaan terus menyusut akibat perang harga"},{"id":"opt_2","text":"Perusahaan menurunkan kualitas demi memangkas biaya"},{"id":"opt_3","text":"Meskipun persaingan harga ketat berlanjut, pangsa pasar produk berkualitas tinggi perusahaan itu terus meluas"},{"id":"opt_4","text":"Perusahaan menghentikan penjualan di pasar domestik"}],"audio_text":"厳しい価格競争が続いているにもかかわらず、高品質を貫く同社の製品シェアは拡大し続けている。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '～にもかかわらず menyoroti kontras kuat antara persaingan ketat dan pertumbuhan pangsa pasar.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2552f937-5630-4240-b343-c8a6f8dde42b', '27558c4b-8e0b-47b9-b326-9137ab8e2d50', 'd1000019-0000-0000-0000-000000000024', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah mempertimbangkan masukan seluruh departemen, kami akan menetapkan rencana final."', '{"romaji":"Kaku busho no iken o fumaeta ue de, saishuu keikaku o kettei itashimasu.","display_text":"各部署の意見を踏まえた上で、最終計画を決定いたします。","phonetic_breakdown":["かくぶしょの","いけんをふまえたうえで","さいしゅうけいかくを","けっていいたします"]}'::jsonb, '{"expected_transcript":"各部署の意見を踏まえた上で、最終計画を決定いたします。"}'::jsonb, NULL, NULL, 'V-ta + 上で menyatakan langkah A diselesaikan lebih dulu sebelum keputusan B.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dff84a82-d1d1-4326-8803-5502bc74dd83', '27558c4b-8e0b-47b9-b326-9137ab8e2d50', 'd1000019-0000-0000-0000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat: "Kesadaran perusahaan terhadap keberlanjutan lingkungan sedang terus meningkat."', '{"romaji":"Kankyou e no hairyo ni taisuru kigyou no ishiki ga takamaritsutsu aru.","tokens":["企業の意識が","高まり","ある。","ざるを得ない。","環境配慮に対する","年々","つつ","高まった"],"target_translation":"Kesadaran perusahaan terhadap keberlanjutan lingkungan sedang terus meningkat."}'::jsonb, '["環境配慮に対する","企業の意識が","年々","高まり","つつ","ある。"]'::jsonb, NULL, NULL, 'V-masu stem + つつある menggambarkan tren perubahan yang sedang berlangsung.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('93fff7bf-a3bc-49c7-bd70-39489d4a3f5c', '27558c4b-8e0b-47b9-b326-9137ab8e2d50', 'd1000019-0000-0000-0000-000000000026', 'listening', 'listening_choice', 'Simulasi N2 (9/10): Dengarkan peringatan manajer kualitas. Apa risiko yang ia khawatirkan?', '{"options":[{"id":"opt_1","text":"Biaya produksi akan menjadi nol tanpa pemeriksaan"},{"id":"opt_2","text":"Pelanggan akan lebih cepat menerima produk sempurna"},{"id":"opt_3","text":"Pabrik akan menerima penghargaan kualitas internasional"},{"id":"opt_4","text":"Jika tahap inspeksi sebelum kirim dilewati, produk cacat bisa beredar dan memicu penarikan massal"}],"audio_text":"出荷前の検査工程を省略すれば、不良品が市場に流出して大規模なリコールに発展しかねません。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '発展しかねません memperingatkan eskalasi risiko serius (recall massal).', 9, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dbd24bd0-69e8-4a32-9857-04727536c512', '27558c4b-8e0b-47b9-b326-9137ab8e2d50', 'd1000019-0000-0000-0000-000000000027', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Apakah Bapak Direktur sudah berkenan memeriksa draf kontrak yang kami kirimkan kemarin?"', '{"romaji":"Sakujitsu ookuri shita keiyakushoan wa, sude ni goran ni narimashita deshou ka.","display_text":"昨日お送りした契約書案は、すでにご覧になりましたでしょうか。","phonetic_breakdown":["さくじつ","おおくりしたけいやくしょあんは","すでに","ごらんになりましたでしょうか"]}'::jsonb, '{"expected_transcript":"昨日お送りした契約書案は、すでにご覧になりましたでしょうか。"}'::jsonb, NULL, NULL, 'ご覧になりましたでしょうか menggunakan sonkeigo baku tanpa kesalahan keigo ganda.', 10, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('96946546-4cb8-4bc3-882c-4ae0ccbbca97', '281bd232-b464-44a3-b38f-e26977a5bdfc', 'd1000019-0000-0000-0000-000000000021', 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 会社の看板を背負っている以上、いい加減な仕事をする___。', '{"options":["わけにはいかない","にあたって","に伴って","に限らず"],"translation":"Selama membawa nama baik perusahaan, saya tidak boleh bekerja secara asal-asalan.","sentence_template":"会社の看板を背負っている以上、いい加減な仕事をする[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, NULL, NULL, 'いい加減な仕事 (pekerjaan asal-asalan) + わけにはいかない menyatakan standar etika kerja.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c492287d-8c21-4f9a-b1c5-50b63a2bd27a', '281bd232-b464-44a3-b38f-e26977a5bdfc', 'd1000019-0000-0000-0000-000000000021', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: せっかく先輩が丁寧に教えてくれたのだから、感謝___わけにはいかない。', '{"options":["しない","する","した","して"],"translation":"Karena senior sudah bersusah payah mengajari dengan sabar, mau tidak mau saya harus berterima kasih.","sentence_template":"せっかく先輩が丁寧に教えてくれたのだから、感謝[blank]わけにはいかない。"}'::jsonb, '{"selected":"しない"}'::jsonb, NULL, NULL, '感謝しないわけにはいかない (tidak pantas jika tidak berterima kasih).', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f0bfa556-8959-4f3b-a819-83ead298d5b1', '281bd232-b464-44a3-b38f-e26977a5bdfc', 'd1000019-0000-0000-0000-000000000021', 'listening', 'listening_choice', 'Dengarkan percakapan berikut. Mengapa pembicara tetap datang ke rapat meski kurang sehat?', '{"options":[{"id":"opt_1","text":"Karena dialah yang dijadwalkan memimpin rapat hari ini"},{"id":"opt_2","text":"Karena rapat tersebut menyediakan makan siang gratis"},{"id":"opt_3","text":"Karena ruang rapat terletak di sebelah klinik"},{"id":"opt_4","text":"Karena dia lupa membawa laptop pulang kemarin"}],"audio_text":"今日の会議は私が主導する予定なので、少し熱があっても欠席するわけにはいかないんです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '私が主導する予定 (saya yang dijadwalkan memimpin) menjadi alasan tanggung jawabnya.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e9c431dc-51d3-497e-9a11-5dbd60af3b1f', '281bd232-b464-44a3-b38f-e26977a5bdfc', 'd1000019-0000-0000-0000-000000000021', 'listening', 'listening_choice', 'Dengarkan pernyataan berikut. Apa sikap pembicara terhadap informasi tersebut?', '{"options":[{"id":"opt_1","text":"Akan segera menyebarkannya melalui grup obrolan"},{"id":"opt_2","text":"Akan mencetaknya untuk ditempel di papan pengumuman"},{"id":"opt_3","text":"Tidak akan membicarakannya bahkan ke departemen lain sebelum pengumuman resmi"},{"id":"opt_4","text":"Sudah mendiskusikannya dengan semua karyawan kemarin"}],"audio_text":"正式な発表があるまでは、この計画について他部署の人にも話すわけにはいきません。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '他部署の人にも話すわけにはいかない menegaskan kewajiban menjaga kerahasiaan internal.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7b6cf021-88dc-4dc0-8b8a-91ee50790ad2', '281bd232-b464-44a3-b38f-e26977a5bdfc', 'd1000019-0000-0000-0000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat: "Karena batas waktu pengumpulan adalah hari ini, saya tidak bisa menundanya."', '{"romaji":"Teishutsu kigen ga kyou nanode, sakinobashi ni suru wake ni wa ikanai.","tokens":["わけには","先延ばしに","提出期限が","しない","にもかかわらず","する","いかない。","今日なので、"],"target_translation":"Karena batas waktu pengumpulan adalah hari ini, saya tidak bisa menundanya."}'::jsonb, '["提出期限が","今日なので、","先延ばしに","する","わけには","いかない。"]'::jsonb, NULL, NULL, '先延ばしにする berarti menunda-nunda pekerjaan.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d116473a-7602-40ef-9950-f5c3310233eb', '281bd232-b464-44a3-b38f-e26977a5bdfc', 'd1000019-0000-0000-0000-000000000021', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Demi keselamatan pelanggan, kami tidak boleh mengabaikan kelainan sekecil apa pun."', '{"romaji":"Okyakusama no anzen no tame, chiisana ijou mo misugosu wake ni wa ikimasen.","display_text":"お客様の安全のため、小さな異常も見過ごすわけにはいきません。","phonetic_breakdown":["おきゃくさまの","あんぜんのため","ちいさな","いじょうも","みすごす","わけにはいきません"]}'::jsonb, '{"expected_transcript":"お客様の安全のため、小さな異常も見過ごすわけにはいきません。"}'::jsonb, NULL, NULL, '見過ごす (misugosu) berarti melewatkan atau mengabaikan sesuatu yang penting.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('92410986-ca22-4ac0-a341-803de86095bd', '281bd232-b464-44a3-b38f-e26977a5bdfc', 'd1000019-0000-0000-0000-000000000021', 'listening', 'listening_choice', 'Dengarkan ucapan negosiator berikut. Mengapa mereka tidak menerima tawaran harga tersebut?', '{"options":[{"id":"opt_1","text":"Karena stok barang sudah habis terjual"},{"id":"opt_2","text":"Karena harga di bawah modal tidak mungkin diterima meski untuk pelanggan setia"},{"id":"opt_3","text":"Karena pengiriman ke luar kota sedang dihentikan"},{"id":"opt_4","text":"Karena pelanggan membatalkan pesanan secara sepihak"}],"audio_text":"原価を下回る価格では、いくらお得意様であってもお引き受けするわけにはまいりません。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '原価を下回る (di bawah biaya modal) menjadi alasan objektif untuk menolak secara sopan (お引き受けするわけにはまいりません).', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('865a2a12-1e46-45a5-a656-5d4d543e85ef', '281bd232-b464-44a3-b38f-e26977a5bdfc', 'd1000019-0000-0000-0000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat: "Karena besok harus menyetir jauh, malam ini saya tidak boleh minum alkohol."', '{"romaji":"Ashita choukyori unten suru node, konya wa osake o nomu wake ni wa ikanai.","tokens":["運転するので、","お酒を飲む","いかない。","にもかかわらず、","明日長距離","今夜は","わけには","お酒を飲んだ"],"target_translation":"Karena besok harus menyetir jauh, malam ini saya tidak boleh minum alkohol."}'::jsonb, '["明日長距離","運転するので、","今夜は","お酒を飲む","わけには","いかない。"]'::jsonb, NULL, NULL, 'お酒を飲むわけにはいかない menyatakan larangan jelas demi keselamatan berkendara.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0383de7e-7315-4602-a699-fc582ab864a3', '29982aea-31a4-4333-8832-0bf196a32c65', NULL, 'reading', 'fill_blank', 'Pilih bentuk Sonkeigo yang tepat untuk 見る: 部長、先ほどお送りした資料はすでに___になりましたか。', '{"options":["ご覧","拝見","お見","ご見"],"translation":"Pak Kepala Departemen, apakah Bapak sudah melihat materi yang saya kirimkan tadi?","sentence_template":"部長、先ほどお送りした資料はすでに[blank]になりましたか。"}'::jsonb, '{"selected":"ご覧"}'::jsonb, NULL, NULL, 'Sonkeigo khusus dari 見る adalah ご覧になる (sedangkan 拝見する adalah Kenjougo untuk diri sendiri).', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('49607409-f1c6-41b3-893d-1eddc5983669', '29982aea-31a4-4333-8832-0bf196a32c65', NULL, 'reading', 'fill_blank', 'Pilih bentuk Sonkeigo yang tepat untuk 言う: 社長が___とおりに、企画書を修正いたしました。', '{"options":["おっしゃった","申した","伺った","いただいた"],"translation":"Saya telah merevisi proposal sesuai dengan apa yang disampaikan oleh Direktur Utama.","sentence_template":"社長が[blank]とおりに、企画書を修正いたしました。"}'::jsonb, '{"selected":"おっしゃった"}'::jsonb, NULL, NULL, 'Sonkeigo dari 言う adalah おっしゃる (lampau: おっしゃった).', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('03d3bc0a-b92b-41cc-bdf9-45706aee05e3', '29982aea-31a4-4333-8832-0bf196a32c65', NULL, 'reading', 'fill_blank', 'Pilih bentuk Sonkeigo yang tepat untuk いる/行く/来る: ただいま専務は会議室に___。', '{"options":["いらっしゃいます","まいります","おります","いたします"],"translation":"Saat ini Direktur Pelaksana sedang berada di ruang rapat.","sentence_template":"ただいま専務は会議室に[blank]。"}'::jsonb, '{"selected":"いらっしゃいます"}'::jsonb, NULL, NULL, 'いらっしゃる adalah bentuk Sonkeigo untuk いる, 行く, dan 来る.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7f972269-542c-4bd0-8504-1cf297475e9e', '29982aea-31a4-4333-8832-0bf196a32c65', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan resepsionis kantor berikut. Di mana Presiden Direktur berada sekarang?', '{"options":[{"id":"opt_1","text":"Sedang keluar kantor saat ini"},{"id":"opt_2","text":"Sedang makan siang di kantin lantai dua"},{"id":"opt_3","text":"Sedang menerima tamu di ruang resepsionis"},{"id":"opt_4","text":"Sudah pulang ke rumah sejak pagi tadi"}],"audio_text":"申し訳ございません。社長はただいま外出していらっしゃいます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '外出していらっしゃいます menggunakan ～ていらっしゃる untuk meninggikan aksi atasan.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('61699e53-53fe-48de-aa81-2897a5aafc3e', '29982aea-31a4-4333-8832-0bf196a32c65', NULL, 'listening', 'listening_choice', 'Dengarkan kalimat di ruang tamu klien berikut. Apa yang ditawarkan staf?', '{"options":[{"id":"opt_1","text":"Meminta tamu membawa pulang dokumen kontrak"},{"id":"opt_2","text":"Mempersilakan tamu meminum teh yang disediakan"},{"id":"opt_3","text":"Menanyakan jadwal keberangkatan pesawat tamu"},{"id":"opt_4","text":"Meminta tamu menunggu di lobi lantai bawah"}],"audio_text":"よろしければ、こちらのお茶をどうぞ召し上がってください。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '召し上がる (meshiagaru) adalah bentuk Sonkeigo baku untuk 食べる dan 飲む.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f1515d96-4336-4883-8d9d-2b92bc02241d', '29982aea-31a4-4333-8832-0bf196a32c65', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Apakah Bapak sudah memeriksa email yang saya kirim kemarin?"', '{"romaji":"Kinou ookuri shita meeru wa goran ni narimashita deshou ka.","display_text":"昨日お送りしたメールはご覧になりましたでしょうか。","phonetic_breakdown":["きのう","おおくりした","めーるは","ごらんに","なりましたでしょうか"]}'::jsonb, '{"expected_transcript":"昨日お送りしたメールはご覧になりましたでしょうか。"}'::jsonb, NULL, NULL, 'ご覧になりましたでしょうか sangat sopan untuk menanyakan apakah klien/atasan sudah membaca email.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('26bed8e4-cc7d-4832-9d07-20a5a1186965', '29982aea-31a4-4333-8832-0bf196a32c65', 'd1000019-0000-0000-0000-000000000027', 'reading', 'fill_blank', 'Pilih padanan sonkeigo yang tepat untuk 寝る / 休む: 長旅でお疲れでしょうから、今夜はゆっくり___ください。', '{"options":["お休み","ご拝見","お伺い","ご参上"],"translation":"Karena pasti lelah dari perjalanan jauh, malam ini silakan beristirahat dengan tenang.","sentence_template":"長旅でお疲れでしょうから、今夜はゆっくり[blank]ください。"}'::jsonb, '{"selected":"お休み"}'::jsonb, NULL, NULL, 'お休みください adalah sonkeigo baku untuk mempersilakan tamu/atasan beristirahat.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c234dab0-b439-4d49-857a-69b40482d336', '29982aea-31a4-4333-8832-0bf196a32c65', 'd1000019-0000-0000-0000-000000000027', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terima kasih banyak karena Anda selalu memberikan bimbingan yang hangat kepada kami."', '{"romaji":"Higoro yori atatakai goshidou o tamawari, kokoro yori kansha moushiagemasu.","display_text":"日頃より温かいご指導を賜り、心より感謝申し上げます。","phonetic_breakdown":["ひごろより","あたたかい","ごしどうをたまわり","こころより","かんしゃもうしあげます"]}'::jsonb, '{"expected_transcript":"日頃より温かいご指導を賜り、心より感謝申し上げます。"}'::jsonb, NULL, NULL, 'ご指導を賜る (menerima bimbingan dari pihak yang dihormati) adalah ungkapan puncak sopan santun bisnis N2.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('809ad623-8d46-4c9a-8f94-1fbb04b4ee83', '2d710ef5-9a0b-4a0c-a93f-dd11d8b95e4a', 'd1000019-0000-0000-0000-000000000022', 'reading', 'fill_blank', 'Pilih konjugasi yang benar untuk kata kerja する: 悪天候のため、本日の試合は中止___。', '{"options":["せざるを得ない","しざるを得ない","すざるを得ない","するざるを得ない"],"translation":"Karena cuaca buruk, pertandingan hari ini terpaksa dibatalkan.","sentence_template":"悪天候のため、本日の試合は中止[blank]。"}'::jsonb, '{"selected":"せざるを得ない"}'::jsonb, NULL, NULL, 'Pengecualian penting JLPT N2: する berubah menjadi せざるを得ない (bukan しざるを得ない).', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b90e3e1e-4e24-4e45-bbda-c00da87d2220', '2d710ef5-9a0b-4a0c-a93f-dd11d8b95e4a', 'd1000019-0000-0000-0000-000000000022', 'reading', 'fill_blank', 'Lengkapi konjugasi verba berikut: 予算が足りないため、一部の機能を___ざるを得なかった。', '{"options":["削ら","削り","削る","削れ"],"translation":"Karena anggaran tidak mencukupi, kami terpaksa memangkas sebagian fitur.","sentence_template":"予算が足りないため、一部の機能を[blank]ざるを得なかった。"}'::jsonb, '{"selected":"削ら"}'::jsonb, NULL, NULL, 'Bentuk ～ざるを得ない memakai akar bentuk ない (削る → 削らない → 削ら + ざるを得ない).', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6e8b014e-1a21-4a01-83b2-176f5d15b618', '2d710ef5-9a0b-4a0c-a93f-dd11d8b95e4a', 'd1000019-0000-0000-0000-000000000022', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 証拠がこれだけ揃っている以上、事実を___ざるを得ない。', '{"options":["認め","認める","認めた","認めら"],"translation":"Selama bukti sudah selengkap ini, mau tidak mau harus mengakui faktanya.","sentence_template":"証拠がこれだけ揃っている以上、事実を[blank]ざるを得ない。"}'::jsonb, '{"selected":"認め"}'::jsonb, NULL, NULL, 'Verba Ichidan 認める → akar ない adalah 認め → 認めざるを得ない.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a4478820-b308-4f2e-bc27-a6eb5f70724e', '2d710ef5-9a0b-4a0c-a93f-dd11d8b95e4a', 'd1000019-0000-0000-0000-000000000022', 'writing', 'sentence_builder', 'Susun kalimat: "Karena kereta berhenti, saya terpaksa pergi ke kantor naik taksi."', '{"romaji":"Densha ga tomatta node, takushii de shussha sezaru o enakatta.","tokens":["得なかった。","にあたって","止まったので、","電車が","せざるを","出社","しざるを","タクシーで"],"target_translation":"Karena kereta berhenti, saya terpaksa pergi ke kantor naik taksi."}'::jsonb, '["電車が","止まったので、","タクシーで","出社","せざるを","得なかった。"]'::jsonb, NULL, NULL, '出社する (pergi ke kantor) memakai bentuk せざるを得なかった.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3cee4381-4560-4305-aa8a-0719915511f6', '2d710ef5-9a0b-4a0c-a93f-dd11d8b95e4a', 'd1000019-0000-0000-0000-000000000022', 'writing', 'sentence_builder', 'Susun kalimat: "Demi keselamatan warga, jalan ini terpaksa ditutup sementara."', '{"romaji":"Juumin no anzen no tame, kono douro wa ichiji heisa sezaru o enai.","tokens":["この道路は","一時閉鎖","一時閉鎖し","安全のため、","住民の","に限らず","得ない。","せざるを"],"target_translation":"Demi keselamatan warga, jalan ini terpaksa ditutup sementara."}'::jsonb, '["住民の","安全のため、","この道路は","一時閉鎖","せざるを","得ない。"]'::jsonb, NULL, NULL, '一時閉鎖 (penutupan sementara) + せざるを得ない menyatakan keputusan darurat.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0a8a0a33-8114-40d0-85fd-04bd531200df', '2d710ef5-9a0b-4a0c-a93f-dd11d8b95e4a', 'd1000019-0000-0000-0000-000000000022', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena biaya bahan baku naik, kami terpaksa menaikkan harga jual."', '{"romaji":"Genzairyou no koutou ni yori, hanbai kakaku o hikiagezaru o enaku narimashita.","display_text":"原材料の高騰により、販売価格を引き上げざるを得なくなりました。","phonetic_breakdown":["げんざいりょうの","こうとうにより","はんばいかかくを","ひきあげざるを","えなくなりました"]}'::jsonb, '{"expected_transcript":"原材料の高騰により、販売価格を引き上げざるを得なくなりました。"}'::jsonb, NULL, NULL, '引き上げる (menaikkan harga) → 引き上げざるを得なくなる (menjadi terpaksa menaikkan).', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c63f7a11-a2a6-4e8e-a87f-b28bea38793f', '2d710ef5-9a0b-4a0c-a93f-dd11d8b95e4a', 'd1000019-0000-0000-0000-000000000022', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa nuansa perasaan pembicara?', '{"options":[{"id":"opt_1","text":"Pembicara sangat senang menutup usahanya"},{"id":"opt_2","text":"Pembicara sebenarnya ingin melanjutkan, tetapi terpaksa menutup usaha karena dana habis"},{"id":"opt_3","text":"Pembicara menutup usaha karena ingin pindah profesi ke bidang seni"},{"id":"opt_4","text":"Pembicara masih memiliki banyak dana cadangan"}],"audio_text":"本当は続けたかったが、資金が尽きたため事業を畳まざるを得なかった。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '畳まざるを得なかった (terpaksa menutup usaha) mengandung nuansa berat hati karena tidak ada pilihan lain.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('248bb33b-e4ee-4319-9244-eadc96bf8372', '2d710ef5-9a0b-4a0c-a93f-dd11d8b95e4a', 'd1000019-0000-0000-0000-000000000022', 'reading', 'fill_blank', 'Lengkapi kalimat dengan konjugasi yang benar: 法律で定められている以上、この規則に従わ___。', '{"options":["ざるを得ない","かねない","にあたらない","つつある"],"translation":"Selama sudah ditetapkan oleh undang-undang, mau tidak mau kita harus mematuhi aturan ini.","sentence_template":"法律で定められている以上、この規則に従わ[blank]。"}'::jsonb, '{"selected":"ざるを得ない"}'::jsonb, NULL, NULL, '従う (mematuhi) -> 従わ + ざるを得ない.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5f455839-eaae-431a-9368-a919cc31efce', '2f19491a-ce65-46d9-b10a-93e6e975db61', 'd1000019-0000-0000-0000-000000000022', 'listening', 'listening_choice', 'Dengarkan pernyataan direktur keuangan. Langkah apa yang terpaksa dilakukan perusahaan?', '{"options":[{"id":"opt_1","text":"Menambah anggaran untuk divisi yang merugi"},{"id":"opt_2","text":"Memindahkan kantor pusat ke luar negeri"},{"id":"opt_3","text":"Merekrut seratus karyawan baru untuk divisi tersebut"},{"id":"opt_4","text":"Memutuskan terpaksa mundur dari divisi yang terus merugi sebelum akhir tahun"}],"audio_text":"赤字が続いている不採算部門については、年内に撤退せざるを得ないと判断しました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '撤退せざるを得ない berarti terpaksa harus menarik diri/menutup lini bisnis.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b7708dcf-aa50-4f91-acab-fd42493d8e97', '2f19491a-ce65-46d9-b10a-93e6e975db61', 'd1000019-0000-0000-0000-000000000022', 'writing', 'sentence_builder', 'Susun kalimat: "Karena kereta berhenti akibat kecelakaan, saya terpaksa naik taksi ke kantor."', '{"romaji":"Densha ga jiko de tomatta node, takushii de shussha sezaru o enakatta.","tokens":["事故で止まったので、","出社","得なかった。","わけにはいかなかった。","電車が","タクシーで","せざるを","出社する"],"target_translation":"Karena kereta berhenti akibat kecelakaan, saya terpaksa naik taksi ke kantor."}'::jsonb, '["電車が","事故で止まったので、","タクシーで","出社","せざるを","得なかった。"]'::jsonb, NULL, NULL, '出社する -> 出社せざるを得なかった menunjukkan tidak adanya pilihan transportasi lain.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4d3b1cd7-0b38-45fc-be8e-6f32ba48c67b', '2f19491a-ce65-46d9-b10a-93e6e975db61', 'd1000019-0000-0000-0000-000000000022', 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 期限までに修正が間に合わず、納期の延長をお願い___。', '{"options":["せざるを得なかった","しざるを得なかった","するざるを得なかった","されざるを得なかった"],"translation":"Karena perbaikan tidak sempat selesai sebelum tenggat, kami terpaksa memohon perpanjangan jadwal pengiriman.","sentence_template":"期限までに修正が間に合わず、納期の延長をお願い[blank]。"}'::jsonb, '{"selected":"せざるを得なかった"}'::jsonb, NULL, NULL, 'お願いする adalah kata kerja する, sehingga bentuknya お願いせざるを得なかった.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1ff10e54-64ec-4523-b3d3-9ce75236c935', '2f19491a-ce65-46d9-b10a-93e6e975db61', 'd1000019-0000-0000-0000-000000000022', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena kondisi kesehatan keluarga, saya terpaksa mengajukan cuti panjang."', '{"romaji":"Kazoku no taichou furyou no tame, chouki kyuuka o torazaru o enaku narimashita.","display_text":"家族の体調不良のため、長期休暇を取らざるを得なくなりました。","phonetic_breakdown":["かぞくの","たいちょうふりょうのため","ちょうききゅうかを","とらざるを","えなくなりました"]}'::jsonb, '{"expected_transcript":"家族の体調不良のため、長期休暇を取らざるを得なくなりました。"}'::jsonb, NULL, NULL, '取る -> 取らざるを得なくなりました menggambarkan perubahan keadaan yang memaksa mengambil cuti.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d99f1271-1f28-4d7d-b7b1-fbfe53d10188', '2f19491a-ce65-46d9-b10a-93e6e975db61', 'd1000019-0000-0000-0000-000000000022', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 相手側の条件があまりに厳しく、今回の契約は見送ら___。', '{"options":["ざるを得なかった","わけにはいかなかった","かねなかった","つつあった"],"translation":"Karena syarat pihak lawan terlalu ketat, kami terpaksa melewatkan kontrak kali ini.","sentence_template":"相手側の条件があまりに厳しく、今回の契約は見送ら[blank]。"}'::jsonb, '{"selected":"ざるを得なかった"}'::jsonb, NULL, NULL, '見送る (melewatkan/menunda) -> 見送ら + ざるを得なかった.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2b38c752-8ca9-485b-abf6-2012cfa14341', '2f19491a-ce65-46d9-b10a-93e6e975db61', 'd1000019-0000-0000-0000-000000000022', 'listening', 'listening_choice', 'Dengarkan berita lokal. Mengapa toko buku legendaris itu tutup?', '{"options":[{"id":"opt_1","text":"Karena gedung sudah tua dan tidak ada penerus usaha"},{"id":"opt_2","text":"Karena pemiliknya memenangkan undian besar"},{"id":"opt_3","text":"Karena lokasi toko akan dijadikan stasiun baru"},{"id":"opt_4","text":"Karena penjualan buku cetak meningkat terlalu cepat"}],"audio_text":"建物の老朽化と後継者不足により、創業八十年の老舗書店も閉店せざるを得なくなった。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '建物の老朽化 (penuaan bangunan) dan 後継者不足 (kurangnya penerus) memaksa penutupan toko.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('efed233c-523f-4cbd-b952-133ddbf060a5', '2f19491a-ce65-46d9-b10a-93e6e975db61', 'd1000019-0000-0000-0000-000000000022', 'writing', 'sentence_builder', 'Susun kalimat: "Karena bukti baru ditemukan, laporan sebelumnya terpaksa direvisi seluruhnya."', '{"romaji":"Arata na shouko ga mitsukatta tame, izen no houkokusho wa zenmen shuusei sezaru o enai.","tokens":["見つかったため、","全面修正","得ない。","にあたって、","新たな証拠が","以前の報告書は","せざるを","全面修正し"],"target_translation":"Karena bukti baru ditemukan, laporan sebelumnya terpaksa direvisi seluruhnya."}'::jsonb, '["新たな証拠が","見つかったため、","以前の報告書は","全面修正","せざるを","得ない。"]'::jsonb, NULL, NULL, '全面修正せざるを得ない berarti terpaksa melakukan revisi menyeluruh.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3b04a53f-4438-440f-8365-5b20d5c6e787', '2f19491a-ce65-46d9-b10a-93e6e975db61', 'd1000019-0000-0000-0000-000000000022', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meski berat hati, kami terpaksa mengurangi jumlah peserta karena kapasitas ruangan terbatas."', '{"romaji":"Kokorogurushii no desu ga, kaijou no tsugoujou, teiin o sakugen sezaru o emasen.","display_text":"心苦しいのですが、会場の都合上、定員を削減せざるを得ません。","phonetic_breakdown":["こころぐるしいのですが","かいじょうのつごうじょう","ていいんを","さくげんせざるをえません"]}'::jsonb, '{"expected_transcript":"心苦しいのですが、会場の都合上、定員を削減せざるを得ません。"}'::jsonb, NULL, NULL, '心苦しいのですが (dengan berat hati) memperhalus penyampaian keputusan terpaksa ～せざるを得ません.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b8929bc9-4c8b-46db-bfde-a4a502084e1c', '330ed226-2c3f-4869-a701-d4003a79b283', 'd1000019-0000-0000-0000-000000000023', 'reading', 'fill_blank', 'Lengkapi berita berikut: 大雨警報が出ていた___、会場には予定通り多くの参加者が集まった。', '{"options":["にもかかわらず","にあたって","に伴って","の上で"],"translation":"Meskipun peringatan hujan deras telah dikeluarkan, banyak peserta tetap berkumpul di lokasi sesuai jadwal.","sentence_template":"大雨警報が出ていた[blank]、会場には予定通り多くの参加者が集まった。"}'::jsonb, '{"selected":"にもかかわらず"}'::jsonb, NULL, NULL, '～にもかかわらず menyatakan kontras tajam antara kondisi yang ada dan hasil yang terjadi di luar dugaan.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c63fe213-62b3-439c-a09d-751e05640aad', '330ed226-2c3f-4869-a701-d4003a79b283', 'd1000019-0000-0000-0000-000000000023', 'reading', 'fill_blank', 'Pilih bentuk yang tepat setelah kata sifat-na: 彼はまだ入社二年目___にもかかわらず、大型案件を見事にまとめ上げた。', '{"options":["である","な","に","を"],"translation":"Meskipun ia baru tahun kedua masuk perusahaan, ia berhasil merampungkan proyek berskala besar dengan gemilang.","sentence_template":"彼はまだ入社二年目[blank]にもかかわらず、大型案件を見事にまとめ上げた。"}'::jsonb, '{"selected":"である"}'::jsonb, NULL, NULL, 'Kata benda (入社二年目) dapat langsung diikuti にもかかわらず, atau dengan である + にもかかわらず dalam gaya formal.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('70fb9773-c9ba-4d54-9a01-8bc888d1f205', '330ed226-2c3f-4869-a701-d4003a79b283', 'd1000019-0000-0000-0000-000000000023', 'listening', 'listening_choice', 'Dengarkan laporan survei berikut. Fakta kontras apa yang ditemukan?', '{"options":[{"id":"opt_1","text":"Tidak ada lagi karyawan yang membuka email mencurigakan"},{"id":"opt_2","text":"Meskipun sudah berkali-kali diperingatkan, kasus membuka lampiran email mencurigakan masih terus terjadi"},{"id":"opt_3","text":"Sistem email kantor dihapus sepenuhnya karena serangan siber"},{"id":"opt_4","text":"Karyawan tidak pernah menerima peringatan tentang keamanan data"}],"audio_text":"何度も注意喚起を行ったにもかかわらず、不審メールの添付ファイルを開いてしまう事例が後を絶たない。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '注意喚起を行ったにもかかわらず (meski sudah diperingatkan) dikontraskan dengan 事例が後を絶たない (kasus tak kunjung berhenti).', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dedebbaf-44bb-4eed-9088-e1ce5c3e73ba', '330ed226-2c3f-4869-a701-d4003a79b283', 'd1000019-0000-0000-0000-000000000023', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun usianya sudah lanjut, beliau masih aktif meneliti setiap hari."', '{"romaji":"Kourei ni mo kakawarazu, sensei wa mainichi geneki de kenkyuu o tsuzukete iru.","tokens":["にも","先生は毎日","続けている。","続けた。","高齢","かかわらず、","現役で研究を","に伴って、"],"target_translation":"Meskipun usianya sudah lanjut, beliau masih aktif meneliti setiap hari."}'::jsonb, '["高齢","にも","かかわらず、","先生は毎日","現役で研究を","続けている。"]'::jsonb, NULL, NULL, 'Kata benda 高齢 + にもかかわらず menyatakan kontras yang penuh rasa kagum.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6b92ac5e-523e-4baf-9dfa-2d82eb065547', '330ed226-2c3f-4869-a701-d4003a79b283', 'd1000019-0000-0000-0000-000000000023', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun jadwal Anda sangat padat, terima kasih telah meluangkan waktu untuk hadir."', '{"romaji":"Gotabou ni mo kakawarazu, goshusseki itadaki makoto ni arigatou gozaimasu.","display_text":"ご多忙にもかかわらず、ご出席いただき誠にありがとうございます。","phonetic_breakdown":["ごたぼうに","もかかわらず","ごしゅっせきいただき","まことに","ありがとうございます"]}'::jsonb, '{"expected_transcript":"ご多忙にもかかわらず、ご出席いただき誠にありがとうございます。"}'::jsonb, NULL, NULL, 'ご多忙にもかかわらず adalah frasa pembuka sangat sopan yang wajib dikuasai di dunia kerja Jepang.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f80e731a-343b-4e2e-9c02-0ed8c56cf13b', '330ed226-2c3f-4869-a701-d4003a79b283', 'd1000019-0000-0000-0000-000000000023', 'reading', 'fill_blank', 'Lengkapi kalimat analisis: 厳しい不況___、同社のクラウド事業は過去最高の売上を記録した。', '{"options":["にもかかわらず","に限らず","ざるを得ず","つつあり"],"translation":"Terlepas dari resesi ekonomi yang berat, bisnis cloud perusahaan tersebut mencatat penjualan tertinggi sepanjang masa.","sentence_template":"厳しい不況[blank]、同社のクラウド事業は過去最高の売上を記録した。"}'::jsonb, '{"selected":"にもかかわらず"}'::jsonb, NULL, NULL, 'Kata benda 不況 + にもかかわらず menyoroti kinerja luar biasa di tengah kondisi sulit.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('637d756b-e428-48c3-89fe-b0c385beb958', '330ed226-2c3f-4869-a701-d4003a79b283', 'd1000019-0000-0000-0000-000000000023', 'listening', 'listening_choice', 'Dengarkan tanggapan pembaca berita. Apa yang mengherankan dari hasil pemilu daerah?', '{"options":[{"id":"opt_1","text":"Kandidat baru itu mengundurkan diri sebelum pemungutan suara"},{"id":"opt_2","text":"Hasil pemilu sama persis dengan prediksi survei"},{"id":"opt_3","text":"Meski diprediksi kesulitan dalam survei sebelumnya, kandidat baru menang dengan selisih suara telak"},{"id":"opt_4","text":"Tingkat partisipasi pemilih hanya mencapai sepuluh persen"}],"audio_text":"事前の世論調査では苦戦が予想されていたにもかかわらず、新人候補が圧倒的な票差で当選した。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '苦戦が予想されていたにもかかわらず dikontraskan dengan 圧倒的な票差で当選した.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a7fe6aab-2f2b-43b3-9377-6eaeafa1948e', '330ed226-2c3f-4869-a701-d4003a79b283', 'd1000019-0000-0000-0000-000000000023', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun biayanya mahal, kualitas layanan hotel itu jauh di bawah harapan."', '{"romaji":"Ryoukin ga kougaku de aru ni mo kakawarazu, hoteru no saabisu wa kitai hazure datta.","tokens":["である","ホテルのサービスは","だった。","期待外れだ。","料金が高額","にもかかわらず、","期待外れ","にあたって、"],"target_translation":"Meskipun biayanya mahal, kualitas layanan hotel itu jauh di bawah harapan."}'::jsonb, '["料金が高額","である","にもかかわらず、","ホテルのサービスは","期待外れ","だった。"]'::jsonb, NULL, NULL, '高額であるにもかかわらず menonjolkan kekecewaan yang kontras dengan harga tinggi.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a265950b-9521-40c9-88dc-984f78e7dc68', '38a8e466-a2cd-4c16-8283-261ead5f3ca1', 'd1000019-0000-0000-0000-000000000021', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 重要な会議の司会を任されたので、風邪気味でも___わけにはいかない。', '{"options":["休む","休んだ","休んで","休み"],"translation":"Karena dipercaya menjadi moderator rapat penting, meski agak masuk angin saya tidak bisa libur.","sentence_template":"重要な会議の司会を任されたので、風邪気味でも[blank]わけにはいかない。"}'::jsonb, '{"selected":"休む"}'::jsonb, NULL, NULL, 'Sebelum わけにはいかない, verba menggunakan bentuk kamus (休む) atau bentuk ない.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('90869e3c-84fa-4ca9-876c-f4be3d3b39b7', '38a8e466-a2cd-4c16-8283-261ead5f3ca1', 'd1000019-0000-0000-0000-000000000021', 'reading', 'fill_blank', 'Pilih bentuk negatif ganda yang tepat (''mau tidak mau harus''): 上司から直接頼まれた仕事なので、___わけにはいかない。', '{"options":["引き受けない","引き受ける","引き受けた","引き受けて"],"translation":"Karena pekerjaan ini diminta langsung oleh atasan, mau tidak mau saya harus menerimanya.","sentence_template":"上司から直接頼まれた仕事なので、[blank]わけにはいかない。"}'::jsonb, '{"selected":"引き受けない"}'::jsonb, NULL, NULL, 'V-ない + わけにはいかない berarti ''tidak bisa tidak melakukan'' alias mau tidak mau harus melakukan.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('877f37f9-4db1-437f-ad1d-c8a63a8a8e12', '38a8e466-a2cd-4c16-8283-261ead5f3ca1', 'd1000019-0000-0000-0000-000000000021', 'reading', 'fill_blank', 'Lengkapi pola N2 berikut: ここは病院の待合室なので、大声で話す___。', '{"options":["わけにはいかない","にあたって","に伴って","に限らず"],"translation":"Karena ini ruang tunggu rumah sakit, tidak pantas berbicara dengan suara keras.","sentence_template":"ここは病院の待合室なので、大声で話す[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, NULL, NULL, '～わけにはいかない menyatakan ketidakbolehan berdasarkan norma sosial atau kepantasan.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('67f07a52-6d32-496a-8ed6-57234525aec7', '38a8e466-a2cd-4c16-8283-261ead5f3ca1', 'd1000019-0000-0000-0000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat: "Saya tidak mungkin menceritakan rahasia teman kepada orang lain."', '{"romaji":"Yuujin no himitsu o tanin ni hanasu wake ni wa ikanai.","tokens":["わけには","話した","話す","友人の","秘密を","いかない。","他人に","に限らず"],"target_translation":"Saya tidak mungkin menceritakan rahasia teman kepada orang lain."}'::jsonb, '["友人の","秘密を","他人に","話す","わけには","いかない。"]'::jsonb, NULL, NULL, 'Urutan baku: [Objek] + [V-dict] + わけにはいかない.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1992cb8c-c0c3-469f-981b-74429ec10a43', '38a8e466-a2cd-4c16-8283-261ead5f3ca1', 'd1000019-0000-0000-0000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat: "Karena sudah diundang ke pernikahan atasan, mau tidak mau saya harus hadir."', '{"romaji":"Joushi no kekkonshiki ni shoutai sareta node, shusseki shinai wake ni wa ikanai.","tokens":["招待されたので、","上司の","出席する","わけには","結婚式に","出席しない","いかない。","かねない。"],"target_translation":"Karena sudah diundang ke pernikahan atasan, mau tidak mau saya harus hadir."}'::jsonb, '["上司の","結婚式に","招待されたので、","出席しない","わけには","いかない。"]'::jsonb, NULL, NULL, '出席しないわけにはいかない (tidak bisa tidak hadir = harus hadir karena etika sosial).', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('51de34b5-4f4e-4f47-9088-ae28d3c29a56', '38a8e466-a2cd-4c16-8283-261ead5f3ca1', 'd1000019-0000-0000-0000-000000000021', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya tidak mungkin berhenti di tengah jalan pada proyek ini."', '{"romaji":"Kono purojekuto o tochuu de akirameru wake ni wa ikimasen.","display_text":"このプロジェクトを途中で諦めるわけにはいきません。","phonetic_breakdown":["このぷろじぇくとを","とちゅうで","あきらめる","わけには","いきません"]}'::jsonb, '{"expected_transcript":"このプロジェクトを途中で諦めるわけにはいきません。"}'::jsonb, NULL, NULL, '途中で諦める berarti menyerah di tengah jalan.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d40baacd-a95b-4ca0-851b-d8e28cd3d9ab', '38a8e466-a2cd-4c16-8283-261ead5f3ca1', 'd1000019-0000-0000-0000-000000000021', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Mengapa pembicara tetap pergi ke kantor?', '{"options":[{"id":"opt_1","text":"Karena pembicara ditugaskan menjadi moderator rapat hari ini sehingga tidak bisa absen"},{"id":"opt_2","text":"Karena pembicara sama sekali tidak merasa sakit"},{"id":"opt_3","text":"Karena tidak ada dokter yang buka hari ini"},{"id":"opt_4","text":"Karena rapat hari ini sudah dibatalkan"}],"audio_text":"少し熱があるけれど、今日の会議の司会を任されているので休むわけにはいかない。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '休むわけにはいかない menunjukkan rasa tanggung jawab meski sedang kurang sehat.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('815168b8-8cc1-4835-9f78-ec7dcc335e39', '38a8e466-a2cd-4c16-8283-261ead5f3ca1', 'd1000019-0000-0000-0000-000000000021', 'reading', 'fill_blank', 'Lengkapi kalimat dengan bentuk yang tepat: 約束の時間が迫っているから、もうこれ以上待つ___。', '{"options":["わけにはいかない","にあたらない","に伴わない","つつある"],"translation":"Karena waktu janji sudah semakin mepet, kita tidak bisa menunggu lebih lama lagi.","sentence_template":"約束の時間が迫っているから、もうこれ以上待つ[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, NULL, NULL, 'もうこれ以上待つわけにはいかない berarti kondisi tidak lagi memungkinkan untuk menunggu.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cc2f71e0-05df-4afb-9b2e-c723482ab2b3', '3eec5895-b0c2-49f9-b6c5-2c2a7200b0ce', 'd1000019-0000-0000-0000-000000000023', 'reading', 'fill_blank', 'Lengkapi sambungan kata benda berikut: 深夜___にもかかわらず、駅前の通りは人通りが絶えない。', '{"options":["である","な","の","を"],"translation":"Meskipun sudah larut malam, jalan di depan stasiun tidak pernah sepi pejalan kaki.","sentence_template":"深夜[blank]にもかかわらず、駅前の通りは人通りが絶えない。"}'::jsonb, '{"selected":"である"}'::jsonb, NULL, NULL, 'Nomina dan Adjektiva-な dapat langsung diikuti にもかかわらず atau memakai であるにもかかわらず.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('be1a9601-52e8-4663-89ad-fa90554d3f81', '3eec5895-b0c2-49f9-b6c5-2c2a7200b0ce', 'd1000019-0000-0000-0000-000000000023', 'reading', 'fill_blank', 'Pilih pola kontras formal yang tepat: 何度も注意した___、同じミスが繰り返されている。', '{"options":["にもかかわらず","にあたって","に伴って","に限らず"],"translation":"Meskipun sudah berkali-kali diperingatkan, kesalahan yang sama masih terus terulang.","sentence_template":"何度も注意した[blank]、同じミスが繰り返されている。"}'::jsonb, '{"selected":"にもかかわらず"}'::jsonb, NULL, NULL, 'Bentuk biasa (注意した) + にもかかわらず menekankan rasa heran atau kecewa atas hasil yang bertolak belakang.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5c5e314b-e80b-4f14-b32a-e8bbb0b59676', '3eec5895-b0c2-49f9-b6c5-2c2a7200b0ce', 'd1000019-0000-0000-0000-000000000023', 'reading', 'fill_blank', 'Lengkapi kalimat berikut dengan bentuk Adjektiva-な yang benar: 立地が___にもかかわらず、そのレストランはいつも満席だ。', '{"options":["不便である","不便な","不便に","不便で"],"translation":"Meskipun lokasinya kurang strategis, restoran itu selalu penuh.","sentence_template":"立地が[blank]にもかかわらず、そのレストランはいつも満席だ。"}'::jsonb, '{"selected":"不便である"}'::jsonb, NULL, NULL, '不便 adalah Adjektiva-な; sebelum にもかかわらず, gunakan bentuk langsung (不便にもかかわらず) atau 不便であるにもかかわらず (bukan 不便な).', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0a197df8-6391-4bb7-849e-a92aadc5f564', '3eec5895-b0c2-49f9-b6c5-2c2a7200b0ce', 'd1000019-0000-0000-0000-000000000023', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun usianya masih muda, ia memimpin tim yang besar."', '{"romaji":"Nenrei ga wakai ni mo kakawarazu, ookina chiimu o hikiite iru.","tokens":["チームを","若い","年齢が","大きな","若くて","にもかかわらず、","にあたって、","率いている。"],"target_translation":"Meskipun usianya masih muda, ia memimpin tim yang besar."}'::jsonb, '["年齢が","若い","にもかかわらず、","大きな","チームを","率いている。"]'::jsonb, NULL, NULL, 'Adjektiva-い (若い) langsung diikuti にもかかわらず.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('668820b5-8b38-40f2-b8f2-0df874112868', '3eec5895-b0c2-49f9-b6c5-2c2a7200b0ce', 'd1000019-0000-0000-0000-000000000023', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun waktu persiapan singkat, acara itu sukses besar."', '{"romaji":"Junbi kikan ga mijikakatta ni mo kakawarazu, ibento wa daiseikou datta.","tokens":["短いのに","に伴って、","イベントは","だった。","短かった","準備期間が","にもかかわらず、","大成功"],"target_translation":"Meskipun waktu persiapan singkat, acara itu sukses besar."}'::jsonb, '["準備期間が","短かった","にもかかわらず、","イベントは","大成功","だった。"]'::jsonb, NULL, NULL, 'Bentuk lampau (短かった) + にもかかわらず menyatakan kontras fakta masa lalu.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('00340cc3-6f19-448c-ba43-1f13d6e0431c', '3eec5895-b0c2-49f9-b6c5-2c2a7200b0ce', 'd1000019-0000-0000-0000-000000000023', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun sudah belajar keras, hasil ujian kali ini belum memuaskan."', '{"romaji":"Isshoukenmei benkyou shita ni mo kakawarazu, konkai no kekka wa manzoku dekimasen deshita.","display_text":"一生懸命勉強したにもかかわらず、今回の結果は満足できませんでした。","phonetic_breakdown":["いっしょうけんめい","べんきょうした","にもかかわらず","こんかいのけっかは","まんぞくできませんでした"]}'::jsonb, '{"expected_transcript":"一生懸命勉強したにもかかわらず、今回の結果は満足できませんでした。"}'::jsonb, NULL, NULL, '満足する (puas) sangat lazim digunakan dalam evaluasi diri maupun laporan hasil.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4e33c960-f286-4342-8379-94b76c7689ba', '3eec5895-b0c2-49f9-b6c5-2c2a7200b0ce', 'd1000019-0000-0000-0000-000000000023', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Pernyataan mana yang benar?', '{"options":[{"id":"opt_1","text":"Ia pulang lebih awal karena tidak enak badan"},{"id":"opt_2","text":"Ia tetap mengikuti rapat sampai selesai demi rasa tanggung jawab meski kondisinya kurang sehat"},{"id":"opt_3","text":"Ia sama sekali tidak hadir dalam rapat hari ini"},{"id":"opt_4","text":"Rapat dibatalkan karena kondisinya memburuk"}],"audio_text":"体調が優れないにもかかわらず、彼は責任感から会議に最後まで出席した。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '体調が優れないにもかかわらず berarti meskipun kondisi badan sedang tidak prima.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6aa1a172-2455-40f5-bf68-c7f1073dd2df', '3eec5895-b0c2-49f9-b6c5-2c2a7200b0ce', 'd1000019-0000-0000-0000-000000000023', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 立地が不便___にもかかわらず、そのレストランは連日満席だ。', '{"options":["である","な","に","の"],"translation":"Meskipun lokasinya kurang strategis, restoran itu penuh pengunjung setiap hari.","sentence_template":"立地が不便[blank]にもかかわらず、そのレストランは連日満席だ。"}'::jsonb, '{"selected":"である"}'::jsonb, NULL, NULL, 'Kata sifat-na (不便) tidak memakai な sebelum にもかかわらず; gunakan 不便にもかかわらず atau 不便であるにもかかわらず.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('def71d55-091f-4218-9049-99feb9d253c1', '40b41168-7cdb-4003-aa86-d946a7938abc', 'd1000019-0000-0000-0000-000000000019', 'listening', 'listening_choice', 'Dengarkan laporan cuaca dan transportasi. Mengapa jadwal kereta diubah?', '{"options":[{"id":"opt_1","text":"Karena adanya perbaikan rel rutin bulanan"},{"id":"opt_2","text":"Karena mendekatnya topan sehingga jadwal shinkansen dikurangi atau dihentikan sementara"},{"id":"opt_3","text":"Karena lonjakan penumpang pada hari libur nasional"},{"id":"opt_4","text":"Karena pemogokan masinis di stasiun pusat"}],"audio_text":"台風の接近に伴い、午後の新幹線は大幅な減便と運転見合わせが予定されています。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '台風の接近に伴い berarti seiring mendekatnya topan; 減便 berarti pengurangan frekuensi perjalanan.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('15a7cfc9-86da-4a80-84e9-9433c2c4218b', '40b41168-7cdb-4003-aa86-d946a7938abc', 'd1000019-0000-0000-0000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat: "Seiring dengan bertambahnya usia, perhatian terhadap kesehatan semakin meningkat."', '{"romaji":"Nenrei o kasaneru ni tomonatte, kenkou e no kanshin ga takamatte iru.","tokens":["重ねる","健康への","高まっている。","に限らず、","年齢を","に伴って、","関心が","重ねた"],"target_translation":"Seiring dengan bertambahnya usia, perhatian terhadap kesehatan semakin meningkat."}'::jsonb, '["年齢を","重ねる","に伴って、","健康への","関心が","高まっている。"]'::jsonb, NULL, NULL, '年齢を重ねる (bertambah usia) + に伴って menggunakan verba bentuk kamus.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1bfefb1a-6965-42d5-adff-8e943df72100', '40b41168-7cdb-4003-aa86-d946a7938abc', 'd1000019-0000-0000-0000-000000000019', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 人口の減少___、地方の公共交通機関の維持が困難になりつつある。', '{"options":["に伴い","にあたり","の上で","かねず"],"translation":"Seiring dengan menurunnya populasi, pemeliharaan transportasi umum di daerah menjadi semakin sulit.","sentence_template":"人口の減少[blank]、地方の公共交通機関の維持が困難になりつつある。"}'::jsonb, '{"selected":"に伴い"}'::jsonb, NULL, NULL, '人口の減少に伴い menunjukkan perubahan struktural yang berjalan beriringan.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('70dc7efe-3baf-4ca2-af47-844c8735c3c4', '40b41168-7cdb-4003-aa86-d946a7938abc', 'd1000019-0000-0000-0000-000000000019', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring dengan perluasan bisnis, jumlah karyawan baru juga bertambah."', '{"romaji":"Jigyou no kakudai ni tomonatte, shinnyuu shain no kazu mo fuete imasu.","display_text":"事業の拡大に伴って、新入社員の数も増えています。","phonetic_breakdown":["じぎょうの","かくだいに","ともなって","しんにゅうしゃいんの","かずも","ふえています"]}'::jsonb, '{"expected_transcript":"事業の拡大に伴って、新入社員の数も増えています。"}'::jsonb, NULL, NULL, '事業の拡大 (perluasan bisnis) berpasangan alami dengan ～に伴って.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ed914955-13fa-439b-a597-ffb5ea5363dc', '40b41168-7cdb-4003-aa86-d946a7938abc', 'd1000019-0000-0000-0000-000000000019', 'reading', 'fill_blank', 'Lengkapi kalimat kebijakan berikut: 法律の改正___手続きの変更点について、資料にまとめました。', '{"options":["に伴う","に伴って","にあたって","つつある"],"translation":"Saya telah merangkum poin-poin perubahan prosedur yang menyertai revisi undang-undang ke dalam materi.","sentence_template":"法律の改正[blank]手続きの変更点について、資料にまとめました。"}'::jsonb, '{"selected":"に伴う"}'::jsonb, NULL, NULL, 'Karena langsung memodifikasi frasa nominal 手続きの変更点, bentuk yang benar adalah に伴う.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('474f4614-a145-457e-8d1d-ddfccab41af5', '40b41168-7cdb-4003-aa86-d946a7938abc', 'd1000019-0000-0000-0000-000000000019', 'listening', 'listening_choice', 'Dengarkan komentar pakar energi. Perubahan apa yang sedang terjadi?', '{"options":[{"id":"opt_1","text":"Pembangunan stasiun pengisian cepat di seluruh negeri berlangsung pesat"},{"id":"opt_2","text":"Harga bahan bakar bensin turun ke titik terendah"},{"id":"opt_3","text":"Penjualan mobil listrik dilarang di wilayah pegunungan"},{"id":"opt_4","text":"Pemerintah menghentikan subsidi kendaraan ramah lingkungan"}],"audio_text":"電気自動車の普及に伴い、全国各地で急速充電器の設置が急ピッチで進んでいる。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '急速充電器の設置が急ピッチで進んでいる berarti pemasangan pengisi daya cepat berlangsung dengan tempo tinggi.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0f0f974e-27bc-4866-bf84-24cad1f28485', '40b41168-7cdb-4003-aa86-d946a7938abc', 'd1000019-0000-0000-0000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat: "Seiring dengan naiknya biaya hidup, banyak keluarga meninjau ulang pengeluaran."', '{"romaji":"Bukka no joushou ni tomonai, ooku no katei ga shishutsu o minaoshite iru.","tokens":["上昇","多くの家庭が","見直している。","にもかかわらず、","物価の","に伴い、","支出を","見直す"],"target_translation":"Seiring dengan naiknya biaya hidup, banyak keluarga meninjau ulang pengeluaran."}'::jsonb, '["物価の","上昇","に伴い、","多くの家庭が","支出を","見直している。"]'::jsonb, NULL, NULL, '物価の上昇に伴い menyatakan dampak langsung inflasi terhadap anggaran rumah tangga.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a604d0d8-eb52-4028-affd-786af13551c9', '40b41168-7cdb-4003-aa86-d946a7938abc', 'd1000019-0000-0000-0000-000000000019', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami menanggung biaya pengiriman yang menyertai pengembalian barang rusak."', '{"romaji":"Furyouhin no henpin ni tomonau souryou wa, heisha ga futan itashimasu.","display_text":"不良品の返品に伴う送料は、弊社が負担いたします。","phonetic_breakdown":["ふりょうひんの","へんぴんに","ともなう","そうりょうは","へいしゃが","ふたんいたします"]}'::jsonb, '{"expected_transcript":"不良品の返品に伴う送料は、弊社が負担いたします。"}'::jsonb, NULL, NULL, '返品に伴う送料 (ongkos kirim yang menyertai retur) adalah frasa standar layanan pelanggan Jepang.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('81cef5cc-455f-42b9-b090-a135fdecdb5a', '40c0e772-8b86-4f32-a1fc-74cf5ecfb57e', 'd1000019-0000-0000-0000-000000000027', 'listening', 'listening_choice', 'Dengarkan sambutan pembawa acara. Siapa yang akan memberikan pidato pembukaan?', '{"options":[{"id":"opt_1","text":"Ketua Dewan Sato akan menyampaikan sambutan mewakili para tamu kehormatan"},{"id":"opt_2","text":"Acara resmi ditutup sekarang juga"},{"id":"opt_3","text":"Pembawa acara akan menyanyikan lagu perpisahan"},{"id":"opt_4","text":"Para tamu diminta segera menuju ruang makan"}],"audio_text":"続きまして、来賓を代表いたしまして、佐藤理事長よりご挨拶を頂戴いたします。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '来賓を代表いたしまして dan ご挨拶を頂戴いたします adalah protokol formal upacara Jepang.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4fef4afe-daf5-4e2a-95ac-97a26b41a1d8', '40c0e772-8b86-4f32-a1fc-74cf5ecfb57e', 'd1000019-0000-0000-0000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat: "Kapan Bapak Profesor berangkat menuju konferensi internasional di Osaka?"', '{"romaji":"Sensei wa itsu Oosaka no kokusai kaigi e odekake ni narimasu ka.","tokens":["大阪の","お出かけ","ますか。","まいり","先生はいつ","国際会議へ","になり","出かけいたし"],"target_translation":"Kapan Bapak Profesor berangkat menuju konferensi internasional di Osaka?"}'::jsonb, '["先生はいつ","大阪の","国際会議へ","お出かけ","になり","ますか。"]'::jsonb, NULL, NULL, 'お出かけになる adalah sonkeigo baku untuk 出かける (bepergian/berangkat).', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f0fcc092-aa21-44cd-943c-4b92a761562a', '40c0e772-8b86-4f32-a1fc-74cf5ecfb57e', 'd1000019-0000-0000-0000-000000000027', 'reading', 'fill_blank', 'Pilih bentuk sonkeigo yang tepat (hindari keigo ganda!): 課長は昨日、新しい企画書を___。', '{"options":["ご覧になりました","ご覧になられました","拝見しました","お読みいたしました"],"translation":"Kemarin kepala seksi telah membaca/melihat proposal baru tersebut.","sentence_template":"課長は昨日、新しい企画書を[blank]。"}'::jsonb, '{"selected":"ご覧になりました"}'::jsonb, NULL, NULL, 'ご覧になりました sudah merupakan sonkeigo penuh; ご覧になられました adalah kesalahan keigo ganda (二重敬語).', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('13ce7b5f-73f2-4fe0-8e0c-8d395b33bf58', '40c0e772-8b86-4f32-a1fc-74cf5ecfb57e', 'd1000019-0000-0000-0000-000000000027', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Apakah Bapak/Ibu berkenan memilih kopi atau teh hijau?"', '{"romaji":"Onomimono wa koohii to ryokucha no dochira ni nasaimasu ka.","display_text":"お飲み物はコーヒーと緑茶のどちらになさいますか。","phonetic_breakdown":["おのみものは","こーひーと","りょくちゃの","どちらに","なさいますか"]}'::jsonb, '{"expected_transcript":"お飲み物はコーヒーと緑茶のどちらになさいますか。"}'::jsonb, NULL, NULL, 'なさる adalah sonkeigo baku untuk する; どちらになさいますか berarti ''hendak memilih yang mana?''.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ea0d76b5-49cd-4188-a0c1-f15ecc8c6be6', '40c0e772-8b86-4f32-a1fc-74cf5ecfb57e', 'd1000019-0000-0000-0000-000000000027', 'reading', 'fill_blank', 'Lengkapi kalimat email bisnis: 添付ファイルをご確認の___、ご返信いただけますと幸いです。', '{"options":["上","下","前","内"],"translation":"Kami akan sangat berterima kasih apabila Anda berkenan membalas setelah memeriksa file lampiran.","sentence_template":"添付ファイルをご確認の[blank]、ご返信いただけますと幸いです。"}'::jsonb, '{"selected":"上"}'::jsonb, NULL, NULL, 'ご確認の上 (setelah Anda memeriksa) menggabungkan sopan-santun ご確認 dengan pola 上.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2eb7dca7-0103-4c63-b325-1b3362f3f32d', '40c0e772-8b86-4f32-a1fc-74cf5ecfb57e', 'd1000019-0000-0000-0000-000000000027', 'listening', 'listening_choice', 'Dengarkan ucapan staf hotel kepada tamu VIP. Apa yang diinformasikan staf?', '{"options":[{"id":"opt_1","text":"Bagasi tamu hilang di bandara"},{"id":"opt_2","text":"Tamu harus mengangkat sendiri koper ke lantai sepuluh"},{"id":"opt_3","text":"Kamar tamu belum selesai dibersihkan"},{"id":"opt_4","text":"Bagasi tamu sudah diantarkan ke kamar sehingga tamu dipersilakan beristirahat dengan tenang"}],"audio_text":"お荷物はすでにお部屋へお運びしてございますので、どうぞごゆっくりお寛ぎくださいませ。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'お寛ぎくださいませ (silakan beristirahat santai) adalah ungkapan sonkeigo ramah khas layanan Jepang.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('320c01c4-ae72-4924-8d14-65efd13b5d76', '40c0e772-8b86-4f32-a1fc-74cf5ecfb57e', 'd1000019-0000-0000-0000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat: "Silakan Anda menuliskan nama dan alamat pada formulir ini."', '{"romaji":"Kochira no youshi ni onamae to gojuusho o okaki kudasai.","tokens":["用紙に","ご住所を","ください。","お書き申し","こちらの","お名前と","お書き","書いていたし"],"target_translation":"Silakan Anda menuliskan nama dan alamat pada formulir ini."}'::jsonb, '["こちらの","用紙に","お名前と","ご住所を","お書き","ください。"]'::jsonb, NULL, NULL, 'お + V-masu stem + ください (お書きください) adalah permintaan sopan bergaya sonkeigo.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bf27e8a3-f656-4c16-94a1-58b684032549', '40c0e772-8b86-4f32-a1fc-74cf5ecfb57e', 'd1000019-0000-0000-0000-000000000027', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Bapak Direktur berkata bahwa beliau akan menghadiri pertemuan besok pagi."', '{"romaji":"Shachou wa asu no asa no uchiawase ni goshusseki ni naru to osshaimashita.","display_text":"社長は明日の朝の打ち合わせにご出席になるとおっしゃいました。","phonetic_breakdown":["しゃちょうは","あしたのあさの","うちあわせに","ごしゅっせきになると","おっしゃいました"]}'::jsonb, '{"expected_transcript":"社長は明日の朝の打ち合わせにご出席になるとおっしゃいました。"}'::jsonb, NULL, NULL, 'ご出席になる (hadir) dan おっしゃいました (berkata) adalah kombinasi sonkeigo yang tepat tanpa tumpang tindih.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2f9e3fa1-fc49-4558-9913-b44e89e75107', '505f6f34-1b40-4967-87c3-d53f240f6e4a', 'd1000019-0000-0000-0000-000000000020', 'reading', 'fill_blank', 'Lengkapi pola N2 berikut: 語学の習得は英語___、毎日の継続的な練習が大切だ。', '{"options":["に限らず","にあたって","に伴って","かねない"],"translation":"Penguasaan bahasa tidak terbatas pada bahasa Inggris, latihan rutin setiap hari sangat penting.","sentence_template":"語学の習得は英語[blank]、毎日の継続的な練習が大切だ。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, NULL, NULL, 'Kata Benda + に限らず berarti ''tidak hanya terbatas pada [Kata Benda], tetapi juga berlaku untuk yang lain''.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('925bb476-4401-478e-a6eb-8ec30b078fad', '505f6f34-1b40-4967-87c3-d53f240f6e4a', 'd1000019-0000-0000-0000-000000000020', 'reading', 'fill_blank', 'Pilih jawaban yang tepat: このスポーツクラブは会員___、一般の方も体験利用が可能だ。', '{"options":["に限らず","ざるを得ず","にもかかわらず","つつあり"],"translation":"Klub olahraga ini tidak terbatas bagi anggota saja; masyarakat umum pun dapat mencoba layanan uji coba.","sentence_template":"このスポーツクラブは会員[blank]、一般の方も体験利用が可能だ。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, NULL, NULL, '会員に限らず (tidak terbatas pada anggota) sangat lazim dalam pengumuman fasilitas umum.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8bf130a5-dd34-4da3-b5c3-c384d6b9a9e3', '505f6f34-1b40-4967-87c3-d53f240f6e4a', 'd1000019-0000-0000-0000-000000000020', 'reading', 'fill_blank', 'Lengkapi kalimat evaluasi berikut: ___に限らず、どの仕事でも基礎を固めることが成功の鍵となる。', '{"options":["IT分野","IT分野を","IT分野で","IT分野に"],"translation":"Tidak terbatas pada bidang IT, dalam pekerjaan apa pun memperkuat dasar adalah kunci keberhasilan.","sentence_template":"[blank]に限らず、どの仕事でも基礎を固めることが成功の鍵となる。"}'::jsonb, '{"selected":"IT分野"}'::jsonb, NULL, NULL, 'Di depan に限らず, kata benda dipakai langsung tanpa partikel tambahan.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b16eab80-eb5b-43a4-aa52-befb9cbc652b', '505f6f34-1b40-4967-87c3-d53f240f6e4a', 'd1000019-0000-0000-0000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat: "Masalah ini tidak terbatas di Jepang, tetapi juga terjadi di banyak negara."', '{"romaji":"Kono mondai wa Nihon ni kagirazu, ooku no kuni de okite iru.","tokens":["国で","起きている。","に限らず、","にあたって、","日本に","この問題は","日本","多くの"],"target_translation":"Masalah ini tidak terbatas di Jepang, tetapi juga terjadi di banyak negara."}'::jsonb, '["この問題は","日本","に限らず、","多くの","国で","起きている。"]'::jsonb, NULL, NULL, '日本に限らず (tidak terbatas pada Jepang) diikuti pernyataan yang memperluas cakupan ke banyak negara.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1f5cac00-f944-43d8-a7dd-56cac09ea9b8', '505f6f34-1b40-4967-87c3-d53f240f6e4a', 'd1000019-0000-0000-0000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat: "Seminar ini dapat diikuti tidak terbatas pada usia maupun kewarganegaraan."', '{"romaji":"Kono seminaa wa nenrei ya kokuseki ni kagirazu, daredemo sanka dekiru.","tokens":["参加できる。","このセミナーは","に限らず、","国籍","年齢や","誰でも","国籍を","に伴って、"],"target_translation":"Seminar ini dapat diikuti tidak terbatas pada usia maupun kewarganegaraan."}'::jsonb, '["このセミナーは","年齢や","国籍","に限らず、","誰でも","参加できる。"]'::jsonb, NULL, NULL, 'Kombinasi AやBに限らず menegaskan bahwa tidak ada batasan pada kedua kategori tersebut.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f61351d7-f2f7-468d-8a03-d74234bbbe86', '505f6f34-1b40-4967-87c3-d53f240f6e4a', 'd1000019-0000-0000-0000-000000000020', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Produk ramah lingkungan tidak terbatas pada makanan, tetapi juga meluas ke pakaian."', '{"romaji":"Kankyou ni yasashii seihin wa shokuhin ni kagirazu, irui ni mo hirogatte imasu.","display_text":"環境に優しい製品は食品に限らず、衣類にも広がっています。","phonetic_breakdown":["かんきょうに","やさしい","せいひんは","しょくひんに","かぎらず","いるいにも","ひろがっています"]}'::jsonb, '{"expected_transcript":"環境に優しい製品は食品に限らず、衣類にも広がっています。"}'::jsonb, NULL, NULL, '衣類 (irui) berarti pakaian/sandang; 広がる berarti meluas.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1ef0d365-d7d1-437f-9887-ba2861cfa754', '505f6f34-1b40-4967-87c3-d53f240f6e4a', 'd1000019-0000-0000-0000-000000000020', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa makna utama yang ingin ditekankan pembicara?', '{"options":[{"id":"opt_1","text":"Hanya lansia yang perlu menjaga kesehatan"},{"id":"opt_2","text":"Generasi usia produktif tidak perlu memikirkan kesehatan"},{"id":"opt_3","text":"Manajemen kesehatan adalah prioritas utama bagi lansia maupun generasi usia produktif"},{"id":"opt_4","text":"Pemerintah hanya menanggung biaya kesehatan lansia"}],"audio_text":"健康管理は高齢者に限らず、働き盛りの世代にとっても最優先課題だ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '高齢者に限らず memperluas subjek kepada 働き盛りの世代 (generasi usia produktif).', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('91f0222b-1a2d-47a1-8fc5-8b55ab763177', '505f6f34-1b40-4967-87c3-d53f240f6e4a', 'd1000019-0000-0000-0000-000000000020', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 災害対策は地震___、水害や停電への備えも含めるべきだ。', '{"options":["に限らず","にあたり","に伴って","かねない"],"translation":"Penanggulangan bencana tidak terbatas pada gempa bumi, melainkan harus mencakup kesiapan menghadapi banjir dan pemadaman listrik.","sentence_template":"災害対策は地震[blank]、水害や停電への備えも含めるべきだ。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, NULL, NULL, '地震に限らず + 水害や停電への備えも menunjukkan cakupan mitigasi yang komprehensif.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0eae3482-a69d-428a-8544-50090b6cafc5', '568c790b-1ac3-4b22-a9f9-418e58feed57', NULL, 'listening', 'listening_choice', 'Dengarkan penjelasan agen properti berikut. Apa yang disarankan sebelum menyewa apartemen?', '{"options":[{"id":"opt_1","text":"Langsung mentransfer uang muka tanpa melihat kamar"},{"id":"opt_2","text":"Memutuskan kontrak setelah benar-benar meninjau kamar secara langsung"},{"id":"opt_3","text":"Menandatangani kontrak jangka panjang selama sepuluh tahun"},{"id":"opt_4","text":"Meminta teman memilihkan kamar lewat foto saja"}],"audio_text":"実際に部屋を見学した上で、契約するかどうかを決めたほうがいいですよ。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '見学した上で berarti ''setelah meninjau langsung''.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e6069632-2836-44c1-9ac5-999eb2548a51', '568c790b-1ac3-4b22-a9f9-418e58feed57', NULL, 'listening', 'listening_choice', 'Dengarkan komentar manajer HRD berikut. Apa yang dianggap penting dalam kepemimpinan?', '{"options":[{"id":"opt_1","text":"Memberi tugas sebanyak mungkin setiap hari"},{"id":"opt_2","text":"Menghindari rapat tatap muka dengan anggota tim"},{"id":"opt_3","text":"Sikap mendengarkan perkataan lawan bicara hingga selesai saat membimbing bawahan"},{"id":"opt_4","text":"Membuat aturan tertulis sepanjang seratus halaman"}],"audio_text":"部下を指導する上で、相手の話を最後まで聞く姿勢が不可欠です。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '部下を指導する上で berarti ''dalam hal membimbing bawahan''.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4aea9cc7-42e1-48e6-99a8-e6d990dd6e79', '568c790b-1ac3-4b22-a9f9-418e58feed57', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman rapat berikut. Apa yang akan dilakukan setelah melihat data survei?', '{"options":[{"id":"opt_1","text":"Menghentikan seluruh layanan pelanggan mulai minggu depan"},{"id":"opt_2","text":"Membagikan hadiah kepada seluruh responden survei"},{"id":"opt_3","text":"Menghapus hasil survei yang lama dari server"},{"id":"opt_4","text":"Merangkum langkah perbaikan bulan depan setelah menganalisis hasil survei pelanggan"}],"audio_text":"顧客アンケートの結果を分析した上で、来月の改善策をまとめる予定です。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '分析した上で (setelah menganalisis) → 改善策をまとめる (merangkum rencana perbaikan).', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c7fb8cd8-345e-45f2-a722-b32ff4c69049', '568c790b-1ac3-4b22-a9f9-418e58feed57', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 複数の会社の条件を___上で、最も適した取引先を選んだ。', '{"options":["比較した","比較する","比較して","比較せず"],"translation":"Setelah membandingkan ketentuan beberapa perusahaan, kami memilih mitra bisnis yang paling sesuai.","sentence_template":"複数の会社の条件を[blank]上で、最も適した取引先を選んだ。"}'::jsonb, '{"selected":"比較した"}'::jsonb, NULL, NULL, 'Urutan aksi ''membandingkan dulu, lalu memilih'' memakai bentuk lampau 比較した上で.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d6adb71c-7888-45bd-ae0e-826bc76656f6', '568c790b-1ac3-4b22-a9f9-418e58feed57', NULL, 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 国際ビジネスを展開___上で、現地法規の遵守は絶対条件だ。', '{"options":["する","した","して","された"],"translation":"Dalam mengembangkan bisnis internasional, kepatuhan terhadap hukum setempat adalah syarat mutlak.","sentence_template":"国際ビジネスを展開[blank]上で、現地法規の遵守は絶対条件だ。"}'::jsonb, '{"selected":"する"}'::jsonb, NULL, NULL, '展開する上で menyatakan ruang lingkup/konteks ''dalam mengembangkan...''.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f1441c7a-17da-49a2-9430-1c1356737a9c', '568c790b-1ac3-4b22-a9f9-418e58feed57', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah memahami risiko dan manfaatnya, mari kita ambil keputusan."', '{"romaji":"Meritto to demeritto o rikai shita ue de, handan shimashou.","display_text":"メリットとデメリットを理解した上で、判断しましょう。","phonetic_breakdown":["めりっとと","でめりっとを","りかいした","うえで","はんだんしましょう"]}'::jsonb, '{"expected_transcript":"メリットとデメリットを理解した上で、判断しましょう。"}'::jsonb, NULL, NULL, 'メリット (kelebihan) dan デメリット (kekurangan) sangat umum dalam rapat bisnis Jepang.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e446ae39-221c-41ce-8875-d6fca397fb9e', '568c790b-1ac3-4b22-a9f9-418e58feed57', 'd1000019-0000-0000-0000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat: "Dalam hal memelihara kesehatan, keseimbangan makan dan tidur sangat menentukan."', '{"romaji":"Kenkou o iji suru ue de, shokuji to suimin no baransu ga juuyou da.","tokens":["維持する","食事と睡眠の","重要だ。","かねない。","健康を","上で、","バランスが","維持した"],"target_translation":"Dalam hal memelihara kesehatan, keseimbangan makan dan tidur sangat menentukan."}'::jsonb, '["健康を","維持する","上で、","食事と睡眠の","バランスが","重要だ。"]'::jsonb, NULL, NULL, '維持する上で (dalam hal menjaga/memelihara) memakai verba bentuk kamus.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dfc575b8-de52-446a-afd0-65487c3813d9', '568c790b-1ac3-4b22-a9f9-418e58feed57', 'd1000019-0000-0000-0000-000000000024', 'listening', 'listening_choice', 'Dengarkan pengumuman bank. Apa syarat sebelum mengajukan pinjaman?', '{"options":[{"id":"opt_1","text":"Mengajukan pinjaman tanpa rencana pengembalian"},{"id":"opt_2","text":"Menyusun rencana pelunasan masa depan yang realistis terlebih dahulu sebelum mendaftar"},{"id":"opt_3","text":"Melunasi pinjaman dalam waktu satu hari"},{"id":"opt_4","text":"Menutup seluruh rekening tabungan sebelum mendaftar"}],"audio_text":"将来の返済計画を無理なく立てた上で、お申し込みいただくようお願いしております。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '無理なく立てた上で berarti setelah menyusun rencana secara realistis tanpa memaksakan diri.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('976ac7d6-e0d5-48d1-8099-5cd670018261', '5723189e-54c6-43ef-8364-ce9d5564c652', 'd1000019-0000-0000-0000-000000000027', 'reading', 'fill_blank', 'Pilih Sonkeigo yang tepat: 社長が明日の式典でご挨拶を___予定です。', '{"options":["なさる","いたす","申す","伺う"],"translation":"Direktur Utama dijadwalkan memberikan kata sambutan pada upacara besok.","sentence_template":"社長が明日の式典でご挨拶を[blank]予定です。"}'::jsonb, '{"selected":"なさる"}'::jsonb, NULL, NULL, 'ご挨拶をなさる menggunakan なさる (Sonkeigo dari する) untuk meninggikan tindakan Direktur Utama.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3328c6c2-82e1-46ce-9b5e-4cba8b7e121d', '5723189e-54c6-43ef-8364-ce9d5564c652', 'd1000019-0000-0000-0000-000000000027', 'reading', 'fill_blank', 'Lengkapi kalimat gabungan N2 berikut: 新規事業の発足___、社長より今後の展望についてお話がございました。', '{"options":["にあたり","かねない","つつある","ざるを得ない"],"translation":"Pada kesempatan peluncuran bisnis baru, ada sambutan dari Direktur Utama mengenai prospek ke depan.","sentence_template":"新規事業の発足[blank]、社長より今後の展望についてお話がございました。"}'::jsonb, '{"selected":"にあたり"}'::jsonb, NULL, NULL, 'Menggabungkan pola Unit 1 (～にあたり) dan bahasa hormat Unit 10 (お話がございました).', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d4c4aa1c-160c-4ed5-bc92-378d2391e5fe', '5723189e-54c6-43ef-8364-ce9d5564c652', 'd1000019-0000-0000-0000-000000000027', 'listening', 'listening_choice', 'Dengarkan percakapan bisnis berikut. Apa yang akan dilakukan pembicara setelah ini?', '{"options":[{"id":"opt_1","text":"Merapikan ruang tamu segera setelah klien pulang"},{"id":"opt_2","text":"Mengantar klien ke bandara dengan mobil perusahaan"},{"id":"opt_3","text":"Memesan makan siang untuk rapat sore"},{"id":"opt_4","text":"Menghubungi cabang luar negeri lewat telepon"}],"audio_text":"お客様がお帰りになりましたら、すぐに応接室の片付けをしてまいります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'お帰りになりましたら (Sonkeigo untuk klien) diikuti してまいります (Kenjougo untuk diri sendiri).', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('826b275a-e93c-42cd-90c5-a36b2e93f191', '5723189e-54c6-43ef-8364-ce9d5564c652', 'd1000019-0000-0000-0000-000000000027', 'listening', 'listening_choice', 'Dengarkan sambutan penutup berikut. Apa harapan pembicara?', '{"options":[{"id":"opt_1","text":"Menghentikan kerja sama setelah proyek ini selesai"},{"id":"opt_2","text":"Menunda pembahasan usulan hingga tahun depan"},{"id":"opt_3","text":"Terus berkembang bersama seluruh pihak berdasarkan usulan yang diterima hari ini"},{"id":"opt_4","text":"Memindahkan seluruh kegiatan rapat ke sistem daring"}],"audio_text":"本日の会議でご提案いただいた内容を踏まえ、今後も皆様と協力して発展してまいりたいと存じます。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'ご提案いただいた内容 (isi usulan yang Anda berikan) + 発展してまいりたいと存じます (kami ingin terus berkembang bersama).', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ba043181-414f-4e20-825e-55072901d553', '5723189e-54c6-43ef-8364-ce9d5564c652', 'd1000019-0000-0000-0000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat: "Apakah Bapak Profesor sudah menerima surat undangan dari kami?"', '{"romaji":"Sensei wa watakushidomo no annaijou o ouketori ni narimashita ka.","tokens":["申し上げ","お受け取りに","私どもの","先生は","なりましたか。","案内状を","お受け取りいたし"],"target_translation":"Apakah Bapak Profesor sudah menerima surat undangan dari kami?"}'::jsonb, '["先生は","私どもの","案内状を","お受け取りに","なりましたか。"]'::jsonb, NULL, NULL, '私ども (kami, sangat sopan) dan お受け取りになる (menerima, Sonkeigo).', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ec798b8e-5098-4a70-92a1-921d93a49deb', '5723189e-54c6-43ef-8364-ce9d5564c652', 'd1000019-0000-0000-0000-000000000027', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dengan bekal bahasa Jepang N2 ini, saya siap berkarya secara profesional di Jepang."', '{"romaji":"Kono Nihongoryoku o ikashite, Nihon no shokuba de katsuyaku dekiru you doryoku shite mairimasu.","display_text":"この日本語力を活かして、日本の職場で活躍できるよう努力してまいります。","phonetic_breakdown":["このにほんごりょくを","いかして","にほんのしょくばで","かつやくできるよう","どりょくしてまいります"]}'::jsonb, '{"expected_transcript":"この日本語力を活かして、日本の職場で活躍できるよう努力してまいります。"}'::jsonb, NULL, NULL, 'Kalimat penutup yang sangat kuat dan alami untuk wawancara kerja profesional maupun beasiswa di Jepang.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('793554d2-dc83-4a8e-b036-12f27bff1f9f', '5723189e-54c6-43ef-8364-ce9d5564c652', 'd1000019-0000-0000-0000-000000000027', 'listening', 'listening_choice', 'Dengarkan pengumuman di ruang seminar. Apa yang diminta panitia kepada hadirin?', '{"options":[{"id":"opt_1","text":"Hadirin diminta meninggalkan gedung seminar"},{"id":"opt_2","text":"Acara seminar diundur dua jam"},{"id":"opt_3","text":"Hadirin yang belum duduk dipersilakan maju ke bagian depan karena kuliah segera dimulai"},{"id":"opt_4","text":"Hadirin dilarang membawa catatan ke dalam ruangan"}],"audio_text":"まもなく講演が始まりますので、まだお席に着いていらっしゃらない方は前方へお進みください。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '着いていらっしゃらない方 menggunakan sonkeigo ～ていらっしゃる secara tepat dan sopan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2e284ea0-5b35-4919-adbc-66bfae6a039b', '5723189e-54c6-43ef-8364-ce9d5564c652', 'd1000019-0000-0000-0000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat: "Bapak Presiden Direktur berkenan menyampaikan pesan penyemangat kepada seluruh staf."', '{"romaji":"Shachou wa zenshain ni hagemashi no okotoba o kudasaimashita.","tokens":["全社員に","お言葉を","ました。","いたし","社長は","励ましの","ください","さしあげ"],"target_translation":"Bapak Presiden Direktur berkenan menyampaikan pesan penyemangat kepada seluruh staf."}'::jsonb, '["社長は","全社員に","励ましの","お言葉を","ください","ました。"]'::jsonb, NULL, NULL, 'お言葉をくださいました menggunakan sonkeigo くださる untuk tindakan memberi pesan dari atasan tertinggi.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d1a9f078-c623-4855-958b-8e091fe46067', '596f6362-f8ac-4b6f-9796-19bcd63392a5', 'd1000019-0000-0000-0000-000000000020', 'listening', 'listening_choice', 'Dengarkan pengumuman festival kota. Siapa yang boleh berpartisipasi?', '{"options":[{"id":"opt_1","text":"Warga setempat maupun siapa saja yang bekerja atau bersekolah di kota tersebut"},{"id":"opt_2","text":"Hanya petugas pemadam kebakaran profesional"},{"id":"opt_3","text":"Hanya pemilik rumah yang tinggal lebih dari lima tahun"},{"id":"opt_4","text":"Hanya mahasiswa asing yang tinggal di asrama"}],"audio_text":"地域の防災訓練は地元住民に限らず、市内に通勤・通学している方ならどなたでも参加できます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '地元住民に限らず memperluas peserta kepada pekerja dan pelajar komuter di kota tersebut.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c583858d-b8aa-4c71-a75c-19cfcb5b9cfd', '596f6362-f8ac-4b6f-9796-19bcd63392a5', 'd1000019-0000-0000-0000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat: "Bukan hanya musim panas, tetapi sepanjang tahun kita perlu menjaga asupan cairan."', '{"romaji":"Natsu ni kagirazu, ichinenjuu suibun hokyuu o kokorogakeru beki da.","tokens":["に限らず、","水分補給を","べきだ。","心がけた","夏","一年中","心がける","にあたって、"],"target_translation":"Bukan hanya musim panas, tetapi sepanjang tahun kita perlu menjaga asupan cairan."}'::jsonb, '["夏","に限らず、","一年中","水分補給を","心がける","べきだ。"]'::jsonb, NULL, NULL, '夏に限らず (tidak hanya musim panas) + 一年中 (sepanjang tahun) menunjukkan perluasan waktu.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c9e0e933-f37c-42cb-865f-23f7334e79ca', '596f6362-f8ac-4b6f-9796-19bcd63392a5', 'd1000019-0000-0000-0000-000000000020', 'reading', 'fill_blank', 'Pilih pola yang sesuai: 近年は都市部___、地方でも空き家を活用したカフェが増えている。', '{"options":["に限らず","に伴い","かねず","つつあり"],"translation":"Belakangan ini, tidak terbatas pada wilayah perkotaan, di daerah pun kafe yang memanfaatkan rumah kosong makin bertambah.","sentence_template":"近年は都市部[blank]、地方でも空き家を活用したカフェが増えている。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, NULL, NULL, '都市部に限らず、地方でも menyajikan perluasan geografis.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bbac2b93-7a56-4171-83f4-29abeae0ade9', '596f6362-f8ac-4b6f-9796-19bcd63392a5', 'd1000019-0000-0000-0000-000000000020', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Olahraga ini dapat dinikmati oleh siapa saja, tanpa terbatas usia maupun gender."', '{"romaji":"Kono supootsu wa nenrei ya seibetsu ni kagirazu, dare demo kigaru ni tanoshimemasu.","display_text":"このスポーツは年齢や性別に限らず、誰でも気軽に楽しめます。","phonetic_breakdown":["このすぽーつは","ねんれいや","せいべつに","かぎらず","だれでも","きがるにたのしめます"]}'::jsonb, '{"expected_transcript":"このスポーツは年齢や性別に限らず、誰でも気軽に楽しめます。"}'::jsonb, NULL, NULL, '年齢や性別に限らず adalah ungkapan inklusif yang sangat lazim dalam brosur layanan.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('07397db3-8b50-4411-9bc3-4b4822fccaa0', '596f6362-f8ac-4b6f-9796-19bcd63392a5', 'd1000019-0000-0000-0000-000000000020', 'reading', 'fill_blank', 'Lengkapi kalimat akademis: 歴史研究においては、文献資料___現地調査も欠かせない。', '{"options":["に限らず","にあたって","ざるを得ず","わけにはいかず"],"translation":"Dalam penelitian sejarah, tidak hanya dokumen tertulis, survei lapangan pun tidak boleh terlewatkan.","sentence_template":"歴史研究においては、文献資料[blank]現地調査も欠かせない。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, NULL, NULL, '文献資料に限らず、現地調査も menegaskan keduanya sama-sama esensial.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a5f288b6-fb38-4bc4-bc2c-14797d576feb', '596f6362-f8ac-4b6f-9796-19bcd63392a5', 'd1000019-0000-0000-0000-000000000020', 'listening', 'listening_choice', 'Dengarkan penjelasan pustakawan. Fasilitas apa yang tersedia di lantai dua?', '{"options":[{"id":"opt_1","text":"Hanya menyediakan koran harian lokal"},{"id":"opt_2","text":"Ditutup sementara untuk renovasi"},{"id":"opt_3","text":"Khusus untuk ruang makan siang mahasiswa"},{"id":"opt_4","text":"Menyediakan akses buku cetak, jurnal elektronik, serta materi video"}],"audio_text":"二階の学習スペースは紙の書籍に限らず、電子ジャーナルや映像資料も自由に閲覧できます。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '紙の書籍に限らず diikuti 電子ジャーナルや映像資料も (juga jurnal elektronik dan materi video).', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3d53845e-fc4d-40bc-8815-bb7661dc284e', '596f6362-f8ac-4b6f-9796-19bcd63392a5', 'd1000019-0000-0000-0000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat: "Tidak hanya bahasa Inggris, kemampuan bahasa Jepang juga membuka peluang karier luas."', '{"romaji":"Eigo ni kagirazu, Nihongo no nouryoku mo kyaria no kanousei o hirogeru.","tokens":["に限らず、","キャリアの","広げる。","広げた","英語","日本語の能力も","可能性を","に伴って、"],"target_translation":"Tidak hanya bahasa Inggris, kemampuan bahasa Jepang juga membuka peluang karier luas."}'::jsonb, '["英語","に限らず、","日本語の能力も","キャリアの","可能性を","広げる。"]'::jsonb, NULL, NULL, '英語に限らず、日本語の能力も menghubungkan dua hal yang sama-sama memberi manfaat.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0156f98d-647d-4228-ad24-83f2efe47f20', '596f6362-f8ac-4b6f-9796-19bcd63392a5', 'd1000019-0000-0000-0000-000000000020', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tidak hanya kualitas produk, layanan purnajual juga menentukan kepercayaan pelanggan."', '{"romaji":"Seihin no hinshitsu ni kagirazu, afutaa saabisu mo kokyaku no shinrai o sayuu shimasu.","display_text":"製品の品質に限らず、アフターサービスも顧客の信頼を左右します。","phonetic_breakdown":["せいひんの","ひんしつに","かぎらず","あふたーさーびすも","こきゃくのしんらいを","さゆうします"]}'::jsonb, '{"expected_transcript":"製品の品質に限らず、アフターサービスも顧客の信頼を左右します。"}'::jsonb, NULL, NULL, '信頼を左右する berarti sangat menentukan kepercayaan pelanggan.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b32cba28-4745-441e-8eed-c3dd076aca3b', '5fd7ee1c-190e-4b21-ba7d-04a1aaa6326c', 'd1000019-0000-0000-0000-000000000018', 'reading', 'fill_blank', 'Lengkapi pola tata bahasa N2: 新支社を設立する___、現地の市場調査を徹底的に行った。', '{"options":["にあたって","に限らず","にもかかわらず","かねない"],"translation":"Menjelang pendirian kantor cabang baru, kami melakukan riset pasar lokal secara menyeluruh.","sentence_template":"新支社を設立する[blank]、現地の市場調査を徹底的に行った。"}'::jsonb, '{"selected":"にあたって"}'::jsonb, NULL, NULL, 'V-dict + にあたって menyatakan momen penting yang akan dimulai dan persiapan yang dilakukan.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4d73dfda-7c82-4f15-a1c7-2787d2899904', '5fd7ee1c-190e-4b21-ba7d-04a1aaa6326c', 'd1000019-0000-0000-0000-000000000018', 'reading', 'fill_blank', 'Pilih bentuk yang paling formal untuk pidato: 開会式を始める___、一言ご挨拶申し上げます。', '{"options":["にあたり","に伴って","つつあり","ざるを得ず"],"translation":"Pada kesempatan dimulainya upacara pembukaan, izinkan saya menyampaikan sepatah kata sambutan.","sentence_template":"開会式を始める[blank]、一言ご挨拶申し上げます。"}'::jsonb, '{"selected":"にあたり"}'::jsonb, NULL, NULL, '～にあたり adalah bentuk tulisan/pidato yang lebih ringkas dan formal dari ～にあたって.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c29cd855-3c6a-4583-aa3f-33d2bcef0cae', '5fd7ee1c-190e-4b21-ba7d-04a1aaa6326c', 'd1000019-0000-0000-0000-000000000018', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 留学生活の開始___、必要な手続きを確認しておこう。', '{"options":["にあたって","においての","にしては","にわたって"],"translation":"Menjelang dimulainya kehidupan studi di luar negeri, mari kita pastikan prosedur yang diperlukan.","sentence_template":"留学生活の開始[blank]、必要な手続きを確認しておこう。"}'::jsonb, '{"selected":"にあたって"}'::jsonb, NULL, NULL, 'Kata benda (開始) dapat langsung diikuti にあたって untuk menyatakan ''menjelang dimulainya...''.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('78caabfe-876e-433f-866a-001b13a01ce6', '5fd7ee1c-190e-4b21-ba7d-04a1aaa6326c', 'd1000019-0000-0000-0000-000000000018', 'writing', 'sentence_builder', 'Susun kalimat: "Menjelang pelaksanaan acara, kami mengadakan rapat terakhir."', '{"romaji":"Ibento no jisshi ni atatte, saishuu uchiawase o okonatta.","tokens":["イベントの","打ち合わせを","最終","にあたって、","実施","行った。","かねない。","にもかかわらず、"],"target_translation":"Menjelang pelaksanaan acara, kami mengadakan rapat terakhir."}'::jsonb, '["イベントの","実施","にあたって、","最終","打ち合わせを","行った。"]'::jsonb, NULL, NULL, 'Pola [Kata Benda] + にあたって menghubungkan momen penting dengan persiapan konkret.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('60446491-6b1a-4682-bdad-c1c88aed68df', '5fd7ee1c-190e-4b21-ba7d-04a1aaa6326c', 'd1000019-0000-0000-0000-000000000018', 'writing', 'sentence_builder', 'Susun kalimat: "Dalam rangka peluncuran produk baru, kami menyusun strategi pemasaran."', '{"romaji":"Shinseihin o hatsubai suru ni atari, hanbai senryaku o tateta.","tokens":["にあたり、","立てた。","発売した","に限らず、","戦略を","新製品を","販売","発売する"],"target_translation":"Dalam rangka peluncuran produk baru, kami menyusun strategi pemasaran."}'::jsonb, '["新製品を","発売する","にあたり、","販売","戦略を","立てた。"]'::jsonb, NULL, NULL, 'Sebelum にあたり, verba selalu memakai bentuk kamus (発売する), bukan bentuk lampau.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5695aac-66bd-4264-b8b1-8ae9822eeee7', '5fd7ee1c-190e-4b21-ba7d-04a1aaa6326c', 'd1000019-0000-0000-0000-000000000018', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Menjelang dimulainya kuliah semester baru, saya membeli buku referensi."', '{"romaji":"Shingakki no kaishi ni atatte, sankousho o kounyuu shimashita.","display_text":"新学期の開始にあたって、参考書を購入しました。","phonetic_breakdown":["しんがっきの","かいしに","あたって","さんこうしょを","こうにゅうしました"]}'::jsonb, '{"expected_transcript":"新学期の開始にあたって、参考書を購入しました。"}'::jsonb, NULL, NULL, '購入する (kounyuu suru) adalah padanan formal dari 買う yang cocok dipasangkan dengan ～にあたって.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6bbf8aee-a2b1-46db-a9fc-0e2b7b87be8e', '5fd7ee1c-190e-4b21-ba7d-04a1aaa6326c', 'd1000019-0000-0000-0000-000000000018', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Manakah pernyataan yang sesuai dengan isi audio?', '{"options":[{"id":"opt_1","text":"Perusahaan tidak meminta masukan sebelum mengubah sistem"},{"id":"opt_2","text":"Perusahaan menjaring masukan luas dari staf lapangan menjelang penerapan sistem baru"},{"id":"opt_3","text":"Sistem baru dibatalkan karena penolakan staf lapangan"},{"id":"opt_4","text":"Staf lapangan diminta membuat sistem sendiri tanpa panduan"}],"audio_text":"新制度を導入するにあたって、現場の担当者から広く意見を募った。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '意見を募る (menjaring pendapat) dilakukan menjelang penerapan sistem baru (導入するにあたって).', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f331e554-54ba-4d4b-8674-aeab96ea1774', '5fd7ee1c-190e-4b21-ba7d-04a1aaa6326c', 'd1000019-0000-0000-0000-000000000018', 'reading', 'fill_blank', 'Lengkapi kalimat dengan partikel penegas: 契約を更新する___、現行の料金体系を見直す必要がある。', '{"options":["にあたっては","にかかわらず","につれては","わけには"],"translation":"Dalam hal memperbarui kontrak, perlu meninjau kembali struktur tarif yang berlaku saat ini.","sentence_template":"契約を更新する[blank]、現行の料金体系を見直す必要がある。"}'::jsonb, '{"selected":"にあたっては"}'::jsonb, NULL, NULL, '～にあたっては menekankan persyaratan penting pada momen pembaruan kontrak.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d51848f7-3a5c-4f84-b5bc-75bab3d17305', '63b87eba-fca4-483d-a29c-9826d734208d', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat untuk melengkapi kalimat: 新規プロジェクトの___にあたり、関係者に資料を配布した。', '{"options":["実施","欠席","撤退","妥協"],"translation":"Menjelang pelaksanaan proyek baru, materi telah dibagikan kepada pihak terkait.","sentence_template":"新規プロジェクトの[blank]にあたり、関係者に資料を配布した。"}'::jsonb, '{"selected":"実施"}'::jsonb, NULL, NULL, '実施 (jisshi) berarti pelaksanaan atau implementasi resmi suatu proyek atau kebijakan.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7ab35d18-5413-42d6-b095-bd95b6bc1fe7', '63b87eba-fca4-483d-a29c-9826d734208d', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat bisnis berikut: 社長から今期の営業___について詳しい説明があった。', '{"options":["方針","気候","趣味","景色"],"translation":"Ada penjelasan rinci dari direktur utama mengenai kebijakan penjualan periode ini.","sentence_template":"社長から今期の営業[blank]について詳しい説明があった。"}'::jsonb, '{"selected":"方針"}'::jsonb, NULL, NULL, '方針 (houshin) berarti arah kebijakan atau pedoman strategis perusahaan.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('87625728-76d5-438b-b2af-ede06ecb7101', '63b87eba-fca4-483d-a29c-9826d734208d', NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: 式典の___に先立ち、司会者が注意事項を案内した。', '{"options":["開会","解散","閉店","休暇"],"translation":"Sebelum pembukaan upacara, pembawa acara menyampaikan hal-hal yang perlu diperhatikan.","sentence_template":"式典の[blank]に先立ち、司会者が注意事項を案内した。"}'::jsonb, '{"selected":"開会"}'::jsonb, NULL, NULL, '開会 (kaikai) berarti pembukaan rapat, seminar, atau upacara resmi.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('726336f4-8941-4088-965a-248c4ed63b55', '63b87eba-fca4-483d-a29c-9826d734208d', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman pembukaan rapat berikut. Apa yang disampaikan oleh pembicara?', '{"options":[{"id":"opt_1","text":"Mengucapkan terima kasih atas kerja sama para peserta rapat"},{"id":"opt_2","text":"Meminta peserta segera meninggalkan ruang rapat"},{"id":"opt_3","text":"Mengumumkan bahwa rapat ditunda hingga minggu depan"},{"id":"opt_4","text":"Menanyakan daftar menu makan siang setelah rapat"}],"audio_text":"会議の開会にあたり、まずは皆様のご協力に心より感謝申し上げます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Frasa ご協力に心より感謝申し上げます adalah ungkapan terima kasih yang sangat sopan di awal acara resmi.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d26ce4e9-3fea-47ba-bc4c-1b3e2c45decd', '63b87eba-fca4-483d-a29c-9826d734208d', NULL, 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Dokumen apa yang sedang dibahas?', '{"options":[{"id":"opt_1","text":"Jadwal liburan karyawan tahunan"},{"id":"opt_2","text":"Ketentuan rinci dalam kontrak baru"},{"id":"opt_3","text":"Laporan kerusakan mesin pabrik"},{"id":"opt_4","text":"Daftar hadir mahasiswa tingkat akhir"}],"audio_text":"新しい契約を結ぶ前に、法務部で細かい条件を確認する必要があります。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '契約を結ぶ (menandatangani kontrak) dan 細かい条件を確認する (memeriksa ketentuan rinci) adalah kosakata inti bisnis N2.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3025b138-2932-4c00-b22d-e41785c7d7ee', '63b87eba-fca4-483d-a29c-9826d734208d', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terima kasih banyak atas kerja sama Anda semua dalam proyek ini."', '{"romaji":"Hon purojekuto e no gokyouryoku, makoto ni arigatou gozaimasu.","display_text":"本プロジェクトへのご協力、誠にありがとうございます。","phonetic_breakdown":["ほん","ぷろじぇくと","えの","ごきょうりょく","まことに","ありがとうございます"]}'::jsonb, '{"expected_transcript":"本プロジェクトへのご協力、誠にありがとうございます。"}'::jsonb, NULL, NULL, '誠に (makoto ni) jauh lebih formal daripada 本当に dan sering dipakai dalam pidato atau email bisnis.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f933b7d2-694c-4f1b-a1f4-32544a8658a3', '63b87eba-fca4-483d-a29c-9826d734208d', 'd1000019-0000-0000-0000-000000000018', 'reading', 'fill_blank', 'Pilih istilah bisnis yang tepat: 新規事業の___にあたり、綿密な予算案が策定された。', '{"options":["立ち上げ","見送り","廃止","延期"],"translation":"Menjelang perintisan bisnis baru, rancangan anggaran yang cermat telah disusun.","sentence_template":"新規事業の[blank]にあたり、綿密な予算案が策定された。"}'::jsonb, '{"selected":"立ち上げ"}'::jsonb, NULL, NULL, '立ち上げ (tachiage) berarti peluncuran atau perintisan proyek/bisnis baru.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7b5a6dec-9cab-4fb8-8937-45cc0124ba67', '63b87eba-fca4-483d-a29c-9826d734208d', 'd1000019-0000-0000-0000-000000000018', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Menjelang pembukaan rapat umum, mohon matikan suara ponsel Anda."', '{"romaji":"Soukai no kaikai ni atari, keitai denwa no dengen o okiri kudasai.","display_text":"総会の開会にあたり、携帯電話の電源をお切りください。","phonetic_breakdown":["そうかいの","かいかいに","あたり","けいたいでんわの","でんげんを","おきりください"]}'::jsonb, '{"expected_transcript":"総会の開会にあたり、携帯電話の電源をお切りください。"}'::jsonb, NULL, NULL, 'お切りください adalah bentuk sopan untuk meminta hadirin mematikan perangkat.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8f7da4f7-2cbe-4484-892e-54d26b748076', '74a1ba4e-5047-4bcf-906f-40df5f5e62d0', 'd1000019-0000-0000-0000-000000000020', 'reading', 'fill_blank', 'Pilih pola yang paling sesuai: このデザインは専門家___、一般の利用者からも高く評価された。', '{"options":["に限らず","に伴って","にあたって","かねない"],"translation":"Desain ini mendapat penilaian tinggi tidak hanya dari para ahli, melainkan juga dari pengguna umum.","sentence_template":"このデザインは専門家[blank]、一般の利用者からも高く評価された。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, NULL, NULL, '専門家に限らず memperluas subjek pemberi evaluasi hingga ke pengguna umum.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('22e57338-cf2f-4ee7-9fb2-b7ce7217068d', '74a1ba4e-5047-4bcf-906f-40df5f5e62d0', 'd1000019-0000-0000-0000-000000000020', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 災害対策は地震___、台風や豪雨への備えも欠かせない。', '{"options":["に限らず","わけにはいかず","ざるを得ず","つつあり"],"translation":"Mitigasi bencana tidak terbatas pada gempa bumi, persiapan menghadapi topan dan hujan lebat juga tak boleh dilewatkan.","sentence_template":"災害対策は地震[blank]、台風や豪雨への備えも欠かせない。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, NULL, NULL, '災害対策 (mitigasi bencana) dan 備え (persiapan) adalah kosakata penting tinggal di Jepang.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d56b8fe4-1f2a-4fcc-9ad0-8cb6494a22ee', '74a1ba4e-5047-4bcf-906f-40df5f5e62d0', 'd1000019-0000-0000-0000-000000000020', 'listening', 'listening_choice', 'Dengarkan presentasi produk berikut. Mengapa desain aplikasi ini dipuji?', '{"options":[{"id":"opt_1","text":"Karena mudah digunakan semua orang, bukan hanya lansia"},{"id":"opt_2","text":"Karena hanya dapat diunduh secara gratis oleh lansia"},{"id":"opt_3","text":"Karena memiliki fitur permainan berbayar di dalamnya"},{"id":"opt_4","text":"Karena hanya memakai warna hitam dan putih"}],"audio_text":"文字の大きさや色使いを工夫した結果、高齢者に限らず誰にとっても使いやすいアプリになりました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '高齢者に限らず誰にとっても使いやすい berarti mudah digunakan siapa saja, tidak terbatas pada lansia.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('746194b7-c201-4f12-80d0-aadb72fb63d9', '74a1ba4e-5047-4bcf-906f-40df5f5e62d0', 'd1000019-0000-0000-0000-000000000020', 'listening', 'listening_choice', 'Dengarkan komentar dosen berikut. Apa pesan utamanya kepada mahasiswa?', '{"options":[{"id":"opt_1","text":"Fokus hanya pada satu buku wajib di semester ini"},{"id":"opt_2","text":"Kurangi jumlah mata kuliah pilihan di luar jurusan"},{"id":"opt_3","text":"Kuasai pengetahuan luas, tidak terbatas pada bidang spesialisasi sendiri"},{"id":"opt_4","text":"Segera tentukan topik skripsi sebelum kuliah dimulai"}],"audio_text":"自分の専門分野に限らず、幅広い知識を身につけることが将来の研究に役立ちます。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '専門分野に限らず (tidak terbatas pada bidang spesialisasi) + 幅広い知識 (pengetahuan luas).', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7babd678-60e5-482f-86b4-f3fe5cf02b90', '74a1ba4e-5047-4bcf-906f-40df5f5e62d0', 'd1000019-0000-0000-0000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat: "Tidak terbatas pada kopi, kafe ini menyediakan berbagai teh herbal."', '{"romaji":"Kono kafe wa koohii ni kagirazu, samazamana haabutii mo soroete iru.","tokens":["ハーブティーも","コーヒーを","揃えている。","このカフェは","にあたって、","様々な","に限らず、","コーヒー"],"target_translation":"Tidak terbatas pada kopi, kafe ini menyediakan berbagai teh herbal."}'::jsonb, '["このカフェは","コーヒー","に限らず、","様々な","ハーブティーも","揃えている。"]'::jsonb, NULL, NULL, '揃えている (menyediakan secara lengkap) sering dipakai untuk menu atau koleksi barang.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ff486dd9-fe44-4b02-85e8-b9d93272ff31', '74a1ba4e-5047-4bcf-906f-40df5f5e62d0', 'd1000019-0000-0000-0000-000000000020', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tidak terbatas pada perusahaan besar, perusahaan rintisan pun mulai merekrut secara global."', '{"romaji":"Daikigyou ni kagirazu, benchaa kigyou demo guroobaru saiyou ga susunde imasu.","display_text":"大企業に限らず、ベンチャー企業でもグローバル採用が進んでいます。","phonetic_breakdown":["だいきぎょうに","かぎらず","べんちゃー","きぎょうでも","ぐろーばるさいようが","すすんでいます"]}'::jsonb, '{"expected_transcript":"大企業に限らず、ベンチャー企業でもグローバル採用が進んでいます。"}'::jsonb, NULL, NULL, 'ベンチャー企業 (perusahaan rintisan/startup) dan グローバル採用 (rekrutmen global) populer di dunia karier Jepang.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ef2a9275-3716-4ce0-a845-74643959ae79', '74a1ba4e-5047-4bcf-906f-40df5f5e62d0', 'd1000019-0000-0000-0000-000000000020', 'listening', 'listening_choice', 'Dengarkan komentar pengamat teknologi. Apa kesimpulannya?', '{"options":[{"id":"opt_1","text":"Serangan siber kini menyasar bukan hanya perusahaan IT besar, melainkan juga rumah sakit dan pemda"},{"id":"opt_2","text":"Hanya perusahaan IT besar yang pernah mengalami serangan siber"},{"id":"opt_3","text":"Rumah sakit sepenuhnya aman dari ancaman peretasan"},{"id":"opt_4","text":"Pemerintah daerah tidak menggunakan sistem digital"}],"audio_text":"サイバー攻撃の標的は大手IT企業に限らず、病院や自治体にも広がっている。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '大手IT企業に限らず、病院や自治体にも広がっている menjelaskan perluasan target ancaman.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('111e3da7-1a35-41e2-a849-65edbf72c498', '74a1ba4e-5047-4bcf-906f-40df5f5e62d0', 'd1000019-0000-0000-0000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat: "Tidak hanya membaca buku, berdiskusi dengan orang lain juga memperdalam pemahaman."', '{"romaji":"Dokusho ni kagirazu, tanin to no giron mo rikai o fukameru koto ga dekiru.","tokens":["に限らず、","理解を","ことができる。","深めた","読書","他人との議論も","深める","にあたり、"],"target_translation":"Tidak hanya membaca buku, berdiskusi dengan orang lain juga memperdalam pemahaman."}'::jsonb, '["読書","に限らず、","他人との議論も","理解を","深める","ことができる。"]'::jsonb, NULL, NULL, '読書に限らず + 他人との議論も memperluas metode belajar.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dc1f6592-ad97-4d24-9dd4-d864e181c5b4', '800f76e6-fe8d-45f0-949c-993df6ad1bc9', NULL, 'listening', 'listening_choice', 'Dengarkan berita berikut. Dampak apa yang muncul akibat pembangunan stasiun baru?', '{"options":[{"id":"opt_1","text":"Harga tanah dan sewa apartemen di sekitarnya naik"},{"id":"opt_2","text":"Jumlah penumpang bus antarkota meningkat tajam"},{"id":"opt_3","text":"Sekolah dasar di sekitar stasiun ditutup sementara"},{"id":"opt_4","text":"Lahan parkir gratis ditambah di pusat perbelanjaan"}],"audio_text":"新駅の開業に伴い、周辺の地価やマンションの家賃が上昇している。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '周辺の地価 (harga tanah sekitar) dan 家賃 (biaya sewa) naik seiring pembukaan stasiun baru (新駅の開業).', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('581815cf-9127-45f7-ad88-29ea95c405df', '800f76e6-fe8d-45f0-949c-993df6ad1bc9', NULL, 'listening', 'listening_choice', 'Dengarkan komentar analis berikut. Mengapa perusahaan memperbarui sistem keamanan?', '{"options":[{"id":"opt_1","text":"Karena biaya langganan server turun drastis"},{"id":"opt_2","text":"Karena risiko serangan siber naik seiring meluasnya layanan cloud"},{"id":"opt_3","text":"Karena karyawan diminta bekerja tanpa internet"},{"id":"opt_4","text":"Karena kontrak dengan penyedia lama telah berakhir"}],"audio_text":"クラウドサービスの利用拡大に伴って、サイバー攻撃のリスクも高まっているためです。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '利用拡大に伴って (seiring meluasnya penggunaan) risiko serangan siber ikut meningkat.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c6af336f-3f92-47a1-bea1-124c4f0c583d', '800f76e6-fe8d-45f0-949c-993df6ad1bc9', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan logistik berikut. Apa yang berubah?', '{"options":[{"id":"opt_1","text":"Jam operasional gudang diperpanjang hingga malam"},{"id":"opt_2","text":"Layanan pengiriman ke luar negeri dihentikan total"},{"id":"opt_3","text":"Biaya pengiriman di sebagian wilayah akan disesuaikan bulan depan"},{"id":"opt_4","text":"Semua pelanggan mendapatkan diskon pengiriman bulan depan"}],"audio_text":"燃料費の高騰に伴い、来月より一部地域の配送料を改定させていただきます。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '配送料を改定する (menyesuaikan/merevisi tarif pengiriman) sering diumumkan dengan pola ～に伴い.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a2ff7473-c0df-4212-9220-e7622c8b3cfd', '800f76e6-fe8d-45f0-949c-993df6ad1bc9', NULL, 'reading', 'fill_blank', 'Lengkapi kutipan artikel berikut: 高齢化が進む___、医療や介護の費用も増大している。', '{"options":["に伴って","にあたって","わけにはいかない","に限らず"],"translation":"Seiring berlanjutnya penuaan penduduk, biaya medis dan perawatan lansia juga membengkak.","sentence_template":"高齢化が進む[blank]、医療や介護の費用も増大している。"}'::jsonb, '{"selected":"に伴って"}'::jsonb, NULL, NULL, '高齢化が進む (proses perubahan) diikuti に伴って lalu 費用が増大している (perubahan paralel).', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('04df35d9-dff4-4a25-8114-8a09c2c745df', '800f76e6-fe8d-45f0-949c-993df6ad1bc9', NULL, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 業務のデジタル化___コスト削減が、今年度の重要課題だ。', '{"options":["に伴う","に伴って","にあたり","にかかわらず"],"translation":"Pengurangan biaya yang menyertai digitalisasi operasional merupakan agenda penting tahun fiskal ini.","sentence_template":"業務のデジタル化[blank]コスト削減が、今年度の重要課題だ。"}'::jsonb, '{"selected":"に伴う"}'::jsonb, NULL, NULL, 'Karena langsung memodifikasi kata benda コスト削減, bentuk yang benar adalah ～に伴う.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('923835d4-14d4-435c-9db8-d8e114ebce4c', '800f76e6-fe8d-45f0-949c-993df6ad1bc9', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring perluasan pasar Asia, kebutuhan staf berbahasa asing meningkat."', '{"romaji":"Ajia shijou no kakudai ni tomonai, gogakuryoku no aru jinzai ga motomerarete imasu.","display_text":"アジア市場の拡大に伴い、語学力のある人材が求められています。","phonetic_breakdown":["あじあ","しじょうの","かくだいに","ともない","ごがくりょくのある","じんざいが","もとめられています"]}'::jsonb, '{"expected_transcript":"アジア市場の拡大に伴い、語学力のある人材が求められています。"}'::jsonb, NULL, NULL, '語学力のある人材 (SDM yang memiliki kemampuan bahasa) adalah frasa umum dalam rekrutmen global Jepang.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('be39d147-4e67-48c2-b0e4-33c7c37d370c', '800f76e6-fe8d-45f0-949c-993df6ad1bc9', 'd1000019-0000-0000-0000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat: "Seiring dengan pertumbuhan ekonomi, konsumsi energi meningkat tajam."', '{"romaji":"Keizai no seichou ni tomonatte, enerugii shouhi ga kyuuzou shita.","tokens":["成長","エネルギー消費が","した。","急増する","経済の","に伴って、","急増","にあたって、"],"target_translation":"Seiring dengan pertumbuhan ekonomi, konsumsi energi meningkat tajam."}'::jsonb, '["経済の","成長","に伴って、","エネルギー消費が","急増","した。"]'::jsonb, NULL, NULL, '成長に伴って + 急増した menggambarkan lonjakan konsumsi energi.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('419f5fc8-b1d3-488e-9742-eb270cb495e8', '800f76e6-fe8d-45f0-949c-993df6ad1bc9', 'd1000019-0000-0000-0000-000000000019', 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan kereta. Apa yang terjadi saat jam sibuk?', '{"options":[{"id":"opt_1","text":"Tiga kereta ekspres tambahan dioperasikan pada jam komuter hari kerja"},{"id":"opt_2","text":"Semua kereta ekspres dihapus pada hari kerja"},{"id":"opt_3","text":"Tarif tiket komuter dinaikkan tiga kali lipat"},{"id":"opt_4","text":"Stasiun ditutup lebih awal pada hari kerja"}],"audio_text":"ダイヤ改正に伴い、平日の通勤時間帯に急行列車が三本増発されます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '増発されます berarti jumlah keberangkatan kereta ditambah.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5f78d973-13d8-4308-96eb-4b30f3925dac', '80b7aa29-8374-4abd-b2b2-bf3477478e9f', NULL, 'listening', 'listening_choice', 'Dengarkan iklan fasilitas berikut. Kapan kafe tersebut ramai pengunjung?', '{"options":[{"id":"opt_1","text":"Hanya pada hari kerja saat jam makan siang"},{"id":"opt_2","text":"Baik pada hari kerja maupun akhir pekan"},{"id":"opt_3","text":"Hanya pada malam hari menjelang tutup"},{"id":"opt_4","text":"Khusus saat hari libur nasional saja"}],"audio_text":"駅前の新しいカフェは平日に限らず、週末もビジネス客や学生で賑わっている。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '平日に限らず、週末も berarti tidak terbatas pada hari kerja, akhir pekan pun ramai.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('31b91733-4111-4b28-8f42-3fe7d60870b8', '80b7aa29-8374-4abd-b2b2-bf3477478e9f', NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan kepala HRD berikut. Apa kebijakan perekrutan perusahaan itu?', '{"options":[{"id":"opt_1","text":"Hanya menerima lulusan baru dari universitas negeri"},{"id":"opt_2","text":"Menghentikan perekrutan karyawan baru tahun ini"},{"id":"opt_3","text":"Membuka peluang bagi lulusan baru maupun pelamar lintas industri"},{"id":"opt_4","text":"Hanya menerima pelamar dengan pengalaman di industri yang sama"}],"audio_text":"当社では新卒に限らず、異業種からの転職者も積極的に採用しています。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '新卒に限らず (tidak terbatas lulusan baru) dan 異業種からの転職者 (pelamar pindah karier dari industri berbeda).', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('be8ee979-ca22-4d1e-a653-ffb9166e9bfe', '80b7aa29-8374-4abd-b2b2-bf3477478e9f', NULL, 'listening', 'listening_choice', 'Dengarkan berita pariwisata berikut. Mengapa kota ini populer sepanjang tahun?', '{"options":[{"id":"opt_1","text":"Karena biaya hotel di sana selalu sangat murah"},{"id":"opt_2","text":"Karena mudah dijangkau dengan pesawat langsung"},{"id":"opt_3","text":"Karena terkenal dengan pusat perbelanjaan modernnya"},{"id":"opt_4","text":"Karena menawarkan keindahan di berbagai musim, bukan hanya musim sakura"}],"audio_text":"この観光地は桜の季節に限らず、秋の紅葉や冬の雪景色も魅力的だからです。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '桜の季節に限らず menegaskan daya tarik tidak terbatas pada musim semi saja.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0c12fa53-3134-4e87-b8a6-74ecd76761d7', '80b7aa29-8374-4abd-b2b2-bf3477478e9f', NULL, 'reading', 'fill_blank', 'Lengkapi bacaan bisnis berikut: 最近の消費者は価格___、企業の環境への取り組みも重視している。', '{"options":["に限らず","にあたって","わけにはいかず","ざるを得ず"],"translation":"Konsumen masa kini tidak hanya memperhatikan harga, tetapi juga mementingkan upaya lingkungan perusahaan.","sentence_template":"最近の消費者は価格[blank]、企業の環境への取り組みも重視している。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, NULL, NULL, '価格に限らず menunjukkan bahwa faktor penilaian konsumen meluas di luar harga semata.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cd2880b9-9935-4a2c-adae-0a5a7cbbe50e', '80b7aa29-8374-4abd-b2b2-bf3477478e9f', NULL, 'reading', 'fill_blank', 'Pilih partikel pelengkap yang alami: この図書館は本に限らず、電子資料や雑誌___利用できる。', '{"options":["も","だけ","しか","より"],"translation":"Perpustakaan ini tidak terbatas pada buku saja, melainkan juga menyediakan materi elektronik dan majalah.","sentence_template":"この図書館は本に限らず、電子資料や雑誌[blank]利用できる。"}'::jsonb, '{"selected":"も"}'::jsonb, NULL, NULL, 'Pola ～に限らず sangat sering berpasangan dengan partikel も di klausa berikutnya.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('15a5d9ee-fb51-4f44-8c27-8fdb0facc9c3', '80b7aa29-8374-4abd-b2b2-bf3477478e9f', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Di restoran ini, bukan hanya masakan Jepang, masakan Asia juga populer."', '{"romaji":"Kono resutoran de wa washoku ni kagirazu, Ajia ryouri mo ninki ga arimasu.","display_text":"このレストランでは和食に限らず、アジア料理も人気があります。","phonetic_breakdown":["このれすとらんでは","わしょくに","かぎらず","あじありょうりも","にんきがあります"]}'::jsonb, '{"expected_transcript":"このレストランでは和食に限らず、アジア料理も人気があります。"}'::jsonb, NULL, NULL, '和食 (washoku) berarti masakan Jepang; dipasangkan dengan も pada klausa kedua.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('95fe4e12-97b2-4f18-920b-e02285fce75d', '80b7aa29-8374-4abd-b2b2-bf3477478e9f', 'd1000019-0000-0000-0000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat: "Tidak hanya perusahaan besar, usaha kecil pun mulai menerapkan kerja fleksibel."', '{"romaji":"Daikigyou ni kagirazu, chuushou kigyou demo furekkusu seido ga hirogatte iru.","tokens":["に限らず、","フレックス制度が","いる。","広がった","大企業","中小企業でも","広がって","にもかかわらず、"],"target_translation":"Tidak hanya perusahaan besar, usaha kecil pun mulai menerapkan kerja fleksibel."}'::jsonb, '["大企業","に限らず、","中小企業でも","フレックス制度が","広がって","いる。"]'::jsonb, NULL, NULL, '大企業に限らず、中小企業でも adalah pasangan kontras-perluasan klasik di bacaan bisnis.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('359faa72-0d2d-4c86-bd06-9e0a949e380b', '80b7aa29-8374-4abd-b2b2-bf3477478e9f', 'd1000019-0000-0000-0000-000000000020', 'listening', 'listening_choice', 'Dengarkan informasi kursus memasak. Menu apa saja yang diajarkan?', '{"options":[{"id":"opt_1","text":"Hanya masakan tradisional Kyoto"},{"id":"opt_2","text":"Masakan Jepang, serta dasar-dasar masakan Italia dan etnik"},{"id":"opt_3","text":"Hanya pembuatan kue kering dan roti"},{"id":"opt_4","text":"Hanya teknik memotong ikan untuk koki profesional"}],"audio_text":"この料理教室では和食に限らず、イタリアンやエスニック料理の基本も学べます。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '和食に限らず diikuti イタリアンやエスニック料理の基本も.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3889cc8a-e58c-4479-a1f3-ee3e82e8c743', '81a58e2b-db8d-4e3c-bb71-96c0456fe598', 'd1000019-0000-0000-0000-000000000024', 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 双方の合意を___上で、正式な契約書に調印した。', '{"options":["確認した","確認する","確認して","確認せず"],"translation":"Setelah memastikan kesepakatan kedua belah pihak, kami menandatangani surat kontrak resmi.","sentence_template":"双方の合意を[blank]上で、正式な契約書に調印した。"}'::jsonb, '{"selected":"確認した"}'::jsonb, NULL, NULL, '調印する (menandatangani perjanjian resmi) dilakukan setelah 合意を確認した (memastikan kesepakatan).', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('845902fd-bc30-4829-95d8-19f66a67ab56', '81a58e2b-db8d-4e3c-bb71-96c0456fe598', 'd1000019-0000-0000-0000-000000000024', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 企業を経営___上で、法令遵守と顧客からの信頼は欠かせない。', '{"options":["する","した","して","された"],"translation":"Dalam mengelola perusahaan, kepatuhan hukum dan kepercayaan pelanggan tidak boleh terlewatkan.","sentence_template":"企業を経営[blank]上で、法令遵守と顧客からの信頼は欠かせない。"}'::jsonb, '{"selected":"する"}'::jsonb, NULL, NULL, '経営する上で berarti ''dalam hal mengelola (perusahaan)''.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a7633d7f-9715-4795-b505-09d8f43cd279', '81a58e2b-db8d-4e3c-bb71-96c0456fe598', 'd1000019-0000-0000-0000-000000000024', 'listening', 'listening_choice', 'Dengarkan arahan rapat berikut. Apa langkah pertama sebelum mengubah anggaran?', '{"options":[{"id":"opt_1","text":"Mendata secara menyeluruh seluruh data pengeluaran saat ini"},{"id":"opt_2","text":"Langsung memotong anggaran promosi sebesar lima puluh persen"},{"id":"opt_3","text":"Menunda rapat anggaran hingga kuartal berikutnya"},{"id":"opt_4","text":"Meminta pinjaman baru dari bank sebelum rapat dimulai"}],"audio_text":"現状の支出データをすべて洗い出した上で、来期の予算配分を見直しましょう。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '洗い出す (araidasu) berarti membongkar/mendata secara menyeluruh tanpa terlewat.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('281f083b-66c3-45b1-aaac-f0a529a3974a', '81a58e2b-db8d-4e3c-bb71-96c0456fe598', 'd1000019-0000-0000-0000-000000000024', 'listening', 'listening_choice', 'Dengarkan saran karier berikut. Apa yang penting dalam membangun jaringan kerja?', '{"options":[{"id":"opt_1","text":"Hanya bergaul dengan rekan satu ruangan saja"},{"id":"opt_2","text":"Sering berpindah pekerjaan setiap tiga bulan"},{"id":"opt_3","text":"Membangun jejaring dengan para ahli di luar perusahaan"},{"id":"opt_4","text":"Menghindari seminar dan konferensi industri"}],"audio_text":"長期的なキャリアを築く上で、社外の専門家との人脈づくりも非常に有効です。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '人脈づくり (membangun jaringan relasi) sangat efektif dalam キャリアを築く上で (membangun karier jangka panjang).', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9b83d5dd-cd1e-4533-9f8e-2d40c9564bde', '81a58e2b-db8d-4e3c-bb71-96c0456fe598', 'd1000019-0000-0000-0000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat: "Setelah berdiskusi dengan dosen, saya menetapkan tema penelitian."', '{"romaji":"Kyouju to hanashiatta ue de, kenkyuu teema o kettei shita.","tokens":["研究テーマを","話し合う","にもかかわらず、","教授と","上で、","話し合った","決定","した。"],"target_translation":"Setelah berdiskusi dengan dosen, saya menetapkan tema penelitian."}'::jsonb, '["教授と","話し合った","上で、","研究テーマを","決定","した。"]'::jsonb, NULL, NULL, '話し合った上で berarti setelah berdiskusi bersama.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8bbfe886-4bf3-4ac9-a008-224e31cf6d84', '81a58e2b-db8d-4e3c-bb71-96c0456fe598', 'd1000019-0000-0000-0000-000000000024', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah memahami syarat dan ketentuan, silakan tekan tombol setuju."', '{"romaji":"Riyou kiyaku o gokakunin itadaita ue de, doui botan o oshite kudasai.","display_text":"利用規約をご確認いただいた上で、同意ボタンを押してください。","phonetic_breakdown":["りようきやくを","ごかくにんいただいた","うえで","どういぼたんを","おしてください"]}'::jsonb, '{"expected_transcript":"利用規約をご確認いただいた上で、同意ボタンを押してください。"}'::jsonb, NULL, NULL, '利用規約 (syarat dan ketentuan layanan) sangat sering ditemui pada situs web dan aplikasi Jepang.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c2981119-43e5-4832-8260-19daa5ec10c2', '81a58e2b-db8d-4e3c-bb71-96c0456fe598', 'd1000019-0000-0000-0000-000000000024', 'listening', 'listening_choice', 'Dengarkan arahan manajer IT. Apa langkah yang harus didahulukan?', '{"options":[{"id":"opt_1","text":"Langsung memperbarui sistem tanpa cadangan data"},{"id":"opt_2","text":"Menghapus seluruh data lama sebelum pembaruan"},{"id":"opt_3","text":"Membuat cadangan data secara penuh terlebih dahulu, baru menjalankan pembaruan sistem"},{"id":"opt_4","text":"Mematikan server selama satu minggu"}],"audio_text":"データのバックアップを完全に取った上で、システムのアップデートを実行してください。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'バックアップを完全に取った上で memastikan langkah pengamanan dilakukan sebelum pembaruan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e2602c87-f182-4e0a-9de0-570b0ee97bc2', '81a58e2b-db8d-4e3c-bb71-96c0456fe598', 'd1000019-0000-0000-0000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat: "Dalam hal mengembangkan karier, terus memperbarui keterampilan adalah hal esensial."', '{"romaji":"Kyaria o nobasu ue de, sukiru o migaki tsuzukeru koto ga kakasenai.","tokens":["伸ばす","スキルを磨き続ける","欠かせない。","にもかかわらず、","キャリアを","上で、","ことが","伸ばした"],"target_translation":"Dalam hal mengembangkan karier, terus memperbarui keterampilan adalah hal esensial."}'::jsonb, '["キャリアを","伸ばす","上で、","スキルを磨き続ける","ことが","欠かせない。"]'::jsonb, NULL, NULL, '伸ばす上で (dalam hal mengembangkan karier) memakai bentuk kamus + 上で.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dbb46f9b-3fcd-405c-b047-8c469345c4fd', '81c04f14-111b-4850-9360-675c02910482', 'd1000019-0000-0000-0000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat: "Kesadaran akan pentingnya kesehatan mental sedang meningkat di tempat kerja."', '{"romaji":"Shokuba de no mentaru herusu e no ishiki ga takamaritsutsu aru.","tokens":["メンタルヘルスへの","高まり","つつ","かねない","職場での","高まる","意識が","ある。"],"target_translation":"Kesadaran akan pentingnya kesehatan mental sedang meningkat di tempat kerja."}'::jsonb, '["職場での","メンタルヘルスへの","意識が","高まり","つつ","ある。"]'::jsonb, NULL, NULL, '高まる (meningkat) → 高まりつつある.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ecdfdfd4-8980-4820-9dce-1a57fee778b3', '81c04f14-111b-4850-9360-675c02910482', 'd1000019-0000-0000-0000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat: "Upaya mengurangi sampah plastik sedang menyebar ke seluruh lapisan masyarakat."', '{"romaji":"Purasuchikku gomi o herasu torikumi ga shakai zentai ni shintou shitsutsu aru.","tokens":["社会全体に","にあたって","減らす","取り組みが","しつつある。","プラスチックごみを","浸透","浸透した"],"target_translation":"Upaya mengurangi sampah plastik sedang menyebar ke seluruh lapisan masyarakat."}'::jsonb, '["プラスチックごみを","減らす","取り組みが","社会全体に","浸透","しつつある。"]'::jsonb, NULL, NULL, '浸透する (shintou suru) berarti meresap/menyebar luas.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6a06146a-042c-4560-89a3-e01ec60eaea7', '81c04f14-111b-4850-9360-675c02910482', 'd1000019-0000-0000-0000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat: "Sistem kerja fleksibel sedang mulai diterapkan di banyak perusahaan Jepang."', '{"romaji":"Juunanna kinmu seido ga ooku no Nihon kigyou de dounyuu saretsutsu aru.","tokens":["勤務制度が","日本企業で","導入して","柔軟な","導入","に限らず","されつつある。","多くの"],"target_translation":"Sistem kerja fleksibel sedang mulai diterapkan di banyak perusahaan Jepang."}'::jsonb, '["柔軟な","勤務制度が","多くの","日本企業で","導入","されつつある。"]'::jsonb, NULL, NULL, '柔軟な勤務制度 berarti sistem kerja yang fleksibel.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('95cbb021-5da9-4705-bc86-8000cfae5649', '81c04f14-111b-4850-9360-675c02910482', 'd1000019-0000-0000-0000-000000000025', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Proyek pembangunan jembatan baru akhirnya sedang mendekati tahap penyelesaian."', '{"romaji":"Atarashii hashi no kensetsu kouji wa, youyaku kansei ni chikazukitsutsu arimasu.","display_text":"新しい橋の建設工事は、ようやく完成に近づきつつあります。","phonetic_breakdown":["あたらしいはしの","けんせつこうじは","ようやく","かんせいに","ちかづきつつあります"]}'::jsonb, '{"expected_transcript":"新しい橋の建設工事は、ようやく完成に近づきつつあります。"}'::jsonb, NULL, NULL, '完成に近づく (mendekati penyelesaian) → 近づきつつある.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('667fc2ce-d9ab-47a0-b3c5-e7cc19369f7a', '81c04f14-111b-4850-9360-675c02910482', 'd1000019-0000-0000-0000-000000000025', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Perbedaan antara bekerja di kantor dan dari rumah sedang semakin kabur."', '{"romaji":"Ofisu kinmu to zaitaku kinmu no kyoukai wa, shidai ni aimai ni naritsutsu arimasu.","display_text":"オフィス勤務と在宅勤務の境界は、次第に曖昧になりつつあります。","phonetic_breakdown":["おふぃすきんむと","ざいたくきんむの","きょうかいは","しだいに","あいまいになりつつあります"]}'::jsonb, '{"expected_transcript":"オフィス勤務と在宅勤務の境界は、次第に曖昧になりつつあります。"}'::jsonb, NULL, NULL, '次第に (lambat laun) dan 曖昧 (kabur/tidak tegas) cocok dengan ～つつある.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('493f486f-a5ff-4cb6-bae5-9caea0e8dde6', '81c04f14-111b-4850-9360-675c02910482', 'd1000019-0000-0000-0000-000000000025', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kerja sama penelitian antara universitas dan industri sedang semakin erat."', '{"romaji":"Daigaku to kigyou no kyoudou kenkyuu wa, kongo sara ni kappatsu ni naritsutsu arimasu.","display_text":"大学と企業の共同研究は、今後さらに活発になりつつあります。","phonetic_breakdown":["だいがくときぎょうの","きょうどうけんきゅうは","こんごさらに","かっぱつに","なりつつあります"]}'::jsonb, '{"expected_transcript":"大学と企業の共同研究は、今後さらに活発になりつつあります。"}'::jsonb, NULL, NULL, '活発になる (menjadi aktif/giat) → 活発になりつつある.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bf9671ba-24aa-4a8b-bbb7-05820216418f', '81c04f14-111b-4850-9360-675c02910482', 'd1000019-0000-0000-0000-000000000025', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 都市部の空き家対策として、新しい活用法が広がり___。', '{"options":["つつある","にあたって","にもかかわらず","の上で"],"translation":"Sebagai langkah mengatasi rumah kosong di perkotaan, cara pemanfaatan baru sedang terus meluas.","sentence_template":"都市部の空き家対策として、新しい活用法が広がり[blank]。"}'::jsonb, '{"selected":"つつある"}'::jsonb, NULL, NULL, '広がりつつある menyatakan penyebaran yang progresif.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4e85da83-bee2-4ff2-8da3-d0879696264c', '81c04f14-111b-4850-9360-675c02910482', 'd1000019-0000-0000-0000-000000000025', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kesenjangan informasi antara kota besar dan daerah perlahan sedang mengecil."', '{"romaji":"Toshi to chihou no jouhou kakusa wa, sukoshizutsu shukushou shitsutsu arimasu.","display_text":"都市と地方の情報格差は、少しずつ縮小しつつあります。","phonetic_breakdown":["としとちほうの","じょうほうかくさは","すこしずつ","しゅくしょうしつつあります"]}'::jsonb, '{"expected_transcript":"都市と地方の情報格差は、少しずつ縮小しつつあります。"}'::jsonb, NULL, NULL, '縮小しつつあります berarti sedang berangsur-angsur menyusut/mengecil.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6073558f-f65a-4308-8ef3-6ea724404f87', '82f0456c-340e-47b0-bb6e-ba56143a3119', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan telepon bisnis berikut. Kapan Ibu Sato akan kembali?', '{"options":[{"id":"opt_1","text":"Ibu Sato tidak masuk kerja hari ini"},{"id":"opt_2","text":"Ibu Sato sedang meninggalkan meja sebentar dan akan segera kembali"},{"id":"opt_3","text":"Ibu Sato sedang dinas ke luar negeri hingga minggu depan"},{"id":"opt_4","text":"Ibu Sato sedang memindahkan ruang kerjanya ke lantai atas"}],"audio_text":"佐藤はただいま席を外しておりますが、まもなくお戻りになる予定です。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '席を外しております (sedang meninggalkan meja) dan お戻りになる (akan kembali).', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6272bad8-b689-4a11-8045-0e874c4e2e6a', '82f0456c-340e-47b0-bb6e-ba56143a3119', NULL, 'listening', 'listening_choice', 'Dengarkan ucapan moderator seminar berikut. Siapa yang akan berbicara selanjutnya?', '{"options":[{"id":"opt_1","text":"Direktur keuangan dari perusahaan sponsor"},{"id":"opt_2","text":"Perwakilan mahasiswa tingkat pertama"},{"id":"opt_3","text":"Profesor Yamada yang akan memberikan ceramah"},{"id":"opt_4","text":"Staf administrasi penyelenggara seminar"}],"audio_text":"続きまして、山田教授にご講演をいただきます。先生、よろしくお願いいたします。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'ご講演をいただく adalah bentuk sopan mempersilakan pembicara menyampaikan kuliah/ceramah.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('676a4e81-8851-4146-9477-e8e210cc4033', '82f0456c-340e-47b0-bb6e-ba56143a3119', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan di kantor berikut. Apa yang ditanyakan kepada klien?', '{"options":[{"id":"opt_1","text":"Menanyakan alamat pengiriman katalog produk baru"},{"id":"opt_2","text":"Meminta klien mengisi formulir survei kepuasan"},{"id":"opt_3","text":"Menanyakan apakah klien ingin memesan taksi ke bandara"},{"id":"opt_4","text":"Mengingatkan klien memeriksa barang bawaan agar tidak ada yang tertinggal"}],"audio_text":"お帰りの際、お忘れ物のないよう今一度お手回り品をご確認くださいますでしょうか。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'お手回り品 (barang bawaan pribadi) dan ご確認くださいますでしょうか (mohon berkenan memeriksa).', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('82b8ef5d-539c-4cdf-9c62-74a87082c766', '82f0456c-340e-47b0-bb6e-ba56143a3119', NULL, 'reading', 'fill_blank', 'Pilih bentuk Sonkeigo yang tepat (hindari salah tukar dengan Kenjougo): 先生、明日何時ごろ大学へ___ますか。', '{"options":["いらっしゃい","参り","伺い","いたし"],"translation":"Sensei, besok sekitar pukul berapa Bapak/Ibu datang ke universitas?","sentence_template":"先生、明日何時ごろ大学へ[blank]ますか。"}'::jsonb, '{"selected":"いらっしゃい"}'::jsonb, NULL, NULL, 'Untuk menanyakan kedatangan guru/atasan, gunakan いらっしゃいます (bukan 参ります atau 伺います yang merupakan Kenjougo).', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d052b26d-9d19-4748-9c4a-803300c7b555', '82f0456c-340e-47b0-bb6e-ba56143a3119', NULL, 'reading', 'fill_blank', 'Lengkapi email bisnis berikut: 先日___いただいた件につきまして、社内で検討いたしました。', '{"options":["ご相談","お聞き","拝見","お伺い"],"translation":"Mengenai hal yang tempo hari Anda konsultasikan kepada kami, kami telah membahasnya di internal.","sentence_template":"先日[blank]いただいた件につきまして、社内で検討いたしました。"}'::jsonb, '{"selected":"ご相談"}'::jsonb, NULL, NULL, 'ご相談いただいた件 merujuk pada konsultasi/permintaan yang datang dari pihak klien.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('43075195-3916-4a53-b779-4a043c61e8dd', '82f0456c-340e-47b0-bb6e-ba56143a3119', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kapan Bapak/Ibu berencana berkunjung ke kantor kami?"', '{"romaji":"Itsugoro heisha e okoshi ni naru goyotei deshou ka.","display_text":"いつごろ弊社へお越しになるご予定でしょうか。","phonetic_breakdown":["いつごろ","へいしゃえ","おこしになる","ごよていでしょうか"]}'::jsonb, '{"expected_transcript":"いつごろ弊社へお越しになるご予定でしょうか。"}'::jsonb, NULL, NULL, '弊社 (perusahaan kami, bentuk merendah) dan お越しになる (datang, Sonkeigo baku).', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6229619f-4f53-43e1-b54c-9509858ac9f0', '82f0456c-340e-47b0-bb6e-ba56143a3119', 'd1000019-0000-0000-0000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat: "Apakah Ibu Manajer sudah memeriksa laporan bulanan tersebut?"', '{"romaji":"Buchou wa mou sono geppou o goran ni narimashita ka.","tokens":["もうその月報を","になり","か。","いたし","部長は","ご覧","ました","拝見し"],"target_translation":"Apakah Ibu Manajer sudah memeriksa laporan bulanan tersebut?"}'::jsonb, '["部長は","もうその月報を","ご覧","になり","ました","か。"]'::jsonb, NULL, NULL, 'ご覧になりましたか menggunakan sonkeigo baku untuk menanyakan apakah atasan sudah melihat laporan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4c50ae45-7507-4a8a-ada1-209798d4785c', '82f0456c-340e-47b0-bb6e-ba56143a3119', 'd1000019-0000-0000-0000-000000000027', 'listening', 'listening_choice', 'Dengarkan pesan suara klien. Apa yang disampaikan Bapak Yamada?', '{"options":[{"id":"opt_1","text":"Bapak Yamada ingin membatalkan seluruh pesanan"},{"id":"opt_2","text":"Bapak Yamada meminta materi produk baru yang baru saja dibicarakan dikirimkan melalui email"},{"id":"opt_3","text":"Bapak Yamada mengundang rapat tatap muka hari Minggu"},{"id":"opt_4","text":"Bapak Yamada salah sambung nomor telepon"}],"audio_text":"恐れ入りますが、先ほどお話しになった新製品の資料をメールでお送りいただけますか。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'お話しになった (sonkeigo dari 話した) merujuk pada hal yang baru saja disampaikan lawan bicara.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d5463d19-32c8-4f6b-999b-730cb4d4a395', '82f1450f-dfd1-471e-b50d-62d8170a402a', 'd1000019-0000-0000-0000-000000000022', 'reading', 'fill_blank', 'Lengkapi laporan bisnis berikut: 原材料費の高騰が続いており、来月から商品価格を改定___。', '{"options":["せざるを得ない","するにあたらない","するに限らず","しつつある"],"translation":"Karena lonjakan biaya bahan baku terus berlanjut, mau tidak mau kami terpaksa menyesuaikan harga produk mulai bulan depan.","sentence_template":"原材料費の高騰が続いており、来月から商品価格を改定[blank]。"}'::jsonb, '{"selected":"せざるを得ない"}'::jsonb, NULL, NULL, 'Untuk kata kerja golongan 3 (する), bentuk yang benar adalah せざるを得ない.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('98bbc3a0-1e32-41b9-b149-6dbafd678775', '82f1450f-dfd1-471e-b50d-62d8170a402a', 'd1000019-0000-0000-0000-000000000022', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 悪天候のため、屋外での記念式典は中止___結果となった。', '{"options":["せざるを得ない","しざるを得ない","すざるを得ない","さざるを得ない"],"translation":"Akibat cuaca buruk, hasilnya upacara peringatan di luar ruangan terpaksa harus dibatalkan.","sentence_template":"悪天候のため、屋外での記念式典は中止[blank]結果となった。"}'::jsonb, '{"selected":"せざるを得ない"}'::jsonb, NULL, NULL, 'Ingat aturan penting JLPT N2: する berubah menjadi せざるを得ない (bukan しざる).', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7ddfd461-55dd-49ec-a2e6-643cad5af312', '82f1450f-dfd1-471e-b50d-62d8170a402a', 'd1000019-0000-0000-0000-000000000022', 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan penerbangan. Keputusan apa yang terpaksa diambil?', '{"options":[{"id":"opt_1","text":"Penerbangan terakhir hari ini terpaksa dibatalkan karena perawatan pesawat memakan waktu lebih lama dari perkiraan"},{"id":"opt_2","text":"Penerbangan terakhir dipercepat satu jam dari jadwal"},{"id":"opt_3","text":"Semua penumpang dipindahkan ke kelas bisnis secara gratis"},{"id":"opt_4","text":"Bandara ditutup selama satu bulan penuh"}],"audio_text":"機材の整備に想定以上の時間を要するため、本日の最終便は欠航とせざるを得なくなりました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '欠航とせざるを得なくなりました berarti terpaksa harus membatalkan penerbangan.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1e1ecbc4-7cc4-40c6-9c1d-516af08b16a3', '82f1450f-dfd1-471e-b50d-62d8170a402a', 'd1000019-0000-0000-0000-000000000022', 'writing', 'sentence_builder', 'Susun kalimat: "Karena kekurangan bukti, penyelidikan kasus tersebut terpaksa dihentikan."', '{"romaji":"Shouko fusoku no tame, sono jiken no sousa wa uchikirazaru o enakatta.","tokens":["その事件の","打ち切ら","得なかった。","かねなかった。","証拠不足のため、","捜査は","ざるを","打ち切る"],"target_translation":"Karena kekurangan bukti, penyelidikan kasus tersebut terpaksa dihentikan."}'::jsonb, '["証拠不足のため、","その事件の","捜査は","打ち切ら","ざるを","得なかった。"]'::jsonb, NULL, NULL, '打ち切る (menghentikan) -> bentuk nai tanpa い (打ち切ら) + ざるを得なかった.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5f20a18e-c361-4e04-a952-a8405c2df12b', '82f1450f-dfd1-471e-b50d-62d8170a402a', 'd1000019-0000-0000-0000-000000000022', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mengingat kondisi anggaran saat ini, kami terpaksa menunda rencana ekspansi."', '{"romaji":"Genzai no yosan joukyou o kangaeru to, kakudai keikaku wa enki sezaru o emasen.","display_text":"現在の予算状況を考えると、拡大計画は延期せざるを得ません。","phonetic_breakdown":["げんざいの","よさんじょうきょうを","かんがえると","かくだいけいかくは","えんきせざるをえません"]}'::jsonb, '{"expected_transcript":"現在の予算状況を考えると、拡大計画は延期せざるを得ません。"}'::jsonb, NULL, NULL, '延期せざるを得ません menyampaikan keputusan berat secara profesional dan objektif.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3a17ba5e-0f2a-438a-8e9c-1345453a9c64', '82f1450f-dfd1-471e-b50d-62d8170a402a', 'd1000019-0000-0000-0000-000000000022', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: これだけ明確なデータを見せられては、自分の誤りを認め___。', '{"options":["ざるを得ない","かねない","に伴わない","にあたらない"],"translation":"Setelah diperlihatkan data sejelas ini, mau tidak mau saya terpaksa mengakui kesalahan saya sendiri.","sentence_template":"これだけ明確なデータを見せられては、自分の誤りを認め[blank]。"}'::jsonb, '{"selected":"ざるを得ない"}'::jsonb, NULL, NULL, '認める (golongan 2) -> 認め + ざるを得ない.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7a73a700-5c49-4851-9f38-86c0004d497f', '82f1450f-dfd1-471e-b50d-62d8170a402a', 'd1000019-0000-0000-0000-000000000022', 'listening', 'listening_choice', 'Dengarkan komentar manajer pabrik. Mengapa lini produksi dihentikan sementara?', '{"options":[{"id":"opt_1","text":"Karena semua pekerja sedang mengikuti pelatihan"},{"id":"opt_2","text":"Karena listrik di seluruh kota padam total"},{"id":"opt_3","text":"Karena pasokan suku cadang terhenti total sehingga operasional pabrik terpaksa dihentikan sementara"},{"id":"opt_4","text":"Karena permintaan produk menurun drastis"}],"audio_text":"部品の供給が完全に止まってしまったため、工場の稼働を一時停止せざるを得ない状況です。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '部品の供給が完全に止まってしまった (pasokan suku cadang terhenti total) memaksa penghentian operasional.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('febc8831-2feb-4519-8fbb-3dc8c60bc164', '82f1450f-dfd1-471e-b50d-62d8170a402a', 'd1000019-0000-0000-0000-000000000022', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun enggan, demi keselamatan warga jalan tersebut terpaksa ditutup."', '{"romaji":"Fuhoni nagara, juumin no anzen no tame ni sono douro wa heisa sezaru o enakatta.","tokens":["住民の安全のために","閉鎖","得なかった。","に限らず、","不本意ながら、","その道路は","せざるを","しざるを"],"target_translation":"Meskipun enggan, demi keselamatan warga jalan tersebut terpaksa ditutup."}'::jsonb, '["不本意ながら、","住民の安全のために","その道路は","閉鎖","せざるを","得なかった。"]'::jsonb, NULL, NULL, '閉鎖する -> 閉鎖せざるを得なかった menyatakan tindakan terpaksa demi keselamatan.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('05fc12e8-d776-4c59-9439-437e48aa8a78', '8c39d8aa-0ea3-41a6-962a-f162798d5d10', 'd1000019-0000-0000-0000-000000000022', 'writing', 'sentence_builder', 'Susun kalimat: "Karena kekurangan tenaga kerja, kami terpaksa mempersingkat jam operasional."', '{"romaji":"Hitode busoku no tame, eigyou jikan o tanshuku sezaru o enai.","tokens":["短縮","に限らず","せざるを","得ない。","ため、","短縮し","人手不足の","営業時間を"],"target_translation":"Karena kekurangan tenaga kerja, kami terpaksa mempersingkat jam operasional."}'::jsonb, '["人手不足の","ため、","営業時間を","短縮","せざるを","得ない。"]'::jsonb, NULL, NULL, '人手不足 (kekurangan tenaga kerja) adalah topik aktual yang sangat sering muncul di N2.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ebf04ecd-b526-4cb9-9178-5628158752fe', '8c39d8aa-0ea3-41a6-962a-f162798d5d10', 'd1000019-0000-0000-0000-000000000022', 'writing', 'sentence_builder', 'Susun kalimat: "Karena masalah sistem, layanan terpaksa dihentikan sementara."', '{"romaji":"Shisutemu shougai ni yori, saabisu o ichiji teishi sezaru o enakatta.","tokens":["得なかった。","システム障害","により、","一時停止","せざるを","一時停止し","にあたって","サービスを"],"target_translation":"Karena masalah sistem, layanan terpaksa dihentikan sementara."}'::jsonb, '["システム障害","により、","サービスを","一時停止","せざるを","得なかった。"]'::jsonb, NULL, NULL, 'システム障害 berarti gangguan sistem.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('602c134a-537b-4f40-9005-c39e234dbbda', '8c39d8aa-0ea3-41a6-962a-f162798d5d10', 'd1000019-0000-0000-0000-000000000022', 'writing', 'sentence_builder', 'Susun kalimat: "Meski menyakitkan, saya terpaksa memberitahukan fakta yang sebenarnya."', '{"romaji":"Iinikui ga, hontou no jijitsu o tsutaezaru o enai.","tokens":["言いにくいが、","事実を","本当の","伝え","得ない。","かねない","ざるを","伝える"],"target_translation":"Meski menyakitkan, saya terpaksa memberitahukan fakta yang sebenarnya."}'::jsonb, '["言いにくいが、","本当の","事実を","伝え","ざるを","得ない。"]'::jsonb, NULL, NULL, '伝える (Ichidan) → 伝えざるを得ない.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('385e08d5-a3e3-4c4b-93d7-57bef9f1c022', '8c39d8aa-0ea3-41a6-962a-f162798d5d10', 'd1000019-0000-0000-0000-000000000022', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena jadwal bentrok, saya terpaksa membatalkan perjalanan dinas itu."', '{"romaji":"Nittei ga kasanatte shimai, shucchou o toriyamezaru o enaku narimashita.","display_text":"日程が重なってしまい、出張を取りやめざるを得なくなりました。","phonetic_breakdown":["にっていが","かさなってしまい","しゅっちょうを","とりやめざるを","えなくなりました"]}'::jsonb, '{"expected_transcript":"日程が重なってしまい、出張を取りやめざるを得なくなりました。"}'::jsonb, NULL, NULL, '取りやめる (membatalkan) → 取りやめざるを得なくなる.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('551d3ea2-2415-4587-8611-030f6234da96', '8c39d8aa-0ea3-41a6-962a-f162798d5d10', 'd1000019-0000-0000-0000-000000000022', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Melihat hasil survei ini, kami terpaksa meninjau ulang strategi pemasaran."', '{"romaji":"Kono chousa kekka o miru to, hanbai senryaku o minaosa zaru o emasen.","display_text":"この調査結果を見ると、販売戦略を見直さざるを得ません。","phonetic_breakdown":["このちょうさけっかを","みると","はんばいせんりゃくを","みなおさざるを","えません"]}'::jsonb, '{"expected_transcript":"この調査結果を見ると、販売戦略を見直さざるを得ません。"}'::jsonb, NULL, NULL, '見直す (Godan) → 見直さない → 見直さざるを得ません.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('756bb951-048a-454f-a8d2-a7f64d469a18', '8c39d8aa-0ea3-41a6-962a-f162798d5d10', 'd1000019-0000-0000-0000-000000000022', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena tidak ada penerbangan langsung, kami terpaksa transit di bandara lain."', '{"romaji":"Chokkoubin ga nai tame, betsu no kuukou de noritsugazaru o emasen deshita.","display_text":"直行便がないため、別の空港で乗り継がざるを得ませんでした。","phonetic_breakdown":["ちょっこうびんが","ないため","べつのくうこうで","のりつがざるを","えませんでした"]}'::jsonb, '{"expected_transcript":"直行便がないため、別の空港で乗り継がざるを得ませんでした。"}'::jsonb, NULL, NULL, '乗り継ぐ (transit/ganti pesawat) → 乗り継がない → 乗り継がざるを得ない.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d2a01b4a-14b7-402f-b009-892f30e3d4f6', '8c39d8aa-0ea3-41a6-962a-f162798d5d10', 'd1000019-0000-0000-0000-000000000022', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: ほかに頼める人がいないので、自分で対応___。', '{"options":["せざるを得ない","しざるを得ない","するわけがない","しかねない"],"translation":"Karena tidak ada orang lain yang bisa dimintai tolong, terpaksa saya tangani sendiri.","sentence_template":"ほかに頼める人がいないので、自分で対応[blank]。"}'::jsonb, '{"selected":"せざるを得ない"}'::jsonb, NULL, NULL, '対応する -> 対応せざるを得ない.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a8ebf7c3-1608-4c5a-971c-a3935bfbfa4a', '8c39d8aa-0ea3-41a6-962a-f162798d5d10', 'd1000019-0000-0000-0000-000000000022', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena tidak ada alternatif lain, kami terpaksa menerima syarat tersebut."', '{"romaji":"Hoka ni sentakushi ga nai tame, sono jouken o ukeirezaru o emasen deshita.","display_text":"他に選択肢がないため、その条件を受け入れざるを得ませんでした。","phonetic_breakdown":["ほかに","せんたくしがないため","そのじょうけんを","うけいれざるを","えませんでした"]}'::jsonb, '{"expected_transcript":"他に選択肢がないため、その条件を受け入れざるを得ませんでした。"}'::jsonb, NULL, NULL, '受け入れる (menerima) -> 受け入れざるを得ませんでした.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ab9fe745-38a0-4b3e-852d-454e5b7d3f56', '8d74474a-d21b-421e-a210-916affed514a', 'd1000019-0000-0000-0000-000000000024', 'listening', 'listening_choice', 'Dengarkan penjelasan bagian HRD. Bagaimana proses penentuan penempatan karyawan baru?', '{"options":[{"id":"opt_1","text":"Penempatan ditentukan sepenuhnya secara acak lewat undian"},{"id":"opt_2","text":"Penempatan ditetapkan setelah mempertimbangkan minat dan kecocokan masing-masing secara menyeluruh"},{"id":"opt_3","text":"Karyawan baru memilih sendiri gaji sebelum wawancara"},{"id":"opt_4","text":"Semua karyawan baru ditempatkan di cabang luar negeri"}],"audio_text":"本人の希望と適性を総合的に考慮した上で、配属先を決定いたします。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '総合的に考慮した上で berarti setelah mempertimbangkan secara komprehensif.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7a6e8d5e-ff97-431b-a5e5-3a05de800c49', '8d74474a-d21b-421e-a210-916affed514a', 'd1000019-0000-0000-0000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat: "Setelah berkonsultasi dengan keluarga, saya memutuskan menerima tawaran mutasi kerja."', '{"romaji":"Kazoku to soudan shita ue de, tenkin no jirei o ukeru koto ni shita.","tokens":["相談した","転勤の辞令を","した。","に限らず、","家族と","上で、","受けることに","相談する"],"target_translation":"Setelah berkonsultasi dengan keluarga, saya memutuskan menerima tawaran mutasi kerja."}'::jsonb, '["家族と","相談した","上で、","転勤の辞令を","受けることに","した。"]'::jsonb, NULL, NULL, '相談した上で (setelah berkonsultasi) diikuti keputusan akhir 受けることにした.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d0ec84b1-973c-4fe1-9b84-ed425ce6795d', '8d74474a-d21b-421e-a210-916affed514a', 'd1000019-0000-0000-0000-000000000024', 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: リスクを十分に理解した___、投資を判断してください。', '{"options":["上で","にあたって","つつある","かねない"],"translation":"Setelah memahami risikonya dengan cukup baik, silakan putuskan investasi Anda.","sentence_template":"リスクを十分に理解した[blank]、投資を判断してください。"}'::jsonb, '{"selected":"上で"}'::jsonb, NULL, NULL, '理解した上で lazim muncul dalam ketentuan layanan keuangan dan kontrak.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8d26986f-044a-4f82-a4b0-817aa75ac742', '8d74474a-d21b-421e-a210-916affed514a', 'd1000019-0000-0000-0000-000000000024', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dalam hal membangun kepercayaan, menepati janji kecil sekalipun sangatlah penting."', '{"romaji":"Shinrai kankei o kizuku ue de, chiisana yakusoku o mamoru koto ga nani yori taisetsu desu.","display_text":"信頼関係を築く上で、小さな約束を守ることが何より大切です。","phonetic_breakdown":["しんらいかんけいを","きずくうえで","ちいさなやくそくを","まもることが","なによりたいせつです"]}'::jsonb, '{"expected_transcript":"信頼関係を築く上で、小さな約束を守ることが何より大切です。"}'::jsonb, NULL, NULL, '信頼関係を築く上で berarti ''dalam hal membangun hubungan saling percaya''.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2ca70703-e9f6-4217-86e3-dfbf7da2ff2c', '8d74474a-d21b-421e-a210-916affed514a', 'd1000019-0000-0000-0000-000000000024', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 複数の見積もりを比較検討した___、発注先を選定した。', '{"options":["上で","に伴い","に限らず","わけにはいかず"],"translation":"Setelah membandingkan dan menelaah beberapa penawaran harga, kami memilih vendor pemesanan.","sentence_template":"複数の見積もりを比較検討した[blank]、発注先を選定した。"}'::jsonb, '{"selected":"上で"}'::jsonb, NULL, NULL, '比較検討した上で (setelah membandingkan dan menelaah) adalah ungkapan pengadaan barang/bisnis.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2878498f-2df9-4477-8850-3059db62b616', '8d74474a-d21b-421e-a210-916affed514a', 'd1000019-0000-0000-0000-000000000024', 'listening', 'listening_choice', 'Dengarkan wawancara kepala koki. Apa kunci penting dalam mengelola restoran?', '{"options":[{"id":"opt_1","text":"Hanya desain interior yang menentukan kesuksesan restoran"},{"id":"opt_2","text":"Harga makanan harus selalu lebih murah dari pesaing"},{"id":"opt_3","text":"Lokasi restoran tidak memengaruhi jumlah pelanggan"},{"id":"opt_4","text":"Dalam mengelola restoran, selain rasa masakan, ketegasan manajemen kebersihan adalah yang terpenting"}],"audio_text":"飲食店を経営する上では、料理の味はもちろんですが、衛生管理の徹底が最も重要です。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '経営する上では (dalam hal mengelola usaha) menyoroti poin terpenting 衛生管理の徹底.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0b96a38f-5fd9-4115-af98-b33f8528fcd3', '8d74474a-d21b-421e-a210-916affed514a', 'd1000019-0000-0000-0000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat: "Setelah menguji prototipe berkali-kali, kami memulai produksi massal."', '{"romaji":"Shisakuhin o nando mo kenshou shita ue de, ryousan o kaishi shita.","tokens":["何度も","上で、","開始した。","にもかかわらず、","試作品を","検証した","量産を","検証する"],"target_translation":"Setelah menguji prototipe berkali-kali, kami memulai produksi massal."}'::jsonb, '["試作品を","何度も","検証した","上で、","量産を","開始した。"]'::jsonb, NULL, NULL, '検証した上で (setelah memverifikasi/menguji) diikuti tahap produksi massal 量産を開始した.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6648ee14-dce6-4e68-bd4c-e3e61ea54e8a', '8d74474a-d21b-421e-a210-916affed514a', 'd1000019-0000-0000-0000-000000000024', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah berdiskusi di internal perusahaan, kami akan menghubungi Anda kembali besok."', '{"romaji":"Shanai de kentou itashimashita ue de, asu aratamete gorenraku itashimasu.","display_text":"社内で検討いたしました上で、明日改めてご連絡いたします。","phonetic_breakdown":["しゃないで","けんとういたしました","うえで","あしたあらためて","ごれんらくいたします"]}'::jsonb, '{"expected_transcript":"社内で検討いたしました上で、明日改めてご連絡いたします。"}'::jsonb, NULL, NULL, '検討いたしました上で adalah balasan bisnis sangat sopan sebelum memberi jawaban resmi.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ae047ec6-0636-4f5a-a00f-c6aea95d794f', '8e64d6db-29e8-4431-be70-3742470cdf60', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan di kantor berikut. Mengapa pembicara menolak tawaran minum?', '{"options":[{"id":"opt_1","text":"Karena sedang diet ketat menjelang pemeriksaan kesehatan"},{"id":"opt_2","text":"Karena tidak menyukai rasa minuman tersebut"},{"id":"opt_3","text":"Karena akan menyetir mobil untuk menjemput keluarga"},{"id":"opt_4","text":"Karena harus langsung masuk kerja shift malam"}],"audio_text":"今夜はこれから車で家族を迎えに行くので、お酒を飲むわけにはいかないんです。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '車で家族を迎えに行く (menjemput keluarga dengan mobil) membuat minum alkohol melanggar hukum & keselamatan.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fceed852-8d30-4c3e-8f86-52a8d96121a5', '8e64d6db-29e8-4431-be70-3742470cdf60', NULL, 'listening', 'listening_choice', 'Dengarkan ucapan mahasiswa berikut. Apa yang akan ia lakukan?', '{"options":[{"id":"opt_1","text":"Begadang semalaman untuk menonton film"},{"id":"opt_2","text":"Tidur lebih awal dan tidak begadang karena ada wawancara beasiswa besok"},{"id":"opt_3","text":"Mengubah jadwal wawancara ke minggu depan"},{"id":"opt_4","text":"Pergi makan malam bersama teman sampai larut"}],"audio_text":"明日は奨学金の面接があるから、今夜は夜更かしするわけにはいかない。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '夜更かしするわけにはいかない berarti ''tidak boleh begadang'' karena ada agenda penting esok hari.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7406ce1a-399a-4d17-bbdc-4f0898e2a0f8', '8e64d6db-29e8-4431-be70-3742470cdf60', NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan kepala tim berikut. Apa alasannya tidak bisa menunda pengiriman?', '{"options":[{"id":"opt_1","text":"Karena harga komponen akan naik minggu depan"},{"id":"opt_2","text":"Karena gudang penyimpanan sudah penuh"},{"id":"opt_3","text":"Karena truk pengiriman sedang diperbaiki"},{"id":"opt_4","text":"Karena jadwal operasional pabrik sudah ditetapkan"}],"audio_text":"すでに工場の稼働スケジュールが決まっているので、部品の納入を遅らせるわけにはいきません。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '工場の稼働スケジュールが決まっている (jadwal operasional pabrik sudah tetap) sehingga pengiriman komponen tak bisa ditunda.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0ac5ffb0-f24b-4458-9502-b9e13ef28ace', '8e64d6db-29e8-4431-be70-3742470cdf60', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 試験の本番まであと一週間だから、ここで気を緩める___。', '{"options":["わけにはいかない","にあたって","に伴う","つつある"],"translation":"Karena ujian sesungguhnya tinggal satu minggu lagi, saya tidak boleh lengah di saat seperti ini.","sentence_template":"試験の本番まであと一週間だから、ここで気を緩める[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, NULL, NULL, '気を緩める (melengahkan diri/mengendurkan fokus) + わけにはいかない.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('04458455-9f2c-4faa-8be3-5fb3b75cb169', '8e64d6db-29e8-4431-be70-3742470cdf60', NULL, 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 顧客からクレームが入った以上、誠意を持って___わけにはいかない。', '{"options":["対応しない","対応する","対応した","対応して"],"translation":"Begitu ada keluhan dari pelanggan, mau tidak mau kami harus menanganinya dengan sungguh-sungguh.","sentence_template":"顧客からクレームが入った以上、誠意を持って[blank]わけにはいかない。"}'::jsonb, '{"selected":"対応しない"}'::jsonb, NULL, NULL, '誠意を持って対応しないわけにはいかない menegaskan kewajiban profesional menanggapi keluhan.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2bb2c7fd-ed77-4629-95ea-5bad6291f42e', '8e64d6db-29e8-4431-be70-3742470cdf60', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena rekan kerja sedang kesulitan, saya tidak mungkin diam saja melihatnya."', '{"romaji":"Douryou ga komatte iru noni, damatte mite iru wake ni wa ikimasen.","display_text":"同僚が困っているのに、黙って見ているわけにはいきません。","phonetic_breakdown":["どうりょうが","こまっているのに","だまって","みている","わけには","いきません"]}'::jsonb, '{"expected_transcript":"同僚が困っているのに、黙って見ているわけにはいきません。"}'::jsonb, NULL, NULL, '黙って見ているわけにはいかない berarti tidak bisa hanya diam menonton tanpa membantu.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c76e8cc1-aa97-4e29-954c-2ede67a65b7c', '8e64d6db-29e8-4431-be70-3742470cdf60', 'd1000019-0000-0000-0000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat: "Karena sudah menerima subsidi, kita harus melaporkan penggunaan dana dengan transparan."', '{"romaji":"Hojokin o uketa kara ni wa, shito o houkoku shinai wake ni wa ikanai.","tokens":["受けたからには、","報告しない","いかない。","かねない。","補助金を","使途を","わけには","報告する"],"target_translation":"Karena sudah menerima subsidi, kita harus melaporkan penggunaan dana dengan transparan."}'::jsonb, '["補助金を","受けたからには、","使途を","報告しない","わけには","いかない。"]'::jsonb, NULL, NULL, '報告しないわけにはいかない menegaskan kewajiban pelaporan akuntabel.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3c8e99d9-7b50-449c-93de-64af7cf3d884', '8e64d6db-29e8-4431-be70-3742470cdf60', 'd1000019-0000-0000-0000-000000000021', 'listening', 'listening_choice', 'Dengarkan komentar pelatih tim nasional. Apa pesan utamanya?', '{"options":[{"id":"opt_1","text":"Pelatih ingin membatalkan pertandingan kandang"},{"id":"opt_2","text":"Pelatih tidak peduli dengan hasil pertandingan"},{"id":"opt_3","text":"Pelatih merasa tidak boleh menampilkan permainan buruk di hadapan pendukung tuan rumah"},{"id":"opt_4","text":"Pelatih meminta penonton pulang lebih awal"}],"audio_text":"地元のファンの前で、情けない試合を見せるわけにはいかないんです。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '情けない試合を見せるわけにはいかない berarti tidak boleh menunjukkan pertandingan yang memalukan.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c86fd0df-ce86-4d79-844d-acbc5ce0ddbc', '90a296f7-2b51-4fde-af35-54aefab3d345', 'd1000019-0000-0000-0000-000000000018', 'writing', 'sentence_builder', 'Susun kalimat: "Menjelang penandatanganan kontrak, mari kita periksa ulang jadwalnya."', '{"romaji":"Keiyaku no teiketsu ni atatte, nittei o saikakunin shimashou.","tokens":["締結した","締結","再確認","にもかかわらず、","契約の","しましょう。","にあたって、","日程を"],"target_translation":"Menjelang penandatanganan kontrak, mari kita periksa ulang jadwalnya."}'::jsonb, '["契約の","締結","にあたって、","日程を","再確認","しましょう。"]'::jsonb, NULL, NULL, '締結 (teiketsu) berarti penandatanganan/pengesahan kontrak secara resmi.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cbbc076c-1470-4833-95e6-3e53e46c4ab8', '90a296f7-2b51-4fde-af35-54aefab3d345', 'd1000019-0000-0000-0000-000000000018', 'writing', 'sentence_builder', 'Susun kalimat: "Dalam rangka ekspansi ke luar negeri, kami merekrut tenaga ahli."', '{"romaji":"Kaigai e shinshutsu suru ni atari, senmonka o saiyou shita.","tokens":["にあたり、","海外へ","専門家を","進出して","進出する","採用","かねない","した。"],"target_translation":"Dalam rangka ekspansi ke luar negeri, kami merekrut tenaga ahli."}'::jsonb, '["海外へ","進出する","にあたり、","専門家を","採用","した。"]'::jsonb, NULL, NULL, '進出する (melakukan ekspansi pasar) + にあたり menyatakan persiapan strategis sebelum ekspansi.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4f043e94-6752-456d-abf1-1b2f5403e43d', '90a296f7-2b51-4fde-af35-54aefab3d345', 'd1000019-0000-0000-0000-000000000018', 'writing', 'sentence_builder', 'Susun kalimat: "Menjelang ujian kelulusan, mahasiswa berdiskusi dengan dosen pembimbing."', '{"romaji":"Sotsugyou shiken o ukeru ni atatte, shidou kyouin to soudan shita.","tokens":["にあたって、","指導教員と","卒業試験を","に限らず、","相談","受ける","した。","受けた"],"target_translation":"Menjelang ujian kelulusan, mahasiswa berdiskusi dengan dosen pembimbing."}'::jsonb, '["卒業試験を","受ける","にあたって、","指導教員と","相談","した。"]'::jsonb, NULL, NULL, '指導教員 (dosen pembimbing) adalah kosakata penting bagi mahasiswa Indonesia di universitas Jepang.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('993019fa-c438-406f-8eb5-6f8d8efd74d4', '90a296f7-2b51-4fde-af35-54aefab3d345', 'd1000019-0000-0000-0000-000000000018', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Menjelang kerja sama ini, saya ingin menjelaskan jadwal pelaksanaannya."', '{"romaji":"Konkai no teikei ni atatte, jisshi sukejuuru o gosetsumei itashimasu.","display_text":"今回の提携にあたって、実施スケジュールをご説明いたします。","phonetic_breakdown":["こんかいの","ていけいに","あたって","じっし","すけじゅーるを","ごせつめいいたします"]}'::jsonb, '{"expected_transcript":"今回の提携にあたって、実施スケジュールをご説明いたします。"}'::jsonb, NULL, NULL, '提携 (teikei) berarti aliansi atau kerja sama bisnis antarperusahaan.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('53b186c3-ad0a-4345-836c-a82d51eb00eb', '90a296f7-2b51-4fde-af35-54aefab3d345', 'd1000019-0000-0000-0000-000000000018', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pada kesempatan pindah tugas ke Tokyo, saya mengucapkan banyak terima kasih."', '{"romaji":"Toukyou e no tenkin ni atari, kore made no goshien ni kansha itashimasu.","display_text":"東京への転勤にあたり、これまでのご支援に感謝いたします。","phonetic_breakdown":["とうきょうえの","てんきんに","あたり","これまでの","ごしえんに","かんしゃいたします"]}'::jsonb, '{"expected_transcript":"東京への転勤にあたり、これまでのご支援に感謝いたします。"}'::jsonb, NULL, NULL, '転勤 (tenkin) adalah mutasi kerja; ungkapan ini sangat alami untuk email perpisahan kantor.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9adc1681-c5de-4136-842e-39da08a794e6', '90a296f7-2b51-4fde-af35-54aefab3d345', 'd1000019-0000-0000-0000-000000000018', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Menjelang pembukaan cabang baru, kami sedang melatih staf lokal."', '{"romaji":"Shintenpo no kaiten ni atatte, genchi sutaffu no kenshuu o okonatte imasu.","display_text":"新店舗の開店にあたって、現地スタッフの研修を行っています。","phonetic_breakdown":["しんてんぽの","かいてんに","あたって","げんちすたっふの","けんしゅうを","おこなっています"]}'::jsonb, '{"expected_transcript":"新店舗の開店にあたって、現地スタッフの研修を行っています。"}'::jsonb, NULL, NULL, '研修を行う (menyelenggarakan pelatihan) lazim dipakai dalam persiapan operasional bisnis.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c028e874-9454-41cb-ade6-d370926329e6', '90a296f7-2b51-4fde-af35-54aefab3d345', 'd1000019-0000-0000-0000-000000000018', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 大会に出場する___、毎日の練習メニューを強化した。', '{"options":["にあたって","ざるを得ず","かねなく","つつあり"],"translation":"Menjelang bertanding di turnamen, saya meningkatkan intensitas menu latihan harian.","sentence_template":"大会に出場する[blank]、毎日の練習メニューを強化した。"}'::jsonb, '{"selected":"にあたって"}'::jsonb, NULL, NULL, '出場する (ikut bertanding) adalah peristiwa penting yang tepat memakai ～にあたって.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('23eaf685-6567-4cff-8b72-0bfc7f9aec81', '90a296f7-2b51-4fde-af35-54aefab3d345', 'd1000019-0000-0000-0000-000000000018', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Menjelang presentasi akhir, kami memeriksa kembali seluruh data statistik."', '{"romaji":"Saishuu happyou ni atatte, subete no toukei deeta o saikakunin shimashita.","display_text":"最終発表にあたって、すべての統計データを再確認しました。","phonetic_breakdown":["さいしゅうはっぴょうに","あたって","すべての","とうけいでーたを","さいかくにんしました"]}'::jsonb, '{"expected_transcript":"最終発表にあたって、すべての統計データを再確認しました。"}'::jsonb, NULL, NULL, '統計データ (data statistik) dan 再確認 (verifikasi ulang) lazim di konteks akademik dan bisnis.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9413c1e3-6ec8-41f5-8d1f-8f5ee88a54db', '91c88d1b-19a8-4598-8cdb-00239fa72a07', 'd1000019-0000-0000-0000-000000000023', 'listening', 'listening_choice', 'Dengarkan diskusi dua analis. Apa masalah utama dari kebijakan subsidi tersebut?', '{"options":[{"id":"opt_1","text":"Anggaran besar yang digelontorkan belum membuahkan pemulihan angka kelahiran sesuai target"},{"id":"opt_2","text":"Anggaran yang dialokasikan jauh lebih kecil dari tahun lalu"},{"id":"opt_3","text":"Angka kelahiran melonjak tajam melampaui target pemerintah"},{"id":"opt_4","text":"Kebijakan subsidi belum pernah dilaksanakan"}],"audio_text":"莫大な予算を投入したにもかかわらず、目標としていた出生率の回復には結びついていない。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '莫大な予算を投入したにもかかわらず (meski mengucurkan anggaran besar) kontras dengan 結びついていない.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3f318597-957d-4663-a2df-ddc28450f8a3', '91c88d1b-19a8-4598-8cdb-00239fa72a07', 'd1000019-0000-0000-0000-000000000023', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun dilarang keras, masih saja ada pengunjung yang memotret di dalam galeri."', '{"romaji":"Kibishiku kinshi sarete iru ni mo kakawarazu, shashin o toru nyuujousha ga iru.","tokens":["されている","写真を撮る","いる。","禁止した","厳しく禁止","にもかかわらず、","入場者が","に伴って、"],"target_translation":"Meskipun dilarang keras, masih saja ada pengunjung yang memotret di dalam galeri."}'::jsonb, '["厳しく禁止","されている","にもかかわらず、","写真を撮る","入場者が","いる。"]'::jsonb, NULL, NULL, 'V-te iru + にもかかわらず menyatakan tindakan yang tetap terjadi meski dilarang.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c2d67a62-5c88-4aec-a718-47b4c75fd7dc', '91c88d1b-19a8-4598-8cdb-00239fa72a07', 'd1000019-0000-0000-0000-000000000023', 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 足元が悪い___、本日は遠方よりお越しいただき感謝申し上げます。', '{"options":["にもかかわらず","にあたり","に伴い","かねない"],"translation":"Meskipun kondisi jalan sedang kurang baik (hujan/licin), kami ucapkan terima kasih atas kehadiran Anda dari jauh hari ini.","sentence_template":"足元が悪い[blank]、本日は遠方よりお越しいただき感謝申し上げます。"}'::jsonb, '{"selected":"にもかかわらず"}'::jsonb, NULL, NULL, '足元が悪いにもかかわらず adalah ungkapan sambutan standar saat cuaca hujan di Jepang.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7a6f76d2-0861-485e-96d2-0aa9aba6e380', '91c88d1b-19a8-4598-8cdb-00239fa72a07', 'd1000019-0000-0000-0000-000000000023', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun baru pertama kali berkunjung ke Jepang, ia berbicara sangat fasih."', '{"romaji":"Hajimete no rainichi ni mo kakawarazu, totemo ryuuchou na Nihongo o hanashimasu ne.","display_text":"初めての来日にもかかわらず、とても流暢な日本語を話しますね。","phonetic_breakdown":["はじめての","らいにちに","もかかわらず","とてもりゅうちょうな","にほんごを","はなしますね"]}'::jsonb, '{"expected_transcript":"初めての来日にもかかわらず、とても流暢な日本語を話しますね。"}'::jsonb, NULL, NULL, '初めての来日 (kunjungan pertama ke Jepang) + にもかかわらず mengekspresikan kekaguman.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1e96f538-0397-48b8-9b5b-e760a3adff46', '91c88d1b-19a8-4598-8cdb-00239fa72a07', 'd1000019-0000-0000-0000-000000000023', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 十分な説明を受けた___、まだ納得していない社員が多いようだ。', '{"options":["にもかかわらず","の上で","に限らず","ざるを得ない"],"translation":"Meskipun telah menerima penjelasan yang memadai, tampaknya masih banyak karyawan yang belum merasa yakin.","sentence_template":"十分な説明を受けた[blank]、まだ納得していない社員が多いようだ。"}'::jsonb, '{"selected":"にもかかわらず"}'::jsonb, NULL, NULL, 'V-ta + にもかかわらず menunjukkan hasil yang berlawanan dari yang diharapkan setelah penjelasan.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3a3c88ee-8082-4458-ba9a-bf8e4c7e0b07', '91c88d1b-19a8-4598-8cdb-00239fa72a07', 'd1000019-0000-0000-0000-000000000023', 'listening', 'listening_choice', 'Dengarkan ulasan film. Mengapa kritikus terkesan dengan film independen itu?', '{"options":[{"id":"opt_1","text":"Karena film itu dibuat dengan anggaran terbesar tahun ini"},{"id":"opt_2","text":"Karena film itu hanya berdurasi lima menit"},{"id":"opt_3","text":"Karena seluruh pemerannya adalah aktor Hollywood terkenal"},{"id":"opt_4","text":"Karena meski dibuat dengan biaya sangat terbatas, keindahan visual dan naskahnya setara film besar"}],"audio_text":"極めて限られた制作費で作られたにもかかわらず、映像美と脚本の完成度は大作に引けを取らない。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '大作に引けを取らない berarti tidak kalah mutunya dibanding film beranggaran besar.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8536ab9e-156f-49e2-a16a-a6d2745ca894', '91c88d1b-19a8-4598-8cdb-00239fa72a07', 'd1000019-0000-0000-0000-000000000023', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun sudah larut malam, lampu di ruang rapat masih menyala terang."', '{"romaji":"Shinya ni mo kakawarazu, kaigishitsu no akari wa mada tsuite iru.","tokens":["にも","会議室の明かりは","いる。","点いた。","深夜","かかわらず、","まだ点いて","にあたって、"],"target_translation":"Meskipun sudah larut malam, lampu di ruang rapat masih menyala terang."}'::jsonb, '["深夜","にも","かかわらず、","会議室の明かりは","まだ点いて","いる。"]'::jsonb, NULL, NULL, '深夜にもかかわらず menekankan suasana kerja lembur di luar jam wajar.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e999f403-c3b9-4476-a1a1-dc50326e6fdd', '91c88d1b-19a8-4598-8cdb-00239fa72a07', 'd1000019-0000-0000-0000-000000000023', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun sudah diperiksa berkali-kali, ternyata masih ada satu kesalahan ketik."', '{"romaji":"Nando mo kakunin shita ni mo kakawarazu, goji ga ikkasho nokotte imashita.","display_text":"何度も確認したにもかかわらず、誤字が一箇所残っていました。","phonetic_breakdown":["なんども","かくにんしたに","もかかわらず","ごじが","いっかしょ","のこっていました"]}'::jsonb, '{"expected_transcript":"何度も確認したにもかかわらず、誤字が一箇所残っていました。"}'::jsonb, NULL, NULL, '誤字 (salah ketik/aksara) sering dibahas dalam konteks penyuntingan dokumen kantor.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0c5b928a-ca70-46f6-9b15-ba56e16ea8df', '947641f3-096e-430a-b8b8-54ca3ccb99cd', 'd1000019-0000-0000-0000-000000000023', 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 彼はまだ来日して一年___にもかかわらず、日本語のニュースを正確に理解できる。', '{"options":["である","な","の","を"],"translation":"Meskipun baru satu tahun datang ke Jepang, ia dapat memahami berita bahasa Jepang secara akurat.","sentence_template":"彼はまだ来日して一年[blank]にもかかわらず、日本語のニュースを正確に理解できる。"}'::jsonb, '{"selected":"である"}'::jsonb, NULL, NULL, 'Kata benda 一年 diikuti であるにもかかわらず (atau langsung 一年にもかかわらず).', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('01e33125-8811-4215-a410-bd43429b7253', '947641f3-096e-430a-b8b8-54ca3ccb99cd', 'd1000019-0000-0000-0000-000000000023', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 医師から安静にするよう言われた___、彼は仕事を続けてしまった。', '{"options":["にもかかわらず","にあたって","に伴って","に限らず"],"translation":"Meskipun sudah diminta dokter untuk beristirahat total, ia tetap saja melanjutkan bekerja.","sentence_template":"医師から安静にするよう言われた[blank]、彼は仕事を続けてしまった。"}'::jsonb, '{"selected":"にもかかわらず"}'::jsonb, NULL, NULL, '安静にする (beristirahat tenang/bed rest) + 言われたにもかかわらず menekankan tindakan yang bertentangan dengan saran.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a48244dd-e8e1-4c3d-87a7-faeaa421c7f4', '947641f3-096e-430a-b8b8-54ca3ccb99cd', 'd1000019-0000-0000-0000-000000000023', 'listening', 'listening_choice', 'Dengarkan laporan cuaca berikut. Apa yang terjadi meski peringatan sudah dikeluarkan?', '{"options":[{"id":"opt_1","text":"Semua warga tetap berada di dalam rumah dengan aman"},{"id":"opt_2","text":"Terjadi serangkaian insiden orang mendekati sungai hingga harus diselamatkan"},{"id":"opt_3","text":"Peringatan hujan lebat dicabut lebih cepat dari jadwal"},{"id":"opt_4","text":"Air sungai justru surut drastis sepanjang malam"}],"audio_text":"大雨警報が出ていたにもかかわらず、川に近づいて救助される事故が相次いだ。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '相次ぐ (aitsugu) berarti terjadi berturut-turut; 救助される berarti diselamatkan.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eb5ee8af-276b-403c-acfe-e2c7702b4b37', '947641f3-096e-430a-b8b8-54ca3ccb99cd', 'd1000019-0000-0000-0000-000000000023', 'listening', 'listening_choice', 'Dengarkan ulasan film berikut. Apa keunikan film tersebut?', '{"options":[{"id":"opt_1","text":"Film itu gagal total karena kurang promosi televisi"},{"id":"opt_2","text":"Film itu dibintangi puluhan aktor papan atas dunia"},{"id":"opt_3","text":"Film itu hanya diputar selama tiga hari di bioskop kecil"},{"id":"opt_4","text":"Film itu menjadi hit besar lewat rekomendasi dari mulut ke mulut meski tanpa aktor terkenal"}],"audio_text":"有名な俳優が出ていないにもかかわらず、口コミで評判が広がり大ヒットとなった。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '口コミ (kuchikomi) berarti informasi dari mulut ke mulut.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1476cf7b-d179-4034-9b67-e8f86c303629', '947641f3-096e-430a-b8b8-54ca3ccb99cd', 'd1000019-0000-0000-0000-000000000023', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun sudah larut malam, ia membalas email saya dengan cepat."', '{"romaji":"Yoru osoi jikan ni mo kakawarazu, sugu ni henshin o kureta.","tokens":["すぐに","くれた。","に伴って、","時間","返信を","夜遅い","にもかかわらず、","時間な"],"target_translation":"Meskipun sudah larut malam, ia membalas email saya dengan cepat."}'::jsonb, '["夜遅い","時間","にもかかわらず、","すぐに","返信を","くれた。"]'::jsonb, NULL, NULL, '返信をくれる berarti membalas pesan/email untuk saya.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bbb2809b-b119-42e3-a365-6e036a249d81', '947641f3-096e-430a-b8b8-54ca3ccb99cd', 'd1000019-0000-0000-0000-000000000023', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun ini percobaan pertama, semuanya berjalan lebih lancar dari dugaan."', '{"romaji":"Hajimete no kokoromi ni mo kakawarazu, yosou ijou ni junchou ni susumimashita.","display_text":"初めての試みにもかかわらず、予想以上に順調に進みました。","phonetic_breakdown":["はじめての","こころみにも","かかわらず","よそういじょうに","じゅんちょうに","すすみました"]}'::jsonb, '{"expected_transcript":"初めての試みにもかかわらず、予想以上に順調に進みました。"}'::jsonb, NULL, NULL, '試み (kokoromi) berarti upaya/inisiatif baru; 順調に進む berarti berjalan lancar.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c47ce063-44e3-476d-8912-571dcf832c31', '947641f3-096e-430a-b8b8-54ca3ccb99cd', 'd1000019-0000-0000-0000-000000000023', 'listening', 'listening_choice', 'Dengarkan kutipan editorial berikut. Apa poin kritik penulis?', '{"options":[{"id":"opt_1","text":"Penulis mendukung penuh pelaksanaan rencana secepatnya"},{"id":"opt_2","text":"Semua kekhawatiran soal keamanan telah terjawab tuntas"},{"id":"opt_3","text":"Rencana tersebut sudah dibatalkan oleh pihak berwenang"},{"id":"opt_4","text":"Penulis mempertanyakan sikap memaksakan rencana meski kekhawatiran keamanan belum teratasi"}],"audio_text":"安全性への懸念が解消されていないにもかかわらず、計画を強行する姿勢には疑問が残る。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '懸念が解消されていないにもかかわらず (meski kekhawatiran belum terselesaikan) + 疑問が残る (menyisakan tanda tanya).', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0915dbd4-cc53-4fc1-88dd-bd38985af35e', '947641f3-096e-430a-b8b8-54ca3ccb99cd', 'd1000019-0000-0000-0000-000000000023', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun jaraknya jauh, banyak pelanggan tetap datang berkunjung dari luar prefektur."', '{"romaji":"Enpou ni mo kakawarazu, kengai kara mo ooku no kyaku ga otozureru.","tokens":["にも","県外からも","訪れる。","訪れた。","遠方","かかわらず、","多くの客が","に限らず、"],"target_translation":"Meskipun jaraknya jauh, banyak pelanggan tetap datang berkunjung dari luar prefektur."}'::jsonb, '["遠方","にも","かかわらず、","県外からも","多くの客が","訪れる。"]'::jsonb, NULL, NULL, '遠方にもかかわらず adalah ungkapan formal untuk menghargai kedatangan dari jauh.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cc5f43d4-19d7-4297-b95f-2785e50ae3ab', '9bb0504d-814d-485b-83b1-0624f0a4c23d', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: チーム全員で十分に___した上で、最終案を決定した。', '{"options":["検討","欠席","撤退","渋滞"],"translation":"Setelah seluruh tim mempertimbangkan secara matang, kami memutuskan draf final.","sentence_template":"チーム全員で十分に[blank]した上で、最終案を決定した。"}'::jsonb, '{"selected":"検討"}'::jsonb, NULL, NULL, '検討する (kentou suru) berarti meninjau atau mempertimbangkan secara mendalam sebelum mengambil keputusan.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d764fe02-6d2f-48e0-ab8d-388608efbd32', '9bb0504d-814d-485b-83b1-0624f0a4c23d', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat bisnis berikut: 契約書の条項をすべて___した上で、署名してください。', '{"options":["確認","延期","普及","卒業"],"translation":"Silakan tanda tangan setelah memastikan seluruh pasal dalam surat kontrak.","sentence_template":"契約書の条項をすべて[blank]した上で、署名してください。"}'::jsonb, '{"selected":"確認"}'::jsonb, NULL, NULL, '条項 (joukou) adalah pasal/klausul; 確認した上で berarti ''setelah memastikan''.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5f474028-7ac9-449b-944c-10316ef5ac5c', '9bb0504d-814d-485b-83b1-0624f0a4c23d', NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: 海外で働く上で、現地の商習慣への___が欠かせない。', '{"options":["理解","物価","天候","予算"],"translation":"Dalam bekerja di luar negeri, pemahaman terhadap kebiasaan bisnis lokal tidak boleh terlewatkan.","sentence_template":"海外で働く上で、現地の商習慣への[blank]が欠かせない。"}'::jsonb, '{"selected":"理解"}'::jsonb, NULL, NULL, '商習慣 (shoushuukan) berarti adat/kebiasaan bisnis; 理解 berarti pemahaman.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('78d088ff-e698-4bf5-8edb-3affaeea0141', '9bb0504d-814d-485b-83b1-0624f0a4c23d', NULL, 'listening', 'listening_choice', 'Dengarkan arahan manajer berikut. Kapan keputusan akhir akan dibuat?', '{"options":[{"id":"opt_1","text":"Setelah mendengarkan pendapat tiap departemen pada rapat minggu depan"},{"id":"opt_2","text":"Hari ini juga sebelum jam makan siang berakhir"},{"id":"opt_3","text":"Bulan depan setelah laporan keuangan tahunan terbit"},{"id":"opt_4","text":"Segera tanpa perlu berkonsultasi dengan departemen lain"}],"audio_text":"来週の会議で各部署の意見を聞いた上で、正式なスケジュールを決定します。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '意見を聞いた上で (setelah mendengarkan pendapat) menunjukkan syarat sebelum keputusan resmi dibuat.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e79a4f9f-f797-461e-afe6-35fb241f51ea', '9bb0504d-814d-485b-83b1-0624f0a4c23d', NULL, 'listening', 'listening_choice', 'Dengarkan nasihat dosen berikut. Hal apa yang penting saat menulis karya ilmiah?', '{"options":[{"id":"opt_1","text":"Membuat sampul berwarna cerah"},{"id":"opt_2","text":"Memilih daftar pustaka yang tepercaya"},{"id":"opt_3","text":"Menulis dengan jumlah halaman seminimal mungkin"},{"id":"opt_4","text":"Menggunakan bahasa percakapan sehari-hari"}],"audio_text":"論文を書く上で、信頼できる参考文献を選ぶことが何よりも重要です。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '論文を書く上で (dalam menulis makalah ilmiah) + 信頼できる参考文献 (referensi yang dapat dipercaya).', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('19b20452-a70c-45ba-be1f-47b7b9c056e1', '9bb0504d-814d-485b-83b1-0624f0a4c23d', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah berdiskusi dengan keluarga, saya memutuskan untuk melamar pekerjaan ini."', '{"romaji":"Kazoku to soudan shita ue de, kono kaisha ni oubo suru koto ni shimashita.","display_text":"家族と相談した上で、この会社に応募することにしました。","phonetic_breakdown":["かぞくと","そうだんした","うえで","このかいしゃに","おうぼすることに","しました"]}'::jsonb, '{"expected_transcript":"家族と相談した上で、この会社に応募することにしました。"}'::jsonb, NULL, NULL, '相談した上で (setelah berkonsultasi) dan 応募する (melamar pekerjaan/beasiswa).', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cb95a45a-374d-4068-a578-6cb4c5589552', '9bb0504d-814d-485b-83b1-0624f0a4c23d', 'd1000019-0000-0000-0000-000000000024', 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 現状の課題を正確に___した上で、改善計画を立てよう。', '{"options":["把握","廃止","撤退","欠席"],"translation":"Setelah memahami permasalahan saat ini secara akurat, mari kita susun rencana perbaikan.","sentence_template":"現状の課題を正確に[blank]した上で、改善計画を立てよう。"}'::jsonb, '{"selected":"把握"}'::jsonb, NULL, NULL, '把握する (haaku suru = memahami/menguasai situasi secara akurat) sangat sering dipasangkan dengan ～した上で.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('43fc3618-e7d0-4a98-a46f-fc5e87b10272', '9bb0504d-814d-485b-83b1-0624f0a4c23d', 'd1000019-0000-0000-0000-000000000024', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dalam hal bekerja sama secara internasional, pemahaman budaya sangat membantu."', '{"romaji":"Kokusaiteki ni kyoudou suru ue de, ibunka e no rikai ga ookina tasuke ni narimasu.","display_text":"国際的に協働する上で、異文化への理解が大きな助けになります。","phonetic_breakdown":["こくさいてきに","きょうどうするうえで","いぶんかえのりかいが","おおきなたすけに","なります"]}'::jsonb, '{"expected_transcript":"国際的に協働する上で、異文化への理解が大きな助けになります。"}'::jsonb, NULL, NULL, '協働する (bekerja sama secara setara) + 上で cocok untuk konteks profesional global.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0c108c4e-8f93-44c2-91cc-f03d18cb3304', '9c66d2e2-27ab-44b5-9b95-0fae05433ce4', 'd1000019-0000-0000-0000-000000000027', 'reading', 'fill_blank', 'Lengkapi pola Sonkeigo お + V-ます stem + になる: お客様はもう会場に___になりました。', '{"options":["お着き","お着く","お着いた","お着いて"],"translation":"Tamu sudah tiba di lokasi acara.","sentence_template":"お客様はもう会場に[blank]になりました。"}'::jsonb, '{"selected":"お着き"}'::jsonb, NULL, NULL, 'Pola お + [Akar ます] + になる: 着く → お着きになる.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6367048f-25ad-4d5a-b940-b5a1f683c052', '9c66d2e2-27ab-44b5-9b95-0fae05433ce4', 'd1000019-0000-0000-0000-000000000027', 'reading', 'fill_blank', 'Pilih bentuk Sonkeigo yang benar untuk kata kerja する (kango): 田中様はこちらの資料をすでに___ましたか。', '{"options":["ご確認なさい","ご確認いたし","ご確認申し","ご確認参り"],"translation":"Apakah Bapak Tanaka sudah memeriksa dokumen ini?","sentence_template":"田中様はこちらの資料をすでに[blank]ましたか。"}'::jsonb, '{"selected":"ご確認なさい"}'::jsonb, NULL, NULL, 'ご + [Nomina Kango] + なさる adalah pola Sonkeigo yang sangat baku (konjugasi ます: なさいます).', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('98514d95-0d85-439d-85fc-96752cf5e943', '9c66d2e2-27ab-44b5-9b95-0fae05433ce4', 'd1000019-0000-0000-0000-000000000027', 'reading', 'fill_blank', 'Pilih bentuk Sonkeigo dari 知っている: 部長は今度の人事異動について___ですか。', '{"options":["ご存じ","存じ上げ","お知り","ご承知いたし"],"translation":"Apakah Bapak Kepala Departemen mengetahui mengenai mutasi personalia kali ini?","sentence_template":"部長は今度の人事異動について[blank]ですか。"}'::jsonb, '{"selected":"ご存じ"}'::jsonb, NULL, NULL, 'Sonkeigo dari 知っている adalah ご存じです (sedangkan 存じ上げる adalah Kenjougo).', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('425e18c0-a120-44bf-b735-e3e65d877baf', '9c66d2e2-27ab-44b5-9b95-0fae05433ce4', 'd1000019-0000-0000-0000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat: "Bapak Presiden Direktur sudah pulang ke rumah sekitar pukul lima."', '{"romaji":"Shachou wa goji goro okaeri ni narimashita.","tokens":["お帰りに","五時ごろ","参り","お帰りいたし","ました。","なり","社長は"],"target_translation":"Bapak Presiden Direktur sudah pulang ke rumah sekitar pukul lima."}'::jsonb, '["社長は","五時ごろ","お帰りに","なり","ました。"]'::jsonb, NULL, NULL, '帰る → お帰りになる adalah bentuk Sonkeigo yang tepat untuk atasan.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f76f949b-d174-4a55-b683-667b0c66da09', '9c66d2e2-27ab-44b5-9b95-0fae05433ce4', 'd1000019-0000-0000-0000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat: "Silakan duduk di kursi sebelah sini sambil menunggu."', '{"romaji":"Douzo kochira no oseki ni okake kudasai.","tokens":["ください。","こちらの","掛けいたし","どうぞ","お席に","お掛け","参って"],"target_translation":"Silakan duduk di kursi sebelah sini sambil menunggu."}'::jsonb, '["どうぞ","こちらの","お席に","お掛け","ください。"]'::jsonb, NULL, NULL, 'お掛けください (dari 腰掛ける) adalah ungkapan baku mempersilakan tamu duduk.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d64812b7-0a00-45ed-ae44-29e010cf8eae', '9c66d2e2-27ab-44b5-9b95-0fae05433ce4', 'd1000019-0000-0000-0000-000000000027', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika ada pertanyaan, silakan bertanya kapan saja."', '{"romaji":"Gofumei na ten ga gozaimashitara, itsudemo otazune kudasai.","display_text":"ご不明な点がございましたら、いつでもお尋ねください。","phonetic_breakdown":["ごふめいなてんが","ございましたら","いつでも","おたずねください"]}'::jsonb, '{"expected_transcript":"ご不明な点がございましたら、いつでもお尋ねください。"}'::jsonb, NULL, NULL, 'お尋ねください berarti ''silakan bertanya'' dengan tingkat kesopanan bisnis baku.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6419837a-5f47-405d-b3a4-ff5d328ba275', '9c66d2e2-27ab-44b5-9b95-0fae05433ce4', 'd1000019-0000-0000-0000-000000000027', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Manakah pilihan yang menjelaskan penggunaan sonkeigo di dalamnya?', '{"options":[{"id":"opt_1","text":"Pembicara menghormati dosen dengan memakai ～てくださった karena dosen berkenan merekomendasikan buku"},{"id":"opt_2","text":"Pembicara meminta dosen meminjamkan kartu perpustakaan"},{"id":"opt_3","text":"Dosen meminjam buku dari mahasiswa"},{"id":"opt_4","text":"Pembicara lupa judul buku yang direkomendasikan"}],"audio_text":"先生が推薦してくださった専門書を、さっそく図書館で借りてきました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '～てくださる adalah bentuk sonkeigo dari ～てくれる yang meninggikan tindakan baik dari atasan/dosen.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1d2feb3e-a534-4771-86e6-13c3504d9271', '9c66d2e2-27ab-44b5-9b95-0fae05433ce4', 'd1000019-0000-0000-0000-000000000027', 'reading', 'fill_blank', 'Lengkapi kalimat dengan sonkeigo untuk する: 本日のイベントには、多くの来賓の方々にご参加___。', '{"options":["いただきました","いたしました","申しました","おりました"],"translation":"Pada acara hari ini, banyak tamu kehormatan berkenan turut berpartisipasi.","sentence_template":"本日のイベントには、多くの来賓の方々にご参加[blank]。"}'::jsonb, '{"selected":"いただきました"}'::jsonb, NULL, NULL, 'ご参加いただきました (menerima kehormatan partisipasi Anda) adalah ungkapan baku dalam laporan acara.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d4f85f91-ee57-449b-ad48-b6e2067b1442', '9da4305a-e998-45d3-92d0-ebca7fd8e82c', 'd1000019-0000-0000-0000-000000000025', 'reading', 'fill_blank', 'Pilih konjugasi yang benar untuk ～つつある: 地球温暖化の影響は、年々深刻に___つつある。', '{"options":["なり","なる","なった","なって"],"translation":"Dampak pemanasan global sedang menjadi semakin serius dari tahun ke tahun.","sentence_template":"地球温暖化の影響は、年々深刻に[blank]つつある。"}'::jsonb, '{"selected":"なり"}'::jsonb, NULL, NULL, 'Pola ～つつある selalu menempel pada akar bentuk ます (なる → なります → なりつつある).', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2442ea9d-06cf-42cb-986c-7e88551226b2', '9da4305a-e998-45d3-92d0-ebca7fd8e82c', 'd1000019-0000-0000-0000-000000000025', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 長年の研究の成果が、ようやく実用化___つつある。', '{"options":["され","する","した","して"],"translation":"Hasil penelitian bertahun-tahun akhirnya sedang mulai diterapkan secara praktis.","sentence_template":"長年の研究の成果が、ようやく実用化[blank]つつある。"}'::jsonb, '{"selected":"され"}'::jsonb, NULL, NULL, '実用化される (diterapkan secara praktis) → akar ます adalah 実用化され → 実用化されつつある.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3f9c1119-29f3-4a5c-a672-732d70622f7a', '9da4305a-e998-45d3-92d0-ebca7fd8e82c', 'd1000019-0000-0000-0000-000000000025', 'reading', 'fill_blank', 'Pilih pola yang paling tepat: 少子化の影響で、地方の学校の統廃合が___。', '{"options":["進みつつある","進みたつつある","進むつつある","進んでつつある"],"translation":"Akibat penurunan angka kelahiran, penggabungan dan penutupan sekolah daerah sedang terus berlanjut.","sentence_template":"少子化の影響で、地方の学校の統廃合が[blank]。"}'::jsonb, '{"selected":"進みつつある"}'::jsonb, NULL, NULL, '進む → 進みます → 進みつつある.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('57fee017-67c6-4b5f-ad91-d63443134158', '9da4305a-e998-45d3-92d0-ebca7fd8e82c', 'd1000019-0000-0000-0000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat: "Lingkungan bisnis di industri ini sedang mengalami perubahan besar."', '{"romaji":"Kono gyoukai no bijinesu kankyou wa ookiku henka shitsutsu aru.","tokens":["しつつ","にあたって","この業界の","ビジネス環境は","大きく","変化して","ある。","変化"],"target_translation":"Lingkungan bisnis di industri ini sedang mengalami perubahan besar."}'::jsonb, '["この業界の","ビジネス環境は","大きく","変化","しつつ","ある。"]'::jsonb, NULL, NULL, '変化する → 変化します → 変化しつつある.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dcf4ba1e-9c31-46e4-8399-5f3f25197c68', '9da4305a-e998-45d3-92d0-ebca7fd8e82c', 'd1000019-0000-0000-0000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat: "Penggunaan kendaraan listrik sedang meluas secara bertahap di seluruh dunia."', '{"romaji":"Denki jidousha no riyou ga sekaijuu de jojo ni hirogaritsutsu aru.","tokens":["徐々に","広がり","利用が","つつある。","広がる","電気自動車の","に限らず","世界中で"],"target_translation":"Penggunaan kendaraan listrik sedang meluas secara bertahap di seluruh dunia."}'::jsonb, '["電気自動車の","利用が","世界中で","徐々に","広がり","つつある。"]'::jsonb, NULL, NULL, '徐々に (secara bertahap) sering berkolokasi dengan ～つつある.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('74680338-c08a-47c7-a55b-06a64ad29c96', '9da4305a-e998-45d3-92d0-ebca7fd8e82c', 'd1000019-0000-0000-0000-000000000025', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kepercayaan pelanggan terhadap merek kami sedang berangsur pulih."', '{"romaji":"Tousha burando e no kokyaku no shinrai wa, chakujitsu ni kaifuku shitsutsu arimasu.","display_text":"当社ブランドへの顧客の信頼は、着実に回復しつつあります。","phonetic_breakdown":["とうしゃぶらんどえの","こきゃくのしんらいは","ちゃくじつに","かいふくしつつ","あります"]}'::jsonb, '{"expected_transcript":"当社ブランドへの顧客の信頼は、着実に回復しつつあります。"}'::jsonb, NULL, NULL, '着実に (chakujitsu ni) berarti secara mantap dan pasti.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1191f083-e974-447d-a494-7d4c140c3913', '9da4305a-e998-45d3-92d0-ebca7fd8e82c', 'd1000019-0000-0000-0000-000000000025', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa yang sedang terjadi pada proyek tersebut?', '{"options":[{"id":"opt_1","text":"Proyek pengembangan sedang makin mendekati penyelesaian sesuai jadwal setelah mengejar ketertinggalan awal"},{"id":"opt_2","text":"Proyek pengembangan dibatalkan karena terlalu terlambat"},{"id":"opt_3","text":"Proyek belum dimulai sama sekali"},{"id":"opt_4","text":"Tim pengembang mengundurkan diri di tengah jalan"}],"audio_text":"当初の遅れを取り戻し、開発プロジェクトは予定通りの完成に近づきつつある。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '完成に近づきつつある berarti sedang semakin mendekati tahap penyelesaian.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9f594b1c-01a0-40c5-aecb-a654944f86ea', '9da4305a-e998-45d3-92d0-ebca7fd8e82c', 'd1000019-0000-0000-0000-000000000025', 'reading', 'fill_blank', 'Lengkapi kalimat dengan konjugasi yang benar: 長年続いた習慣も、時代の変化とともに忘れられ___。', '{"options":["つつある","かねない","ざるを得ない","わけにはいかない"],"translation":"Kebiasaan yang berlangsung bertahun-tahun pun sedang perlahan terlupakan seiring perubahan zaman.","sentence_template":"長年続いた習慣も、時代の変化とともに忘れられ[blank]。"}'::jsonb, '{"selected":"つつある"}'::jsonb, NULL, NULL, '忘れられる (pasif) -> 忘れられつつある menyatakan proses pelupaan yang sedang terjadi.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('07c2e3cb-41cf-4062-80ea-6abd2a912c08', 'a1b45de6-ce82-4960-824b-43717c7c9108', NULL, 'listening', 'listening_choice', 'Dengarkan berita ekonomi berikut. Fakta apa yang mengejutkan?', '{"options":[{"id":"opt_1","text":"Penjualan barang merek mewah justru melampaui tahun lalu meski ekonomi lesu"},{"id":"opt_2","text":"Seluruh toko merek mewah tutup karena ekonomi lesu"},{"id":"opt_3","text":"Ekonomi tumbuh pesat namun penjualan barang mewah turun"},{"id":"opt_4","text":"Harga barang kebutuhan pokok turun tajam dibanding tahun lalu"}],"audio_text":"景気が低迷しているにもかかわらず、高級ブランド品の売上は前年を上回った。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '前年を上回る berarti melampaui capaian tahun sebelumnya.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('59340202-90e2-442f-a46f-db2425a7a848', 'a1b45de6-ce82-4960-824b-43717c7c9108', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman layanan berikut. Apa yang terjadi meski pemeliharaan sudah selesai?', '{"options":[{"id":"opt_1","text":"Semua pengguna sudah bisa masuk tanpa hambatan"},{"id":"opt_2","text":"Gangguan gagal masuk pada sebagian perangkat masih berlanjut"},{"id":"opt_3","text":"Pembaruan sistem ditunda hingga bulan depan"},{"id":"opt_4","text":"Seluruh perangkat lama harus diganti dengan yang baru"}],"audio_text":"システムを更新したにもかかわらず、一部の端末でログインできない不具合が続いています。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '不具合 (fuguai) berarti malfungsi atau bug sistem.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f891c2cd-04da-46a8-a33b-b2e9ccf614d1', 'a1b45de6-ce82-4960-824b-43717c7c9108', NULL, 'listening', 'listening_choice', 'Dengarkan komentar pelatih berikut. Mengapa pemain itu dipuji?', '{"options":[{"id":"opt_1","text":"Karena mencetak rekor kecepatan tertinggi pada babak pertama"},{"id":"opt_2","text":"Karena memutuskan mundur demi menjaga kondisi tim"},{"id":"opt_3","text":"Karena tetap berlari sekuat tenaga hingga akhir meski kakinya cedera"},{"id":"opt_4","text":"Karena membantu wasit mengatur jalannya pertandingan"}],"audio_text":"試合の途中で足を痛めたにもかかわらず、最後まで全力で走り抜いた姿に感動しました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '足を痛めたにもかかわらず (meskipun kakinya cedera) diikuti 最後まで全力で走り抜いた (berlari sekuat tenaga hingga akhir).', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('04f8b89f-73f4-40e5-8910-a52aaeced62d', 'a1b45de6-ce82-4960-824b-43717c7c9108', NULL, 'reading', 'fill_blank', 'Lengkapi kutipan artikel berikut: 事前に何度も確認した___、書類に誤字が残っていた。', '{"options":["にもかかわらず","にあたって","に限らず","に伴って"],"translation":"Meskipun telah memeriksa berkali-kali sebelumnya, masih ada salah ketik yang tertinggal di dokumen.","sentence_template":"事前に何度も確認した[blank]、書類に誤字が残っていた。"}'::jsonb, '{"selected":"にもかかわらず"}'::jsonb, NULL, NULL, '誤字 (goji) berarti salah ketik/salah tulis huruf.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b1dfaa00-5244-4728-a1dd-952b274f9a7a', 'a1b45de6-ce82-4960-824b-43717c7c9108', NULL, 'reading', 'fill_blank', 'Pilih kata hubung yang tepat di awal kalimat kedua: 昨日は大雪だった。___、電車は一本も遅れなかった。', '{"options":["それにもかかわらず","それにあたって","それに伴って","それに限らず"],"translation":"Kemarin salju turun lebat. Meskipun demikian, tidak ada satu pun kereta yang terlambat.","sentence_template":"昨日は大雪だった。[blank]、電車は一本も遅れなかった。"}'::jsonb, '{"selected":"それにもかかわらず"}'::jsonb, NULL, NULL, 'それにもかかわらず berfungsi sebagai konjungsi antarkalimat yang berarti ''meskipun demikian''.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ad472093-e861-42e7-b148-33978bcf61bf', 'a1b45de6-ce82-4960-824b-43717c7c9108', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun tidak memiliki pengalaman, ia dengan cepat menguasai pekerjaan tersebut."', '{"romaji":"Mikeiken de aru ni mo kakawarazu, kare wa sugu ni gyoumu o oboemashita.","display_text":"未経験であるにもかかわらず、彼はすぐに業務を覚えました。","phonetic_breakdown":["みけいけん","であるにも","かかわらず","かれはすぐに","ぎょうむを","おぼえました"]}'::jsonb, '{"expected_transcript":"未経験であるにもかかわらず、彼はすぐに業務を覚えました。"}'::jsonb, NULL, NULL, '未経験 (belum berpengalaman) dan 業務を覚える (menguasai tugas kerja) adalah kosakata dunia kerja.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2cc258a3-9cc2-400b-9c13-550d21240da4', 'a1b45de6-ce82-4960-824b-43717c7c9108', 'd1000019-0000-0000-0000-000000000023', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun mendapat kritik keras, ia tidak mengubah pendiriannya."', '{"romaji":"Kibishii hihan o abita ni mo kakawarazu, kare wa shuchou o kaenakatta.","tokens":["浴びた","彼は主張を","なかった。","かねなかった。","厳しい批判を","にもかかわらず、","変え","浴びる"],"target_translation":"Meskipun mendapat kritik keras, ia tidak mengubah pendiriannya."}'::jsonb, '["厳しい批判を","浴びた","にもかかわらず、","彼は主張を","変え","なかった。"]'::jsonb, NULL, NULL, '批判を浴びる (dihujani kritik) + にもかかわらず menggambarkan keteguhan sikap.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('506a45a9-b375-4201-acf8-6a6a477672bc', 'a1b45de6-ce82-4960-824b-43717c7c9108', 'd1000019-0000-0000-0000-000000000023', 'listening', 'listening_choice', 'Dengarkan laporan lalu lintas. Kondisi apa yang terjadi di jalan tol?', '{"options":[{"id":"opt_1","text":"Terjadi kemacetan parah sepanjang lima puluh kilometer"},{"id":"opt_2","text":"Jalan tol ditutup karena perbaikan jembatan"},{"id":"opt_3","text":"Meskipun hari pertama libur tiga hari berturut-turut, sejauh ini belum ada kemacetan besar"},{"id":"opt_4","text":"Semua gerbang tol digratiskan hari ini"}],"audio_text":"三連休の初日にもかかわらず、現在のところ高速道路に大きな渋滞は発生していません。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '三連休の初日にもかかわらず kontras dengan 大きな渋滞は発生していません.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c8dab2c8-187b-45fa-806d-81b75ed6b821', 'a3645058-b04b-4958-9c91-35a2e545af95', 'd1000019-0000-0000-0000-000000000026', 'reading', 'fill_blank', 'Lengkapi konjugasi yang benar: このまま赤字が続けば、会社は倒産___かねない。', '{"options":["し","する","した","して"],"translation":"Jika defisit terus berlanjut seperti ini, perusahaan bisa saja bangkrut.","sentence_template":"このまま赤字が続けば、会社は倒産[blank]かねない。"}'::jsonb, '{"selected":"し"}'::jsonb, NULL, NULL, 'Pola ～かねない menempel pada akar bentuk ます (倒産する → 倒産し + かねない).', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1c55f464-e225-41f8-a6af-de9257c17113', 'a3645058-b04b-4958-9c91-35a2e545af95', 'd1000019-0000-0000-0000-000000000026', 'reading', 'fill_blank', 'Pilih pola yang tepat untuk risiko negatif: 噂を軽率に広めると、深刻なトラブルに発展___。', '{"options":["しかねない","しつつある","するにあたって","するに限らず"],"translation":"Jika menyebarkan rumor secara gegabah, hal itu bisa saja berkembang menjadi masalah serius.","sentence_template":"噂を軽率に広めると、深刻なトラブルに発展[blank]。"}'::jsonb, '{"selected":"しかねない"}'::jsonb, NULL, NULL, '～かねない khusus digunakan untuk kemungkinan terjadinya hal buruk/tidak diinginkan.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bb9f42cc-daaf-442f-b8c9-c6f7f889d82e', 'a3645058-b04b-4958-9c91-35a2e545af95', 'd1000019-0000-0000-0000-000000000026', 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk verba Godan berikut: 準備不足のまま発表すれば、質問に答えられず恥を___かねない。', '{"options":["かき","かく","かいた","かいて"],"translation":"Jika presentasi tanpa persiapan cukup, kita bisa saja malu karena tak mampu menjawab pertanyaan.","sentence_template":"準備不足のまま発表すれば、質問に答えられず恥を[blank]かねない。"}'::jsonb, '{"selected":"かき"}'::jsonb, NULL, NULL, '恥をかく (mendapat malu) → akar ます adalah 恥をかき → 恥をかきかねない.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('23b69438-849b-44c0-a01e-4a263dbc6e6f', 'a3645058-b04b-4958-9c91-35a2e545af95', 'd1000019-0000-0000-0000-000000000026', 'writing', 'sentence_builder', 'Susun kalimat: "Keterlambatan pengiriman bisa saja memicu pembatalan kontrak."', '{"romaji":"Nouki no okure wa, keiyaku no kaijo o manekikanenai.","tokens":["解除を","契約の","遅れは、","納期の","つつある。","招く","かねない。","招き"],"target_translation":"Keterlambatan pengiriman bisa saja memicu pembatalan kontrak."}'::jsonb, '["納期の","遅れは、","契約の","解除を","招き","かねない。"]'::jsonb, NULL, NULL, '招く (mengundang/memicu dampak buruk) → 招きかねない.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dee168e7-363a-417b-84af-5f7c91aafd41', 'a3645058-b04b-4958-9c91-35a2e545af95', 'd1000019-0000-0000-0000-000000000026', 'writing', 'sentence_builder', 'Susun kalimat: "Mengemudi dalam keadaan mengantuk bisa saja menyebabkan kecelakaan fatal."', '{"romaji":"Inemuri unten wa, inochi ni kakawaru jiko o hikiokoshikanenai.","tokens":["にあたって。","かねない。","居眠り運転は、","引き起こし","命に関わる","事故を","引き起こす"],"target_translation":"Mengemudi dalam keadaan mengantuk bisa saja menyebabkan kecelakaan fatal."}'::jsonb, '["居眠り運転は、","命に関わる","事故を","引き起こし","かねない。"]'::jsonb, NULL, NULL, '命に関わる事故 (kecelakaan yang mengancam nyawa) + 引き起こしかねない.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('48300a22-8844-4502-adbe-d60e963b52eb', 'a3645058-b04b-4958-9c91-35a2e545af95', 'd1000019-0000-0000-0000-000000000026', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika data tidak dicadangkan, dokumen penting bisa saja hilang seluruhnya."', '{"romaji":"Bakkuappu o toranai to, juuyouna deeta ga subete kiekanemasen.","display_text":"バックアップを取らないと、重要なデータがすべて消えかねません。","phonetic_breakdown":["ばっくあっぷを","とらないと","じゅうような","でーたがすべて","きえかねません"]}'::jsonb, '{"expected_transcript":"バックアップを取らないと、重要なデータがすべて消えかねません。"}'::jsonb, NULL, NULL, '消える (Ichidan) → 消えかねない (bisa saja hilang).', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f6625ad8-8e9f-457f-b127-6937659d6cef', 'a3645058-b04b-4958-9c91-35a2e545af95', 'd1000019-0000-0000-0000-000000000026', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa nuansa utama dari ～かねない dalam konteks ini?', '{"options":[{"id":"opt_1","text":"Kekhawatiran realistis bahwa perusahaan bisa saja jatuh bangkrut jika defisit berlanjut"},{"id":"opt_2","text":"Harapan gembira bahwa keuntungan akan meningkat"},{"id":"opt_3","text":"Kepastian bahwa perusahaan pasti sukses besar"},{"id":"opt_4","text":"Kewajiban etis untuk mengambil cuti bersama"}],"audio_text":"このまま赤字が続けば、来期は経営破綻に陥りかねない状況だ。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '～かねない selalu digunakan untuk memperingatkan kemungkinan hasil negatif yang dikhawatirkan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2cc7dd47-c40e-4572-ae61-823cf80ff61f', 'a3645058-b04b-4958-9c91-35a2e545af95', 'd1000019-0000-0000-0000-000000000026', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 電源コードが傷んだまま使い続けると、火災の原因になり___。', '{"options":["かねない","つつある","ざるを得ない","わけにはいかない"],"translation":"Jika terus digunakan saat kabel daya rusak, hal itu bisa saja menjadi penyebab kebakaran.","sentence_template":"電源コードが傷んだまま使い続けると、火災の原因になり[blank]。"}'::jsonb, '{"selected":"かねない"}'::jsonb, NULL, NULL, '原因になりかねない adalah frasa standar dalam buku panduan keselamatan produk.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3e40549f-aaf3-41fc-ab58-93193780fb62', 'aaf3b2f6-95a9-406a-9b7c-f71c3a2a1bb6', 'd1000019-0000-0000-0000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat: "Setelah mendengarkan laporan lapangan, kami menyusun langkah berikutnya."', '{"romaji":"Genba no houkoku o kiita ue de, tsugi no taisaku o tateta.","tokens":["報告を","立てた。","聞く","現場の","にあたって、","上で、","聞いた","次の対策を"],"target_translation":"Setelah mendengarkan laporan lapangan, kami menyusun langkah berikutnya."}'::jsonb, '["現場の","報告を","聞いた","上で、","次の対策を","立てた。"]'::jsonb, NULL, NULL, '現場 (genba) berarti lokasi kerja/lapangan; 聞いた上で berarti setelah mendengar.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('84704bee-3249-4459-b9ea-a24ce7520477', 'aaf3b2f6-95a9-406a-9b7c-f71c3a2a1bb6', 'd1000019-0000-0000-0000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat: "Dalam menjaga keamanan data, pengelolaan kata sandi sangat penting."', '{"romaji":"Deeta kanri no ue de, pasuwaado no hogo ga kiwamete juuyou da.","tokens":["の","パスワードの","保護が","に伴って、","極めて重要だ。","データ管理","な","上で、"],"target_translation":"Dalam menjaga keamanan data, pengelolaan kata sandi sangat penting."}'::jsonb, '["データ管理","の","上で、","パスワードの","保護が","極めて重要だ。"]'::jsonb, NULL, NULL, 'データ管理の上で memakai partikel の setelah kata benda.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0bc7fee8-d5bf-486f-9c95-b4a0ac4a8eb3', 'aaf3b2f6-95a9-406a-9b7c-f71c3a2a1bb6', 'd1000019-0000-0000-0000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat: "Setelah mendapatkan persetujuan atasan, saya akan mengirim email ke klien."', '{"romaji":"Joushi no shounin o eta ue de, kokyaku e renraku shimasu.","tokens":["連絡します。","上で、","得る","上司の","顧客へ","得た","に限らず、","承認を"],"target_translation":"Setelah mendapatkan persetujuan atasan, saya akan mengirim email ke klien."}'::jsonb, '["上司の","承認を","得た","上で、","顧客へ","連絡します。"]'::jsonb, NULL, NULL, '承認を得る (mendapatkan persetujuan) → 承認を得た上で.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('150bea0c-34df-4615-99bd-fd7592a700b0', 'aaf3b2f6-95a9-406a-9b7c-f71c3a2a1bb6', 'd1000019-0000-0000-0000-000000000024', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dalam belajar bahasa asing, keberanian untuk tidak takut salah itu penting."', '{"romaji":"Gaikokugo o manabu ue de, machigai o osorenai shisei ga taisetsu desu.","display_text":"外国語を学ぶ上で、間違いを恐れない姿勢が大切です。","phonetic_breakdown":["がいこくごを","まなぶ","うえで","まちがいを","おそれない","しせいがたいせつです"]}'::jsonb, '{"expected_transcript":"外国語を学ぶ上で、間違いを恐れない姿勢が大切です。"}'::jsonb, NULL, NULL, '間違いを恐れない (tidak takut membuat kesalahan) + 学ぶ上で.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('554fdd1f-822b-4926-8b5d-89f8d53f1752', 'aaf3b2f6-95a9-406a-9b7c-f71c3a2a1bb6', 'd1000019-0000-0000-0000-000000000024', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah meninjau isi proposal, kami akan menghubungi Anda kembali besok."', '{"romaji":"Goteian no naiyou o seisa shita ue de, asu aratamete gorenraku itashimasu.","display_text":"ご提案の内容を精査した上で、明日改めてご連絡いたします。","phonetic_breakdown":["ごていあんの","ないようを","せいさしたうえで","あすあらためて","ごれんらくいたします"]}'::jsonb, '{"expected_transcript":"ご提案の内容を精査した上で、明日改めてご連絡いたします。"}'::jsonb, NULL, NULL, '精査する (seisa suru) berarti memeriksa secara saksama; 改めて berarti kembali/di lain waktu.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cdfe4704-f8ee-4c7d-bb7d-415a5c992576', 'aaf3b2f6-95a9-406a-9b7c-f71c3a2a1bb6', 'd1000019-0000-0000-0000-000000000024', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dalam menjalankan kehidupan di Jepang, memahami aturan pemilahan sampah itu perlu."', '{"romaji":"Nihon de seikatsu suru ue de, gomi bunbetsu no ruuru o shiru hitsuyou ga arimasu.","display_text":"日本で生活する上で、ゴミ分別のルールを知る必要があります。","phonetic_breakdown":["にほんで","せいかつする","うえで","ごみぶんべつの","るーるをしる","ひつようがあります"]}'::jsonb, '{"expected_transcript":"日本で生活する上で、ゴミ分別のルールを知る必要があります。"}'::jsonb, NULL, NULL, 'ゴミ分別 (pemilahan sampah) adalah bagian penting dari kehidupan sehari-hari di Jepang.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3e8b0a99-44b1-4782-a872-6ad8db149704', 'aaf3b2f6-95a9-406a-9b7c-f71c3a2a1bb6', 'd1000019-0000-0000-0000-000000000024', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 現場の意見を聞いた___、最終案を修正しました。', '{"options":["上で","つつ","かねず","ざるを得ず"],"translation":"Setelah mendengarkan pendapat dari lapangan, kami merevisi draf akhirnya.","sentence_template":"現場の意見を聞いた[blank]、最終案を修正しました。"}'::jsonb, '{"selected":"上で"}'::jsonb, NULL, NULL, '聞いた上で menunjukkan urutan mendengarkan masukan terlebih dahulu sebelum revisi.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('abf9dd0a-53d0-4484-b659-17abceca4f7e', 'aaf3b2f6-95a9-406a-9b7c-f71c3a2a1bb6', 'd1000019-0000-0000-0000-000000000024', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah menimbang pro dan kontranya, kami memilih opsi yang paling aman."', '{"romaji":"Riten to ketten o hikaku shita ue de, mottomo anzen na houhou o erabimashita.","display_text":"利点と欠点を比較した上で、最も安全な方法を選びました。","phonetic_breakdown":["りてんとけってんを","ひかくしたうえで","もっともあんぜんな","ほうほうを","えらびました"]}'::jsonb, '{"expected_transcript":"利点と欠点を比較した上で、最も安全な方法を選びました。"}'::jsonb, NULL, NULL, '利点と欠点 (kelebihan dan kekurangan) + 比較した上で lazim dalam pengambilan keputusan.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('20837377-6911-4031-85f9-9bbaad686390', 'ac8d1ef0-3bdf-465d-a068-48eff29446cb', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 再生可能エネルギーへの___が世界規模で進みつつある。', '{"options":["移行","欠席","挨拶","妥協"],"translation":"Transisi menuju energi terbarukan sedang terus berlangsung dalam skala global.","sentence_template":"再生可能エネルギーへの[blank]が世界規模で進みつつある。"}'::jsonb, '{"selected":"移行"}'::jsonb, NULL, NULL, '移行 (ikou) berarti peralihan atau transisi dari sistem lama ke sistem baru.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('baec5df7-cc9d-4d30-a1d7-e19c91aad60a', 'ac8d1ef0-3bdf-465d-a068-48eff29446cb', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berita berikut: 経済状況は緩やかに___しつつあると報告された。', '{"options":["回復","中止","撤退","閉会"],"translation":"Dilaporkan bahwa kondisi ekonomi sedang berangsur-angsur pulih.","sentence_template":"経済状況は緩やかに[blank]しつつあると報告された。"}'::jsonb, '{"selected":"回復"}'::jsonb, NULL, NULL, '回復する (kaifuku suru) berarti pulih; 緩やかに berarti secara perlahan/bertahap.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2d762844-920e-486f-8868-985fd642d704', 'ac8d1ef0-3bdf-465d-a068-48eff29446cb', NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: 地域の伝統文化が担い手不足により___しつつある。', '{"options":["衰退","普及","拡大","発展"],"translation":"Budaya tradisional daerah sedang terus mengalami kemunduran akibat kurangnya penerus.","sentence_template":"地域の伝統文化が担い手不足により[blank]しつつある。"}'::jsonb, '{"selected":"衰退"}'::jsonb, NULL, NULL, '衰退 (suitai) berarti kemunduran atau penyusutan; 担い手 berarti penerus/pelaku.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8a8d09e6-be86-462d-8eb4-790d812f45e3', 'ac8d1ef0-3bdf-465d-a068-48eff29446cb', NULL, 'listening', 'listening_choice', 'Dengarkan berita sosial berikut. Perubahan apa yang sedang berlangsung?', '{"options":[{"id":"opt_1","text":"Pembayaran nontunai sedang mulai mengakar hingga ke toko perorangan di daerah"},{"id":"opt_2","text":"Toko di daerah mulai menolak semua kartu kredit"},{"id":"opt_3","text":"Uang tunai kembali menjadi satu-satunya alat pembayaran"},{"id":"opt_4","text":"Jumlah toko perorangan meningkat dua kali lipat tahun ini"}],"audio_text":"近年、キャッシュレス決済が地方の個人商店にも定着しつつあります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '定着しつつある berarti sedang berproses mengakar/menjadi kebiasaan tetap.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d991dc1a-abbb-49eb-86b5-480bcac10255', 'ac8d1ef0-3bdf-465d-a068-48eff29446cb', NULL, 'listening', 'listening_choice', 'Dengarkan laporan lingkungan berikut. Apa yang sedang terjadi di laut?', '{"options":[{"id":"opt_1","text":"Jumlah kapal penangkap ikan berkurang drastis"},{"id":"opt_2","text":"Habitat sebagian jenis ikan sedang bergeser ke arah utara"},{"id":"opt_3","text":"Suhu air laut turun di bawah rata-rata musiman"},{"id":"opt_4","text":"Polusi plastik di laut sudah sepenuhnya hilang"}],"audio_text":"海水温の上昇により、一部の魚種の生息域が北へ移動しつつある。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '移動しつつある berarti sedang terus berpindah/bergeser secara bertahap.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b97b6be1-8dc1-4fa1-ab6a-1e782ca2d3cb', 'ac8d1ef0-3bdf-465d-a068-48eff29446cb', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Nilai-nilai masyarakat mengenai cara bekerja sedang berubah perlahan."', '{"romaji":"Hatarakikata ni taisuru shakai no kachikan wa, sukoshizutsu kawari tsutsu arimasu.","display_text":"働き方に対する社会の価値観は、少しずつ変わりつつあります。","phonetic_breakdown":["はたらきかたに","たいする","しゃかいのかちかんは","すこしずつ","かわりつつあります"]}'::jsonb, '{"expected_transcript":"働き方に対する社会の価値観は、少しずつ変わりつつあります。"}'::jsonb, NULL, NULL, '価値観 (kachikan) berarti nilai-nilai atau cara pandang; 変わりつつある berarti sedang terus berubah.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1d44e67a-bf60-4cd2-9a97-12170d53166d', 'ac8d1ef0-3bdf-465d-a068-48eff29446cb', 'd1000019-0000-0000-0000-000000000025', 'reading', 'fill_blank', 'Pilih kosakata yang tepat: オンライン診療の仕組みが全国で___しつつある。', '{"options":["定着","撤回","欠陥","延期"],"translation":"Sistem konsultasi medis daring sedang mulai mengakar/mapan di seluruh negeri.","sentence_template":"オンライン診療の仕組みが全国で[blank]しつつある。"}'::jsonb, '{"selected":"定着"}'::jsonb, NULL, NULL, '定着する (teichaku suru = mengakar/menjadi kebiasaan mapan) sangat cocok dengan ～つつある.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f4c59e6e-98dd-41b2-a506-617823e11068', 'ac8d1ef0-3bdf-465d-a068-48eff29446cb', 'd1000019-0000-0000-0000-000000000025', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jumlah pengguna kendaraan ramah lingkungan sedang terus bertambah setiap tahun."', '{"romaji":"Kankyou hairyogata jidousha no riyousha ga nennen zouka shitsutsu arimasu.","display_text":"環境配慮型自動車の利用者が年々増加しつつあります。","phonetic_breakdown":["かんきょうはいりょがた","じどうしゃのりようしゃが","ねんねん","ぞうかしつつあります"]}'::jsonb, '{"expected_transcript":"環境配慮型自動車の利用者が年々増加しつつあります。"}'::jsonb, NULL, NULL, '増加しつつあります adalah padanan formal dari 増えてきている.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e24b27a0-0c6b-481b-9d54-7b900bcd8a71', 'ada38cb6-f717-4921-8ffc-b7d4ec30bdc7', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: このアプリは若者だけでなく、幅広い___から支持されている。', '{"options":["世代","気候","納期","予算"],"translation":"Aplikasi ini didukung bukan hanya oleh anak muda, melainkan oleh berbagai generasi secara luas.","sentence_template":"このアプリは若者だけでなく、幅広い[blank]から支持されている。"}'::jsonb, '{"selected":"世代"}'::jsonb, NULL, NULL, '世代 (sedai) berarti generasi atau kelompok usia.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fd6f222b-438c-4e55-b5ae-387a80d10128', 'ada38cb6-f717-4921-8ffc-b7d4ec30bdc7', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat pemasaran berikut: 当社の製品は国内だけでなく、海外の___からも高い評価を得ている。', '{"options":["顧客","欠席","延期","渋滞"],"translation":"Produk perusahaan kami memperoleh penilaian tinggi bukan hanya di dalam negeri, melainkan juga dari pelanggan luar negeri.","sentence_template":"当社の製品は国内だけでなく、海外の[blank]からも高い評価を得ている。"}'::jsonb, '{"selected":"顧客"}'::jsonb, NULL, NULL, '顧客 (kokyaku) adalah istilah formal untuk pelanggan atau klien bisnis.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cd23486e-e23b-4695-aa34-47f62d460050', 'ada38cb6-f717-4921-8ffc-b7d4ec30bdc7', NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: 現代の企業には、人材の___を尊重する姿勢が求められる。', '{"options":["多様性","少子化","物価高","転勤"],"translation":"Perusahaan modern dituntut memiliki sikap yang menghargai keragaman sumber daya manusia.","sentence_template":"現代の企業には、人材の[blank]を尊重する姿勢が求められる。"}'::jsonb, '{"selected":"多様性"}'::jsonb, NULL, NULL, '多様性 (tayousei) berarti keberagaman atau diversitas.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7f62e6e6-f88f-4996-a958-64b3fda2ae9c', 'ada38cb6-f717-4921-8ffc-b7d4ec30bdc7', NULL, 'listening', 'listening_choice', 'Dengarkan deskripsi produk berikut. Siapa saja yang menggunakan layanan ini?', '{"options":[{"id":"opt_1","text":"Hanya mahasiswa tingkat pertama"},{"id":"opt_2","text":"Mahasiswa maupun pekerja profesional yang belajar kembali"},{"id":"opt_3","text":"Khusus dosen dan peneliti universitas"},{"id":"opt_4","text":"Hanya siswa sekolah menengah atas"}],"audio_text":"このオンライン講座は学生に限らず、社会人の学び直しにも広く活用されています。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '学生に限らず (tidak terbatas pada mahasiswa) + 社会人 (pekerja/masyarakat umum) menunjukkan cakupan luas.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e6df18cf-ef6f-40d7-af22-016d669b29ea', 'ada38cb6-f717-4921-8ffc-b7d4ec30bdc7', NULL, 'listening', 'listening_choice', 'Dengarkan wawancara berikut. Di mana merek tersebut populer?', '{"options":[{"id":"opt_1","text":"Hanya di kawasan Asia Timur"},{"id":"opt_2","text":"Khusus di kota-kota besar Jepang"},{"id":"opt_3","text":"Di Asia, Eropa, hingga Amerika Utara"},{"id":"opt_4","text":"Hanya di negara-negara berbahasa Inggris"}],"audio_text":"日本のアニメ文化はアジアに限らず、ヨーロッパや北米でも熱心なファンが多い。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'アジアに限らず berarti tidak terbatas di Asia, melainkan meluas ke Eropa dan Amerika Utara.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4399a9a7-40fd-473c-a666-285f67434cc3', 'ada38cb6-f717-4921-8ffc-b7d4ec30bdc7', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Layanan ini tersedia bukan hanya di dalam negeri, tetapi juga di seluruh dunia."', '{"romaji":"Kono saabisu wa kokunai ni kagirazu, sekaijuu de riyou dekimasu.","display_text":"このサービスは国内に限らず、世界中で利用できます。","phonetic_breakdown":["このさーびすは","こくないに","かぎらず","せかいじゅうで","りようできます"]}'::jsonb, '{"expected_transcript":"このサービスは国内に限らず、世界中で利用できます。"}'::jsonb, NULL, NULL, '国内に限らず (tidak terbatas di dalam negeri) sering dipasangkan dengan 世界中で (di seluruh dunia).', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('28a6cd97-9dab-4b57-8596-921fc6ebc34c', 'ada38cb6-f717-4921-8ffc-b7d4ec30bdc7', 'd1000019-0000-0000-0000-000000000020', 'reading', 'fill_blank', 'Pilih kosakata yang tepat: この映画は国内に限らず、海外でも高い___を得ている。', '{"options":["評価","欠陥","延期","制限"],"translation":"Film ini tidak hanya di dalam negeri, tetapi di luar negeri pun mendapat penilaian tinggi.","sentence_template":"この映画は国内に限らず、海外でも高い[blank]を得ている。"}'::jsonb, '{"selected":"評価"}'::jsonb, NULL, NULL, '高い評価を得る (mendapatkan penilaian/apresiasi tinggi) adalah kolokasi umum N2.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7f550160-042d-4bc3-afed-79c0dea47311', 'ada38cb6-f717-4921-8ffc-b7d4ec30bdc7', 'd1000019-0000-0000-0000-000000000020', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Toko ini menyediakan bahan makanan organik dari berbagai wilayah di seluruh negeri."', '{"romaji":"Touten dewa jimotosan ni kagirazu, zenkoku kakuchi no yuuki shokuzai o torisoroete orimasu.","display_text":"当店では地元産に限らず、全国各地の有機食材を取り揃えております。","phonetic_breakdown":["とうてんでは","じもとさんに","かぎらず","ぜんこくかくちの","ゆうきしょくざいを","とりそろえております"]}'::jsonb, '{"expected_transcript":"当店では地元産に限らず、全国各地の有機食材を取り揃えております。"}'::jsonb, NULL, NULL, '取り揃えております adalah bentuk rendah hati/sopan yang umum di dunia ritel Jepang.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('537d3554-7177-4f1b-b57c-8d199c60a6a2', 'ae63765e-6cad-4892-9fb1-0c67c1adefb9', 'd1000019-0000-0000-0000-000000000025', 'listening', 'listening_choice', 'Dengarkan laporan lingkungan. Kondisi apa yang dilaporkan tentang gletser di kutub?', '{"options":[{"id":"opt_1","text":"Es di wilayah Arktik bertambah tebal setiap tahun"},{"id":"opt_2","text":"Dilaporkan bahwa es di wilayah Arktik sedang mencair dengan kecepatan yang belum pernah terjadi sebelumnya"},{"id":"opt_3","text":"Suhu di wilayah Arktik turun drastis tahun ini"},{"id":"opt_4","text":"Penelitian di wilayah Arktik dihentikan selama lima tahun"}],"audio_text":"地球温暖化の影響で、北極圏の氷がかつてない速さで溶けつつあると報告された。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '溶けつつある berarti sedang dalam proses mencair secara terus-menerus.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('67666f46-f584-441f-a55f-5c2ad2e98273', 'ae63765e-6cad-4892-9fb1-0c67c1adefb9', 'd1000019-0000-0000-0000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat: "Pola konsumsi generasi muda sedang bergeser dari kepemilikan ke layanan berlangganan."', '{"romaji":"Wakamono no shouhi wa shoyuu kara riyou e to henka shitsutsu aru.","tokens":["所有から","変化","ある。","わけにはいかない。","若者の消費は","利用へと","しつつ","変化する"],"target_translation":"Pola konsumsi generasi muda sedang bergeser dari kepemilikan ke layanan berlangganan."}'::jsonb, '["若者の消費は","所有から","利用へと","変化","しつつ","ある。"]'::jsonb, NULL, NULL, '変化しつつある menggambarkan pergeseran tren konsumen yang sedang berjalan.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dd1b89d3-267a-43d9-a828-5adb54e77dac', 'ae63765e-6cad-4892-9fb1-0c67c1adefb9', 'd1000019-0000-0000-0000-000000000025', 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 長年の対立を経て、両国の関係はようやく改善に向かい___。', '{"options":["つつある","ざるを得ない","に限らず","にもかかわらず"],"translation":"Setelah perselisihan bertahun-tahun, hubungan kedua negara akhirnya sedang bergerak menuju perbaikan.","sentence_template":"長年の対立を経て、両国の関係はようやく改善に向かい[blank]。"}'::jsonb, '{"selected":"つつある"}'::jsonb, NULL, NULL, '向かう -> 向かいつつある menyatakan arah perubahan yang sedang terjadi.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8d2ae65b-d34a-4ab3-9659-cc13bc01bfde', 'ae63765e-6cad-4892-9fb1-0c67c1adefb9', 'd1000019-0000-0000-0000-000000000025', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Teknologi penerjemahan otomatis sedang berkembang pesat hingga mendekati tingkat alami."', '{"romaji":"Jidou honyaku no seido wa, kyuusoku ni koujou shitsutsu arimasu.","display_text":"自動翻訳の精度は、急速に向上しつつあります。","phonetic_breakdown":["じどうほんやくの","せいどは","きゅうそくに","こうじょうしつつ","あります"]}'::jsonb, '{"expected_transcript":"自動翻訳の精度は、急速に向上しつつあります。"}'::jsonb, NULL, NULL, '向上しつつあります (sedang terus meningkat) sering dipakai untuk perkembangan teknologi.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d9ae0604-6006-4599-955f-edf3038b6af5', 'ae63765e-6cad-4892-9fb1-0c67c1adefb9', 'd1000019-0000-0000-0000-000000000025', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 紙の書類を廃止し、業務の完全デジタル化が定着___。', '{"options":["しつつある","するつつある","したつつある","せつつある"],"translation":"Dokumen kertas dihapus dan digitalisasi penuh operasional kerja sedang mulai mengakar.","sentence_template":"紙の書類を廃止し、業務の完全デジタル化が定着[blank]。"}'::jsonb, '{"selected":"しつつある"}'::jsonb, NULL, NULL, '定着する -> bentuk masu stem 定着し + つつある.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a453c7e3-90e4-471a-bb77-c039df4cfe09', 'ae63765e-6cad-4892-9fb1-0c67c1adefb9', 'd1000019-0000-0000-0000-000000000025', 'listening', 'listening_choice', 'Dengarkan berita sosial berikut. Tren apa yang sedang terjadi pada gaya hidup perkotaan?', '{"options":[{"id":"opt_1","text":"Semakin sedikit orang yang tertarik tinggal di daerah"},{"id":"opt_2","text":"Harga rumah di desa menjadi lebih mahal dari pusat kota"},{"id":"opt_3","text":"Pemerintah melarang warga pindah ke luar kota besar"},{"id":"opt_4","text":"Makin banyak keluarga muda yang sedang beralih pindah ke daerah yang kaya alam meninggalkan hiruk-pikuk kota"}],"audio_text":"都会の喧騒を離れ、自然豊かな地方へ移住する若い世帯が増えつつある。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '増えつつある menyatakan tren peningkatan yang sedang berlangsung saat ini.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0d014cbd-c220-4e13-ba8f-ab2a06d9167f', 'ae63765e-6cad-4892-9fb1-0c67c1adefb9', 'd1000019-0000-0000-0000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat: "Kepercayaan konsumen terhadap merek tersebut perlahan sedang pulih kembali."', '{"romaji":"Sono burando e no shouhisha no shinrai wa joujou ni modoritsutsu aru.","tokens":["消費者の信頼は","戻り","ある。","かねない。","そのブランドへの","徐々に","つつ","戻った"],"target_translation":"Kepercayaan konsumen terhadap merek tersebut perlahan sedang pulih kembali."}'::jsonb, '["そのブランドへの","消費者の信頼は","徐々に","戻り","つつ","ある。"]'::jsonb, NULL, NULL, '徐々に戻りつつある berarti sedang berangsur-angsur kembali pulih.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('df74f37b-e5b4-47c9-a4dc-7b17473f849e', 'ae63765e-6cad-4892-9fb1-0c67c1adefb9', 'd1000019-0000-0000-0000-000000000025', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kesalahpahaman di antara kedua tim akhirnya sedang mulai terurai."', '{"romaji":"Ryou chiimu no aida no gokai wa, youyaku kaishou saretsutsu arimasu.","display_text":"両チームの間の誤解は、ようやく解消されつつあります。","phonetic_breakdown":["りょうちーむの","あいだのごかいは","ようやく","かいしょうされつつ","あります"]}'::jsonb, '{"expected_transcript":"両チームの間の誤解は、ようやく解消されつつあります。"}'::jsonb, NULL, NULL, '解消されつつあります (bentuk pasif + つつある) berarti sedang berangsur-angsur terselesaikan.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('56883d7f-15df-411b-83f7-8b2d2b7f073d', 'afeae3a2-ad40-4367-a911-875679f371b2', 'd1000019-0000-0000-0000-000000000026', 'reading', 'fill_blank', 'Lengkapi kalimat peringatan keselamatan berikut: わずかな確認ミスが、重大な事故を引き起こし___。', '{"options":["かねない","つつある","にあたらない","に限らない"],"translation":"Kesalahan pengecekan sekecil apa pun bisa saja memicu kecelakaan fatal.","sentence_template":"わずかな確認ミスが、重大な事故を引き起こし[blank]。"}'::jsonb, '{"selected":"かねない"}'::jsonb, NULL, NULL, 'V-masu stem (引き起こし) + かねない menyatakan kekhawatiran akan dampak negatif yang mungkin terjadi.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7094f645-17cc-44b4-b3b1-8891979af2f1', 'afeae3a2-ad40-4367-a911-875679f371b2', 'd1000019-0000-0000-0000-000000000026', 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk peringatan bisnis: 対応を先延ばしにすれば、長年の顧客の信頼を失い___。', '{"options":["かねない","ざるを得ない","わけにはいかない","に伴う"],"translation":"Jika kita menunda-nunda penanganan, kita bisa saja kehilangan kepercayaan pelanggan bertahun-tahun.","sentence_template":"対応を先延ばしにすれば、長年の顧客の信頼を失い[blank]。"}'::jsonb, '{"selected":"かねない"}'::jsonb, NULL, NULL, '失う -> 失いかねない mengekspresikan risiko serius bila tidak segera bertindak.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2ebb026f-0e0a-4a54-91c7-11e0a45fdd1c', 'afeae3a2-ad40-4367-a911-875679f371b2', 'd1000019-0000-0000-0000-000000000026', 'listening', 'listening_choice', 'Dengarkan arahan manajer keamanan IT. Risiko apa yang ia peringatkan?', '{"options":[{"id":"opt_1","text":"Akun akan otomatis mendapatkan penyimpanan gratis tambahan"},{"id":"opt_2","text":"Menggunakan kata sandi yang sama di beberapa layanan bisa berisiko terkena akses tidak sah"},{"id":"opt_3","text":"Kecepatan internet di kantor akan meningkat dua kali lipat"},{"id":"opt_4","text":"Kata sandi akan otomatis diperbarui setiap hari"}],"audio_text":"パスワードを複数のサービスで使い回していると、不正アクセスの被害に遭いかねませんよ。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '被害に遭いかねません berarti bisa saja mengalami kerugian/menjadi korban peretasan.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3e2d2492-68d6-4b91-bc7e-617f6391aaaa', 'afeae3a2-ad40-4367-a911-875679f371b2', 'd1000019-0000-0000-0000-000000000026', 'writing', 'sentence_builder', 'Susun kalimat: "Jika terus bekerja tanpa istirahat, Anda bisa saja jatuh sakit."', '{"romaji":"Yasumazu ni hataraki tsuzukeru to, karada o kowashikanenai.","tokens":["働き続けると、","壊し","ない。","つつある。","休まずに","体を","かね","壊した"],"target_translation":"Jika terus bekerja tanpa istirahat, Anda bisa saja jatuh sakit."}'::jsonb, '["休まずに","働き続けると、","体を","壊し","かね","ない。"]'::jsonb, NULL, NULL, '体を壊す -> 体を壊しかねない adalah peringatan kesehatan yang sangat alami.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('98d585df-de72-40bd-bbcd-bd0b0c30a9e4', 'afeae3a2-ad40-4367-a911-875679f371b2', 'd1000019-0000-0000-0000-000000000026', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pernyataan yang kurang hati-hati itu bisa saja menimbulkan kesalahpahaman besar."', '{"romaji":"Sono keisotsu na hatsugen wa, ookina gokai o manekikanemasen.","display_text":"その軽率な発言は、大きな誤解を招きかねません。","phonetic_breakdown":["そのけいそつな","はつげんは","おおきなごかいを","まねきかねません"]}'::jsonb, '{"expected_transcript":"その軽率な発言は、大きな誤解を招きかねません。"}'::jsonb, NULL, NULL, '誤解を招きかねません (bisa saja mengundang kesalahpahaman) adalah kolokasi klasik JLPT N2.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b01dda1f-009b-4e3f-b1b0-a6bb37fa94ac', 'afeae3a2-ad40-4367-a911-875679f371b2', 'd1000019-0000-0000-0000-000000000026', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 予算管理を甘く見ていると、年度末に深刻な資金不足に陥り___。', '{"options":["かねない","にあたって","の上で","にもかかわらず"],"translation":"Jika meremehkan pengelolaan anggaran, pada akhir tahun fiskal bisa saja terjerumus ke kekurangan dana serius.","sentence_template":"予算管理を甘く見ていると、年度末に深刻な資金不足に陥り[blank]。"}'::jsonb, '{"selected":"かねない"}'::jsonb, NULL, NULL, '陥る (terjerumus) -> 陥りかねない menggambarkan risiko finansial.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('743bfd3c-3b34-4ec6-94bf-236f1bc3bd28', 'afeae3a2-ad40-4367-a911-875679f371b2', 'd1000019-0000-0000-0000-000000000026', 'listening', 'listening_choice', 'Dengarkan peringatan dokter berikut. Apa bahaya jika gejala dibiarkan?', '{"options":[{"id":"opt_1","text":"Gejala ringan pasti sembuh sendiri dalam satu jam"},{"id":"opt_2","text":"Obat tidak diperlukan untuk penyakit kronis"},{"id":"opt_3","text":"Jika dibiarkan karena dianggap ringan, kondisi bisa menjadi kronis dan pengobatan berlarut-larut"},{"id":"opt_4","text":"Pasien tidak perlu memeriksakan diri lagi"}],"audio_text":"軽い症状だからといって放置しておくと、慢性化して治療が長引きかねないのです。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '治療が長引きかねない berarti pengobatan bisa saja menjadi berkepanjangan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f764c260-4e04-4fe6-abda-02853ea12e9b', 'afeae3a2-ad40-4367-a911-875679f371b2', 'd1000019-0000-0000-0000-000000000026', 'writing', 'sentence_builder', 'Susun kalimat: "Jika jadwal terlalu dipaksakan, kualitas produk bisa saja menurun drastis."', '{"romaji":"Muri na sukejuuru o kumu to, seihin no hinshitsu ga teika shikanenai.","tokens":["スケジュールを組むと、","低下","ない。","わけにはいかない。","無理な","製品の品質が","しかね","低下した"],"target_translation":"Jika jadwal terlalu dipaksakan, kualitas produk bisa saja menurun drastis."}'::jsonb, '["無理な","スケジュールを組むと、","製品の品質が","低下","しかね","ない。"]'::jsonb, NULL, NULL, '低下する -> 低下しかねない memperingatkan penurunan kualitas.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4faac7b2-1830-470b-8adb-86873574165c', 'b4ac33bc-621f-4b86-8d98-cc6fac03fb2e', 'd1000019-0000-0000-0000-000000000022', 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 建物の老朽化が進んでおり、大規模な改修工事を___。', '{"options":["行わざるを得ない","行いざるを得ない","行うざるを得ない","行ってざるを得ない"],"translation":"Penuaan bangunan terus berlanjut sehingga kami terpaksa melakukan renovasi berskala besar.","sentence_template":"建物の老朽化が進んでおり、大規模な改修工事を[blank]。"}'::jsonb, '{"selected":"行わざるを得ない"}'::jsonb, NULL, NULL, '行う (Godan berakhiran う) bentuk ない adalah 行わない → akar 行わ + ざるを得ない.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f3597528-c7da-47e8-970b-f8d2a23768c6', 'b4ac33bc-621f-4b86-8d98-cc6fac03fb2e', 'd1000019-0000-0000-0000-000000000022', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 相手企業の倒産により、共同開発は中止___。', '{"options":["せざるを得なくなった","しざるを得なくなった","にあたった","に限らなかった"],"translation":"Akibat kebangkrutan perusahaan mitra, pengembangan bersama terpaksa dibatalkan.","sentence_template":"相手企業の倒産により、共同開発は中止[blank]。"}'::jsonb, '{"selected":"せざるを得なくなった"}'::jsonb, NULL, NULL, '中止する + ざるを得なくなる → 中止せざるを得なくなった.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('38e64add-16c8-4bd3-9d2e-efea7ff7b861', 'b4ac33bc-621f-4b86-8d98-cc6fac03fb2e', 'd1000019-0000-0000-0000-000000000022', 'listening', 'listening_choice', 'Dengarkan komentar manajer berikut. Mengapa perekrutan tahun ini dikurangi?', '{"options":[{"id":"opt_1","text":"Karena perubahan lingkungan pasar sangat drastis"},{"id":"opt_2","text":"Karena tidak ada pelamar yang memenuhi syarat"},{"id":"opt_3","text":"Karena seluruh pekerjaan sudah dialihkan ke cabang luar negeri"},{"id":"opt_4","text":"Karena kantor pusat pindah ke gedung yang lebih kecil"}],"audio_text":"市場環境の変化が激しいため、今年の採用人数は当初の予定より減らさざるを得ません。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '市場環境の変化が激しい (perubahan pasar sangat drastis) memaksa pengurangan jumlah rekrutmen.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5f5f5b02-36c4-4669-b3bf-1fe0a44b03fb', 'b4ac33bc-621f-4b86-8d98-cc6fac03fb2e', 'd1000019-0000-0000-0000-000000000022', 'listening', 'listening_choice', 'Dengarkan berita berikut. Apa yang terpaksa dilakukan penduduk setempat?', '{"options":[{"id":"opt_1","text":"Memperbaiki jembatan secara gotong royong"},{"id":"opt_2","text":"Menutup seluruh toko selama satu bulan"},{"id":"opt_3","text":"Menghentikan penggunaan listrik di rumah"},{"id":"opt_4","text":"Berpindah ke tempat pengungsian karena permukaan sungai mencapai batas bahaya"}],"audio_text":"河川の水位が危険水準に達したため、住民は避難所へ移動せざるを得なくなった。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '避難所へ移動せざるを得なくなった berarti terpaksa berpindah ke tempat pengungsian.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('34b652f4-88c7-477d-ab5e-e485060502b0', 'b4ac33bc-621f-4b86-8d98-cc6fac03fb2e', 'd1000019-0000-0000-0000-000000000022', 'writing', 'sentence_builder', 'Susun kalimat: "Karena tidak ada pilihan lain, kami terpaksa menerima syarat tersebut."', '{"romaji":"Hoka ni sentakushi ga nai tame, sono jouken o ukeirezaru o enai.","tokens":["受け入れ","その条件を","にあたって","ざるを","選択肢がないため、","受け入れる","他に","得ない。"],"target_translation":"Karena tidak ada pilihan lain, kami terpaksa menerima syarat tersebut."}'::jsonb, '["他に","選択肢がないため、","その条件を","受け入れ","ざるを","得ない。"]'::jsonb, NULL, NULL, '受け入れる (Ichidan) → 受け入れざるを得ない.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c1073278-603d-4365-8d9f-938d5f83f781', 'b4ac33bc-621f-4b86-8d98-cc6fac03fb2e', 'd1000019-0000-0000-0000-000000000022', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya terpaksa mengakui bahwa perkiraan awal kami terlalu optimistis."', '{"romaji":"Tousho no mitooshi ga amakatta koto o mitomezaru o emasen.","display_text":"当初の見通しが甘かったことを認めざるを得ません。","phonetic_breakdown":["とうしょの","みとおしが","あまかったことを","みとめざるを","えません"]}'::jsonb, '{"expected_transcript":"当初の見通しが甘かったことを認めざるを得ません。"}'::jsonb, NULL, NULL, '見通しが甘い berarti perkiraan/proyeksi terlalu optimistis atau kurang ketat.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a4c1ef59-1173-4885-8f70-29a2023f5969', 'b4ac33bc-621f-4b86-8d98-cc6fac03fb2e', 'd1000019-0000-0000-0000-000000000022', 'listening', 'listening_choice', 'Dengarkan ulasan pengamat ekonomi. Apa penilaian beliau terhadap kebijakan tersebut?', '{"options":[{"id":"opt_1","text":"Bank sentral tidak perlu melakukan apa pun"},{"id":"opt_2","text":"Bank sentral akan menurunkan suku bunga hingga nol"},{"id":"opt_3","text":"Inflasi akan hilang sendiri tanpa kebijakan moneter"},{"id":"opt_4","text":"Bank sentral kemungkinan besar terpaksa menaikkan suku bunga untuk menekan inflasi"}],"audio_text":"インフレを抑え込むためには、中央銀行も金利を引き上げざるを得ないだろう。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '金利を引き上げざるを得ないだろう berarti mau tidak mau akan terpaksa menaikkan suku bunga.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e7b6b26c-cb58-413d-a3fc-e7982d165d7d', 'b4ac33bc-621f-4b86-8d98-cc6fac03fb2e', 'd1000019-0000-0000-0000-000000000022', 'writing', 'sentence_builder', 'Susun kalimat: "Akibat gempa besar, ribuan warga terpaksa mengungsi ke tempat penampungan."', '{"romaji":"Oojishin no eikyou de, ooku no juumin ga hinanjo e hinan sezaru o enakatta.","tokens":["多くの住民が","避難","得なかった。","にもかかわらず、","大地震の影響で、","避難所へ","せざるを","避難する"],"target_translation":"Akibat gempa besar, ribuan warga terpaksa mengungsi ke tempat penampungan."}'::jsonb, '["大地震の影響で、","多くの住民が","避難所へ","避難","せざるを","得なかった。"]'::jsonb, NULL, NULL, '避難せざるを得なかった menggambarkan tindakan pengungsian yang terpaksa akibat bencana.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cb1bdb6d-9b02-432e-ab02-67d492fb820a', 'bc581228-dbdd-449e-8f02-183be445e7ae', 'd1000019-0000-0000-0000-000000000025', 'reading', 'fill_blank', 'Lengkapi artikel berita berikut: 再生可能エネルギーの導入が、世界規模で急速に広がり___。', '{"options":["つつある","かねない","わけにはいかない","ざるを得ない"],"translation":"Penerapan energi terbarukan sedang terus meluas dengan cepat dalam skala global.","sentence_template":"再生可能エネルギーの導入が、世界規模で急速に広がり[blank]。"}'::jsonb, '{"selected":"つつある"}'::jsonb, NULL, NULL, 'V-masu stem (広がり) + つつある menggambarkan proses perubahan yang sedang berlangsung secara bertahap.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0ece0a6e-44f9-4899-970f-72239f2860f6', 'bc581228-dbdd-449e-8f02-183be445e7ae', 'd1000019-0000-0000-0000-000000000025', 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk laporan pemulihan: 長引いていた景気低迷から、ようやく回復の兆しが見え___。', '{"options":["つつある","にあたっている","に限っている","の上である"],"translation":"Dari kelesuan ekonomi yang berkepanjangan, tanda-tanda pemulihan akhirnya mulai terus terlihat.","sentence_template":"長引いていた景気低迷から、ようやく回復の兆しが見え[blank]。"}'::jsonb, '{"selected":"つつある"}'::jsonb, NULL, NULL, '見えつつある menggambarkan perubahan positif yang mulai tampak secara progresif.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b93498e1-c8d6-4ab2-a14f-9fb52c4d5a62', 'bc581228-dbdd-449e-8f02-183be445e7ae', 'd1000019-0000-0000-0000-000000000025', 'listening', 'listening_choice', 'Dengarkan berita ekonomi berikut. Perubahan apa yang sedang berlangsung di pasar kerja?', '{"options":[{"id":"opt_1","text":"Sistem kerja seumur hidup sedang ditinjau ulang dan beralih menuju sistem evaluasi berbasis kompetensi"},{"id":"opt_2","text":"Semua perusahaan mewajibkan karyawan bekerja di satu perusahaan seumur hidup"},{"id":"opt_3","text":"Sistem evaluasi kinerja dihapuskan di seluruh perusahaan"},{"id":"opt_4","text":"Gaji karyawan hanya ditentukan oleh lama masa kerja"}],"audio_text":"従来の終身雇用制度が見直され、実力本位の評価システムへと移行しつつある。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '移行しつつある berarti sedang bertransisi secara bertahap menuju sistem baru.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ed3cb712-9c7b-4a63-b678-701974645ec7', 'bc581228-dbdd-449e-8f02-183be445e7ae', 'd1000019-0000-0000-0000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat: "Kesadaran masyarakat terhadap pengurangan sampah plastik sedang meningkat."', '{"romaji":"Purasuchikku gomi sakugen e no ishiki ga takamaritsutsu aru.","tokens":["削減への","高まり","ある。","かねない。","プラスチックごみ","意識が","つつ","高まった"],"target_translation":"Kesadaran masyarakat terhadap pengurangan sampah plastik sedang meningkat."}'::jsonb, '["プラスチックごみ","削減への","意識が","高まり","つつ","ある。"]'::jsonb, NULL, NULL, '高まる -> 高まりつつある menyatakan peningkatan kesadaran yang terus berlangsung.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b486b11c-695b-444c-964c-f6582350fdd9', 'bc581228-dbdd-449e-8f02-183be445e7ae', 'd1000019-0000-0000-0000-000000000025', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kondisi pasien sedang berangsur-angsur membaik menuju pemulihan."', '{"romaji":"Kanjasan no youdai wa, junchou ni kaifuku ni mukaitsutsu arimasu.","display_text":"患者さんの容体は、順調に回復に向かいつつあります。","phonetic_breakdown":["かんじゃさんの","ようだいは","じゅんちょうに","かいふくに","むかいつつあります"]}'::jsonb, '{"expected_transcript":"患者さんの容体は、順調に回復に向かいつつあります。"}'::jsonb, NULL, NULL, '回復に向かいつつあります adalah ungkapan sopan dan akurat untuk progres pemulihan.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9b912127-4299-41b5-b23f-e65a0ea119ff', 'bc581228-dbdd-449e-8f02-183be445e7ae', 'd1000019-0000-0000-0000-000000000025', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 地域の伝統工芸を受け継ぐ職人の数が、年々減り___のが現状だ。', '{"options":["つつある","かねない","にあたって","の上で"],"translation":"Kenyataannya saat ini jumlah pengrajin yang mewarisi kerajinan tradisional daerah terus berkurang dari tahun ke tahun.","sentence_template":"地域の伝統工芸を受け継ぐ職人の数が、年々減り[blank]のが現状だ。"}'::jsonb, '{"selected":"つつある"}'::jsonb, NULL, NULL, '減りつつある menggambarkan tren penurunan yang sedang berlangsung.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b264a5e5-f9bb-402d-9b6a-9de940b85a0b', 'bc581228-dbdd-449e-8f02-183be445e7ae', 'd1000019-0000-0000-0000-000000000025', 'listening', 'listening_choice', 'Dengarkan ulasan pengamat teknologi. Apa yang terjadi pada layanan transportasi kota?', '{"options":[{"id":"opt_1","text":"Seluruh layanan bus daerah dihentikan permanen"},{"id":"opt_2","text":"Uji coba bus otonom ditolak oleh pemerintah"},{"id":"opt_3","text":"Bentuk transportasi di daerah sedang berubah besar seiring majunya uji coba bus otonom"},{"id":"opt_4","text":"Penumpang bus hanya boleh membayar dengan koin"}],"audio_text":"自動運転バスの実証実験が進み、地方の移動手段のあり方が大きく変わりつつある。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '大きく変わりつつある berarti sedang mengalami perubahan besar secara berkelanjutan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0ebc60a3-d6dd-43c1-82a8-57f9ff28cae1', 'bc581228-dbdd-449e-8f02-183be445e7ae', 'd1000019-0000-0000-0000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat: "Masalah kekurangan air di wilayah tersebut sedang menjadi semakin serius."', '{"romaji":"Sono chiiki no mizubusoku wa sara ni shinkokuka shitsutsu aru.","tokens":["水不足は","深刻化","ある。","ざるを得ない。","その地域の","さらに","しつつ","深刻化した"],"target_translation":"Masalah kekurangan air di wilayah tersebut sedang menjadi semakin serius."}'::jsonb, '["その地域の","水不足は","さらに","深刻化","しつつ","ある。"]'::jsonb, NULL, NULL, '深刻化する -> 深刻化しつつある menyatakan proses yang makin memburuk dari waktu ke waktu.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bc868d8d-8c53-484b-9326-8a95ed92dcf5', 'bca68e3e-73e0-4847-87f7-455391daff59', 'd1000019-0000-0000-0000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat: "Bukan hanya di kota besar, di daerah pun acara ini diselenggarakan."', '{"romaji":"Daitoshi ni kagirazu, chihou demo kono ibento wa kaisai sarete iru.","tokens":["開催","地方でも","大都市に","されている。","に伴って、","大都市","に限らず、","このイベントは"],"target_translation":"Bukan hanya di kota besar, di daerah pun acara ini diselenggarakan."}'::jsonb, '["大都市","に限らず、","地方でも","このイベントは","開催","されている。"]'::jsonb, NULL, NULL, '大都市に限らず、地方でも kontras antara kota besar dan daerah untuk menunjukkan cakupan nasional.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('864ed400-bd7a-4cf4-a07e-1c1eaa5c2ff8', 'bca68e3e-73e0-4847-87f7-455391daff59', 'd1000019-0000-0000-0000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat: "Tidak terbatas pada bidang medis, AI digunakan di berbagai industri."', '{"romaji":"Iryou bunya ni kagirazu, eiai wa arayuru sangyou de katsuyou sarete iru.","tokens":["にあたって、","あらゆる","活用されている。","に限らず、","産業で","AIは","医療分野を","医療分野"],"target_translation":"Tidak terbatas pada bidang medis, AI digunakan di berbagai industri."}'::jsonb, '["医療分野","に限らず、","AIは","あらゆる","産業で","活用されている。"]'::jsonb, NULL, NULL, 'あらゆる (segala/berbagai) sangat cocok menguatkan makna inklusif dari ～に限らず.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ea40d490-46cd-41df-9082-28b5f1540b8e', 'bca68e3e-73e0-4847-87f7-455391daff59', 'd1000019-0000-0000-0000-000000000020', 'writing', 'sentence_builder', 'Susun kalimat: "Keterampilan komunikasi penting tidak terbatas pada pekerjaan penjualan."', '{"romaji":"Komyunikeeshon-ryoku wa eigyoushoku ni kagirazu, subete no shokushu de juuyou da.","tokens":["すべての","に限らず、","にもかかわらず、","営業職","コミュニケーション力は","営業職の","重要だ。","職種で"],"target_translation":"Keterampilan komunikasi penting tidak terbatas pada pekerjaan penjualan."}'::jsonb, '["コミュニケーション力は","営業職","に限らず、","すべての","職種で","重要だ。"]'::jsonb, NULL, NULL, '営業職 (posisi penjualan) dan 職種 (jenis pekerjaan/jabatan) adalah kosakata karier N2.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('825bbf23-895f-46ad-9f81-b15134e2c15c', 'bca68e3e-73e0-4847-87f7-455391daff59', 'd1000019-0000-0000-0000-000000000020', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tidak terbatas pada pria, wanita juga banyak berkarya di bidang teknik."', '{"romaji":"Dansei ni kagirazu, josei mo gijutsu bunya de hiroku katsuyaku shite imasu.","display_text":"男性に限らず、女性も技術分野で広く活躍しています。","phonetic_breakdown":["だんせいに","かぎらず","じょせいも","ぎじゅつぶんやで","ひろく","かつやくしています"]}'::jsonb, '{"expected_transcript":"男性に限らず、女性も技術分野で広く活躍しています。"}'::jsonb, NULL, NULL, '活躍する (katsuyaku suru) berarti berperan aktif atau berkarya secara gemilang.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('02a85d68-d2bb-4f00-8063-4c9450b7d1bc', 'bca68e3e-73e0-4847-87f7-455391daff59', 'd1000019-0000-0000-0000-000000000020', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tidak terbatas pada musim panas, menjaga asupan cairan itu penting sepanjang tahun."', '{"romaji":"Natsu ni kagirazu, ichinenjuu komamena suibun hokyuu ga taisetsu desu.","display_text":"夏に限らず、一年中こまめな水分補給が大切です。","phonetic_breakdown":["なつに","かぎらず","いちねんじゅう","こまめな","すいぶんほきゅうが","たいせつです"]}'::jsonb, '{"expected_transcript":"夏に限らず、一年中こまめな水分補給が大切です。"}'::jsonb, NULL, NULL, '水分補給 (asupan cairan) dan こまめな (rutin/sedikit demi sedikit) sering muncul di pengumuman kesehatan.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a31fa397-0e8c-47f3-a341-8da64e4cbda7', 'bca68e3e-73e0-4847-87f7-455391daff59', 'd1000019-0000-0000-0000-000000000020', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tidak terbatas pada buku teks, saya belajar bahasa Jepang lewat berita juga."', '{"romaji":"Kyoukasho ni kagirazu, nyuusu kiji kara mo Nihongo o manande imasu.","display_text":"教科書に限らず、ニュース記事からも日本語を学んでいます。","phonetic_breakdown":["きょうかしょに","かぎらず","にゅーすきじからも","にほんごを","まなんでいます"]}'::jsonb, '{"expected_transcript":"教科書に限らず、ニュース記事からも日本語を学んでいます。"}'::jsonb, NULL, NULL, 'Kalimat ini alami untuk wawancara kerja atau wawancara beasiswa di Jepang.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('23a393f0-b116-47a3-b058-187ee92358e7', 'bca68e3e-73e0-4847-87f7-455391daff59', 'd1000019-0000-0000-0000-000000000020', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 音楽は言葉の壁を越えて、国籍___人々の心を結びつける。', '{"options":["に限らず","にあたって","ざるを得ず","の上で"],"translation":"Musik melampaui batas bahasa dan menyatukan hati manusia tanpa terbatas kewarganegaraan.","sentence_template":"音楽は言葉の壁を越えて、国籍[blank]人々の心を結びつける。"}'::jsonb, '{"selected":"に限らず"}'::jsonb, NULL, NULL, '国籍に限らず menegaskan keberlakuan universal tanpa batas negara.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9ccafe55-ead7-4ae4-8f4e-9658bab23731', 'bca68e3e-73e0-4847-87f7-455391daff59', 'd1000019-0000-0000-0000-000000000020', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tidak hanya di musim semi, taman ini juga indah saat musim gugur."', '{"romaji":"Kono kouen wa haru ni kagirazu, kouyou no kisetsu mo migoto na keshiki ga tanoshimemasu.","display_text":"この公園は春に限らず、紅葉の季節も見事な景色が楽しめます。","phonetic_breakdown":["このこうえんは","はるに","かぎらず","こうようのきせつも","みごとなけしきが","たのしめます"]}'::jsonb, '{"expected_transcript":"この公園は春に限らず、紅葉の季節も見事な景色が楽しめます。"}'::jsonb, NULL, NULL, '紅葉 (kouyou) adalah dedaunan musim gugur; 見事な景色 berarti pemandangan menakjubkan.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ce046442-336e-4bad-82a4-063f04c9780e', 'bd35a68c-7f00-454a-a759-5c2165579507', 'd1000019-0000-0000-0000-000000000019', 'reading', 'fill_blank', 'Lengkapi laporan ekonomi berikut: 少子高齢化の進行___、労働力不足が深刻な課題となっている。', '{"options":["に伴って","にあたって","に限らず","わけにはいかず"],"translation":"Seiring dengan berlanjutnya penurunan angka kelahiran dan penuaan penduduk, kekurangan tenaga kerja menjadi masalah serius.","sentence_template":"少子高齢化の進行[blank]、労働力不足が深刻な課題となっている。"}'::jsonb, '{"selected":"に伴って"}'::jsonb, NULL, NULL, '進行に伴って menyatakan perubahan kedua (kekurangan tenaga kerja) yang muncul seiring perubahan pertama.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5f4d47a2-73d4-48fd-9aee-dd84752b0502', 'bd35a68c-7f00-454a-a759-5c2165579507', 'd1000019-0000-0000-0000-000000000019', 'reading', 'fill_blank', 'Pilih bentuk penyambung kata benda yang tepat: 都市開発___環境破壊を防ぐため、新たな条例が制定された。', '{"options":["に伴う","に伴って","にあたり","に限る"],"translation":"Untuk mencegah kerusakan lingkungan yang menyertai pembangunan kota, peraturan daerah baru ditetapkan.","sentence_template":"都市開発[blank]環境破壊を防ぐため、新たな条例が制定された。"}'::jsonb, '{"selected":"に伴う"}'::jsonb, NULL, NULL, 'Untuk menerangkan kata benda di belakangnya (環境破壊), digunakan bentuk ～に伴う.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8940857a-3e35-492c-9e12-999ad0289b48', 'bd35a68c-7f00-454a-a759-5c2165579507', 'd1000019-0000-0000-0000-000000000019', 'listening', 'listening_choice', 'Dengarkan berita ekonomi berikut. Apa dampak dari melemahnya nilai tukar yen yang disebutkan?', '{"options":[{"id":"opt_1","text":"Harga bahan baku impor naik dan produsen makanan berturut-turut menaikkan harga"},{"id":"opt_2","text":"Harga seluruh produk makanan turun drastis di supermarket"},{"id":"opt_3","text":"Ekspor kendaraan bermotor dihentikan sementara"},{"id":"opt_4","text":"Jumlah wisatawan asing menurun tajam sepanjang tahun"}],"audio_text":"円安の進行に伴い、輸入原材料の価格が上昇し、食品メーカーの値上げが相次いでいる。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '輸入原材料の価格が上昇 (kenaikan harga bahan baku impor) memicu 値上げが相次いでいる (kenaikan harga berturut-turut).', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a4645d6a-0cff-4735-945d-ee33515dc5e1', 'bd35a68c-7f00-454a-a759-5c2165579507', 'd1000019-0000-0000-0000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat: "Seiring dengan berkembangnya AI, cara kerja di kantor berubah drastis."', '{"romaji":"AI gijutsu no hatten ni tomonatte, ofisu no hatarakikata ga ookiku kawatta.","tokens":["発展","オフィスの","大きく変わった。","かねない。","AI技術の","に伴って、","働き方が","にあたって、"],"target_translation":"Seiring dengan berkembangnya AI, cara kerja di kantor berubah drastis."}'::jsonb, '["AI技術の","発展","に伴って、","オフィスの","働き方が","大きく変わった。"]'::jsonb, NULL, NULL, '発展に伴って menghubungkan kemajuan teknologi dengan perubahan cara kerja.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a53c08b3-1a95-46c9-a9ae-efb03c465747', 'bd35a68c-7f00-454a-a759-5c2165579507', 'd1000019-0000-0000-0000-000000000019', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring dengan meningkatnya wisatawan asing, panduan multibahasa makin diperluas."', '{"romaji":"Gaikokujin kankoukyaku no zouka ni tomonai, tagengo annai ga juujitsu shite kite imasu.","display_text":"外国人観光客の増加に伴い、多言語案内が充実してきています。","phonetic_breakdown":["がいこくじんかんこうきゃくの","ぞうかに","ともない","たげんごあんないが","じゅうじつしてきています"]}'::jsonb, '{"expected_transcript":"外国人観光客の増加に伴い、多言語案内が充実してきています。"}'::jsonb, NULL, NULL, '～に伴い adalah bentuk formal dari ～に伴って yang sering muncul di berita TV dan laporan.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d11dbbda-6225-4ed3-988e-ebad87ba217e', 'bd35a68c-7f00-454a-a759-5c2165579507', 'd1000019-0000-0000-0000-000000000019', 'reading', 'fill_blank', 'Lengkapi kalimat analisis tren: リモートワークが普及する___、郊外の住宅需要が高まっている。', '{"options":["に伴って","にもかかわらず","ざるを得ず","かねない"],"translation":"Seiring dengan meluasnya kerja jarak jauh, permintaan hunian di pinggiran kota semakin meningkat.","sentence_template":"リモートワークが普及する[blank]、郊外の住宅需要が高まっている。"}'::jsonb, '{"selected":"に伴って"}'::jsonb, NULL, NULL, 'Verba bentuk kamus (普及する) + に伴って menyatakan korelasi perubahan yang paralel.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('837ec1df-98f4-4655-9aa6-777fdafea7ae', 'bd35a68c-7f00-454a-a759-5c2165579507', 'd1000019-0000-0000-0000-000000000019', 'listening', 'listening_choice', 'Dengarkan penjelasan analis industri. Apa konsekuensi dari digitalisasi perbankan?', '{"options":[{"id":"opt_1","text":"Bank membuka lebih banyak cabang fisik di pedesaan"},{"id":"opt_2","text":"Penggunaan uang tunai meningkat dua kali lipat"},{"id":"opt_3","text":"Makin banyak lembaga keuangan mengurangi jumlah kantor cabang fisik"},{"id":"opt_4","text":"Transaksi daring dibatasi hanya pada hari kerja"}],"audio_text":"キャッシュレス決済の拡大に伴って、実店舗の数を削減する金融機関が増えている。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '実店舗の数を削減する berarti mengurangi jumlah cabang fisik seiring meluasnya pembayaran nontunai.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f037df94-b457-4cb9-8366-67f1243b411d', 'bd35a68c-7f00-454a-a759-5c2165579507', 'd1000019-0000-0000-0000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat: "Risiko keamanan yang menyertai sistem baru harus segera ditangani."', '{"romaji":"Shin shisutemu dounyuu ni tomonau risuku ni taisho shinakereba naranai.","tokens":["に伴う","対処","ならない。","にあたり","新システム導入","リスクに","しなければ","に伴って"],"target_translation":"Risiko keamanan yang menyertai sistem baru harus segera ditangani."}'::jsonb, '["新システム導入","に伴う","リスクに","対処","しなければ","ならない。"]'::jsonb, NULL, NULL, 'に伴う + kata benda (リスク) menyatakan risiko yang menyertai suatu tindakan.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('322bae91-f7c9-40fd-9e7a-98a116a224aa', 'be9a9970-be70-43b3-a202-f7c8e6e3642b', 'd1000019-0000-0000-0000-000000000018', 'reading', 'fill_blank', 'Lengkapi pengumuman resmi berikut: 新工場の稼働___、安全点検を二週間かけて実施した。', '{"options":["にあたって","にかかわらず","につれて","かねない"],"translation":"Menjelang beroperasinya pabrik baru, pemeriksaan keselamatan dilakukan selama dua minggu.","sentence_template":"新工場の稼働[blank]、安全点検を二週間かけて実施した。"}'::jsonb, '{"selected":"にあたって"}'::jsonb, NULL, NULL, '稼働 (pengoperasian) + にあたって menyatakan persiapan krusial menjelang dimulainya operasional.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0a6f1d39-f49c-44d6-9f6c-b2ad5fe858cd', 'be9a9970-be70-43b3-a202-f7c8e6e3642b', 'd1000019-0000-0000-0000-000000000018', 'reading', 'fill_blank', 'Pilih bentuk yang paling tepat untuk surat edaran: 社名変更___、取引先各位へご案内状を送付いたしました。', '{"options":["にあたり","に伴って","に限らず","の上で"],"translation":"Sehubungan dengan perubahan nama perusahaan, kami telah mengirimkan surat pemberitahuan kepada seluruh mitra bisnis.","sentence_template":"社名変更[blank]、取引先各位へご案内状を送付いたしました。"}'::jsonb, '{"selected":"にあたり"}'::jsonb, NULL, NULL, '～にあたり adalah varian formal tertulis yang lazim pada surat pemberitahuan bisnis.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e29757ec-94d4-473f-b392-aeb9c1b0fc5f', 'be9a9970-be70-43b3-a202-f7c8e6e3642b', 'd1000019-0000-0000-0000-000000000018', 'listening', 'listening_choice', 'Dengarkan pengumuman direksi berikut. Langkah apa yang diambil sebelum merilis layanan baru?', '{"options":[{"id":"opt_1","text":"Menunda peluncuran layanan hingga tahun depan"},{"id":"opt_2","text":"Meninjau ulang sistem perlindungan data pribadi secara menyeluruh"},{"id":"opt_3","text":"Mengurangi jumlah staf layanan pelanggan"},{"id":"opt_4","text":"Memindahkan kantor pusat ke kota lain"}],"audio_text":"新サービスの提供開始にあたり、個人情報の保護体制を全面的に見直しました。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '個人情報の保護体制を全面的に見直しました berarti meninjau ulang sistem perlindungan data pribadi secara menyeluruh.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d0bfca56-e8ef-40ef-872f-19ba1c9ebaaf', 'be9a9970-be70-43b3-a202-f7c8e6e3642b', 'd1000019-0000-0000-0000-000000000018', 'writing', 'sentence_builder', 'Susun kalimat: "Menjelang pelaksanaan survei, kami meminta persetujuan responden."', '{"romaji":"Ankeeto no jisshi ni atatte, kaitousha no doui o eta.","tokens":["実施","回答者の","得た。","かねない。","アンケートの","にあたって、","同意を","にもかかわらず、"],"target_translation":"Menjelang pelaksanaan survei, kami meminta persetujuan responden."}'::jsonb, '["アンケートの","実施","にあたって、","回答者の","同意を","得た。"]'::jsonb, NULL, NULL, '実施にあたって menyatakan persiapan etis sebelum survei dilaksanakan.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6cac97b6-47ef-4281-b6f3-2cf586ff5fc0', 'be9a9970-be70-43b3-a202-f7c8e6e3642b', 'd1000019-0000-0000-0000-000000000018', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pada kesempatan pembukaan pameran ini, terima kasih atas kehadiran Anda."', '{"romaji":"Hon tenjikai no kaisai ni atari, goraijou itadaki makoto ni arigatou gozaimasu.","display_text":"本展示会の開催にあたり、ご来場いただき誠にありがとうございます。","phonetic_breakdown":["ほんてんじかいの","かいさいに","あたり","ごらいじょういただき","まことに","ありがとうございます"]}'::jsonb, '{"expected_transcript":"本展示会の開催にあたり、ご来場いただき誠にありがとうございます。"}'::jsonb, NULL, NULL, '開催にあたり sering digunakan pada sambutan pembukaan pameran atau konferensi.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c49e60d2-f6ba-4cf5-baaf-258c1c160a01', 'be9a9970-be70-43b3-a202-f7c8e6e3642b', 'd1000019-0000-0000-0000-000000000018', 'reading', 'fill_blank', 'Lengkapi kalimat panduan akademik: 博士論文を提出する___、所定の書式を厳守すること。', '{"options":["にあたっては","つつあっては","ざるを得ずに","わけにはいかず"],"translation":"Dalam rangka menyerahkan disertasi doktor, wajib mematuhi format yang ditetapkan.","sentence_template":"博士論文を提出する[blank]、所定の書式を厳守すること。"}'::jsonb, '{"selected":"にあたっては"}'::jsonb, NULL, NULL, '～にあたっては memberi penekanan syarat khusus yang harus dipenuhi pada momen tersebut.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8632e5da-7fc5-475d-886f-e40a03511ad9', 'be9a9970-be70-43b3-a202-f7c8e6e3642b', 'd1000019-0000-0000-0000-000000000018', 'listening', 'listening_choice', 'Dengarkan arahan manajer proyek. Apa yang ditekankan sebelum rapat dengan klien?', '{"options":[{"id":"opt_1","text":"Memesan ruang rapat yang lebih besar"},{"id":"opt_2","text":"Membatalkan kontrak yang sudah berjalan"},{"id":"opt_3","text":"Berbagi jawaban atas pertanyaan yang diperkirakan muncul"},{"id":"opt_4","text":"Mengundang media massa ke sesi negosiasi"}],"audio_text":"顧客との最終交渉にあたり、想定される質問への回答を事前に共有しておきたい。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '想定される質問への回答を事前に共有する berarti membagikan jawaban atas pertanyaan yang diprediksi sebelumnya.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6c78d2de-c672-4f30-a722-896b4467f12e', 'be9a9970-be70-43b3-a202-f7c8e6e3642b', 'd1000019-0000-0000-0000-000000000018', 'writing', 'sentence_builder', 'Susun kalimat: "Dalam rangka pindah kantor, kami memperbarui sistem keamanan."', '{"romaji":"Ofisu no iten ni atari, sekyuriti shisutemu o koushin shita.","tokens":["移転","セキュリティシステムを","した。","移転した","オフィスの","にあたり、","更新","に限らず、"],"target_translation":"Dalam rangka pindah kantor, kami memperbarui sistem keamanan."}'::jsonb, '["オフィスの","移転","にあたり、","セキュリティシステムを","更新","した。"]'::jsonb, NULL, NULL, '移転 (relokasi kantor) + にあたり tepat dipakai untuk perubahan besar perusahaan.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c5899e7e-ebd5-4fb1-a798-b8c61febd0fd', 'bf7deeb3-5c55-44ad-a670-d5d77bcd82f4', 'd1000019-0000-0000-0000-000000000019', 'reading', 'fill_blank', 'Pilih pola yang tepat: 自動運転技術が進化する___、法整備の見直しが求められている。', '{"options":["に伴って","にあたって","かねない","ざるを得ない"],"translation":"Seiring berkembangnya teknologi kemudi otonom, peninjauan ulang regulasi hukum semakin dituntut.","sentence_template":"自動運転技術が進化する[blank]、法整備の見直しが求められている。"}'::jsonb, '{"selected":"に伴って"}'::jsonb, NULL, NULL, '進化する (berkembang) + に伴って menyatakan perubahan regulasi yang harus mengikuti perkembangan teknologi.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('87410c88-012f-49ec-8047-28a42afb1d6e', 'bf7deeb3-5c55-44ad-a670-d5d77bcd82f4', 'd1000019-0000-0000-0000-000000000019', 'reading', 'fill_blank', 'Lengkapi frasa berikut: 組織再編___人事異動が、来週発表される予定だ。', '{"options":["に伴う","に伴って","に伴い","に限らず"],"translation":"Mutasi personalia yang menyertai reorganisasi dijadwalkan diumumkan minggu depan.","sentence_template":"組織再編[blank]人事異動が、来週発表される予定だ。"}'::jsonb, '{"selected":"に伴う"}'::jsonb, NULL, NULL, '組織再編に伴う人事異動 menggunakan ～に伴う untuk memodifikasi kata benda 人事異動.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('db3f8298-40a6-404f-a434-06d5d416e908', 'bf7deeb3-5c55-44ad-a670-d5d77bcd82f4', 'd1000019-0000-0000-0000-000000000019', 'listening', 'listening_choice', 'Dengarkan berita lingkungan berikut. Apa yang meningkat seiring kesadaran lingkungan?', '{"options":[{"id":"opt_1","text":"Investasi pada energi terbarukan di seluruh dunia"},{"id":"opt_2","text":"Produksi kendaraan berbahan bakar bensin"},{"id":"opt_3","text":"Impor batu bara untuk pembangkit listrik"},{"id":"opt_4","text":"Harga jual plastik sekali pakai"}],"audio_text":"環境意識の高まりに伴い、再生可能エネルギーへの投資が世界中で加速しています。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '再生可能エネルギーへの投資 (investasi energi terbarukan) semakin cepat seiring meningkatnya kesadaran lingkungan.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fc5c9d27-0852-4645-88b6-31fe7e94a794', 'bf7deeb3-5c55-44ad-a670-d5d77bcd82f4', 'd1000019-0000-0000-0000-000000000019', 'listening', 'listening_choice', 'Dengarkan pengumuman bank berikut. Mengapa jam layanan loket berubah?', '{"options":[{"id":"opt_1","text":"Karena gedung cabang sedang direnovasi total"},{"id":"opt_2","text":"Karena staf bank sedang mengikuti pelatihan tahunan"},{"id":"opt_3","text":"Karena jumlah nasabah internet banking menurun"},{"id":"opt_4","text":"Karena penggunaan internet banking meningkat"}],"audio_text":"インターネットバンキングの利用増加に伴って、一部支店の窓口営業時間を短縮いたします。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '利用増加に伴って berarti ''seiring meningkatnya penggunaan''.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('87ee8f0a-35b3-4b1f-b4f2-b52d066a8cbb', 'bf7deeb3-5c55-44ad-a670-d5d77bcd82f4', 'd1000019-0000-0000-0000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat: "Seiring pertumbuhan kota, jaringan kereta bawah tanah diperluas."', '{"romaji":"Toshi no hatten ni tomonatte, chikatetsu no rosenmou ga hirogatta.","tokens":["に伴って、","路線網が","都市の","地下鉄の","広がった。","にあたって、","発展","発展して"],"target_translation":"Seiring pertumbuhan kota, jaringan kereta bawah tanah diperluas."}'::jsonb, '["都市の","発展","に伴って、","地下鉄の","路線網が","広がった。"]'::jsonb, NULL, NULL, '路線網 (rosenmou) berarti jaringan jalur transportasi.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('42e9a54b-0c06-4c92-95f7-f27ba958ea7f', 'bf7deeb3-5c55-44ad-a670-d5d77bcd82f4', 'd1000019-0000-0000-0000-000000000019', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring globalisasi bisnis, pemahaman lintas budaya menjadi makin penting."', '{"romaji":"Bijinesu no kokusaika ni tomonai, ibunka rikai no juuyousei ga mashite imasu.","display_text":"ビジネスの国際化に伴い、異文化理解の重要性が増しています。","phonetic_breakdown":["びじねすの","こくさいかに","ともない","いぶんかりかいの","じゅうようせいが","ましています"]}'::jsonb, '{"expected_transcript":"ビジネスの国際化に伴い、異文化理解の重要性が増しています。"}'::jsonb, NULL, NULL, '重要性が増す (tingkat kepentingan meningkat) adalah ungkapan akademis & bisnis tingkat N2.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('73460b1e-ef6a-4998-95a6-1c2a667bfc90', 'bf7deeb3-5c55-44ad-a670-d5d77bcd82f4', 'd1000019-0000-0000-0000-000000000019', 'listening', 'listening_choice', 'Dengarkan laporan singkat ini. Apa dampak dari perubahan iklim yang dibahas?', '{"options":[{"id":"opt_1","text":"Hasil panen di seluruh dunia meningkat stabil"},{"id":"opt_2","text":"Makin banyak wilayah mengalami ketidakstabilan hasil panen akibat perubahan iklim"},{"id":"opt_3","text":"Harga hasil pertanian menjadi gratis di daerah pedesaan"},{"id":"opt_4","text":"Petani beralih sepenuhnya ke sektor perikanan"}],"audio_text":"気候変動の深刻化に伴い、農作物の収穫量が不安定になる地域が増えている。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '収穫量が不安定になる berarti hasil panen menjadi tidak stabil.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fbcd05b4-de72-4fe6-826d-bcde21319737', 'bf7deeb3-5c55-44ad-a670-d5d77bcd82f4', 'd1000019-0000-0000-0000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat: "Pekerjaan tambahan yang menyertai perubahan spesifikasi sedang kami hitung ulang."', '{"romaji":"Shiyou henkou ni tomonau tsuika sagyou o saikeisan shite imasu.","tokens":["に伴う","再計算","います。","にあたって","仕様変更","追加作業を","して","に伴って"],"target_translation":"Pekerjaan tambahan yang menyertai perubahan spesifikasi sedang kami hitung ulang."}'::jsonb, '["仕様変更","に伴う","追加作業を","再計算","して","います。"]'::jsonb, NULL, NULL, '仕様変更に伴う追加作業 (pekerjaan tambahan akibat perubahan spesifikasi) sangat khas dunia IT/proyek.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('efaa9437-fcdf-4a9b-a40e-159bf237abe2', 'c314957f-86eb-4238-996e-70daf551c7c7', 'd1000019-0000-0000-0000-000000000018', 'listening', 'listening_choice', 'Dengarkan pidato kepala departemen. Apa harapan beliau untuk proyek tahun ini?', '{"options":[{"id":"opt_1","text":"Setiap divisi bekerja secara terpisah tanpa koordinasi"},{"id":"opt_2","text":"Menghentikan seluruh proyek pengembangan tahun ini"},{"id":"opt_3","text":"Mengurangi jam kerja lembur di akhir pekan"},{"id":"opt_4","text":"Terjalinnya kolaborasi lintas divisi dalam ekspansi bisnis"}],"audio_text":"新年度の事業展開にあたって、部署の垣根を越えた連携を期待しています。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '部署の垣根を越えた連携 berarti kolaborasi yang melampaui sekat antardivisi.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8a8c470e-aefb-4a4a-9abf-6437bc4b077c', 'c314957f-86eb-4238-996e-70daf551c7c7', 'd1000019-0000-0000-0000-000000000018', 'writing', 'sentence_builder', 'Susun kalimat: "Menjelang wawancara kerja, saya meneliti profil perusahaan secara mendalam."', '{"romaji":"Mensetsu o ukeru ni atatte, kigyou no jouhou o fukaku shirabeta.","tokens":["受ける","企業の","深く調べた。","にもかかわらず、","面接を","にあたって、","情報を","受けた"],"target_translation":"Menjelang wawancara kerja, saya meneliti profil perusahaan secara mendalam."}'::jsonb, '["面接を","受ける","にあたって、","企業の","情報を","深く調べた。"]'::jsonb, NULL, NULL, 'Verba bentuk kamus 受ける + にあたって menyatakan persiapan sebelum momen penting.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b889ccbb-f180-4883-8287-f27505a7ae53', 'c314957f-86eb-4238-996e-70daf551c7c7', 'd1000019-0000-0000-0000-000000000018', 'reading', 'fill_blank', 'Pilih frasa yang sesuai untuk kontrak: 本規約の改定___、利用者の皆様に三十日前までに通知します。', '{"options":["にあたり","に伴って","かねず","つつあり"],"translation":"Menjelang revisi ketentuan ini, kami akan memberi tahu pengguna paling lambat 30 hari sebelumnya.","sentence_template":"本規約の改定[blank]、利用者の皆様に三十日前までに通知します。"}'::jsonb, '{"selected":"にあたり"}'::jsonb, NULL, NULL, '改定にあたり lazim dipakai dalam pengumuman pembaruan syarat dan ketentuan.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e1bc2c11-cefb-4c2a-b22f-76dfda406474', 'c314957f-86eb-4238-996e-70daf551c7c7', 'd1000019-0000-0000-0000-000000000018', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Menjelang penandatanganan perjanjian, mari kita pastikan setiap pasalnya."', '{"romaji":"Gouisho no shomei ni atatte, kaku joukou o teinei ni kakunin itashimashou.","display_text":"合意書の署名にあたって、各条項を丁寧に確認いたしましょう。","phonetic_breakdown":["ごういしょの","しょめいに","あたって","かくじょうこうを","ていねいに","かくにんいたしましょう"]}'::jsonb, '{"expected_transcript":"合意書の署名にあたって、各条項を丁寧に確認いたしましょう。"}'::jsonb, NULL, NULL, '各条項 (setiap pasal) dan 署名 (penandatanganan) adalah kosakata kunci dokumen bisnis N2.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f4bbac4f-0eed-4675-886a-2c01a7634769', 'c314957f-86eb-4238-996e-70daf551c7c7', 'd1000019-0000-0000-0000-000000000018', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 創業五十周年を___にあたり、記念誌を刊行する運びとなった。', '{"options":["迎える","迎えた","迎えて","迎えよう"],"translation":"Dalam rangka menyongsong ulang tahun berdirinya perusahaan ke-50, diputuskan untuk menerbitkan buku kenangan.","sentence_template":"創業五十周年を[blank]にあたり、記念誌を刊行する運びとなった。"}'::jsonb, '{"selected":"迎える"}'::jsonb, NULL, NULL, 'Di depan にあたり, kata kerja harus dalam bentuk kamus (迎える).', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c3c8738f-8137-4b0e-b73f-72dbd6cebd42', 'c314957f-86eb-4238-996e-70daf551c7c7', 'd1000019-0000-0000-0000-000000000018', 'listening', 'listening_choice', 'Dengarkan pengumuman universitas. Kapan mahasiswa harus mengikuti orientasi?', '{"options":[{"id":"opt_1","text":"Sebelum keberangkatan studi ke luar negeri"},{"id":"opt_2","text":"Setelah kembali ke Jepang dari luar negeri"},{"id":"opt_3","text":"Saat mendaftar beasiswa di tahun pertama"},{"id":"opt_4","text":"Ketika wisuda sarjana berlangsung"}],"audio_text":"海外留学への出発にあたっては、危機管理オリエンテーションの受講が必須となります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '出発にあたっては menegaskan syarat wajib menjelang keberangkatan.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c5852222-fcb0-429d-9234-e86a8889839f', 'c314957f-86eb-4238-996e-70daf551c7c7', 'd1000019-0000-0000-0000-000000000018', 'writing', 'sentence_builder', 'Susun kalimat: "Pada kesempatan peluncuran aplikasi, kami mengadakan sesi uji coba gratis."', '{"romaji":"Apuri no ririisu ni atari, muryou taikenkai o kaisai shita.","tokens":["リリース","無料体験会を","した。","に伴って、","アプリの","にあたり、","開催","開催する"],"target_translation":"Pada kesempatan peluncuran aplikasi, kami mengadakan sesi uji coba gratis."}'::jsonb, '["アプリの","リリース","にあたり、","無料体験会を","開催","した。"]'::jsonb, NULL, NULL, 'Kata benda リリース + にあたり diikuti aksi promosi 開催した.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7147b879-d915-4997-b888-0eaba2c16e04', 'c314957f-86eb-4238-996e-70daf551c7c7', 'd1000019-0000-0000-0000-000000000018', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dalam rangka memulai kehidupan baru di Jepang, saya bertekad belajar lebih giat."', '{"romaji":"Nihon de no shinseikatsu o hajimeru ni atatte, sara ni doryoku suru ketsui desu.","display_text":"日本での新生活を始めるにあたって、さらに努力する決意です。","phonetic_breakdown":["にほんでの","しんせいかつを","はじめるに","あたって","さらに","どりょくするけついです"]}'::jsonb, '{"expected_transcript":"日本での新生活を始めるにあたって、さらに努力する決意です。"}'::jsonb, NULL, NULL, '決意です (bertekad) sangat cocok dipasangkan dengan momen awal ～を始めるにあたって.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7c9f9325-369e-4508-acc6-b30109be0a35', 'cbd1c979-4789-4a96-ba32-e2571ccd60b0', 'd1000019-0000-0000-0000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat: "Apakah Ibu Kepala Bagian sudah membaca laporan hari ini?"', '{"romaji":"Kachou wa honjitsu no houkokusho o oyomi ni narimashita ka.","tokens":["報告書を","お読みに","課長は","お読みいたし","本日の","なりましたか。","拝見し"],"target_translation":"Apakah Ibu Kepala Bagian sudah membaca laporan hari ini?"}'::jsonb, '["課長は","本日の","報告書を","お読みに","なりましたか。"]'::jsonb, NULL, NULL, '読む → お読みになる adalah bentuk Sonkeigo yang benar untuk atasan.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('941bd5ce-d9dd-4cfb-82de-e9fad4d0421e', 'cbd1c979-4789-4a96-ba32-e2571ccd60b0', 'd1000019-0000-0000-0000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat: "Klien telah menyetujui syarat yang kami ajukan kemarin."', '{"romaji":"Okyakusama wa kinou no jouken o goshoudaku nasaimashita.","tokens":["なさいました。","お客様は","ご承諾いたし","申し上げ","昨日の","ご承諾","条件を"],"target_translation":"Klien telah menyetujui syarat yang kami ajukan kemarin."}'::jsonb, '["お客様は","昨日の","条件を","ご承諾","なさいました。"]'::jsonb, NULL, NULL, '承諾する (menyetujui) → ご承諾なさる.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2418b966-77dd-4cdb-b5df-3a7c012f37bc', 'cbd1c979-4789-4a96-ba32-e2571ccd60b0', 'd1000019-0000-0000-0000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat: "Apakah Bapak mengenal penanggung jawab dari kantor cabang Osaka?"', '{"romaji":"Oosaka shiten no gotantousha o gozonji de irasshaimasu ka.","tokens":["おり","ご担当者を","でいらっしゃい","ますか。","存じ上げて","ご存じ","大阪支店の"],"target_translation":"Apakah Bapak mengenal penanggung jawab dari kantor cabang Osaka?"}'::jsonb, '["大阪支店の","ご担当者を","ご存じ","でいらっしゃい","ますか。"]'::jsonb, NULL, NULL, 'ご存じでいらっしゃいますか adalah bentuk Sonkeigo yang sangat sopan dari 知っていますか.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e56edc71-8d68-46dd-a7a8-1ffc90d6be08', 'cbd1c979-4789-4a96-ba32-e2571ccd60b0', 'd1000019-0000-0000-0000-000000000027', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mohon maaf telah membuat Anda menunggu cukup lama."', '{"romaji":"Taihen omatase itashimashita. Douzo naka e ohairi kudasai.","display_text":"大変お待たせいたしました。どうぞ中へお入りください。","phonetic_breakdown":["たいへん","おまたせいたしました","どうぞなかえ","おはいりください"]}'::jsonb, '{"expected_transcript":"大変お待たせいたしました。どうぞ中へお入りください。"}'::jsonb, NULL, NULL, 'お待たせいたしました (Kenjougo) + お入りください (Sonkeigo) adalah kombinasi standar penyambutan tamu.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f327455d-4f59-480c-bc56-feb2e7b265f7', 'cbd1c979-4789-4a96-ba32-e2571ccd60b0', 'd1000019-0000-0000-0000-000000000027', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terima kasih telah meluangkan waktu untuk hadir hari ini."', '{"romaji":"Honjitsu wa oisogashii naka okoshi kudasari, makoto ni arigatou gozaimasu.","display_text":"本日はお忙しい中お越しくださり、誠にありがとうございます。","phonetic_breakdown":["ほんじつは","おいそがしいなか","おこしくださり","まことに","ありがとうございます"]}'::jsonb, '{"expected_transcript":"本日はお忙しい中お越しくださり、誠にありがとうございます。"}'::jsonb, NULL, NULL, 'お越しくださり adalah bentuk sangat sopan dari 来てくれて.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b921bf40-32bf-489c-84a5-a4fa7bec42b4', 'cbd1c979-4789-4a96-ba32-e2571ccd60b0', 'd1000019-0000-0000-0000-000000000027', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Apakah Anda ingin memesan kopi atau teh hijau?"', '{"romaji":"Onomimono wa koohii to ryokucha no dochira ni nasaimasu ka.","display_text":"お飲み物はコーヒーと緑茶のどちらになさいますか。","phonetic_breakdown":["おのみものは","こーひーと","りょくちゃの","どちらに","なさいますか"]}'::jsonb, '{"expected_transcript":"お飲み物はコーヒーと緑茶のどちらになさいますか。"}'::jsonb, NULL, NULL, 'どちらになさいますか adalah bentuk Sonkeigo dari どちらにしますか saat menawarkan pilihan kepada tamu.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('287271db-27e3-40b2-b3a5-f9744c57dd33', 'cbd1c979-4789-4a96-ba32-e2571ccd60b0', 'd1000019-0000-0000-0000-000000000027', 'reading', 'fill_blank', 'Pilih bentuk yang paling tepat: お客様がもうすぐ受付に___ので、会議室へご案内してください。', '{"options":["いらっしゃいます","まいります","おります","いたします"],"translation":"Karena tamu akan segera tiba di resepsionis, tolong antarkan ke ruang rapat.","sentence_template":"お客様がもうすぐ受付に[blank]ので、会議室へご案内してください。"}'::jsonb, '{"selected":"いらっしゃいます"}'::jsonb, NULL, NULL, 'いらっしゃいます adalah sonkeigo baku untuk 来る (datang/tiba) bagi tamu.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5691c30d-6a8d-47cd-80dc-e6fbf9ceabf2', 'cbd1c979-4789-4a96-ba32-e2571ccd60b0', 'd1000019-0000-0000-0000-000000000027', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Apabila ada pertanyaan lebih lanjut, silakan hubungi bagian layanan kami kapan saja."', '{"romaji":"Gofumei na ten ga gozaimashitara, itsudemo okigaru ni otoiawase kudasai.","display_text":"ご不明な点がございましたら、いつでもお気軽にお問い合わせください。","phonetic_breakdown":["ごふめいなてんが","ございましたら","いつでもおきがるに","おといあわせください"]}'::jsonb, '{"expected_transcript":"ご不明な点がございましたら、いつでもお気軽にお問い合わせください。"}'::jsonb, NULL, NULL, 'お問い合わせください (silakan menghubungi) adalah penutup standar email dan layanan pelanggan Jepang.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f2891505-e769-449f-b890-95d9eebfc7d1', 'ccbbcc4c-62e8-4dfa-bbc0-54cdd8e7f64b', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 会社の___情報を外部に漏らすことは厳禁されている。', '{"options":["機密","観光","趣味","天気"],"translation":"Membocorkan informasi rahasia perusahaan ke pihak luar sangat dilarang keras.","sentence_template":"会社の[blank]情報を外部に漏らすことは厳禁されている。"}'::jsonb, '{"selected":"機密"}'::jsonb, NULL, NULL, '機密情報 (kimitsu jouhou) berarti informasi rahasia/konfidensial perusahaan.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('31d563e7-1f31-4bf4-a7b3-da2463997413', 'ccbbcc4c-62e8-4dfa-bbc0-54cdd8e7f64b', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat kerja berikut: 顧客との約束である___を守るため、チーム全員で協力した。', '{"options":["納期","気温","世代","景色"],"translation":"Demi menepati tenggat pengiriman yang telah dijanjikan kepada klien, seluruh tim bekerja sama.","sentence_template":"顧客との約束である[blank]を守るため、チーム全員で協力した。"}'::jsonb, '{"selected":"納期"}'::jsonb, NULL, NULL, '納期 (nouki) berarti tenggat waktu penyerahan atau pengiriman proyek/produk.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bb85507f-976d-4d33-9d97-464c135f5998', 'ccbbcc4c-62e8-4dfa-bbc0-54cdd8e7f64b', NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: プロジェクトの責任者という___上、簡単に諦めることはできない。', '{"options":["立場","物価","普及","季節"],"translation":"Dilihat dari posisi saya sebagai penanggung jawab proyek, saya tidak bisa menyerah begitu saja.","sentence_template":"プロジェクトの責任者という[blank]上、簡単に諦めることはできない。"}'::jsonb, '{"selected":"立場"}'::jsonb, NULL, NULL, '立場 (tachiba) berarti posisi, kedudukan, atau peran seseorang dalam organisasi.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f379cbe7-8917-4c52-bfb7-784086778363', 'ccbbcc4c-62e8-4dfa-bbc0-54cdd8e7f64b', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan rekan kerja berikut. Mengapa pembicara tidak bisa pulang lebih awal?', '{"options":[{"id":"opt_1","text":"Karena pemeriksaan akhir presentasi besok belum selesai"},{"id":"opt_2","text":"Karena kereta terakhir sudah berangkat"},{"id":"opt_3","text":"Karena sedang menunggu paket pribadi di kantor"},{"id":"opt_4","text":"Karena hujan deras di luar gedung"}],"audio_text":"明日のプレゼンの最終確認が終わっていないので、このまま帰るわけにはいかないんだ。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '最終確認が終わっていない (pengecekan akhir belum selesai) membuat pembicara merasa tidak pantas pulang.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('74d34c37-10ce-4e81-b551-5e5364f5def9', 'ccbbcc4c-62e8-4dfa-bbc0-54cdd8e7f64b', NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan berikut. Apa yang dijaga oleh pembicara?', '{"options":[{"id":"opt_1","text":"Jadwal cuti musim panas tim penjualan"},{"id":"opt_2","text":"Kepercayaan mitra bisnis yang sudah susah payah dibangun"},{"id":"opt_3","text":"Anggaran makan siang bulanan kantor"},{"id":"opt_4","text":"Koleksi buku panduan di ruang rapat"}],"audio_text":"せっかく築いた取引先との信頼を失うわけにはいきません。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '信頼を失う (kehilangan kepercayaan) adalah hal yang tidak boleh terjadi secara profesional.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f25ce91a-c1f6-49f5-8588-e0b0d18e94b3', 'ccbbcc4c-62e8-4dfa-bbc0-54cdd8e7f64b', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena sudah berjanji, saya tidak mungkin melanggarnya."', '{"romaji":"Ichido yakusoku shita ijou, yaburu wake ni wa ikimasen.","display_text":"一度約束した以上、破るわけにはいきません。","phonetic_breakdown":["いちど","やくそくした","いじょう","やぶる","わけには","いきません"]}'::jsonb, '{"expected_transcript":"一度約束した以上、破るわけにはいきません。"}'::jsonb, NULL, NULL, '約束を破る berarti melanggar janji; dipadukan dengan ～わけにはいきません untuk menegaskan komitmen.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('05152a92-ffcd-4ecf-914a-29fa285c437b', 'ccbbcc4c-62e8-4dfa-bbc0-54cdd8e7f64b', 'd1000019-0000-0000-0000-000000000021', 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 会社の信用に関わる問題なので、曖昧なまま___するわけにはいかない。', '{"options":["放置","達成","歓迎","契約"],"translation":"Karena ini masalah yang menyangkut kredibilitas perusahaan, tidak mungkin membiarkannya begitu saja tanpa kejelasan.","sentence_template":"会社の信用に関わる問題なので、曖昧なまま[blank]するわけにはいかない。"}'::jsonb, '{"selected":"放置"}'::jsonb, NULL, NULL, '放置する (membiarkan/menelantarkan) sering dipakai bersama わけにはいかない dalam konteks tanggung jawab.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('163492a4-851a-4280-96c1-e00cb618b151', 'ccbbcc4c-62e8-4dfa-bbc0-54cdd8e7f64b', 'd1000019-0000-0000-0000-000000000021', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya tidak bisa menolak permintaan tolong dari senior yang selalu membimbing saya."', '{"romaji":"Itsumo osewa ni natte iru senpai no tanomi wa, kotowaru wake ni wa ikimasen.","display_text":"いつもお世話になっている先輩の頼みは、断るわけにはいきません。","phonetic_breakdown":["いつも","おせわになっている","せんぱいのたのみは","ことわる","わけにはいきません"]}'::jsonb, '{"expected_transcript":"いつもお世話になっている先輩の頼みは、断るわけにはいきません。"}'::jsonb, NULL, NULL, '断るわけにはいきません mengekspresikan rasa sungkan dan tanggung jawab sosial di budaya kerja Jepang.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ecdfc9fe-a5b7-4878-88b1-713d747c4aca', 'd0c99fec-f27b-4fde-8d94-2dd916eead77', 'd1000019-0000-0000-0000-000000000025', 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 人口減少により、地方の公共交通機関の維持が難しく___。', '{"options":["なりつつある","なるつつある","なったつつある","なってつつある"],"translation":"Akibat penurunan populasi, mempertahankan transportasi umum di daerah sedang menjadi makin sulit.","sentence_template":"人口減少により、地方の公共交通機関の維持が難しく[blank]。"}'::jsonb, '{"selected":"なりつつある"}'::jsonb, NULL, NULL, '難しくなる → 難しくなりつつある.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('671add45-48e4-4af8-8e7b-e4887cd28a03', 'd0c99fec-f27b-4fde-8d94-2dd916eead77', 'd1000019-0000-0000-0000-000000000025', 'reading', 'fill_blank', 'Lengkapi kalimat berita berikut: 国際的な協調により、新たな安全基準が___つつある。', '{"options":["整えられ","整える","整えた","整えて"],"translation":"Melalui kerja sama internasional, standar keamanan baru sedang mulai ditata.","sentence_template":"国際的な協調により、新たな安全基準が[blank]つつある。"}'::jsonb, '{"selected":"整えられ"}'::jsonb, NULL, NULL, '整えられる (ditata/disiapkan, bentuk pasif) → 整えられつつある.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ec29ecdc-7335-4410-91bd-ad5514724bef', 'd0c99fec-f27b-4fde-8d94-2dd916eead77', 'd1000019-0000-0000-0000-000000000025', 'listening', 'listening_choice', 'Dengarkan berita keuangan berikut. Apa tren yang dilaporkan?', '{"options":[{"id":"opt_1","text":"Minat terhadap pembentukan aset jangka panjang sedang naik pesat terutama di kalangan muda"},{"id":"opt_2","text":"Kalangan muda berhenti menabung dan berinvestasi sepenuhnya"},{"id":"opt_3","text":"Suku bunga pinjaman perumahan naik tiga kali lipat bulan ini"},{"id":"opt_4","text":"Perusahaan sekuritas menutup seluruh layanan daringnya"}],"audio_text":"若年層を中心に、長期的な資産形成への関心が急速に高まりつつあります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '若年層 (kalangan usia muda) dan 資産形成 (pembentukan aset/investasi).', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cd6cb936-3ff0-41ae-bd30-4ba010ca8915', 'd0c99fec-f27b-4fde-8d94-2dd916eead77', 'd1000019-0000-0000-0000-000000000025', 'listening', 'listening_choice', 'Dengarkan laporan teknologi berikut. Apa yang sedang terwujud?', '{"options":[{"id":"opt_1","text":"Teknologi baru gagal diuji coba di laboratorium"},{"id":"opt_2","text":"Film fiksi ilmiah dilarang tayang di bioskop"},{"id":"opt_3","text":"Teknologi yang dulu dianggap fiksi ilmiah kini sedang menjadi kenyataan"},{"id":"opt_4","text":"Para ilmuwan menghentikan riset kecerdasan buatan"}],"audio_text":"これまでSFの世界の話と思われていた技術が、今まさに現実のものとなりつつある。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '現実のものとなりつつある berarti sedang berubah menjadi kenyataan.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('abc0a588-65ab-4dfd-aff8-6876ae244572', 'd0c99fec-f27b-4fde-8d94-2dd916eead77', 'd1000019-0000-0000-0000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat: "Penggunaan kertas di kantor sedang berkurang berkat digitalisasi."', '{"romaji":"Dejitaruka ni yori, ofisu de no kami no shiyouryou ga genshou shitsutsu aru.","tokens":["ある。","減少","デジタル化により、","オフィスでの","しつつ","減少した","にあたって","紙の使用量が"],"target_translation":"Penggunaan kertas di kantor sedang berkurang berkat digitalisasi."}'::jsonb, '["デジタル化により、","オフィスでの","紙の使用量が","減少","しつつ","ある。"]'::jsonb, NULL, NULL, '使用量 (jumlah pemakaian) dan 減少 (berkurang) sangat umum dalam laporan perusahaan.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1ab42d58-9a0e-4b26-a5bc-88486ce5d315', 'd0c99fec-f27b-4fde-8d94-2dd916eead77', 'd1000019-0000-0000-0000-000000000025', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Persiapan untuk menyambut acara internasional tahun depan sedang berjalan lancar."', '{"romaji":"Rainen no kokusai taikai ni muketa junbi ga, chakuchaku to susumitsutsu arimasu.","display_text":"来年の国際大会に向けた準備が、着々と進みつつあります。","phonetic_breakdown":["らいねんの","こくさいたいかいに","むけたじゅんびが","ちゃくちゃくと","すすみつつあります"]}'::jsonb, '{"expected_transcript":"来年の国際大会に向けた準備が、着々と進みつつあります。"}'::jsonb, NULL, NULL, '着々と (chakuchaku to) berarti langkah demi langkah secara mantap.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4a4f6d82-d6dd-4528-8b91-ff450fba0a2c', 'd0c99fec-f27b-4fde-8d94-2dd916eead77', 'd1000019-0000-0000-0000-000000000025', 'listening', 'listening_choice', 'Dengarkan laporan penelitian berikut. Apa temuan utamanya?', '{"options":[{"id":"opt_1","text":"Populasi satwa liar langka meningkat drastis"},{"id":"opt_2","text":"Penebangan hutan telah berhenti sepenuhnya di seluruh dunia"},{"id":"opt_3","text":"Habitat satwa liar langka sedang hilang dengan cepat akibat penebangan hutan"},{"id":"opt_4","text":"Satwa liar langka dipindahkan semuanya ke kebun binatang"}],"audio_text":"森林伐採の影響で、希少な野生動物の生息地が急速に失われつつある。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '失われつつある menyatakan proses hilangnya habitat yang sedang berlangsung cepat.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('38e4cc80-443b-4f5d-93b8-df2f95b9bb02', 'd0c99fec-f27b-4fde-8d94-2dd916eead77', 'd1000019-0000-0000-0000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat: "Budaya kerja fleksibel sedang menyebar luas di kalangan perusahaan rintisan."', '{"romaji":"Jyuunan na hatarakikata ga sutaatoappu kigyou ni shintou shitsutsu aru.","tokens":["スタートアップ企業に","しつつ","ようだ。","かねない","柔軟な働き方が","浸透","ある","浸透した"],"target_translation":"Budaya kerja fleksibel sedang menyebar luas di kalangan perusahaan rintisan."}'::jsonb, '["柔軟な働き方が","スタートアップ企業に","浸透","しつつ","ある","ようだ。"]'::jsonb, NULL, NULL, '浸透しつつある (sedang meresap/menyebar luas) sering dipakai untuk budaya kerja baru.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c41ab188-aec1-4102-8b25-76e5160c7070', 'd0e0ca64-70c3-426d-8271-d0e281a31428', 'd1000019-0000-0000-0000-000000000019', 'reading', 'fill_blank', 'Lengkapi pola perubahan beriringan: 都市の人口が増加する___、交通渋滞がひどくなっている。', '{"options":["に伴って","にあたって","に限らず","わけにはいかず"],"translation":"Seiring meningkatnya populasi kota, kemacetan lalu lintas menjadi makin parah.","sentence_template":"都市の人口が増加する[blank]、交通渋滞がひどくなっている。"}'::jsonb, '{"selected":"に伴って"}'::jsonb, NULL, NULL, 'V-dict + に伴って menyatakan perubahan B yang terjadi seiring perubahan A.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4d89652a-91a5-4a72-ae78-763f33b813aa', 'd0e0ca64-70c3-426d-8271-d0e281a31428', 'd1000019-0000-0000-0000-000000000019', 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk menerangkan kata benda di belakangnya: 経済成長___環境問題への対策が急がれている。', '{"options":["に伴う","に伴って","に伴い","にあたって"],"translation":"Langkah penanggulangan masalah lingkungan yang menyertai pertumbuhan ekonomi sedang dipercepat.","sentence_template":"経済成長[blank]環境問題への対策が急がれている。"}'::jsonb, '{"selected":"に伴う"}'::jsonb, NULL, NULL, 'Saat langsung menerangkan kata benda (環境問題), gunakan bentuk ～に伴う.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5fbc0bce-2ba8-4154-87e6-f5d548b19f0f', 'd0e0ca64-70c3-426d-8271-d0e281a31428', 'd1000019-0000-0000-0000-000000000019', 'reading', 'fill_blank', 'Lengkapi kalimat bergaya berita formal: 法律の改正___、新しい申請手続きが導入された。', '{"options":["に伴い","かねない","つつある","ざるを得ない"],"translation":"Seiring revisi undang-undang, prosedur pengajuan baru telah diterapkan.","sentence_template":"法律の改正[blank]、新しい申請手続きが導入された。"}'::jsonb, '{"selected":"に伴い"}'::jsonb, NULL, NULL, '～に伴い adalah bentuk tulis/formal dari ～に伴って yang lazim dalam artikel berita dan pengumuman resmi.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('49118a7c-2eaa-495f-b596-344f303bd0f8', 'd0e0ca64-70c3-426d-8271-d0e281a31428', 'd1000019-0000-0000-0000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat: "Seiring meningkatnya wisatawan asing, informasi multibahasa diperluas."', '{"romaji":"Gaikokujin kankoukyaku no zouka ni tomonatte, tagengo annai ga kakujuu sareta.","tokens":["にあたって、","多言語案内が","外国人観光客の","に伴って、","拡充","増加して","増加","された。"],"target_translation":"Seiring meningkatnya wisatawan asing, informasi multibahasa diperluas."}'::jsonb, '["外国人観光客の","増加","に伴って、","多言語案内が","拡充","された。"]'::jsonb, NULL, NULL, '拡充される (diperluas/ditingkatkan cakupannya) sangat alami berpasangan dengan 増加に伴って.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d3f14d3d-fa52-48d5-9845-d66f1ddea639', 'd0e0ca64-70c3-426d-8271-d0e281a31428', 'd1000019-0000-0000-0000-000000000019', 'writing', 'sentence_builder', 'Susun kalimat: "Seiring kemajuan AI, pekerjaan baru bermunculan."', '{"romaji":"Eiai no shinpo ni tomonai, atarashii shokugyou ga umarete iru.","tokens":["に伴い、","生まれている。","進歩した","進歩","にもかかわらず、","AIの","職業が","新しい"],"target_translation":"Seiring kemajuan AI, pekerjaan baru bermunculan."}'::jsonb, '["AIの","進歩","に伴い、","新しい","職業が","生まれている。"]'::jsonb, NULL, NULL, '進歩 (kemajuan) + に伴い menyatakan perubahan sosial yang menyertai kemajuan teknologi.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5e5b283-de55-40a5-a2df-9b8e714c8293', 'd0e0ca64-70c3-426d-8271-d0e281a31428', 'd1000019-0000-0000-0000-000000000019', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring pemulihan ekonomi, perekrutan karyawan baru pun bertambah."', '{"romaji":"Keiki no kaifuku ni tomonatte, shinsotsu saiyou no kazu mo fuete imasu.","display_text":"景気の回復に伴って、新卒採用の数も増えています。","phonetic_breakdown":["けいきの","かいふくに","ともなって","しんそつ","さいようの","かずも","ふえています"]}'::jsonb, '{"expected_transcript":"景気の回復に伴って、新卒採用の数も増えています。"}'::jsonb, NULL, NULL, '景気の回復 (pemulihan ekonomi) dan 新卒採用 (perekrutan lulusan baru) adalah istilah populer dunia kerja Jepang.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0cbf01ed-b5f4-41d8-8586-57e653440a58', 'd0e0ca64-70c3-426d-8271-d0e281a31428', 'd1000019-0000-0000-0000-000000000019', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa hubungan sebab-akibat yang disampaikan?', '{"options":[{"id":"opt_1","text":"Jumlah pembaca koran meningkat karena ponsel"},{"id":"opt_2","text":"Ponsel tidak berpengaruh pada penjualan koran"},{"id":"opt_3","text":"Jumlah pelanggan koran menurun tiap tahun seiring meluasnya ponsel pintar"},{"id":"opt_4","text":"Perusahaan koran berhenti beroperasi mulai bulan depan"}],"audio_text":"スマートフォンの普及に伴って、新聞の購読者数は年々減少している。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '普及に伴って menghubungkan penyebaran smartphone dengan penurunan pelanggan koran (購読者数).', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('23e167b2-af49-4eca-8856-ed9df9d7a6c9', 'd0e0ca64-70c3-426d-8271-d0e281a31428', 'd1000019-0000-0000-0000-000000000019', 'reading', 'fill_blank', 'Lengkapi frasa nominal berikut: 移転___経費は、来期の予算に組み込む予定だ。', '{"options":["に伴う","に伴って","にあたり","に限らず"],"translation":"Biaya yang menyertai relokasi direncanakan akan dimasukkan ke dalam anggaran periode berikutnya.","sentence_template":"移転[blank]経費は、来期の予算に組み込む予定だ。"}'::jsonb, '{"selected":"に伴う"}'::jsonb, NULL, NULL, 'に伴う memodifikasi kata benda 経費 (biaya/pengeluaran).', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ca002a1e-5e0f-420c-9197-0520957bfa47', 'd8fa5b13-47ce-4e19-abf1-5fa5fd49bd80', 'd1000019-0000-0000-0000-000000000023', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun hari libur, banyak staf datang membantu persiapan."', '{"romaji":"Kyuujitsu ni mo kakawarazu, ooku no sutaffu ga junbi o tetsudatta.","tokens":["スタッフが","休日","手伝った。","にあたって、","休日な","多くの","にもかかわらず、","準備を"],"target_translation":"Meskipun hari libur, banyak staf datang membantu persiapan."}'::jsonb, '["休日","にもかかわらず、","多くの","スタッフが","準備を","手伝った。"]'::jsonb, NULL, NULL, '休日 (kata benda) langsung tersambung dengan にもかかわらず.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a4ac6581-c43e-4d20-8576-dc5b124b6ea2', 'd8fa5b13-47ce-4e19-abf1-5fa5fd49bd80', 'd1000019-0000-0000-0000-000000000023', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun tidak banyak beriklan, buku ini menjadi sangat laris."', '{"romaji":"Senden o amari shinakatta ni mo kakawarazu, kono hon wa besutoseraa ni natta.","tokens":["宣伝を","にもかかわらず、","ベストセラーに","この本は","に伴って、","宣伝して","なった。","あまりしなかった"],"target_translation":"Meskipun tidak banyak beriklan, buku ini menjadi sangat laris."}'::jsonb, '["宣伝を","あまりしなかった","にもかかわらず、","この本は","ベストセラーに","なった。"]'::jsonb, NULL, NULL, '宣伝 (iklan/promosi) + あまりしなかったにもかかわらず menyatakan hasil melampaui dugaan.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('db7abfd6-b9a7-4892-910e-5abd7ac1e97e', 'd8fa5b13-47ce-4e19-abf1-5fa5fd49bd80', 'd1000019-0000-0000-0000-000000000023', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun cuaca sangat dingin, semua peserta maraton mencapai garis finis."', '{"romaji":"Kibishii samusa ni mo kakawarazu, zenin ga kansou shita.","tokens":["に限らず、","した。","寒さ","完走","厳しい","にもかかわらず、","全員が","寒くて"],"target_translation":"Meskipun cuaca sangat dingin, semua peserta maraton mencapai garis finis."}'::jsonb, '["厳しい","寒さ","にもかかわらず、","全員が","完走","した。"]'::jsonb, NULL, NULL, '完走する (kansou suru) berarti menyelesaikan lomba lari hingga garis finis.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c67cd4a2-d264-40b7-b9ec-05bb5cc3d5c9', 'd8fa5b13-47ce-4e19-abf1-5fa5fd49bd80', 'd1000019-0000-0000-0000-000000000023', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terima kasih telah datang jauh-jauh meskipun jadwal Anda sangat padat."', '{"romaji":"Gotabou ni mo kakawarazu, enpou yori okoshi itadaki arigatou gozaimasu.","display_text":"ご多忙にもかかわらず、遠方よりお越しいただきありがとうございます。","phonetic_breakdown":["ごたぼうにも","かかわらず","えんぽうより","おこしいただき","ありがとうございます"]}'::jsonb, '{"expected_transcript":"ご多忙にもかかわらず、遠方よりお越しいただきありがとうございます。"}'::jsonb, NULL, NULL, 'ご多忙 (sangat sibuk, bentuk hormat) dan 遠方より (dari tempat jauh) adalah frasa bisnis tingkat tinggi.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('aab7f8c9-e2a9-4e36-99f0-d700da84ddd0', 'd8fa5b13-47ce-4e19-abf1-5fa5fd49bd80', 'd1000019-0000-0000-0000-000000000023', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun sudah dijelaskan berkali-kali, masih ada bagian yang kurang dipahami."', '{"romaji":"Nando mo setsumei o uketa ni mo kakawarazu, mada rikai dekinai bubun ga arimasu.","display_text":"何度も説明を受けたにもかかわらず、まだ理解できない部分があります。","phonetic_breakdown":["なんども","せつめいをうけた","にもかかわらず","まだりかいできない","ぶぶんがあります"]}'::jsonb, '{"expected_transcript":"何度も説明を受けたにもかかわらず、まだ理解できない部分があります。"}'::jsonb, NULL, NULL, '説明を受ける berarti menerima penjelasan.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('abf12ba1-765f-4b77-a866-1ddde2b5af45', 'd8fa5b13-47ce-4e19-abf1-5fa5fd49bd80', 'd1000019-0000-0000-0000-000000000023', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun anggaran terbatas, tim kami berhasil menciptakan hasil terbaik."', '{"romaji":"Yosan ga kagirarete ita ni mo kakawarazu, chiimu wa saikou no seika o dashimashita.","display_text":"予算が限られていたにもかかわらず、チームは最高の成果を出しました。","phonetic_breakdown":["よさんが","かぎられていた","にもかかわらず","ちーむは","さいこうのせいかを","だしました"]}'::jsonb, '{"expected_transcript":"予算が限られていたにもかかわらず、チームは最高の成果を出しました。"}'::jsonb, NULL, NULL, '成果を出す berarti menghasilkan capaian/kinerja nyata.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bb7a7644-9d81-4797-92e1-00945777faf6', 'd8fa5b13-47ce-4e19-abf1-5fa5fd49bd80', 'd1000019-0000-0000-0000-000000000023', 'reading', 'fill_blank', 'Pilih pola yang tepat: 経験が浅い___、彼女は冷静にトラブルを処理した。', '{"options":["にもかかわらず","に伴って","にあたって","ざるを得ず"],"translation":"Meskipun pengalamannya masih minim, ia menangani masalah tersebut dengan tenang.","sentence_template":"経験が浅い[blank]、彼女は冷静にトラブルを処理した。"}'::jsonb, '{"selected":"にもかかわらず"}'::jsonb, NULL, NULL, 'Kata sifat-i (浅い) langsung tersambung ke にもかかわらず.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('205175f6-b05c-4ef0-beab-8e3bcd49e350', 'd8fa5b13-47ce-4e19-abf1-5fa5fd49bd80', 'd1000019-0000-0000-0000-000000000023', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun waktunya singkat, kami berhasil menyelesaikan persiapan dengan rapi."', '{"romaji":"Mijikai junbi kikan ni mo kakawarazu, todokoorinaku kaisai suru koto ga dekimashita.","display_text":"短い準備期間にもかかわらず、滞りなく開催することができました。","phonetic_breakdown":["みじかい","じゅんびきかんに","もかかわらず","とどこおりなく","かいさいすることが","できました"]}'::jsonb, '{"expected_transcript":"短い準備期間にもかかわらず、滞りなく開催することができました。"}'::jsonb, NULL, NULL, '滞りなく (dengan lancar tanpa hambatan) adalah kosakata formal N2.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f6eaae98-900e-4e94-aae9-38f4dda848ca', 'dca41802-7cb1-422a-b3e2-1700bce22561', 'd1000019-0000-0000-0000-000000000026', 'listening', 'listening_choice', 'Dengarkan komentar analis hukum. Risiko apa yang muncul dari klausul kontrak yang ambigu?', '{"options":[{"id":"opt_1","text":"Rumusan kontrak yang ambigu bisa saja berkembang menjadi sengketa hukum serius di masa depan"},{"id":"opt_2","text":"Kontrak yang ambigu mempermudah pembatalan tanpa biaya"},{"id":"opt_3","text":"Pihak hukum tidak memerlukan kontrak tertulis"},{"id":"opt_4","text":"Klausul tersebut akan otomatis diperbaiki oleh pengadilan"}],"audio_text":"契約書の表現が曖昧なままだと、将来的に深刻な法的トラブルに発展しかねない。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'トラブルに発展しかねない berarti bisa saja berkembang menjadi perselisihan serius.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('062465fa-f72b-4cf2-9702-ae84b71b61cb', 'dca41802-7cb1-422a-b3e2-1700bce22561', 'd1000019-0000-0000-0000-000000000026', 'writing', 'sentence_builder', 'Susun kalimat: "Jika pengawasan lalu lintas dilonggarkan, angka kecelakaan bisa saja meningkat."', '{"romaji":"Koutsuu torishimari o yurumeru to, jiko kensuu ga zouka shikanenai.","tokens":["緩めると、","増加","ない。","つつある。","交通取り締まりを","事故件数が","しかね","増加する"],"target_translation":"Jika pengawasan lalu lintas dilonggarkan, angka kecelakaan bisa saja meningkat."}'::jsonb, '["交通取り締まりを","緩めると、","事故件数が","増加","しかね","ない。"]'::jsonb, NULL, NULL, '増加しかねない menyatakan kemungkinan buruk meningkatnya kecelakaan.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('75cee77b-002e-4b56-9d1b-0b4c3e4d5eca', 'dca41802-7cb1-422a-b3e2-1700bce22561', 'd1000019-0000-0000-0000-000000000026', 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 個人情報の管理体制が不十分だと、企業の存続にも関わる問題になり___。', '{"options":["かねない","ざるを得ない","に限らず","に伴って"],"translation":"Jika sistem pengelolaan data pribadi tidak memadai, bisa saja menjadi masalah yang mengancam kelangsungan perusahaan.","sentence_template":"個人情報の管理体制が不十分だと、企業の存続にも関わる問題になり[blank]。"}'::jsonb, '{"selected":"かねない"}'::jsonb, NULL, NULL, 'なる -> なりかねない menekankan potensi eskalasi dampak negatif.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('07b17db5-88a0-4321-ace5-845932ca0df3', 'dca41802-7cb1-422a-b3e2-1700bce22561', 'd1000019-0000-0000-0000-000000000026', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mengemudi dalam keadaan mengantuk sangat berbahaya karena bisa menyebabkan kecelakaan fatal."', '{"romaji":"Inemuri unten wa, inochi ni kakawaru daijiko o okoshikanezu taihen kiken desu.","display_text":"居眠り運転は、命に関わる大事故を起こしかねず大変危険です。","phonetic_breakdown":["いねむりうんてんは","いのちにかかわる","だいじこを","おこしかねず","たいへんきけんです"]}'::jsonb, '{"expected_transcript":"居眠り運転は、命に関わる大事故を起こしかねず大変危険です。"}'::jsonb, NULL, NULL, '～かねず adalah bentuk sambung formal dari ～かねない dalam tulisan/peringatan resmi.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1b3bb5ba-5eda-40db-adc2-0e74a4a057fb', 'dca41802-7cb1-422a-b3e2-1700bce22561', 'd1000019-0000-0000-0000-000000000026', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 証拠を確認せずに情報を拡散すると、名誉毀損で訴えられ___。', '{"options":["かねない","つつある","にあたって","の上で"],"translation":"Jika menyebarkan informasi tanpa memverifikasi bukti, bisa saja dituntut atas pencemaran nama baik.","sentence_template":"証拠を確認せずに情報を拡散すると、名誉毀損で訴えられ[blank]。"}'::jsonb, '{"selected":"かねない"}'::jsonb, NULL, NULL, '訴えられる (pasif) -> 訴えられかねない berarti berisiko dituntut secara hukum.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('45655169-41cd-43af-90d1-e3dbdc2450f2', 'dca41802-7cb1-422a-b3e2-1700bce22561', 'd1000019-0000-0000-0000-000000000026', 'listening', 'listening_choice', 'Dengarkan diskusi rapat krisis. Apa kekhawatiran direktur pemasaran?', '{"options":[{"id":"opt_1","text":"Penjualan produk akan melonjak naik besok pagi"},{"id":"opt_2","text":"Pelanggan tidak akan menyadari adanya masalah"},{"id":"opt_3","text":"Media akan memuji perusahaan karena diam saja"},{"id":"opt_4","text":"Jika lalai meminta maaf dan menjelaskan dengan tulus, bisa saja meluas hingga aksi boikot produk"}],"audio_text":"ここで誠実な謝罪と説明を怠れば、不買運動にまで広がりかねないと危惧しています。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '不買運動にまで広がりかねない berarti bisa saja meluas sampai aksi boikot.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4cdcde9a-d8bf-4003-a32b-71d61cb53498', 'dca41802-7cb1-422a-b3e2-1700bce22561', 'd1000019-0000-0000-0000-000000000026', 'writing', 'sentence_builder', 'Susun kalimat: "Jika pemeliharaan jembatan diabaikan, keselamatan warga bisa saja terancam."', '{"romaji":"Hashi no tenken o okotaru to, shimin no anzen ga obiyakasarekanenai.","tokens":["怠ると、","脅かされ","ない。","に限らず、","橋の点検を","市民の安全が","かね","脅かした"],"target_translation":"Jika pemeliharaan jembatan diabaikan, keselamatan warga bisa saja terancam."}'::jsonb, '["橋の点検を","怠ると、","市民の安全が","脅かされ","かね","ない。"]'::jsonb, NULL, NULL, '脅かされる (terancam) -> 脅かされかねない.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('df57acbd-cc47-4c61-bba1-b4c18cf08a34', 'dca41802-7cb1-422a-b3e2-1700bce22561', 'd1000019-0000-0000-0000-000000000026', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika kita tidak segera memperbaiki bug ini, layanan bisa saja berhenti total."', '{"romaji":"Kono fuguai o soukyuu ni shuusei shinai to, saabisu zentai ga teishi shikanemasen.","display_text":"この不具合を早急に修正しないと、サービス全体が停止しかねません。","phonetic_breakdown":["このふぐあいを","そうきゅうに","しゅうせいしないと","さーびすぜんたいが","ていししかねません"]}'::jsonb, '{"expected_transcript":"この不具合を早急に修正しないと、サービス全体が停止しかねません。"}'::jsonb, NULL, NULL, '停止しかねません memperingatkan risiko downtime total dalam operasional IT.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5a331e5-fdff-48f2-85a3-eb6e31e3a15e', 'de5d0aa0-5c51-4c00-9a22-55b3575e3778', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan berikut. Apa tujuan dari panduan yang dibuat?', '{"options":[{"id":"opt_1","text":"Memandu seluruh karyawan mengoperasikan sistem baru"},{"id":"opt_2","text":"Mengumumkan penutupan sementara kantor pusat"},{"id":"opt_3","text":"Menawarkan pelatihan bahasa asing secara sukarela"},{"id":"opt_4","text":"Mengganti seluruh komputer kantor pada akhir tahun"}],"audio_text":"新システムの導入にあたり、全社員向けの操作マニュアルを作成しました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '導入にあたり (menjelang adopsi sistem baru) diikuti pembuatan 操作マニュアル (panduan pengoperasian).', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5768e429-cef8-4425-9ad7-47ff52b96ae1', 'de5d0aa0-5c51-4c00-9a22-55b3575e3778', NULL, 'listening', 'listening_choice', 'Dengarkan sambutan wisuda berikut. Kapan pembicara menyampaikan pesan ini?', '{"options":[{"id":"opt_1","text":"Saat mendaftar ujian masuk universitas"},{"id":"opt_2","text":"Saat menghadiri wawancara kerja pertama"},{"id":"opt_3","text":"Pada kesempatan upacara kelulusan"},{"id":"opt_4","text":"Ketika menyerahkan laporan praktikum"}],"audio_text":"卒業式にあたり、これまで支えてくださった先生方に深く御礼申し上げます。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '卒業式にあたり berarti ''pada kesempatan upacara kelulusan'', momen positif yang cocok dengan ～にあたり.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3ab7cf05-412d-4007-b0c9-b5f9fd3d3c18', 'de5d0aa0-5c51-4c00-9a22-55b3575e3778', NULL, 'listening', 'listening_choice', 'Dengarkan informasi seminar berikut. Apa yang harus disiapkan peserta?', '{"options":[{"id":"opt_1","text":"Membawa paspor asli ke ruang seminar"},{"id":"opt_2","text":"Membayar biaya pendaftaran di lokasi acara"},{"id":"opt_3","text":"Mengikuti tes wawancara sebelum masuk"},{"id":"opt_4","text":"Melakukan registrasi daring dan menyerahkan materi presentasi"}],"audio_text":"国際会議への参加にあたっては、事前のオンライン登録と発表資料の提出が必要です。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '事前のオンライン登録 (registrasi daring sebelumnya) dan 発表資料の提出 (penyerahan materi presentasi) adalah syarat yang disebutkan.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('57724d7b-81e9-4143-a88c-98115ada48c9', 'de5d0aa0-5c51-4c00-9a22-55b3575e3778', NULL, 'reading', 'fill_blank', 'Baca kutipan pengumuman berikut lalu lengkapi: 引っ越しをする___、市役所で転出届を出す必要がある。', '{"options":["にあたって","つつある","わけにはいかず","に伴って"],"translation":"Menjelang pindah rumah, perlu mengajukan surat keterangan pindah di balai kota.","sentence_template":"引っ越しをする[blank]、市役所で転出届を出す必要がある。"}'::jsonb, '{"selected":"にあたって"}'::jsonb, NULL, NULL, 'Pindah rumah adalah peristiwa penting yang memerlukan prosedur resmi, sehingga tepat memakai ～にあたって.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9ee795ee-9975-47d5-ae76-2f1b17d14595', 'de5d0aa0-5c51-4c00-9a22-55b3575e3778', NULL, 'reading', 'fill_blank', 'Lengkapi teks memo internal: 来月の監査を___にあたり、各部署で書類の整理を進めてください。', '{"options":["迎える","迎えた","迎えて","迎えない"],"translation":"Menjelang menghadapi audit bulan depan, mohon tiap departemen melanjutkan perapian dokumen.","sentence_template":"来月の監査を[blank]にあたり、各部署で書類の整理を進めてください。"}'::jsonb, '{"selected":"迎える"}'::jsonb, NULL, NULL, 'Di depan にあたり, kata kerja selalu memakai bentuk kamus (迎える).', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('86a49a43-a3cd-46c4-83de-9c02f62e9ad8', 'de5d0aa0-5c51-4c00-9a22-55b3575e3778', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pada kesempatan pembukaan seminar hari ini, kami ucapkan selamat datang."', '{"romaji":"Honjitsu no seminaa kaikai ni atari, minasama o kokoro yori kangei itashimasu.","display_text":"本日のセミナー開会にあたり、皆様を心より歓迎いたします。","phonetic_breakdown":["ほんじつの","せみなー","かいかいに","あたり","みなさまを","こころより","かんげいいたします"]}'::jsonb, '{"expected_transcript":"本日のセミナー開会にあたり、皆様を心より歓迎いたします。"}'::jsonb, NULL, NULL, '歓迎いたします adalah bentuk kenjougo sopan untuk menyambut tamu atau peserta seminar.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2d6caf68-f92c-4a83-b007-b81d6aecd9a1', 'de5d0aa0-5c51-4c00-9a22-55b3575e3778', 'd1000019-0000-0000-0000-000000000018', 'writing', 'sentence_builder', 'Susun kalimat: "Menjelang dimulainya penelitian bersama, kedua universitas menandatangani nota kesepahaman."', '{"romaji":"Kyoudou kenkyuu no kaishi ni atari, ryoudaigaku wa oboegaki o kawashita.","tokens":["開始","両大学は","交わした。","に限らず、","共同研究の","にあたり、","覚書を","交わす"],"target_translation":"Menjelang dimulainya penelitian bersama, kedua universitas menandatangani nota kesepahaman."}'::jsonb, '["共同研究の","開始","にあたり、","両大学は","覚書を","交わした。"]'::jsonb, NULL, NULL, '覚書を交わす (menandatangani/bertukar nota kesepahaman) adalah kolokasi formal N2.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0432ad30-344d-4f74-8afb-a3fb22be2a18', 'de5d0aa0-5c51-4c00-9a22-55b3575e3778', 'd1000019-0000-0000-0000-000000000018', 'listening', 'listening_choice', 'Dengarkan pesan pembawa acara. Apa tujuan utama pertemuan hari ini?', '{"options":[{"id":"opt_1","text":"Merayakan selesainya pembangunan pabrik"},{"id":"opt_2","text":"Merekrut pekerja konstruksi dari luar kota"},{"id":"opt_3","text":"Menjelaskan rencana konstruksi pabrik baru kepada warga sekitar"},{"id":"opt_4","text":"Mengumumkan penutupan jalan tol nasional"}],"audio_text":"本日は新工場の建設にあたり、近隣住民の皆様へ工事計画をご説明いたします。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '近隣住民 (warga sekitar) dan 工事計画をご説明いたします menjelaskan rencana proyek konstruksi.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f84571c3-47ed-46dd-bc51-a0f776aa630f', 'e3ed43b0-b89e-4e52-b996-787bef0ecb92', 'd1000019-0000-0000-0000-000000000024', 'reading', 'fill_blank', 'Pilih bentuk verba yang tepat untuk makna ''setelah melakukan A, lalu B'': リスクを十分に___上で、投資の判断を下すべきだ。', '{"options":["把握した","把握する","把握して","把握しない"],"translation":"Sebaiknya mengambil keputusan investasi setelah memahami risikonya secara menyeluruh.","sentence_template":"リスクを十分に[blank]上で、投資の判断を下すべきだ。"}'::jsonb, '{"selected":"把握した"}'::jsonb, NULL, NULL, 'Untuk menyatakan urutan ''setelah menyelesaikan A baru melakukan B'', gunakan V-た + 上で.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('03936899-225c-4a11-b202-577929ff5433', 'e3ed43b0-b89e-4e52-b996-787bef0ecb92', 'd1000019-0000-0000-0000-000000000024', 'reading', 'fill_blank', 'Pilih bentuk verba untuk makna ''dalam hal / saat menjalankan'': プロジェクトを___上で、チーム間の情報共有が最も大切だ。', '{"options":["進める","進めた","進めて","進めない"],"translation":"Dalam menjalankan proyek, berbagi informasi antartim adalah hal yang paling penting.","sentence_template":"プロジェクトを[blank]上で、チーム間の情報共有が最も大切だ。"}'::jsonb, '{"selected":"進める"}'::jsonb, NULL, NULL, 'Untuk menyatakan ruang lingkup ''dalam hal melakukan...'', gunakan V-dict (進める) + 上で.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9700bddf-092e-44a4-9d69-298b11ccb177', 'e3ed43b0-b89e-4e52-b996-787bef0ecb92', 'd1000019-0000-0000-0000-000000000024', 'reading', 'fill_blank', 'Lengkapi sambungan kata benda berikut: 健康管理___上で、規則正しい睡眠は基本中の基本だ。', '{"options":["の","な","に","を"],"translation":"Dalam hal pengelolaan kesehatan, tidur yang teratur adalah dasar dari segala dasar.","sentence_template":"健康管理[blank]上で、規則正しい睡眠は基本中の基本だ。"}'::jsonb, '{"selected":"の"}'::jsonb, NULL, NULL, 'Kata benda selalu disambungkan dengan partikel の sebelum 上で (健康管理の上で).', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a60e11cf-4e88-4fad-b8bb-c69684ab0142', 'e3ed43b0-b89e-4e52-b996-787bef0ecb92', 'd1000019-0000-0000-0000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat: "Setelah membaca petunjuk dengan teliti, silakan mulai tesnya."', '{"romaji":"Setsumeisho o yoku yonda ue de, tesuto o hajimete kudasai.","tokens":["始めてください。","説明書を","上で、","読んだ","読む","よく","に限らず、","テストを"],"target_translation":"Setelah membaca petunjuk dengan teliti, silakan mulai tesnya."}'::jsonb, '["説明書を","よく","読んだ","上で、","テストを","始めてください。"]'::jsonb, NULL, NULL, '読んだ上で menekankan bahwa membaca petunjuk adalah prasyarat sebelum memulai tes.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('659b3ab9-73a8-4c5e-b7fd-daa039ec8615', 'e3ed43b0-b89e-4e52-b996-787bef0ecb92', 'd1000019-0000-0000-0000-000000000024', 'writing', 'sentence_builder', 'Susun kalimat: "Dalam bekerja di Jepang, pemahaman etika bisnis sangatlah berguna."', '{"romaji":"Nihon de hataraku ue de, bijinesu manaa no chishiki ga yakudatsu.","tokens":["日本で","働く","上で、","役立つ。","ビジネスマナーの","にもかかわらず、","働いた","知識が"],"target_translation":"Dalam bekerja di Jepang, pemahaman etika bisnis sangatlah berguna."}'::jsonb, '["日本で","働く","上で、","ビジネスマナーの","知識が","役立つ。"]'::jsonb, NULL, NULL, '働く上で (dalam hal bekerja) memakai bentuk kamus.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f90ab5a3-5d76-42f2-add1-b6bb1bc96d41', 'e3ed43b0-b89e-4e52-b996-787bef0ecb92', 'd1000019-0000-0000-0000-000000000024', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah memeriksa rincian biaya, kami akan mengirimkan surat penawaran resmi."', '{"romaji":"Hiyou no shousai o kakunin shita ue de, seishikina omitsumorisho o ookuri shimasu.","display_text":"費用の詳細を確認した上で、正式なお見積書をお送りします。","phonetic_breakdown":["ひようの","しょうさいを","かくにんした","うえで","せいしきな","おみつもりしょを","おおくりします"]}'::jsonb, '{"expected_transcript":"費用の詳細を確認した上で、正式なお見積書をお送りします。"}'::jsonb, NULL, NULL, '見積書 (mitsumorisho) berarti surat penawaran harga/estimasi biaya dalam bisnis Jepang.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('739e3f4d-a05a-41b8-915b-7532cc8699d7', 'e3ed43b0-b89e-4e52-b996-787bef0ecb92', 'd1000019-0000-0000-0000-000000000024', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa urutan tindakan yang benar?', '{"options":[{"id":"opt_1","text":"Memeriksakan diri ke dokter dulu, baru menentukan menu olahraga yang sesuai"},{"id":"opt_2","text":"Langsung berolahraga berat tanpa berkonsultasi ke dokter"},{"id":"opt_3","text":"Berhenti berolahraga selamanya setelah bertemu dokter"},{"id":"opt_4","text":"Membuat menu olahraga dulu baru mencari dokter"}],"audio_text":"医師の診断を受けた上で、適切な運動メニューを決めることにした。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '診断を受けた上で menyatakan pemeriksaan dokter dilakukan terlebih dahulu.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5834f155-934a-41f7-92c0-20d700cd2d6e', 'e3ed43b0-b89e-4e52-b996-787bef0ecb92', 'd1000019-0000-0000-0000-000000000024', 'reading', 'fill_blank', 'Lengkapi kalimat dengan kata benda + の上で: 業務遂行___、何か問題があればすぐに報告してください。', '{"options":["の上で","にあたって","に伴って","に限らず"],"translation":"Dalam hal pelaksanaan tugas kerja, jika ada masalah apa pun mohon segera laporkan.","sentence_template":"業務遂行[blank]、何か問題があればすぐに報告してください。"}'::jsonb, '{"selected":"の上で"}'::jsonb, NULL, NULL, 'Kata benda (業務遂行) tersambung dengan の上で untuk makna ''dalam pelaksanaan...''.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9cfd4dcf-2275-42e9-9041-1e5e06b5ad96', 'e53f7f03-8128-46d4-a27a-0ef2902931f0', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk berita ekonomi: 原材料費の高騰により、食品の___が上昇している。', '{"options":["物価","挨拶","契約","礼儀"],"translation":"Akibat lonjakan biaya bahan baku, harga bahan pangan sedang meningkat.","sentence_template":"原材料費の高騰により、食品の[blank]が上昇している。"}'::jsonb, '{"selected":"物価"}'::jsonb, NULL, NULL, '物価 (bukka) berarti tingkat harga barang-barang kebutuhan secara umum.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3c198561-34ac-4489-aa67-12601a4c0fae', 'e53f7f03-8128-46d4-a27a-0ef2902931f0', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tentang teknologi: スマートフォンの___により、オンライン決済が一般的になった。', '{"options":["普及","延期","欠席","妥協"],"translation":"Berkat meluasnya penggunaan ponsel pintar, pembayaran daring menjadi hal yang umum.","sentence_template":"スマートフォンの[blank]により、オンライン決済が一般的になった。"}'::jsonb, '{"selected":"普及"}'::jsonb, NULL, NULL, '普及 (fukyuu) berarti penyebaran luas suatu teknologi atau kebiasaan di masyarakat.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0a116c5b-d9c2-4024-bcfb-3fdfc52849f3', 'e53f7f03-8128-46d4-a27a-0ef2902931f0', NULL, 'reading', 'fill_blank', 'Pilih istilah demografi yang tepat: 日本では___が進み、労働力不足が深刻化している。', '{"options":["少子高齢化","国際交流","観光開発","語学学習"],"translation":"Di Jepang, penurunan angka kelahiran dan penuaan penduduk terus berlanjut sehingga kekurangan tenaga kerja makin serius.","sentence_template":"日本では[blank]が進み、労働力不足が深刻化している。"}'::jsonb, '{"selected":"少子高齢化"}'::jsonb, NULL, NULL, '少子高齢化 (shoushi koureika) adalah istilah berita N2 yang sangat sering muncul.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('26ee97fe-326d-4cbf-9cf1-223f24a4efc6', 'e53f7f03-8128-46d4-a27a-0ef2902931f0', NULL, 'listening', 'listening_choice', 'Dengarkan cuplikan berita berikut. Apa yang sedang meningkat?', '{"options":[{"id":"opt_1","text":"Jumlah anak muda yang pindah ke daerah"},{"id":"opt_2","text":"Harga tiket kereta cepat antarkota"},{"id":"opt_3","text":"Jumlah kantor baru di pusat kota Tokyo"},{"id":"opt_4","text":"Jam kerja lembur di perusahaan manufaktur"}],"audio_text":"リモートワークの普及に伴って、地方へ移住する若者が増加しています。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '地方へ移住する若者が増加 (anak muda yang pindah ke daerah meningkat) terjadi seiring meluasnya kerja jarak jauh.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bceb244f-5a04-4e66-a02b-4acb1eb4be1b', 'e53f7f03-8128-46d4-a27a-0ef2902931f0', NULL, 'listening', 'listening_choice', 'Dengarkan laporan pasar berikut. Mengapa permintaan energi meningkat?', '{"options":[{"id":"opt_1","text":"Karena musim dingin berlangsung lebih lama"},{"id":"opt_2","text":"Karena ekspansi pusat data"},{"id":"opt_3","text":"Karena tarif listrik diturunkan setengahnya"},{"id":"opt_4","text":"Karena pabrik mobil listrik baru dibuka"}],"audio_text":"データセンターの拡大に伴い、電力の需要が急激に高まっています。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'データセンターの拡大 (ekspansi pusat data) menyebabkan 電力の需要 (permintaan listrik) melonjak.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6be4f576-92cc-453d-b62f-2209a4382780', 'e53f7f03-8128-46d4-a27a-0ef2902931f0', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring perkembangan teknologi, cara kita bekerja pun berubah drastis."', '{"romaji":"Gijutsu no hatten ni tomonatte, watashitachi no hatarakikata mo ookiku kawarimashita.","display_text":"技術の発展に伴って、私たちの働き方も大きく変わりました。","phonetic_breakdown":["ぎじゅつの","はってんに","ともなって","わたしたちの","はたらきかたも","おおきく","かわりました"]}'::jsonb, '{"expected_transcript":"技術の発展に伴って、私たちの働き方も大きく変わりました。"}'::jsonb, NULL, NULL, '発展 (hatten) berarti perkembangan; 働き方 (hatarakikata) berarti cara/gaya bekerja.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('292053c4-d03e-46ba-afb7-c6a1fb0b255a', 'e53f7f03-8128-46d4-a27a-0ef2902931f0', 'd1000019-0000-0000-0000-000000000019', 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 都市部への人口___に伴い、住宅価格の高騰が続いている。', '{"options":["集中","分散","解散","撤収"],"translation":"Seiring dengan terkonsentrasinya populasi ke wilayah perkotaan, lonjakan harga rumah terus berlanjut.","sentence_template":"都市部への人口[blank]に伴い、住宅価格の高騰が続いている。"}'::jsonb, '{"selected":"集中"}'::jsonb, NULL, NULL, '人口集中 (konsentrasi penduduk) adalah istilah demografi penting di JLPT N2.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d01cd170-d8cb-41d6-bb79-de5de85da306', 'e53f7f03-8128-46d4-a27a-0ef2902931f0', 'd1000019-0000-0000-0000-000000000019', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Seiring dengan kemajuan teknologi medis, angka harapan hidup rata-rata meningkat."', '{"romaji":"Iryou gijutsu no shinpo ni tomonatte, heikin jumyou ga nobite imasu.","display_text":"医療技術の進歩に伴って、平均寿命が延びています。","phonetic_breakdown":["いりょうぎじゅつの","しんぽに","ともなって","へいきんじゅみょうが","のびています"]}'::jsonb, '{"expected_transcript":"医療技術の進歩に伴って、平均寿命が延びています。"}'::jsonb, NULL, NULL, '平均寿命が延びる (angka harapan hidup meningkat) adalah kolokasi berita yang akurat.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('256cbce3-fabb-42d4-8f01-17d75566f0d7', 'e679c1a4-d25c-4729-94bd-42493344bcab', 'd1000019-0000-0000-0000-000000000018', 'reading', 'fill_blank', 'Pilih kalimat yang tepat secara tata bahasa N2: 新規事業を立ち上げる___、十分な資金計画が不可欠だ。', '{"options":["にあたって","に伴いながら","ざるを得ない","わけにはいかない"],"translation":"Menjelang merintis bisnis baru, rencana pendanaan yang memadai sangatlah mutlak diperlukan.","sentence_template":"新規事業を立ち上げる[blank]、十分な資金計画が不可欠だ。"}'::jsonb, '{"selected":"にあたって"}'::jsonb, NULL, NULL, '立ち上げる (merintis/meluncurkan) + にあたって menyatakan momen awal penting yang butuh persiapan.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('33234bf7-0da3-42fb-a218-32f5901c025a', 'e679c1a4-d25c-4729-94bd-42493344bcab', 'd1000019-0000-0000-0000-000000000018', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 調査報告書を作成する___、データの正確性を何度も検証した。', '{"options":["にあたり","かねなく","つつあり","にもかかわらず"],"translation":"Dalam rangka menyusun laporan hasil survei, kami memverifikasi keakuratan data berkali-kali.","sentence_template":"調査報告書を作成する[blank]、データの正確性を何度も検証した。"}'::jsonb, '{"selected":"にあたり"}'::jsonb, NULL, NULL, '～にあたり dapat diikuti tindakan persiapan teliti seperti 検証した (memverifikasi).', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fc7dd027-46e6-4c18-9ae4-f1d6f16df27a', 'e679c1a4-d25c-4729-94bd-42493344bcab', 'd1000019-0000-0000-0000-000000000018', 'listening', 'listening_choice', 'Dengarkan pernyataan manajer proyek berikut. Apa prioritas utama sebelum proyek dimulai?', '{"options":[{"id":"opt_1","text":"Memperjelas sistem komunikasi di dalam tim"},{"id":"opt_2","text":"Mengurangi jumlah anggota tim secara bertahap"},{"id":"opt_3","text":"Memindahkan kantor proyek ke kota lain"},{"id":"opt_4","text":"Membatalkan rapat mingguan selama sebulan"}],"audio_text":"大型プロジェクトの開始にあたり、まずはチーム内の連絡体制を明確にしておきたい。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '連絡体制を明確にする berarti memperjelas alur/sistem komunikasi internal tim.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6c2344fb-e2da-4b9a-80ae-2d5d320f6fb8', 'e679c1a4-d25c-4729-94bd-42493344bcab', 'd1000019-0000-0000-0000-000000000018', 'listening', 'listening_choice', 'Dengarkan pesan rektor berikut. Kepada siapa pesan ini ditujukan?', '{"options":[{"id":"opt_1","text":"Para alumni yang telah bekerja sepuluh tahun"},{"id":"opt_2","text":"Para mahasiswa baru pada upacara penerimaan"},{"id":"opt_3","text":"Para staf administrasi perpustakaan kampus"},{"id":"opt_4","text":"Para tamu undangan dari pemerintah daerah"}],"audio_text":"入学式にあたり、新入生の皆さんが充実した大学生活を送られることを願っております。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '入学式にあたり (pada kesempatan upacara masuk) dan 新入生の皆さん (para mahasiswa baru) adalah petunjuk utamanya.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6031447e-40ac-48ac-bb90-ecb704521b8f', 'e679c1a4-d25c-4729-94bd-42493344bcab', 'd1000019-0000-0000-0000-000000000018', 'writing', 'sentence_builder', 'Susun kalimat: "Menjelang penerbitan buku, penulis memeriksa seluruh naskah."', '{"romaji":"Shoseki no shuppan ni atari, chosha wa zengenkou o kakunin shita.","tokens":["著者は","出版","にあたり、","書籍の","全原稿を","出版して","かねない。","確認した。"],"target_translation":"Menjelang penerbitan buku, penulis memeriksa seluruh naskah."}'::jsonb, '["書籍の","出版","にあたり、","著者は","全原稿を","確認した。"]'::jsonb, NULL, NULL, '原稿 (genkou) adalah naskah; 出版にあたり berarti menjelang/dalam rangka penerbitan.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f2167d4c-939a-4af6-851e-4d9fabb66226', 'e679c1a4-d25c-4729-94bd-42493344bcab', 'd1000019-0000-0000-0000-000000000018', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dalam rangka memulai kerja sama baru, mohon bimbingan dan dukungannya."', '{"romaji":"Aratana torihiki no kaishi ni atari, kongo tomo yoroshiku onegai moushiagemasu.","display_text":"新たな取引の開始にあたり、今後ともよろしくお願い申し上げます。","phonetic_breakdown":["あらたな","とりひきの","かいしに","あたり","こんごとも","よろしくおねがい","もうしあげます"]}'::jsonb, '{"expected_transcript":"新たな取引の開始にあたり、今後ともよろしくお願い申し上げます。"}'::jsonb, NULL, NULL, '取引 (torihiki) adalah transaksi/hubungan bisnis; よろしくお願い申し上げます adalah penutup bisnis paling sopan.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('427ea193-24d3-4b05-bdfa-c769b05a13fd', 'e679c1a4-d25c-4729-94bd-42493344bcab', 'd1000019-0000-0000-0000-000000000018', 'listening', 'listening_choice', 'Dengarkan pengumuman resmi berikut. Tindakan apa yang dilakukan perusahaan?', '{"options":[{"id":"opt_1","text":"Menarik saham dari bursa efek"},{"id":"opt_2","text":"Mengurangi publikasi laporan keuangan tahunan"},{"id":"opt_3","text":"Menunda audit internal selama dua tahun"},{"id":"opt_4","text":"Memperkuat sistem audit dan meningkatkan transparansi keterbukaan informasi"}],"audio_text":"上場にあたり、監査体制の強化と情報開示の透明性向上を図ってまいります。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '上場にあたり berarti menjelang pencatatan saham di bursa (IPO).', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ddbdc9fb-c90e-402a-8afc-c3bc27c050ad', 'e679c1a4-d25c-4729-94bd-42493344bcab', 'd1000019-0000-0000-0000-000000000018', 'writing', 'sentence_builder', 'Susun kalimat: "Dalam rangka menerbitkan majalah baru, tim redaksi menyusun konsep awal."', '{"romaji":"Shin zasshi o soukan suru ni atari, henshuubu wa konseputo o neriageta.","tokens":["創刊する","編集部は","練り上げた。","にもかかわらず、","新雑誌を","にあたり、","コンセプトを","創刊した"],"target_translation":"Dalam rangka menerbitkan majalah baru, tim redaksi menyusun konsep awal."}'::jsonb, '["新雑誌を","創刊する","にあたり、","編集部は","コンセプトを","練り上げた。"]'::jsonb, NULL, NULL, '創刊する (menerbitkan edisi perdana) + にあたり memakai verba bentuk kamus.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1147f7ae-cad0-4a85-9b7d-913cfb406914', 'e67e6a9e-32ba-48a2-b417-d46680a077ce', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 台風の接近により、屋外イベントは___になった。', '{"options":["中止","開会","普及","歓迎"],"translation":"Akibat mendekatnya topan, acara luar ruangan dibatalkan.","sentence_template":"台風の接近により、屋外イベントは[blank]になった。"}'::jsonb, '{"selected":"中止"}'::jsonb, NULL, NULL, '中止 (chuushi) berarti pembatalan suatu kegiatan atau proyek.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a0dcd7fc-6301-4f3a-950d-eccfac695562', 'e67e6a9e-32ba-48a2-b417-d46680a077ce', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat bisnis berikut: 業績の悪化を受け、海外市場からの___を検討している。', '{"options":["撤退","設立","採用","進学"],"translation":"Menyikapi memburuknya kinerja bisnis, kami mempertimbangkan penarikan diri dari pasar luar negeri.","sentence_template":"業績の悪化を受け、海外市場からの[blank]を検討している。"}'::jsonb, '{"selected":"撤退"}'::jsonb, NULL, NULL, '撤退 (tettai) berarti penarikan diri dari pasar, proyek, atau wilayah usaha.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e76c2778-3c80-4b77-a75b-643fee7aada2', 'e67e6a9e-32ba-48a2-b417-d46680a077ce', NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: 限られた___の中で、最も効果的な対策を選ぶ必要がある。', '{"options":["予算","挨拶","世代","気候"],"translation":"Di dalam anggaran yang terbatas, kita perlu memilih langkah penanggulangan yang paling efektif.","sentence_template":"限られた[blank]の中で、最も効果的な対策を選ぶ必要がある。"}'::jsonb, '{"selected":"予算"}'::jsonb, NULL, NULL, '予算 (yosan) berarti anggaran biaya.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dc4e0086-b9f8-4ce0-92ce-e827fb4e0a3f', 'e67e6a9e-32ba-48a2-b417-d46680a077ce', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan berikut. Keputusan apa yang terpaksa diambil?', '{"options":[{"id":"opt_1","text":"Terpaksa menunda peluncuran produk baru"},{"id":"opt_2","text":"Mempercepat jadwal peluncuran produk baru"},{"id":"opt_3","text":"Menurunkan harga jual produk secara drastis"},{"id":"opt_4","text":"Membuka pabrik baru di luar negeri bulan ini"}],"audio_text":"部品の供給が大幅に遅れているため、新製品の発売を延期せざるを得なくなりました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '発売を延期せざるを得ない berarti terpaksa harus menunda peluncuran.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('00cb1cf8-e083-4bbb-ad8e-5860b671d502', 'e67e6a9e-32ba-48a2-b417-d46680a077ce', NULL, 'listening', 'listening_choice', 'Dengarkan laporan rapat berikut. Mengapa rencana proyek harus ditinjau ulang?', '{"options":[{"id":"opt_1","text":"Karena jumlah staf melebihi kapasitas kantor"},{"id":"opt_2","text":"Karena biaya membengkak jauh melampaui perkiraan"},{"id":"opt_3","text":"Karena klien membatalkan seluruh kerja sama"},{"id":"opt_4","text":"Karena produk sudah terjual habis sebelum rilis"}],"audio_text":"予想以上にコストが膨らんだため、計画の見直しをせざるを得ない状況です。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'コストが膨らむ (biaya membengkak) memaksa dilakukannya 計画の見直し (peninjauan ulang rencana).', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('01cee382-4d09-48d9-b3a0-86bf4019e90f', 'e67e6a9e-32ba-48a2-b417-d46680a077ce', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dalam situasi sulit seperti ini, kami terpaksa mengubah rencana awal."', '{"romaji":"Kono youna kibishii joukyou de wa, tousho no keikaku o henkou sezaru o emasen.","display_text":"このような厳しい状況では、当初の計画を変更せざるを得ません。","phonetic_breakdown":["このような","きびしい","じょうきょうでは","とうしょの","けいかくを","へんこう","せざるをえません"]}'::jsonb, '{"expected_transcript":"このような厳しい状況では、当初の計画を変更せざるを得ません。"}'::jsonb, NULL, NULL, '当初の計画 (rencana awal) dan 変更せざるを得ない (terpaksa mengubah) adalah pasangan khas N2.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f09ef3d2-c8d5-485b-bdf4-9ad89b131a01', 'e67e6a9e-32ba-48a2-b417-d46680a077ce', 'd1000019-0000-0000-0000-000000000022', 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 人手不足が深刻化し、営業時間の___をせざるを得なくなった。', '{"options":["短縮","拡張","開催","祝賀"],"translation":"Kekurangan tenaga kerja makin parah sehingga jam operasional terpaksa dipersingkat.","sentence_template":"人手不足が深刻化し、営業時間の[blank]をせざるを得なくなった。"}'::jsonb, '{"selected":"短縮"}'::jsonb, NULL, NULL, '営業時間の短縮 (pemendekan jam operasional) adalah respons bisnis yang lazim saat kekurangan staf.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0d6a67e1-1b4c-491d-b3b4-15427e6716f4', 'e67e6a9e-32ba-48a2-b417-d46680a077ce', 'd1000019-0000-0000-0000-000000000022', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena kendala teknis yang mendadak, kami terpaksa mengganti jadwal presentasi."', '{"romaji":"Kyuu na gijutsu toraburu ni yori, happyou nittei o henkou sezaru o enaku narimashita.","display_text":"急な技術トラブルにより、発表日程を変更せざるを得なくなりました。","phonetic_breakdown":["きゅうな","ぎじゅつとらぶるにより","はっぴょうにっていを","へんこうせざるを","えなくなりました"]}'::jsonb, '{"expected_transcript":"急な技術トラブルにより、発表日程を変更せざるを得なくなりました。"}'::jsonb, NULL, NULL, '変更せざるを得なくなりました menyampaikan perubahan jadwal yang tidak terhindarkan.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('393c9095-4ea8-4a89-bfdb-d97e6453036b', 'eb728140-5136-42eb-8df5-25d6833502a4', 'd1000019-0000-0000-0000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat: "Karena ini data sebelum rilis, saya tidak boleh menunjukkannya ke pihak luar."', '{"romaji":"Koukai mae no deeta nanode, shagai ni miseru wake ni wa ikanai.","tokens":["データなので、","見せる","いかない。","わけには","にあたって","公開前の","社外に","見せない"],"target_translation":"Karena ini data sebelum rilis, saya tidak boleh menunjukkannya ke pihak luar."}'::jsonb, '["公開前の","データなので、","社外に","見せる","わけには","いかない。"]'::jsonb, NULL, NULL, '社外 (pihak luar perusahaan) vs 社内 (internal perusahaan).', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('793b993d-5518-4d17-ab69-fa0b0469c7b1', 'eb728140-5136-42eb-8df5-25d6833502a4', 'd1000019-0000-0000-0000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat: "Karena orang tua mendukung studi saya, saya tidak boleh malas belajar."', '{"romaji":"Ryoushin ga ryuugaku o ouen shite kurete iru node, namakeru wake ni wa ikanai.","tokens":["わけには","応援してくれているので、","両親が","怠けない","留学を","怠ける","に伴って","いかない。"],"target_translation":"Karena orang tua mendukung studi saya, saya tidak boleh malas belajar."}'::jsonb, '["両親が","留学を","応援してくれているので、","怠ける","わけには","いかない。"]'::jsonb, NULL, NULL, '怠ける (namakeru) berarti bermalas-malasan.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2612805f-09a1-4da9-89f3-745020a098f1', 'eb728140-5136-42eb-8df5-25d6833502a4', 'd1000019-0000-0000-0000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat: "Karena telah membuat kesalahan, mau tidak mau saya harus segera meminta maaf."', '{"romaji":"Misu o shite shimatta node, sugu ni ayamaranai wake ni wa ikanai.","tokens":["謝らない","ミスを","に限らず","謝る","わけには","すぐに","いかない。","してしまったので、"],"target_translation":"Karena telah membuat kesalahan, mau tidak mau saya harus segera meminta maaf."}'::jsonb, '["ミスを","してしまったので、","すぐに","謝らない","わけには","いかない。"]'::jsonb, NULL, NULL, '謝らないわけにはいかない (tidak bisa tidak meminta maaf = wajib meminta maaf).', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('21bb2d9b-89ba-4847-a850-935ac82e01e4', 'eb728140-5136-42eb-8df5-25d6833502a4', 'd1000019-0000-0000-0000-000000000021', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya tidak mungkin menolak permintaan penting dari klien lama."', '{"romaji":"Naganen no otorihikisaki kara no taisetsuna goirai o kotowaru wake ni wa ikimasen.","display_text":"長年のお取引先からの大切なご依頼を断るわけにはいきません。","phonetic_breakdown":["ながねんの","おとりひきさきからの","たいせつな","ごいらいを","ことわる","わけには","いきません"]}'::jsonb, '{"expected_transcript":"長年のお取引先からの大切なご依頼を断るわけにはいきません。"}'::jsonb, NULL, NULL, 'ご依頼を断る berarti menolak permintaan/pesanan dari klien.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d1f583d6-8c19-43dd-aff8-d02fcb2fac1b', 'eb728140-5136-42eb-8df5-25d6833502a4', 'd1000019-0000-0000-0000-000000000021', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun sangat lelah, saya tidak bisa membiarkan laporan ini belum selesai."', '{"romaji":"Ikura tsukarete ite mo, kono houkokusho o houtte oku wake ni wa ikimasen.","display_text":"いくら疲れていても、この報告書を放っておくわけにはいきません。","phonetic_breakdown":["いくら","つかれていても","このほうこくしょを","ほうっておく","わけには","いきません"]}'::jsonb, '{"expected_transcript":"いくら疲れていても、この報告書を放っておくわけにはいきません。"}'::jsonb, NULL, NULL, '放っておく (houtte oku) berarti membiarkan begitu saja tanpa diurus.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b27557ca-ca26-4228-9283-e0fe5e216596', 'eb728140-5136-42eb-8df5-25d6833502a4', 'd1000019-0000-0000-0000-000000000021', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena sudah dipilih sebagai perwakilan tim, saya harus memberikan yang terbaik."', '{"romaji":"Chiimu no daihyou ni erabareta kara ni wa, zenryoku o tsukusanai wake ni wa ikimasen.","display_text":"チームの代表に選ばれたからには、全力を尽くさないわけにはいきません。","phonetic_breakdown":["ちーむの","だいひょうに","えらばれたからには","ぜんりょくを","つくさない","わけにはいきません"]}'::jsonb, '{"expected_transcript":"チームの代表に選ばれたからには、全力を尽くさないわけにはいきません。"}'::jsonb, NULL, NULL, '全力を尽くす (mengerahkan segenap tenaga) + ないわけにはいきません.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eac42e1e-434e-4ef7-a370-e0319521e21d', 'eb728140-5136-42eb-8df5-25d6833502a4', 'd1000019-0000-0000-0000-000000000021', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 借りた本に書き込みをする___。', '{"options":["わけにはいかない","ざるを得ない","に限らず","の上で"],"translation":"Tidak mungkin boleh menulis coretan di buku yang dipinjam.","sentence_template":"借りた本に書き込みをする[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, NULL, NULL, '書き込みをするわけにはいかない menyatakan larangan etis terhadap barang pinjaman.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cb93877f-f1a3-468f-8241-4c4662479a34', 'eb728140-5136-42eb-8df5-25d6833502a4', 'd1000019-0000-0000-0000-000000000021', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sebagai anggota tim, saya tidak bisa hanya berpangku tangan melihat rekan kesulitan."', '{"romaji":"Chiimu no ichiin toshite, nakama no kurou o damatte mite iru wake ni wa ikimasen.","display_text":"チームの一員として、仲間の苦労を黙って見ているわけにはいきません。","phonetic_breakdown":["ちーむの","いちいんとして","なかまのくろうを","だまってみている","わけにはいきません"]}'::jsonb, '{"expected_transcript":"チームの一員として、仲間の苦労を黙って見ているわけにはいきません。"}'::jsonb, NULL, NULL, '黙って見ているわけにはいきません berarti tidak bisa hanya diam menonton.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d34c7938-47d2-4968-a628-7a3d2693b342', 'ee581059-1a76-44dd-b3a5-2e96a3ec842b', NULL, 'listening', 'listening_choice', 'Dengarkan komentar analis ekonomi berikut. Risiko apa yang ia soroti?', '{"options":[{"id":"opt_1","text":"Kenaikan suku bunga cepat bisa saja menekan keuangan usaha kecil dan menengah"},{"id":"opt_2","text":"Usaha kecil dan menengah akan memperoleh keuntungan berlipat"},{"id":"opt_3","text":"Bank sentral akan menurunkan suku bunga hingga nol persen"},{"id":"opt_4","text":"Ekspor produk pertanian akan meningkat tajam bulan depan"}],"audio_text":"急速な利上げが続けば、中小企業の経営を圧迫しかねないという懸念が広がっている。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '経営を圧迫しかねない berarti bisa saja menekan/memberatkan operasional bisnis.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('92c33f7d-ef99-433a-9979-b6d35789ab79', 'ee581059-1a76-44dd-b3a5-2e96a3ec842b', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman IT kantor berikut. Mengapa karyawan dilarang membuka tautan mencurigakan?', '{"options":[{"id":"opt_1","text":"Karena ukuran lampiran email terlalu besar untuk kotak masuk"},{"id":"opt_2","text":"Karena komputer hanya perlu dihidupkan ulang sekali sehari"},{"id":"opt_3","text":"Karena seluruh jaringan internal kantor bisa saja terinfeksi virus"},{"id":"opt_4","text":"Karena koneksi internet kantor akan menjadi lebih cepat"}],"audio_text":"不審なメールのリンクを開くと、社内ネットワーク全体がウイルスに感染しかねないからです。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'ウイルスに感染しかねない berarti ''bisa saja terinfeksi virus''.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e0931175-97a3-41f7-af5a-8238cb6ffcbf', 'ee581059-1a76-44dd-b3a5-2e96a3ec842b', NULL, 'listening', 'listening_choice', 'Dengarkan ucapan dosen berikut. Apa yang ia peringatkan kepada mahasiswa?', '{"options":[{"id":"opt_1","text":"Nilai makalah akan otomatis mendapat bonus tambahan"},{"id":"opt_2","text":"Makalah akan langsung diterbitkan di jurnal internasional"},{"id":"opt_3","text":"Jumlah halaman makalah akan berkurang dari batas minimal"},{"id":"opt_4","text":"Tindakan itu bisa saja dianggap sebagai plagiarisme"}],"audio_text":"出典を明記せずに文章を引用すると、盗用とみなされかねないので注意してください。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '盗用 (touyou, plagiarisme) + みなされかねない (bisa saja dianggap sebagai).', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7cc6c160-3d48-473a-8b5d-dbbf20e22afb', 'ee581059-1a76-44dd-b3a5-2e96a3ec842b', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 予算を削りすぎると、製品の品質低下を___かねない。', '{"options":["招き","招く","招いた","招いて"],"translation":"Jika anggaran dipangkas terlalu banyak, hal itu bisa saja mengundang penurunan kualitas produk.","sentence_template":"予算を削りすぎると、製品の品質低下を[blank]かねない。"}'::jsonb, '{"selected":"招き"}'::jsonb, NULL, NULL, '招く (Godan) → 招きかねない.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9952d543-e432-427a-92c1-dd424d60f5d6', 'ee581059-1a76-44dd-b3a5-2e96a3ec842b', NULL, 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 彼は感情的になると、何を言い出すか分からないので、会議で暴言を___かねない。', '{"options":["吐き","吐く","吐いた","吐いて"],"translation":"Karena jika emosional tidak jelas apa yang akan ia katakan, ia bisa saja melontarkan kata-kata kasar di rapat.","sentence_template":"彼は感情的になると、何を言い出すか分からないので、会議で暴言を[blank]かねない。"}'::jsonb, '{"selected":"吐き"}'::jsonb, NULL, NULL, '暴言を吐く (melontarkan kata-kata kasar) → 吐きかねない.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3863b349-0e28-46dd-993a-937bb82d3948', 'ee581059-1a76-44dd-b3a5-2e96a3ec842b', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Keputusan yang tergesa-gesa bisa saja menimbulkan kerugian besar di kemudian hari."', '{"romaji":"Seikyuuna handan wa, ato de ookina sonshitsu o umikanemasen.","display_text":"性急な判断は、後で大きな損失を生みかねません。","phonetic_breakdown":["せいきゅうな","はんだんは","あとで","おおきなそんしつを","うみかねません"]}'::jsonb, '{"expected_transcript":"性急な判断は、後で大きな損失を生みかねません。"}'::jsonb, NULL, NULL, '性急な (tergesa-gesa) dan 損失を生む (menimbulkan kerugian) adalah kosakata bisnis N2.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('db714ed2-ea4b-4cbd-a46f-6b50703d876d', 'ee581059-1a76-44dd-b3a5-2e96a3ec842b', 'd1000019-0000-0000-0000-000000000026', 'writing', 'sentence_builder', 'Susun kalimat: "Jika rumor palsu dibiarkan, reputasi perusahaan bisa saja rusak parah."', '{"romaji":"Ne mo ha mo nai uwasa o houchi suru to, kigyou no hyouban ga kizutsukikanenai.","tokens":["放置すると、","傷つき","ない。","にもかかわらず、","根拠のない噂を","企業の評判が","かね","傷ついた"],"target_translation":"Jika rumor palsu dibiarkan, reputasi perusahaan bisa saja rusak parah."}'::jsonb, '["根拠のない噂を","放置すると、","企業の評判が","傷つき","かね","ない。"]'::jsonb, NULL, NULL, '傷つきかねない mengingatkan potensi rusaknya reputasi.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2b5e3d5d-4b9e-44c5-9cbf-114f2bf2b16c', 'ee581059-1a76-44dd-b3a5-2e96a3ec842b', 'd1000019-0000-0000-0000-000000000026', 'listening', 'listening_choice', 'Dengarkan peringatan pemandu gunung. Mengapa pendaki diminta turun lebih awal?', '{"options":[{"id":"opt_1","text":"Karena jalur pendakian akan segera dipenuhi bunga sakura"},{"id":"opt_2","text":"Karena cuaca mulai berubah mendadak sehingga jika terus mendaki bisa berisiko tersesat/celaka"},{"id":"opt_3","text":"Karena penginapan di puncak gunung sedang diskon besar"},{"id":"opt_4","text":"Karena semua pendaki sudah mencapai puncak"}],"audio_text":"天候が急変し始めていますので、このまま登り続けると遭難しかねません。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '遭難しかねません berarti bisa saja mengalami kecelakaan atau tersesat di gunung.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('90f311c1-ef28-448d-99e6-9cba6f019aca', 'ef7a2d78-3aec-456d-ab5d-d61fcc3946b6', 'd1000019-0000-0000-0000-000000000027', 'reading', 'fill_blank', 'Lengkapi kalimat resepsionis kantor dengan sonkeigo yang tepat: 社長はただいま会議室に___。', '{"options":["いらっしゃいます","おります","まいります","いたします"],"translation":"Direktur utama saat ini sedang berada di ruang rapat.","sentence_template":"社長はただいま会議室に[blank]。"}'::jsonb, '{"selected":"いらっしゃいます"}'::jsonb, NULL, NULL, 'いらっしゃいます adalah sonkeigo (peninggi) dari いる; おります adalah kenjougo (merendahkan diri).', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6abbcbd2-2939-4c14-b2bc-fa4af95ae534', 'ef7a2d78-3aec-456d-ab5d-d61fcc3946b6', 'd1000019-0000-0000-0000-000000000027', 'reading', 'fill_blank', 'Pilih bentuk sonkeigo yang tepat untuk menanyakan apakah klien sudah membaca materi: 先ほどお送りした資料は、すでにご覧___でしょうか。', '{"options":["になりました","いたしました","申しました","伺いました"],"translation":"Apakah Anda sudah sempat melihat materi yang baru saja kami kirimkan?","sentence_template":"先ほどお送りした資料は、すでにご覧[blank]でしょうか。"}'::jsonb, '{"selected":"になりました"}'::jsonb, NULL, NULL, 'ご覧になる adalah bentuk sonkeigo baku untuk 見る (melihat/membaca).', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('51f34417-9c89-440c-ace2-81ebe8d82c81', 'ef7a2d78-3aec-456d-ab5d-d61fcc3946b6', 'd1000019-0000-0000-0000-000000000027', 'listening', 'listening_choice', 'Dengarkan ucapan sekretaris di telepon. Apa yang ia sampaikan mengenai direktur?', '{"options":[{"id":"opt_1","text":"Kepala divisi sudah pensiun minggu lalu"},{"id":"opt_2","text":"Kepala divisi sedang keluar kantor saat ini dan dijadwalkan kembali sekitar pukul tiga"},{"id":"opt_3","text":"Kepala divisi menolak menerima panggilan dari siapa pun"},{"id":"opt_4","text":"Kepala divisi sedang makan siang di kantin lantai satu"}],"audio_text":"あいにく部長はただいま外出しておりまして、三時頃にお戻りになる予定です。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'お戻りになる adalah sonkeigo untuk 戻る; digunakan saat berbicara tentang jadwal kembalinya atasan kepada rekan internal atau sesama staf, atau perhatikan konteks sopan.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3a90d279-4b74-4531-9016-55a76d29cbf6', 'ef7a2d78-3aec-456d-ab5d-d61fcc3946b6', 'd1000019-0000-0000-0000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat: "Apakah Bapak Direktur bersedia menyantap hidangan ini?"', '{"romaji":"Shachou wa kochira no oryouri o meshiagarimasu ka.","tokens":["こちらの","召し上がり","か。","まいります","社長は","お料理を","ます","いただきます"],"target_translation":"Apakah Bapak Direktur bersedia menyantap hidangan ini?"}'::jsonb, '["社長は","こちらの","お料理を","召し上がり","ます","か。"]'::jsonb, NULL, NULL, '召し上がる adalah sonkeigo baku untuk 食べる dan 飲む.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f9fad6ba-3431-46ab-907b-ea9b11cb5ccb', 'ef7a2d78-3aec-456d-ab5d-d61fcc3946b6', 'd1000019-0000-0000-0000-000000000027', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Silakan Anda beristirahat sejenak di ruang tunggu sambil menunggu."', '{"romaji":"Osoreirimasu ga, shoushou kochira de omachi ni natte itadakemasu ka.","display_text":"恐れ入りますが、少々こちらでお待ちになっていただけますか。","phonetic_breakdown":["おそれいりますが","しょうしょうこちらで","おまちになって","いただけますか"]}'::jsonb, '{"expected_transcript":"恐れ入りますが、少々こちらでお待ちになっていただけますか。"}'::jsonb, NULL, NULL, 'お待ちになる (お + V-masu stem + になる) adalah pola sonkeigo standar yang sangat sopan.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('acc963e0-fbeb-415d-a098-76c732209b35', 'ef7a2d78-3aec-456d-ab5d-d61fcc3946b6', 'd1000019-0000-0000-0000-000000000027', 'reading', 'fill_blank', 'Lengkapi kalimat penyambutan tamu: 田中様、本日は遠方よりお越し___、誠にありがとうございます。', '{"options":["くださり","いたし","申し上げ","伺い"],"translation":"Bapak/Ibu Tanaka, terima kasih banyak telah berkenan hadir dari jauh pada hari ini.","sentence_template":"田中様、本日は遠方よりお越し[blank]、誠にありがとうございます。"}'::jsonb, '{"selected":"くださり"}'::jsonb, NULL, NULL, 'お越しくださる adalah bentuk sonkeigo sangat sopan untuk 来てくれる (berkenan datang).', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9310aeca-d9c3-416b-bdd8-85e67ac62da9', 'ef7a2d78-3aec-456d-ab5d-d61fcc3946b6', 'd1000019-0000-0000-0000-000000000027', 'listening', 'listening_choice', 'Dengarkan percakapan di ruang rapat. Apa yang diminta oleh pembicara kepada tamu?', '{"options":[{"id":"opt_1","text":"Meminta tamu segera meninggalkan ruangan"},{"id":"opt_2","text":"Meminta tamu menulis laporan sepuluh halaman"},{"id":"opt_3","text":"Mempersilakan tamu menyampaikan tanpa sungkan jika ada hal yang kurang jelas"},{"id":"opt_4","text":"Meminta tamu mematikan layar presentasi"}],"audio_text":"ご不明な点がございましたら、どうぞ遠慮なくおっしゃってくださいませ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'おっしゃる adalah sonkeigo baku untuk 言う (mengatakan/menyampaikan).', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fd948a9c-f440-4600-81b9-673af01dc28e', 'ef7a2d78-3aec-456d-ab5d-d61fcc3946b6', 'd1000019-0000-0000-0000-000000000027', 'writing', 'sentence_builder', 'Susun kalimat: "Apakah Anda mengetahui jadwal perubahan seminar minggu depan?"', '{"romaji":"Raishuu no seminaa no nittei henkou o gozonji deshou ka.","tokens":["セミナーの","ご存じ","か。","申して","来週の","日程変更を","でしょう","存じて"],"target_translation":"Apakah Anda mengetahui jadwal perubahan seminar minggu depan?"}'::jsonb, '["来週の","セミナーの","日程変更を","ご存じ","でしょう","か。"]'::jsonb, NULL, NULL, 'ご存じです adalah sonkeigo dari 知っている, sedangkan 存じております adalah kenjougo.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('791494bb-6376-4d8d-92c7-f0eb6fd43ed0', 'f064fef6-9159-47b4-9d05-436ea15eedc9', 'd1000019-0000-0000-0000-000000000026', 'writing', 'sentence_builder', 'Susun kalimat: "Jika informasi bocor, perusahaan bisa saja kehilangan kepercayaan klien."', '{"romaji":"Jouhou ga morereba, kokyaku kara no shinrai o ushinaikanenai.","tokens":["つつある。","情報が","漏れれば、","かねない。","顧客からの","失う","失い","信頼を"],"target_translation":"Jika informasi bocor, perusahaan bisa saja kehilangan kepercayaan klien."}'::jsonb, '["情報が","漏れれば、","顧客からの","信頼を","失い","かねない。"]'::jsonb, NULL, NULL, '失う (kehilangan) → 失いかねない.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('20feadfd-866b-4398-a15c-be50a6d942ad', 'f064fef6-9159-47b4-9d05-436ea15eedc9', 'd1000019-0000-0000-0000-000000000026', 'writing', 'sentence_builder', 'Susun kalimat: "Jika aturan keselamatan diabaikan, kecelakaan kerja bisa saja terjadi."', '{"romaji":"Anzen kisoku o keishi sureba, roudou saigai ga hassei shikanenai.","tokens":["軽視すれば、","発生する","しかねない。","労働災害が","にあたって。","安全規則を","発生"],"target_translation":"Jika aturan keselamatan diabaikan, kecelakaan kerja bisa saja terjadi."}'::jsonb, '["安全規則を","軽視すれば、","労働災害が","発生","しかねない。"]'::jsonb, NULL, NULL, '軽視する (meremehkan) dan 労働災害 (kecelakaan kerja).', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7847e000-ebd2-4bee-8191-078f4372f401', 'f064fef6-9159-47b4-9d05-436ea15eedc9', 'd1000019-0000-0000-0000-000000000026', 'writing', 'sentence_builder', 'Susun kalimat: "Kurangnya komunikasi bisa saja menyebabkan keterlambatan seluruh proyek."', '{"romaji":"Renraku busoku wa, purojekuto zentai no chien ni tsunagarikanenai.","tokens":["つながる","つながり","プロジェクト全体の","遅延に","に限らず。","かねない。","連絡不足は、"],"target_translation":"Kurangnya komunikasi bisa saja menyebabkan keterlambatan seluruh proyek."}'::jsonb, '["連絡不足は、","プロジェクト全体の","遅延に","つながり","かねない。"]'::jsonb, NULL, NULL, '～につながりかねない berarti ''bisa saja berujung pada...''.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8baa4d9f-78fd-42f9-b93a-cbac2ff2e537', 'f064fef6-9159-47b4-9d05-436ea15eedc9', 'd1000019-0000-0000-0000-000000000026', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika tidak segera diperbaiki, kerusakan kecil ini bisa saja meluas."', '{"romaji":"Hayame ni shuuri shinai to, kono chiisana koshou ga hirogarikanemasen.","display_text":"早めに修理しないと、この小さな故障が広がりかねません。","phonetic_breakdown":["はやめに","しゅうりしないと","このちいさな","こしょうが","ひろがりかねません"]}'::jsonb, '{"expected_transcript":"早めに修理しないと、この小さな故障が広がりかねません。"}'::jsonb, NULL, NULL, '早めに (lebih awal/segera) + 広がりかねない (bisa saja meluas).', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cf564387-ee42-4984-b4b8-d8b2f1dcbc19', 'f064fef6-9159-47b4-9d05-436ea15eedc9', 'd1000019-0000-0000-0000-000000000026', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pernyataan yang tidak akurat bisa saja memicu kepanikan di pasar."', '{"romaji":"Fuseikakuna happyou wa, shijou no konran o manekikanemasen.","display_text":"不正確な発表は、市場の混乱を招きかねません。","phonetic_breakdown":["ふせいかくな","はっぴょうは","しじょうのこんらんを","まねきかねません"]}'::jsonb, '{"expected_transcript":"不正確な発表は、市場の混乱を招きかねません。"}'::jsonb, NULL, NULL, '市場の混乱 (kekacauan pasar) sering muncul dalam berita ekonomi.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('650c2a38-563b-480f-8d9c-daa44bd3f149', 'f064fef6-9159-47b4-9d05-436ea15eedc9', 'd1000019-0000-0000-0000-000000000026', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika terus menunda keputusan, kita bisa saja kehilangan peluang bisnis terbaik."', '{"romaji":"Ketsudan o sakinobashi ni suru to, zekkou no bijinesu chansu o nogashikanemasen.","display_text":"決断を先延ばしにすると、絶好のビジネスチャンスを逃しかねません。","phonetic_breakdown":["けつだんを","さきのばしにすると","ぜっこうの","びじねすちゃんすを","のがしかねません"]}'::jsonb, '{"expected_transcript":"決断を先延ばしにすると、絶好のビジネスチャンスを逃しかねません。"}'::jsonb, NULL, NULL, 'チャンスを逃す (melewatkan peluang) → 逃しかねない.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9eba8d60-ba22-41d3-93bc-151ae3a795f8', 'f064fef6-9159-47b4-9d05-436ea15eedc9', 'd1000019-0000-0000-0000-000000000026', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 説明不足のまま新ルールを強制すると、現場の反発を招き___。', '{"options":["かねない","に伴って","にあたって","の上で"],"translation":"Jika memaksakan aturan baru tanpa penjelasan cukup, bisa saja memicu penolakan dari lapangan.","sentence_template":"説明不足のまま新ルールを強制すると、現場の反発を招き[blank]。"}'::jsonb, '{"selected":"かねない"}'::jsonb, NULL, NULL, '反発を招きかねない berarti bisa saja mengundang reaksi penolakan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bd9310fc-6748-43dc-bb6a-790451c8f5e6', 'f064fef6-9159-47b4-9d05-436ea15eedc9', 'd1000019-0000-0000-0000-000000000026', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika suhu penyimpanan tidak tepat, bahan makanan bisa saja cepat membusuk."', '{"romaji":"Hozon ondo ga tekisetsu de nai to, shokuzai ga itamikanemasen.","display_text":"保存温度が適切でないと、食材が傷みかねません。","phonetic_breakdown":["ほぞんおんどが","てきせつでないと","しょくざいが","いたみかねません"]}'::jsonb, '{"expected_transcript":"保存温度が適切でないと、食材が傷みかねません。"}'::jsonb, NULL, NULL, '食材が傷む (bahan makanan rusak/busuk) + かねません cocok untuk konteks manajemen kualitas pangan.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bd785669-2bac-4f1b-864f-66572fcca8d7', 'fb5d2f6b-0c3f-4c4b-a3a7-cd7aa2581d2f', NULL, 'listening', 'listening_choice', 'Dengarkan hasil negosiasi berikut. Apa kesimpulan pembicara?', '{"options":[{"id":"opt_1","text":"Menolak seluruh syarat dan membatalkan kontrak"},{"id":"opt_2","text":"Terpaksa berkompromi demi mengejar tenggat waktu"},{"id":"opt_3","text":"Meminta tambahan waktu selama enam bulan"},{"id":"opt_4","text":"Mengganti seluruh anggota tim negosiasi"}],"audio_text":"相手の条件には不満もあるが、納期を考えるとここで妥協せざるを得ない。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '妥協せざるを得ない berarti terpaksa berkompromi meski sebenarnya masih kurang puas.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('374ec0bd-315e-450d-86e6-5e7f535fb2e2', 'fb5d2f6b-0c3f-4c4b-a3a7-cd7aa2581d2f', NULL, 'listening', 'listening_choice', 'Dengarkan berita perusahaan berikut. Langkah apa yang terpaksa dilakukan?', '{"options":[{"id":"opt_1","text":"Membuka sepuluh cabang baru di luar negeri"},{"id":"opt_2","text":"Menaikkan gaji pokok seluruh staf"},{"id":"opt_3","text":"Terpaksa mempertimbangkan penyusutan toko yang merugi"},{"id":"opt_4","text":"Mengubah nama merek perusahaan"}],"audio_text":"売上の減少が続いているため、不採算店舗の縮小を検討せざるを得ない状況だ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '不採算店舗 (toko yang tidak menguntungkan) dan 縮小 (penyusutan/pengurangan).', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f44956dc-45da-44c5-8ce3-f678a18e8da9', 'fb5d2f6b-0c3f-4c4b-a3a7-cd7aa2581d2f', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman kampus berikut. Mengapa kelas dipindahkan ke daring?', '{"options":[{"id":"opt_1","text":"Karena ruang kuliah sedang dipakai ujian masuk"},{"id":"opt_2","text":"Karena dosen sedang dinas ke luar negeri"},{"id":"opt_3","text":"Karena listrik di gedung kuliah padam"},{"id":"opt_4","text":"Karena gangguan transportasi akibat salju lebat diperkirakan terjadi"}],"audio_text":"大雪による交通機関の乱れが予想されるため、午後の講義はオンラインに切り替えざるを得ません。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '切り替える (mengalihkan) → 切り替えざるを得ない (terpaksa mengalihkan ke daring).', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b6da36b6-e0e3-4c52-8448-ddc46caa0282', 'fb5d2f6b-0c3f-4c4b-a3a7-cd7aa2581d2f', NULL, 'reading', 'fill_blank', 'Lengkapi kutipan laporan berikut: これ以上赤字が拡大すれば、事業の継続を___ざるを得なくなる。', '{"options":["断念せ","断念し","断念する","断念した"],"translation":"Jika defisit membesar lebih jauh lagi, kami akan terpaksa membatalkan kelanjutan bisnis ini.","sentence_template":"これ以上赤字が拡大すれば、事業の継続を[blank]ざるを得なくなる。"}'::jsonb, '{"selected":"断念せ"}'::jsonb, NULL, NULL, '断念する (membatalkan/menyerah) berubah menjadi 断念せざるを得なくなる.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('aba0350a-ff8c-4e40-a4d9-0798e4432f76', 'fb5d2f6b-0c3f-4c4b-a3a7-cd7aa2581d2f', NULL, 'reading', 'fill_blank', 'Pilih jawaban yang tepat: 彼の主張には納得できない点もあるが、データを見る限り___ざるを得ない。', '{"options":["同意せ","同意し","同意す","同意する"],"translation":"Meski ada poin yang kurang meyakinkan dalam argumennya, melihat datanya saya terpaksa setuju.","sentence_template":"彼の主張には納得できない点もあるが、データを見る限り[blank]ざるを得ない。"}'::jsonb, '{"selected":"同意せ"}'::jsonb, NULL, NULL, '同意する (setuju) → 同意せざるを得ない.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('46cb8973-dfd8-488d-a3dc-7085fa312199', 'fb5d2f6b-0c3f-4c4b-a3a7-cd7aa2581d2f', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena masalah kesehatan, saya terpaksa mengundurkan diri dari kepanitiaan."', '{"romaji":"Taichou furyou no tame, jikkou iin o jitai sezaru o enaku narimashita.","display_text":"体調不良のため、実行委員を辞退せざるを得なくなりました。","phonetic_breakdown":["たいちょうふりょうの","ため","じっこういいんを","じたい","せざるをえなく","なりました"]}'::jsonb, '{"expected_transcript":"体調不良のため、実行委員を辞退せざるを得なくなりました。"}'::jsonb, NULL, NULL, '辞退する (jitai suru) berarti mengundurkan diri secara sopan dari tawaran atau jabatan.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('92e7b9db-e0dd-4a2f-ab79-9179828ae747', 'fb5d2f6b-0c3f-4c4b-a3a7-cd7aa2581d2f', 'd1000019-0000-0000-0000-000000000022', 'writing', 'sentence_builder', 'Susun kalimat: "Karena kesalahan sistem, transaksi daring terpaksa dihentikan sementara."', '{"romaji":"Shisutemu shoukai ni yori, onrain torihiki o ichiji chuudan sezaru o enakatta.","tokens":["オンライン取引を","せざるを","のです。","に限らず、","システム障害により、","一時中断","得なかった","しざるを"],"target_translation":"Karena kesalahan sistem, transaksi daring terpaksa dihentikan sementara."}'::jsonb, '["システム障害により、","オンライン取引を","一時中断","せざるを","得なかった","のです。"]'::jsonb, NULL, NULL, '一時中断せざるを得なかった berarti terpaksa menghentikan sementara akibat gangguan sistem.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ee3242f4-70e7-4eec-92bf-057a11ce1e15', 'fb5d2f6b-0c3f-4c4b-a3a7-cd7aa2581d2f', 'd1000019-0000-0000-0000-000000000022', 'listening', 'listening_choice', 'Dengarkan laporan cuaca. Keputusan apa yang diambil panitia maraton?', '{"options":[{"id":"opt_1","text":"Lomba tetap dijalankan sesuai jadwal semula"},{"id":"opt_2","text":"Rute lomba diperpanjang dua kali lipat"},{"id":"opt_3","text":"Lomba terpaksa dibatalkan demi mengutamakan keselamatan pelari akibat badai petir"},{"id":"opt_4","text":"Lomba dipindahkan ke dalam gedung olahraga"}],"audio_text":"激しい雷雨が予想されるため、選手の安全を最優先し、大会は中止せざるを得ないとの結論に達しました。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '中止せざるを得ないとの結論に達しました berarti mencapai kesimpulan terpaksa membatalkan acara.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('53a7ed72-e2c0-4dcc-ac17-169e2b010314', 'fd7c7a96-a042-484a-82c1-b9b26bed8115', 'd1000019-0000-0000-0000-000000000021', 'listening', 'listening_choice', 'Dengarkan dialog di rumah sakit. Mengapa dokter tidak bisa meninggalkan ruangan sekarang?', '{"options":[{"id":"opt_1","text":"Dokter sedang menunggu hasil pemeriksaan laboratorium pasien lain"},{"id":"opt_2","text":"Sebagai dokter penanggung jawab, beliau tidak bisa meninggalkan tempat sebelum kondisi pasien stabil"},{"id":"opt_3","text":"Dokter lupa membawa kunci kendaraan pribadi"},{"id":"opt_4","text":"Pintu ruang perawatan sedang rusak"}],"audio_text":"患者さんの容体が安定するまでは、担当医としてこの場を離れるわけにはまいりません。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '～わけにはまいりません adalah bentuk sangat sopan (kenjougo) dari ～わけにはいきません.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8a711b59-f90e-4f37-bf2c-26c1a89b1d88', 'fd7c7a96-a042-484a-82c1-b9b26bed8115', 'd1000019-0000-0000-0000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat: "Sebagai wakil perusahaan, saya tidak mungkin bersikap tidak sopan kepada tamu."', '{"romaji":"Kaisha no daihyou toshite, okyakusama ni shitsurei na taido o toru wake ni wa ikanai.","tokens":["お客様に","取る","いかない。","に限らない。","会社の代表として、","失礼な態度を","わけには","取った"],"target_translation":"Sebagai wakil perusahaan, saya tidak mungkin bersikap tidak sopan kepada tamu."}'::jsonb, '["会社の代表として、","お客様に","失礼な態度を","取る","わけには","いかない。"]'::jsonb, NULL, NULL, '取るわけにはいかない menyatakan larangan kuat karena peran sebagai wakil perusahaan.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0df59df0-953e-4d91-be81-eb1093d59bdc', 'fd7c7a96-a042-484a-82c1-b9b26bed8115', 'd1000019-0000-0000-0000-000000000021', 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: みんなが期待してくれているのに、簡単に引き下がる___。', '{"options":["わけにはいかない","に伴わない","にあたり","かねない"],"translation":"Padahal semua orang menaruh harapan, tidak mungkin saya mundur begitu saja.","sentence_template":"みんなが期待してくれているのに、簡単に引き下がる[blank]。"}'::jsonb, '{"selected":"わけにはいかない"}'::jsonb, NULL, NULL, '簡単に引き下がるわけにはいかない menunjukkan rasa tanggung jawab terhadap ekspektasi tim.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b4744e4f-fa6a-4b99-8512-5df9c817ec75', 'fd7c7a96-a042-484a-82c1-b9b26bed8115', 'd1000019-0000-0000-0000-000000000021', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena ini adalah rahasia perusahaan, saya tidak bisa menceritakannya kepada siapa pun."', '{"romaji":"Kore wa shagaihi desu node, dare ni mo hanasu wake ni wa ikimasen.","display_text":"これは社外秘ですので、誰にも話すわけにはいきません。","phonetic_breakdown":["これは","しゃがいひですので","だれにも","はなす","わけにはいきません"]}'::jsonb, '{"expected_transcript":"これは社外秘ですので、誰にも話すわけにはいきません。"}'::jsonb, NULL, NULL, '社外秘 (rahasia internal perusahaan) berpasangan tepat dengan 話すわけにはいきません.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('27091f31-08a1-4af0-8fae-ce9602b35646', 'fd7c7a96-a042-484a-82c1-b9b26bed8115', 'd1000019-0000-0000-0000-000000000021', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 親友の結婚式なのだから、どんなに忙しくても出席___。', '{"options":["しないわけにはいかない","するわけにはいかない","しかねない","しつつある"],"translation":"Karena ini pernikahan sahabat dekat, sesibuk apa pun mau tidak mau saya harus hadir.","sentence_template":"親友の結婚式なのだから、どんなに忙しくても出席[blank]。"}'::jsonb, '{"selected":"しないわけにはいかない"}'::jsonb, NULL, NULL, '出席しないわけにはいかない menggunakan bentuk negatif + わけにはいかない untuk makna ''harus hadir''.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fc57912a-7798-455f-a8de-fe3a4c2b6268', 'fd7c7a96-a042-484a-82c1-b9b26bed8115', 'd1000019-0000-0000-0000-000000000021', 'listening', 'listening_choice', 'Dengarkan penjelasan manajer operasional. Apa sikap beliau terhadap keluhan pelanggan?', '{"options":[{"id":"opt_1","text":"Mengabaikan keluhan karena bukan kesalahan perusahaan"},{"id":"opt_2","text":"Menunda perbaikan hingga pergantian tahun"},{"id":"opt_3","text":"Menyerahkan seluruh keluhan kepada perusahaan lain"},{"id":"opt_4","text":"Merasa wajib segera mengambil langkah perbaikan karena masukan tersebut sangat masuk akal"}],"audio_text":"いただいたご指摘はもっともなので、早急に改善策を講じないわけにはいきません。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '改善策を講じないわけにはいきません berarti mau tidak mau harus segera mengambil langkah perbaikan.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('faea9c89-3ad3-451e-8b73-91dd2b08cd04', 'fd7c7a96-a042-484a-82c1-b9b26bed8115', 'd1000019-0000-0000-0000-000000000021', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun gaji kecil, saya tidak bisa mengabaikan keselamatan kerja."', '{"romaji":"Yosan ga kagira rete itemo, anzen kanri o orosoka ni suru wake ni wa ikanai.","tokens":["限られていても、","おろそかにする","いかない。","に伴って、","予算が","安全管理を","わけには","おろそかにした"],"target_translation":"Meskipun gaji kecil, saya tidak bisa mengabaikan keselamatan kerja."}'::jsonb, '["予算が","限られていても、","安全管理を","おろそかにする","わけには","いかない。"]'::jsonb, NULL, NULL, 'おろそかにするわけにはいかない berarti tidak boleh mengabaikan/melalaikan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4ee529a3-e2f1-4f3b-bc89-523e589e39f0', 'fd7c7a96-a042-484a-82c1-b9b26bed8115', 'd1000019-0000-0000-0000-000000000021', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah menerima kepercayaan sebesar ini, saya tidak mungkin mengecewakan mereka."', '{"romaji":"Kore hodo shinrai o yosete itadaita ijou, kitai o uragiru wake ni wa ikimasen.","display_text":"これほど信頼を寄せていただいた以上、期待を裏切るわけにはいきません。","phonetic_breakdown":["これほど","しんらいをよせていただいた","いじょう","きたいをうらぎる","わけにはいきません"]}'::jsonb, '{"expected_transcript":"これほど信頼を寄せていただいた以上、期待を裏切るわけにはいきません。"}'::jsonb, NULL, NULL, '期待を裏切る (mengecewakan harapan) + わけにはいきません adalah ungkapan komitmen tinggi N2.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('67db07c3-666c-464f-9aba-73757df97fd5', 'feb47f55-879a-400e-82da-33326900b3c9', NULL, 'listening', 'listening_choice', 'Dengarkan berita industri berikut. Apa yang sedang terjadi di pabrik-pabrik modern?', '{"options":[{"id":"opt_1","text":"Otomatisasi dengan robot sedang berkembang di banyak pabrik untuk menutupi kekurangan tenaga kerja"},{"id":"opt_2","text":"Seluruh pabrik menghentikan penggunaan mesin otomatis"},{"id":"opt_3","text":"Jumlah pekerja pabrik meningkat tajam dibanding dekade lalu"},{"id":"opt_4","text":"Produksi barang manufaktur dipindahkan sepenuhnya ke rumah tangga"}],"audio_text":"人手不足を補うため、多くの製造現場でロボットによる自動化が進みつつある。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ロボットによる自動化が進みつつある berarti otomatisasi oleh robot sedang terus berjalan.', 1, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('165174d9-3c7d-41a9-a9fc-ee8b0506836d', 'feb47f55-879a-400e-82da-33326900b3c9', NULL, 'listening', 'listening_choice', 'Dengarkan laporan pendidikan berikut. Tren apa yang dibahas?', '{"options":[{"id":"opt_1","text":"Sekolah melarang penggunaan tablet di dalam kelas"},{"id":"opt_2","text":"Jumlah jam pelajaran dikurangi setengahnya"},{"id":"opt_3","text":"Gaya pembelajaran di sekolah sedang berubah besar berkat bahan ajar digital"},{"id":"opt_4","text":"Buku tulis kertas kembali diwajibkan untuk semua ujian"}],"audio_text":"デジタル教材の普及により、学校の授業スタイルも大きく様変わりしつつあります。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '様変わりする (samagawari suru) berarti berubah wujud/wajah secara drastis.', 2, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2f611722-0605-4021-89ac-5f0dafe03cce', 'feb47f55-879a-400e-82da-33326900b3c9', NULL, 'listening', 'listening_choice', 'Dengarkan berita perkotaan berikut. Perubahan apa yang sedang terjadi di distrik tua?', '{"options":[{"id":"opt_1","text":"Jumlah toko tradisional bertambah dua kali lipat"},{"id":"opt_2","text":"Rencana pembangunan ulang dibatalkan oleh pemerintah kota"},{"id":"opt_3","text":"Harga sewa toko diturunkan untuk menarik pedagang baru"},{"id":"opt_4","text":"Pemandangan jalan pertokoan bersejarah sedang perlahan menghilang"}],"audio_text":"再開発計画の進行に伴い、歴史ある商店街の風景が少しずつ失われつつある。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '失われつつある (sedang perlahan hilang) menggambarkan perubahan yang memprihatinkan.', 3, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('76237917-82c1-4869-90c7-7ede1a0bbbe3', 'feb47f55-879a-400e-82da-33326900b3c9', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 新しい治療法の開発により、かつての不治の病も克服___つつある。', '{"options":["され","し","する","した"],"translation":"Berkat pengembangan metode pengobatan baru, penyakit yang dulu tak tersembuhkan pun sedang mulai teratasi.","sentence_template":"新しい治療法の開発により、かつての不治の病も克服[blank]つつある。"}'::jsonb, '{"selected":"され"}'::jsonb, NULL, NULL, '克服される (diatasi/ditaklukkan) → 克服されつつある.', 4, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c97c7d1e-86e3-41b0-b8bc-1b3b2d12210a', 'feb47f55-879a-400e-82da-33326900b3c9', NULL, 'reading', 'fill_blank', 'Pilih verba penghubung yang tepat: 地域のコミュニティのつながりが、近年薄れ___ある。', '{"options":["つつ","ながら","ばかり","どころか"],"translation":"Ikatan komunitas lokal sedang perlahan memudar dalam beberapa tahun terakhir.","sentence_template":"地域のコミュニティのつながりが、近年薄れ[blank]ある。"}'::jsonb, '{"selected":"つつ"}'::jsonb, NULL, NULL, '薄れる (usureru, memudar) + つつある menunjukkan proses pelemahan yang berlangsung bertahap.', 5, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('843e3841-4732-4d4a-b343-23abb0751b5f', 'feb47f55-879a-400e-82da-33326900b3c9', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Teknologi terjemahan otomatis sedang berkembang pesat setiap harinya."', '{"romaji":"Jidou honyaku no seido wa, hibi kyuusoku ni koujou shitsutsu arimasu.","display_text":"自動翻訳の精度は、日々急速に向上しつつあります。","phonetic_breakdown":["じどうほんやくの","せいどは","ひびきゅうそくに","こうじょうしつつ","あります"]}'::jsonb, '{"expected_transcript":"自動翻訳の精度は、日々急速に向上しつつあります。"}'::jsonb, NULL, NULL, '精度 (akurasi/presisi) dan 向上する (meningkat) adalah kosakata kunci bidang teknologi.', 6, '2026-11-25T18:49:03.420518+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d417ca02-1d1f-43f7-9945-1f6afed22999', 'feb47f55-879a-400e-82da-33326900b3c9', 'd1000019-0000-0000-0000-000000000025', 'writing', 'sentence_builder', 'Susun kalimat: "Standar keselamatan pangan sedang diperketat di berbagai negara."', '{"romaji":"Shokuhin no anzen kijun wa kakkoku de genkakuka saretsutsu aru.","tokens":["各国で","され","ある。","に限らず、","食品の安全基準は","厳格化","つつ","された"],"target_translation":"Standar keselamatan pangan sedang diperketat di berbagai negara."}'::jsonb, '["食品の安全基準は","各国で","厳格化","され","つつ","ある。"]'::jsonb, NULL, NULL, '厳格化されつつある berarti sedang terus diperketat.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e37d46ed-64a9-4db5-b124-0293d74d60d2', 'feb47f55-879a-400e-82da-33326900b3c9', 'd1000019-0000-0000-0000-000000000025', 'listening', 'listening_choice', 'Dengarkan komentar ekonom. Bagaimana situasi ekspor kuartal ini?', '{"options":[{"id":"opt_1","text":"Nilai ekspor manufaktur anjlok ke titik terendah"},{"id":"opt_2","text":"Nilai ekspor sektor manufaktur sedang pulih secara perlahan seiring membaiknya permintaan pasar luar negeri"},{"id":"opt_3","text":"Ekspor manufaktur dihentikan sementara"},{"id":"opt_4","text":"Pasar luar negeri tidak lagi membeli produk manufaktur"}],"audio_text":"海外市場の需要回復を受け、製造業の輸出額は緩やかに持ち直しつつある。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '緩やかに持ち直しつつある berarti sedang membaik/pulih secara bertahap.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
